insert into public.classes (name, programme, teacher_id, owner_kind, site_slug, subject, listed, self_study, content_programmes) select 'A Level Chemistry', 'Cambridge AS & A Level Chemistry 9701', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e', 'main', 'alevel-chem', 'A Level Chemistry', false, false, array['AS Level','A Level'] where not exists (select 1 from public.classes where site_slug = 'alevel-chem');
insert into public.classes (name, programme, teacher_id, owner_kind, follows, subject, listed, self_study, description) select 'A Level Chemistry · Independent learners', 'Cambridge AS & A Level Chemistry 9701', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e', 'main', 'alevel-chem', 'A Level Chemistry', false, true, 'Learn on your own at your own pace: lessons with instant feedback, quizzes and your personal learning profile.' where not exists (select 1 from public.classes where follows = 'alevel-chem' and self_study);
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'cf77ed64-2b41-5a5c-98a5-7ea0e6644d07', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '1.1' limit 1), '1.1 Particles in the atom and atomic radius: Protons, neutrons and electrons; beams in an electric field; atomic and ionic radius', 'A Level Chemistry · 1 Atomic structure', '/achem-1-1/', 'ACHEM-1-1', 36, 60, 1010 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-1-1', '1.1 Particles in the atom and atomic radius: Protons, neutrons and electrons; beams in an electric field; atomic and ionic radius', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["Nucleus", "Nucleus", "Electron shells", "Nucleus"], "tip": "The nucleus is tiny and dense; the electrons occupy the space around it."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 7, "n": 7, "ans": ["11", "12", "10", "14", "10", "18", "20"], "tip": "Neutrons = A − Z. For an ion, change only the number of electrons."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["calcium", "ca2", "40ca", "ca 2"], ["40"]], "tips": ["The number of protons tells you the element. Compare protons with electrons to find the charge. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Deflected towards the negative plate", "Not deflected", "Deflected towards the positive plate", "Deflected towards the negative plate", "Deflected towards the positive plate"], "tip": "Opposite charges attract. No charge, no deflection."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["same charge", "equal charge", "same size of charge", "same magnitude", "charge is the same", "charges are equal", "equal and opposite", "same size", "charges of the same"], ["smaller mass", "less mass", "lighter", "1/1836", "lower mass", "mass is much smaller", "charge to mass", "charge mass ratio", "much less mass"]], "tips": ["Compare the size of the charge first, then the mass."]}, {"kind": "text", "id": "q3_2", "q": "Q7", "max": 2, "pts": [["charge to mass", "charge/mass", "ratio", "2/4", "1/1", "0.5", "half"], ["proton", "1h"]], "tips": ["Work out charge ÷ mass for each particle."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q8", "max": 5, "n": 5, "ans": ["Smaller", "Larger", "Smaller", "Larger", "Smaller"], "tip": "Think: nuclear charge, number of shells, shielding, repulsion."}, {"kind": "text", "id": "q4_1", "q": "Q9", "max": 3, "pts": [["nuclear charge increases", "more protons", "number of protons increases", "proton number increases", "greater nuclear charge", "increasing nuclear charge", "nuclear charge is greater", "increase in nuclear charge"], ["same shell", "same shielding", "similar shielding", "shielding stays", "shielding is constant", "same number of shells", "same energy level", "shielding remains"], ["attract+strong", "attract+more", "pulled closer", "greater attraction", "stronger attraction", "drawn closer", "attract+greater"]], "tips": ["Three ideas: nuclear charge, shielding (or shell), attraction."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q10", "max": 4, "pts": [["same number of electrons", "same electron", "same electronic configuration", "18 electrons"], ["ca k cl s", "ca2 k cl s2", "calcium potassium chlor", "ca 2 k cl s 2"], ["more protons", "nuclear charge", "proton number", "number of protons", "20 protons"], ["attract", "pulled closer", "held more"]], "tips": ["Count the protons in each ion. The electrons are the same. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}, {"kind": "text", "id": "q5_1", "q": "Q11", "max": 2, "pts": [["27al", "al3", "alumin"], ["31p", "p3", "phosph"]], "tips": ["Protons give the element; protons + neutrons give the mass number; protons − electrons gives the charge. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "Most passed straight through, so most of the atom is empty space. A few bounced back, so the positive charge and nearly all the mass are concentrated in a very small, dense nucleus that repels the positive alpha particles."], ["Q2", "Mass, positive charge and nucleons: nucleus. Almost all of the volume: the electron shells around the nucleus."]], "2": [["Q3", "²³Na: 11 protons, 12 neutrons; Na⁺ has 10 electrons. ²⁷Al: 14 neutrons; Al³⁺ has 10 electrons. S²⁻ has 16 + 2 = 18 electrons. ³⁷Cl has 37 − 17 = 20 neutrons."], ["Q4", "20 protons, so the element is calcium [1]. Mass number = 20 + 20 = 40 and there are two fewer electrons than protons, so the ion is ⁴⁰Ca²⁺ [1]."]], "3": [["Q5", "Positive particles (protons, alpha particles) go towards the negative plate; negative particles (electrons, chloride ions) go towards the positive plate; neutrons carry no charge and go straight on."], ["Q6", "An electron and a proton have charges of the same size (opposite sign) [1], but the electron has a much smaller mass (about 1/1836), so its charge-to-mass ratio is much larger and it is deflected far more [1]."], ["Q7", "Charge-to-mass ratio: proton 1/1 = 1; alpha particle 2/4 = 0.5 [1]. The proton has the larger ratio, so the proton beam is deflected more (about twice as much) [1]."]], "4": [["Q8", "Mg is smaller than Na (more protons, same shell). K is larger than Na (extra shell). Na⁺ is smaller than Na (outer shell lost). Cl⁻ is larger than Cl (more repulsion, same nuclear charge). Mg²⁺ is smaller than O²⁻ (same electrons, 12 protons instead of 8)."], ["Q9", "Nuclear charge increases from Na to Cl [1]. The outer electrons are in the same shell, so shielding is about the same [1]. The outer electrons are attracted more strongly and pulled closer to the nucleus [1]."]], "5": [["Q10", "(a) They have the same number of electrons (18) [1]. (b) Ca²⁺ < K⁺ < Cl⁻ < S²⁻ [1]. The number of protons increases from S (16) to Ca (20) while the number of electrons and the shielding stay the same [1], so the electrons are attracted more strongly and the ion is smaller [1]."], ["Q11", "X is ²⁷Al³⁺ [1]. Y is ³¹P³⁻ [1]."]], "6": [["Exit ticket", "Na⁺ has lost its whole outer shell, and the remaining electrons are attracted more strongly by the same nuclear charge. Cl⁻ has gained an electron in the same shell: there is more repulsion between the outer electrons and the nuclear charge is unchanged, so the ion is larger."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q3_2": "Q7", "q4_1": "Q9", "q5_0": "Q10", "q5_1": "Q11", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Most alpha particles passed straight through the gold foil, but about 1 in 8000 bounced back. What does each observation suggest about the atom?", "Q2": "Which part of the atom?", "Q3": "How many of each particle? Use Z and A.", "Q4": "An ion has 20 protons, 20 neutrons and 18 electrons. Identify the ion, giving its symbol, mass number and charge.", "Q5": "Beams of these particles travel at the same velocity between a positive plate and a negative plate. What happens to each beam?", "Q6": "Explain why a beam of electrons is deflected through a much larger angle than a beam of protons moving at the same velocity in the same electric field.", "Q7": "Protons, ¹H⁺, and alpha particles, ⁴He²⁺, travel at the same velocity through the same electric field. Deduce which beam is deflected more. Show your reasoning.", "Q8": "Larger or smaller?", "Q9": "Explain why atomic radius decreases across Period 3 from sodium to chlorine.", "Q10": "The ions S²⁻, Cl⁻, K⁺ and Ca²⁺ are isoelectronic. (a) State what isoelectronic means. (b) Arrange the four ions in order of increasing radius and explain your order.", "Q11": "Particle X has 13 protons, 14 neutrons and 10 electrons. Particle Y has 15 protons, 16 neutrons and 18 electrons. Give the full symbol of each particle, including mass number and charge."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'f5ca3fd9-c55a-519c-90c4-51260c3529c0', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '1.2' limit 1), '1.2 Isotopes: Defining isotopes, isotope notation, and why isotopes react in the same way', 'A Level Chemistry · 1 Atomic structure', '/achem-1-2/', 'ACHEM-1-2', 31, 60, 1020 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-1-2', '1.2 Isotopes: Defining isotopes, isotope notation, and why isotopes react in the same way', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 7, "n": 7, "ans": ["0", "1", "2", "1", "8", "143", "146"], "tip": "Neutrons = mass number − atomic number."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["same number of protons", "same proton number", "same atomic number", "same element", "same protons"], ["different number of neutrons", "different numbers of neutrons", "different neutron", "different mass number", "different nucleon number", "different amount of neutrons"]], "tips": ["What is the same? What is different?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["Same", "Different", "Same", "Same", "Different", "Different"], "tip": "Electrons decide the chemistry. Neutrons add mass."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["same number of electrons", "same electron", "same electronic configuration", "same outer"], ["depend", "determin", "involve", "outer shell", "outer electron", "transfer", "sharing", "decide"]], "tips": ["Which particles take part in chemical reactions?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 6, "n": 6, "ans": ["Isotopes", "Not isotopes", "Isotopes", "Not isotopes", "Isotopes", "Not isotopes"], "tip": "Isotopes must be the same element."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["26"], ["30"], ["23"]], "tips": ["Neutrons = A − Z. A 3+ ion has lost three electrons."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 5, "pts": [["35 protons", "same number of protons", "same proton number", "same atomic number", "same protons"], ["neutron", "44", "46"], ["greater mass", "more mass", "heavier", "higher mass", "more massive", "larger mass"], ["same volume", "volume is the same", "same size", "similar volume", "same space"], ["same number of electrons", "same electronic configuration", "same electron"]], "tips": ["(a) protons and neutrons. (b) density = mass ÷ volume. (c) electrons. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "The hydrogen atoms in heavy water each contain an extra particle with mass but no charge (a neutron), so each molecule is heavier and the ice is denser. The number of protons and electrons must be the same, because it is still hydrogen and still reacts as water."]], "2": [["Q2", "¹H 0, ²H 1, ³H 2 neutrons; every hydrogen isotope has 1 proton. ¹⁴C has 14 − 6 = 8 neutrons. ²³⁵U has 143 and ²³⁸U has 146 neutrons."], ["Q3", "Atoms of the same element with the same number of protons [1] but different numbers of neutrons [1]."]], "3": [["Q4", "Protons, electronic configuration and reactions are the same. Neutrons, mass and density are different."], ["Q5", "They have the same number of electrons and the same electronic configuration [1], and chemical properties depend on the (outer) electrons [1]."]], "4": [["Q6", "Isotopes: ¹²C/¹⁴C, ¹⁶O/¹⁸O and ²³⁵U/²³⁸U (same protons, different neutrons). ¹⁴C/¹⁴N and ⁴⁰Ar/⁴⁰Ca are different elements. O₂ and O₃ are different molecules of oxygen, not isotopes."], ["Q7", "26 protons [1], 56 − 26 = 30 neutrons [1], 26 − 3 = 23 electrons [1]."]], "5": [["Q8", "(a) Both have 35 protons [1]; ⁷⁹Br has 44 neutrons and ⁸¹Br has 46 [1]. (b) Each ⁸¹Br atom has a greater mass [1] but the molecules take up the same volume, so the mass per unit volume is greater [1]. (c) Both have the same number of electrons and the same electronic configuration, and this decides how they react [1]."]], "6": [["Exit ticket", "Isotopes are atoms of the same element (same number of protons) with different numbers of neutrons, so they have different masses."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Ice made from heavy water sinks in ordinary water. Suggest what could be different about the hydrogen atoms in heavy water, and what must be the same.", "Q2": "How many?", "Q3": "Define the term isotopes.", "Q4": "Same or different for atoms of ³⁵Cl and ³⁷Cl?", "Q5": "Explain why isotopes of the same element have the same chemical properties.", "Q6": "Are the two particles isotopes of each other?", "Q7": "State the numbers of protons, neutrons and electrons in a ⁵⁶Fe³⁺ ion (Z = 26).", "Q8": "Bromine has two isotopes, ⁷⁹Br and ⁸¹Br (Z = 35). (a) State one similarity and one difference in the structure of the nuclei of these isotopes. (b) Liquid bromine made only from ⁸¹Br has a higher density than ordinary bromine. Explain why. (c) Explain why both isotopes react with sodium in exactly the same way."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '01b6de18-bc72-55d9-be0a-46030a101ee4', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '1.3' limit 1), '1.3 Electrons, energy levels and atomic orbitals · Lesson 1: Shells, sub-shells and orbitals; orbital shapes; writing electronic configurations', 'A Level Chemistry · 1 Atomic structure', '/achem-1-3/', 'ACHEM-1-3', 31, 60, 1031 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-1-3', '1.3 Electrons, energy levels and atomic orbitals · Lesson 1: Shells, sub-shells and orbitals; orbital shapes; writing electronic configurations', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 7, "n": 7, "ans": ["3", "2", "5", "10", "8", "18", "3"], "tip": "Each orbital holds 2 electrons. Count orbitals, then double."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 7, "n": 7, "ans": ["1s² 2s² 2p³", "1s² 2s² 2p⁶ 3s¹", "1s² 2s² 2p⁶ 3s² 3p⁵", "1s² 2s² 2p⁶ 3s² 3p⁶ 4s¹", "1s² 2s² 2p⁶ 3s² 3p⁶ 3d¹ 4s²", "1s² 2s² 2p⁶", "1s² 2s² 2p⁶"], "tip": "Count the electrons, then fill 1s, 2s, 2p, 3s, 3p, 4s, 3d."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["3s2 3p4", "3p4"], ["two unpaired", "2 unpaired", "two", "unpaired electrons 2", "2 electrons are unpaired"]], "tips": ["3p has three orbitals. Put four electrons in them, singly first."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 8, "n": 8, "ans": ["1", "0", "2", "3", "2", "1", "0", "3"], "tip": "Put the p electrons into three boxes, singly first."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["repel", "repulsion"], ["separate orbitals", "singly", "single", "lower energy", "more stable", "minimis", "minimiz", "less repulsion", "reduce"]], "tips": ["Electrons all have the same charge."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 5, "pts": [["spher"], ["dumb", "dumbbell", "figure of eight", "two lobes", "lobes"], ["3s2 3p3", "3p3"], ["3s2 3p6", "3p6"], ["three unpaired", "3 unpaired", "three", "unpaired electrons 3"]], "tips": ["The sulfide ion has two more electrons than a sulfur atom."]}]}, "models": {"1": [["Q1", "The electrons can only have certain fixed energies (energy levels). When an electron drops from a higher level to a lower one it gives out light of one particular energy, so the colour is always the same."]], "2": [["Q2", "p: 3 orbitals; one orbital: 2 electrons; d: 5 orbitals, so 10 electrons. n = 2: 2s + 2p = 2 + 6 = 8. n = 3: 3s + 3p + 3d = 2 + 6 + 10 = 18, in three sub-shells."]], "3": [["Q3", "N 1s² 2s² 2p³; Na 1s² 2s² 2p⁶ 3s¹; Cl 1s² 2s² 2p⁶ 3s² 3p⁵; K … 3p⁶ 4s¹; Sc … 3p⁶ 3d¹ 4s². Na⁺ and F⁻ both have 10 electrons: 1s² 2s² 2p⁶."], ["Q4", "1s² 2s² 2p⁶ 3s² 3p⁴ [1]. The four 3p electrons occupy three orbitals: one pair and two unpaired electrons [1]."]], "4": [["Q5", "H 1; He 0; C 2; N 3; O 2 (one pair, two single); F 1; Ne 0; P 3."], ["Q6", "Electrons repel each other [1]. Occupying separate orbitals (with parallel spins) minimises this repulsion and gives a lower-energy, more stable arrangement [1]."]], "5": [["Q7", "(a) An s orbital is spherical [1]; a p orbital is dumb-bell shaped [1]. (b) P: 1s² 2s² 2p⁶ 3s² 3p³ [1]; S²⁻: 1s² 2s² 2p⁶ 3s² 3p⁶ [1]. (c) Three unpaired electrons [1]."]], "6": [["Exit ticket", "s: 1 orbital, 2 electrons. p: 3 orbitals, 6 electrons. d: 5 orbitals, 10 electrons."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Sodium always gives the same yellow light, whatever compound it is in. What might this tell us about the energies that electrons in a sodium atom can have?", "Q2": "How many?", "Q3": "Choose the electronic configuration.", "Q4": "Write the full electronic configuration of a sulfur atom (Z = 16) and state how many unpaired electrons it has. Type it like this: 1s2 2s2 …", "Q5": "How many unpaired electrons does the atom have in its ground state?", "Q6": "Explain why the three electrons in the 2p sub-shell of a nitrogen atom occupy three separate orbitals rather than pairing up.", "Q7": "(a) Describe the shape of an s orbital and of a p orbital. (b) Write the full electronic configuration of a phosphorus atom (Z = 15) and of a sulfide ion, S²⁻ (Z = 16). Type them like this: 1s2 2s2 … (c) State the number of unpaired electrons in a phosphorus atom."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '7a5cf4b5-c399-5bc5-b645-bb11f024a252', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '1.3' limit 1), '1.3 Electrons, energy levels and atomic orbitals · Lesson 2: The 4s and 3d sub-shells, chromium and copper, ions of the 3d elements, and free radicals', 'A Level Chemistry · 1 Atomic structure', '/achem-1-3-2/', 'ACHEM-1-3-2', 43, 60, 1032 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-1-3-2', '1.3 Electrons, energy levels and atomic orbitals · Lesson 2: The 4s and 3d sub-shells, chromium and copper, ions of the 3d elements, and free radicals', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["[Ar] 4s¹", "[Ar] 4s²", "[Ar] 3d¹ 4s²", "[Ar] 3d² 4s²"], "tip": "4s fills first, then 3d."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 7, "n": 7, "ans": ["[Ar] 3d³ 4s²", "[Ar] 3d⁵ 4s²", "[Ar] 3d⁶ 4s²", "[Ar] 3d⁷ 4s²", "[Ar] 3d⁸ 4s²", "[Ar] 3d¹⁰ 4s²", "[Ar] 3d¹⁰ 4s² 4p¹"], "tip": "Argon has 18 electrons. Put the rest into 4s (two), then 3d, then 4p."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["four unpaired", "4 unpaired", "four", "4 electrons"], ["five orbitals", "5 orbitals", "singly", "one pair", "one orbital", "separate orbitals"]], "tips": ["Six electrons into five 3d boxes, singly first."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 4, "n": 4, "ans": ["[Ar] 3d⁴ 4s²", "[Ar] 3d⁵ 4s¹", "[Ar] 3d⁹ 4s²", "[Ar] 3d¹⁰ 4s¹"], "tip": "Half-filled or full 3d is more stable."}, {"kind": "choice", "id": "q3_1", "q": "Q6", "max": 4, "n": 4, "ans": ["6", "1", "5", "0"], "tip": "Count single electrons in 3d and in 4s."}, {"kind": "text", "id": "q3_2", "q": "Q7", "max": 2, "pts": [["half"], ["stable", "lower energy", "less repulsion"]], "tips": ["What is special about 3d⁵?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q8", "max": 7, "n": 7, "ans": ["[Ar] 3d⁶", "[Ar] 3d⁵", "[Ar] 3d⁵", "[Ar] 3d⁹", "[Ar] 3d¹⁰", "[Ar] 3d¹⁰", "[Ar]"], "tip": "Write the atom first, then remove 4s electrons before 3d."}, {"kind": "text", "id": "q4_1", "q": "Q9", "max": 2, "pts": [["4s electrons", "4s first", "lost from 4s", "from the 4s", "4s sub", "4s is lost", "loses 4s", "lose 4s", "4s are lost"], ["3d6"]], "tips": ["Which electrons leave first?"]}], "5": [{"kind": "choice", "id": "q5_0", "q": "Q10", "max": 6, "n": 6, "ans": ["Free radical", "Not a free radical", "Not a free radical", "Free radical", "Not a free radical", "Free radical"], "tip": "Is there an unpaired electron?"}, {"kind": "text", "id": "q5_1", "q": "Q11", "max": 5, "pts": [["3d10 4s1", "3d104s1", "4s1 3d10"], ["3d9"], ["unpaired"], ["chlorine atom", "cl atom", "methyl", "ch3", "hydroxyl", "bromine atom", "hydrogen atom", "cl"], ["3p5", "seven", "7 outer", "eight", "8 outer", "paired", "3p6"]], "tips": ["(a) copper is one of the two exceptions."]}]}, "models": {"1": [["Q1", "The 4s sub-shell must be lower in energy than the 3d sub-shell, so an electron is more stable in 4s. Sub-shells fill in order of energy, not simply shell by shell."], ["Q2", "K [Ar] 4s¹; Ca [Ar] 4s²; Sc [Ar] 3d¹ 4s²; Ti [Ar] 3d² 4s²."]], "2": [["Q3", "V 3d³ 4s²; Mn 3d⁵ 4s²; Fe 3d⁶ 4s²; Co 3d⁷ 4s²; Ni 3d⁸ 4s²; Zn 3d¹⁰ 4s²; Ga 3d¹⁰ 4s² 4p¹ (each after [Ar])."], ["Q4", "Four unpaired electrons [1]. The six 3d electrons occupy five orbitals: all five singly, then one pair, which leaves four unpaired; the two 4s electrons are paired [1]."]], "3": [["Q5", "Predicted Cr 3d⁴ 4s², real Cr 3d⁵ 4s¹. Predicted Cu 3d⁹ 4s², real Cu 3d¹⁰ 4s¹."], ["Q6", "Cr: five in 3d and one in 4s, 6. Cu: only the 4s electron, 1. Mn: five in 3d, 5. Zn: all paired, 0."], ["Q7", "With 3d⁵ 4s¹ the 3d sub-shell is half-filled [1], which is a more stable, lower-energy arrangement with less repulsion between the electrons [1]."]], "4": [["Q8", "Fe²⁺ 3d⁶; Fe³⁺ 3d⁵; Mn²⁺ 3d⁵; Cu²⁺ 3d⁹; Cu⁺ 3d¹⁰; Zn²⁺ 3d¹⁰; Sc³⁺ [Ar]."], ["Q9", "The 4s electrons are lost first, not the 3d electrons [1], so Fe²⁺ is [Ar] 3d⁶ [1]."]], "5": [["Q10", "Cl, •CH₃ and H each have an unpaired electron: free radicals. Cl⁻, Cl₂ and Ne have all their electrons paired."], ["Q11", "(a) Cu: [Ar] 3d¹⁰ 4s¹ [1]; Cu²⁺: [Ar] 3d⁹ [1]. (b) A species with one or more unpaired electrons [1], for example a chlorine atom [1]. (c) A chlorine atom has seven outer electrons (3s² 3p⁵), so one is unpaired; a chloride ion has eight (3p⁶), which are all paired [1]."]], "6": [["Exit ticket", "With 3d⁵ 4s¹ the 3d sub-shell is half-filled and all six electrons are unpaired in separate orbitals, which is a more stable (lower-energy) arrangement with less repulsion."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_2": "Q7", "q4_1": "Q9", "q5_1": "Q11", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "The third shell can hold 18 electrons, but potassium puts its 19th electron into the fourth shell. Suggest what this tells you about the energies of the 3d and 4s sub-shells.", "Q2": "Choose the shorthand electronic configuration.", "Q3": "Choose the shorthand electronic configuration of the atom.", "Q4": "State the number of unpaired electrons in an iron atom, [Ar] 3d⁶ 4s², and explain your answer.", "Q5": "Choose the configuration.", "Q6": "How many unpaired electrons does the atom have?", "Q7": "Explain why chromium has the configuration [Ar] 3d⁵ 4s¹ rather than [Ar] 3d⁴ 4s².", "Q8": "Choose the configuration of the ion.", "Q9": "A student writes the configuration of Fe²⁺ as [Ar] 3d⁴ 4s². Explain the mistake and give the correct configuration. Type it like this: [Ar] 3d6", "Q10": "Is the species a free radical?", "Q11": "(a) Write the shorthand electronic configuration of a copper atom and of a Cu²⁺ ion. Type them like this: [Ar] 3d6 4s2. (b) State what is meant by a free radical and give one example. (c) Explain why a chlorine atom is a free radical but a chloride ion is not."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '285dcc8a-9dcf-560d-9bb2-1ce02c7d997b', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '1.4' limit 1), '1.4 Ionisation energy: Defining ionisation energy; trends across periods and down groups; successive ionisation energies', 'A Level Chemistry · 1 Atomic structure', '/achem-1-4/', 'ACHEM-1-4', 33, 60, 1040 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-1-4', '1.4 Ionisation energy: Defining ionisation energy; trends across periods and down groups; successive ionisation energies', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 3, "n": 3, "ans": ["Mg(g) → Mg⁺(g) + e⁻", "Mg⁺(g) → Mg²⁺(g) + e⁻", "Al²⁺(g) → Al³⁺(g) + e⁻"], "tip": "One electron at a time, everything gaseous."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Increases it", "Decreases it", "Decreases it", "Decreases it"], "tip": "Stronger attraction means more energy is needed."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 3, "pts": [["further", "larger radius", "bigger radius", "greater distance", "more shells", "extra shell", "larger atomic radius", "bigger atom", "larger atom", "greater atomic radius"], ["shield", "screen"], ["weaker attraction", "less attraction", "attract+less", "attract+weak", "less strongly", "held less"]], "tips": ["Distance, shielding, attraction."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 6, "n": 6, "ans": ["Mg", "Mg", "P", "Cl", "Ne", "Li"], "tip": "General increase across a period, with two small falls. Decrease down a group."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["3p", "p sub", "p orbital", "p electron"], ["higher energy", "higher in energy", "further from", "shielded by", "more shielded", "extra shielding"]], "tips": ["Which sub-shell does each electron come from?"]}, {"kind": "text", "id": "q3_2", "q": "Q7", "max": 2, "pts": [["pair", "spin"], ["repel", "repulsion"]], "tips": ["Compare 3p³ with 3p⁴ using electrons in boxes."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q8", "max": 5, "n": 5, "ans": ["Group 1", "Group 2", "Group 13", "Group 14", "Group 15"], "tip": "Find the first very large jump. Count the electrons removed before it."}, {"kind": "text", "id": "q4_1", "q": "Q9", "max": 3, "pts": [["second shell", "inner shell", "new shell", "2p", "shell closer", "lower shell", "full shell", "different shell"], ["closer to the nucleus", "nearer", "smaller distance", "less distance", "closer"], ["less shield", "fewer shield", "stronger attraction", "greater attraction", "attract+more", "attract+strong", "less shielded"]], "tips": ["Sodium is 1s² 2s² 2p⁶ 3s¹. Where does the second electron come from?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q10", "max": 5, "pts": [["group 16", "16", "six outer", "6 outer", "group vi"], ["sulfur", "sulphur"], ["s2 g s3 g e", "s 2 g s 3 g e"], ["positive ion", "increasingly positive", "more positive", "fewer electrons", "same number of protons", "same nuclear charge"], ["stronger attraction", "greater attraction", "attract+more", "attract+strong", "less repulsion", "smaller radius", "closer", "held more"]], "tips": ["(a) find the large jump. (b) the third ionisation starts from the 2+ ion. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "The first electron comes from the outer (third) shell. The second must come from the second shell, which is much closer to the nucleus and much less shielded, so it is attracted far more strongly."], ["Q2", "First: Mg(g) → Mg⁺(g) + e⁻. Second: Mg⁺(g) → Mg²⁺(g) + e⁻. Third for aluminium: Al²⁺(g) → Al³⁺(g) + e⁻. Each equation removes one electron and every species is gaseous."]], "2": [["Q3", "Greater nuclear charge increases it. Greater distance, more shielding and spin-pair repulsion all decrease it."], ["Q4", "The outer electron of potassium is in a shell further from the nucleus [1] and is more shielded by inner shells [1]. These outweigh the greater nuclear charge, so the attraction is weaker and less energy is needed [1]."]], "3": [["Q5", "Mg > Na (greater nuclear charge). Mg > Al (Al loses a 3p electron). P > S (spin-pair repulsion in S). Cl > S. Ne > Na (Na starts a new shell). Li > Na (Na''s outer electron is further away and more shielded)."], ["Q6", "The electron removed from aluminium is in the 3p sub-shell; in magnesium it is in 3s [1]. The 3p electron is higher in energy and is shielded by the 3s electrons, so it is easier to remove [1]."], ["Q7", "In sulfur (3p⁴) the electron removed is one of a pair in the same 3p orbital [1]. The repulsion between the two paired electrons (spin-pair repulsion) makes it easier to remove [1]."]], "4": [["Q8", "Large jump after 1 electron: Group 1. After 2: Group 2. After 3: Group 13. After 4: Group 14. After 5: Group 15."], ["Q9", "The second electron is removed from the second shell (2p), not the third [1]. This shell is much closer to the nucleus [1] and less shielded, so the attraction is much stronger [1]."]], "5": [["Q10", "(a) The large jump comes after the sixth electron, so X has six outer electrons and is in Group 16 [1]: X is sulfur [1]. (b) S²⁺(g) → S³⁺(g) + e⁻ [1]. (c) Each electron is removed from a more positive ion with the same nuclear charge and fewer electrons [1], so the remaining electrons are closer and attracted more strongly [1]."]], "6": [["Exit ticket", "Nuclear charge, atomic (or ionic) radius, shielding by inner shells and sub-shells, and spin-pair repulsion."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q3_2": "Q7", "q4_1": "Q9", "q5_0": "Q10", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "The second ionisation energy of sodium is about nine times its first. Before you study the notes, suggest a reason.", "Q2": "Choose the equation.", "Q3": "What is the effect on the first ionisation energy?", "Q4": "Explain why the first ionisation energy of potassium is lower than that of sodium.", "Q5": "Which element has the higher first ionisation energy?", "Q6": "Explain why the first ionisation energy of aluminium is lower than that of magnesium.", "Q7": "Explain why the first ionisation energy of sulfur is lower than that of phosphorus.", "Q8": "Successive ionisation energies in kJ mol⁻¹ are given. In which group is the element?", "Q9": "Explain why the second ionisation energy of sodium is much greater than its first.", "Q10": "An element X in Period 3 has the successive ionisation energies 1000, 2260, 3390, 4540, 6990, 8490 and 27100 kJ mol⁻¹. (a) Deduce the group of X and identify X. (b) Write an equation, with state symbols, for the third ionisation energy of X, using its real symbol. (c) Explain why successive ionisation energies always increase."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '7a3d0a45-a239-5fc7-b145-5d1818129fcc', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '2.1' limit 1), '2.1 Relative masses of atoms and molecules: The unified atomic mass unit; relative isotopic, atomic, molecular and formula mass', 'A Level Chemistry · 2 Atoms, molecules and stoichiometry', '/achem-2-1/', 'ACHEM-2-1', 24, 60, 2010 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-2-1', '2.1 Relative masses of atoms and molecules: The unified atomic mass unit; relative isotopic, atomic, molecular and formula mass', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Unified atomic mass unit", "Relative atomic mass", "Relative isotopic mass", "Relative formula mass", "Relative molecular mass"], "tip": "Atomic = average for an element. Isotopic = one isotope."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["weighted average", "average mass", "mean mass", "weighted mean"], ["1/12", "one twelfth", "twelfth", "unified atomic mass unit", "carbon 12", "c 12", "12c"]], "tips": ["Two parts: what is averaged, and what it is compared with."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 8, "n": 8, "ans": ["18.0", "44.0", "58.5", "98.1", "100.1", "74.1", "249.6", "342.3"], "tip": "Brackets first: (SO₄)₃ means three S and twelve O."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["10 19.9", "19.9 10", "199", "881", "1080"], ["10.8"]], "tips": ["Multiply each mass by its percentage, add, then divide by 100."]}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["2432", "1896", "24 79", "79 24", "79.0 24"], ["24.3"]], "tips": ["Three isotopes, three products to add."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["100 x", "100-x", "6350", "63x"], ["75"], ["25"]], "tips": ["63x + 65(100 − x) = 63.5 × 100. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}, {"kind": "text", "id": "q5_1", "q": "Q8", "max": 2, "pts": [["isotope"], ["average", "weighted", "mixture", "abundance", "proportion", "75"]], "tips": ["Is every chlorine atom the same?"]}]}, "models": {"1": [["Q1", "The real masses are extremely small and awkward to use. Comparing with a standard gives simple numbers (for example hydrogen about 1, carbon 12, magnesium about 24), and the ratios of these numbers are what matter in reactions."]], "2": [["Q2", "One twelfth of a ¹²C atom: unified atomic mass unit. Weighted average for an element: relative atomic mass. One isotope: relative isotopic mass. Ionic compound: relative formula mass. Molecule: relative molecular mass."], ["Q3", "The weighted average mass of the atoms of an element [1] compared with one twelfth of the mass of an atom of carbon-12 [1]."]], "3": [["Q4", "H₂O 18.0; CO₂ 44.0; NaCl 58.5; H₂SO₄ 2.0 + 32.1 + 64.0 = 98.1; CaCO₃ 40.1 + 12.0 + 48.0 = 100.1; Ca(OH)₂ 40.1 + 34.0 = 74.1; CuSO₄·5H₂O 159.6 + 90.0 = 249.6; Al₂(SO₄)₃ 54.0 + 3 × 96.1 = 342.3."]], "4": [["Q5", "(10 × 19.9 + 11 × 80.1) ÷ 100 [1] = 1080.1 ÷ 100 = 10.8 [1]."], ["Q6", "(24 × 79.0 + 25 × 10.0 + 26 × 11.0) ÷ 100 [1] = 2432 ÷ 100 = 24.3 [1]."]], "5": [["Q7", "Let the abundance of ⁶³Cu be x%: 63x + 65(100 − x) = 6350 [1]. 6500 − 2x = 6350, so x = 75: ⁶³Cu is 75% [1] and ⁶⁵Cu is 25% [1]."], ["Q8", "Chlorine is a mixture of two isotopes, ³⁵Cl and ³⁷Cl [1]. The relative atomic mass is the weighted average of their masses, taking the abundance of each into account [1]."]], "6": [["Exit ticket", "Each is a ratio of two masses (the mass of the particle divided by one twelfth of the mass of a carbon-12 atom), so the units cancel."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q4_0": "Q5", "q4_1": "Q6", "q5_0": "Q7", "q5_1": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Why might chemists prefer to compare the masses of atoms with a standard atom, rather than use their real masses in grams?", "Q2": "Which term?", "Q3": "Define relative atomic mass, Ar.", "Q4": "Calculate the relative molecular mass or relative formula mass.", "Q5": "Boron has two isotopes: ¹⁰B (19.9%) and ¹¹B (80.1%). Calculate the relative atomic mass of boron to three significant figures. Show your working.", "Q6": "Magnesium has three isotopes: ²⁴Mg (79.0%), ²⁵Mg (10.0%) and ²⁶Mg (11.0%). Calculate the relative atomic mass of magnesium to three significant figures.", "Q7": "Copper has two isotopes, ⁶³Cu and ⁶⁵Cu, and a relative atomic mass of 63.5. Calculate the percentage abundance of each isotope. Show your working.", "Q8": "Explain why the relative atomic mass of chlorine is 35.5 and not a whole number, although every chlorine atom contains a whole number of nucleons."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'b08ec6af-79be-548b-a952-14db8a32e12b', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '2.2' limit 1), '2.2 The mole and the Avogadro constant: Counting particles by weighing: moles, molar mass and numbers of particles', 'A Level Chemistry · 2 Atoms, molecules and stoichiometry', '/achem-2-2/', 'ACHEM-2-2', 23, 60, 2020 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-2-2', '2.2 The mole and the Avogadro constant: Counting particles by weighing: moles, molar mass and numbers of particles', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["0.500 mol", "0.100 mol", "2.00 mol", "0.0500 mol", "0.500 mol", "0.250 mol"], "tip": "n = m ÷ M."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 1, "pts": [["25.0", "25.03", "25.025", "25 g", "25g"]], "tips": ["mass = n × M."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["6.02 × 10²³", "3.01 × 10²³", "1.20 × 10²⁴", "1.81 × 10²⁴", "6.02 × 10²²", "3.01 × 10²³"], "tip": "Find the moles of the particle asked for, then multiply by L."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["molecule", "o2", "diatomic"], ["1.20", "12.04", "twice", "two moles of atoms", "2 mol of atoms", "specify", "type of particle", "double"]], "tips": ["What are the particles in oxygen gas? Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["44 0 6 02", "44 6 02", "44.0/6.02", "44/6.02"], ["7.31", "7.3"]], "tips": ["mass of one molecule = M ÷ L."]}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["0.02"], ["1.2", "1.20"]], "tips": ["Mass to moles, then moles to atoms."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["180"], ["1.8", "0.0018"], ["1.08"], ["4.33", "4.3"]], "tips": ["Each answer feeds the next one."]}]}, "models": {"1": [["Q1", "If you know the mass of one particle (or the mass of a fixed number of them), the mass of a sample tells you how many particles it contains. Chemists use the mass of one mole: weighing a sample gives the number of moles, and so the number of particles."]], "2": [["Q2", "9.00 ÷ 18.0 = 0.500; 4.40 ÷ 44.0 = 0.100; 117 ÷ 58.5 = 2.00; 4.905 ÷ 98.1 = 0.0500; 6.00 ÷ 12.0 = 0.500; 8.00 ÷ 32.0 = 0.250 mol."], ["Q3", "0.250 × 100.1 = 25.0 g [1]."]], "3": [["Q4", "1.00 mol of molecules: 6.02 × 10²³. 0.500 mol: 3.01 × 10²³. 2.00 mol of H atoms: 1.20 × 10²⁴. 3.00 mol of atoms: 1.81 × 10²⁴. 0.100 mol of Cl⁻: 6.02 × 10²². 22.0 g is 0.500 mol: 3.01 × 10²³."], ["Q5", "Oxygen gas consists of O₂ molecules, so the particle must be stated [1]. One mole of O₂ contains 6.02 × 10²³ molecules, which is 1.20 × 10²⁴ atoms [1]."]], "4": [["Q6", "44.0 ÷ (6.02 × 10²³) [1] = 7.31 × 10⁻²³ g [1]."], ["Q7", "n = 3.94 ÷ 197.0 = 0.0200 mol [1]. Number of atoms = 0.0200 × 6.02 × 10²³ = 1.20 × 10²² [1]."]], "5": [["Q8", "(a) 9 × 12.0 + 8 × 1.0 + 4 × 16.0 = 180.0 [1]. (b) 0.324 ÷ 180.0 = 1.80 × 10⁻³ mol [1]. (c) 1.80 × 10⁻³ × 6.02 × 10²³ = 1.08 × 10²¹ molecules [1]. (d) 4 × 1.08 × 10²¹ = 4.33 × 10²¹ oxygen atoms [1]."]], "6": [["Exit ticket", "A mole is the amount of substance that contains 6.02 × 10²³ particles (the Avogadro constant). Its mass in grams equals the relative atomic, molecular or formula mass."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "A bank counts coins by weighing bags of them. Suggest how the same idea lets chemists count atoms.", "Q2": "What is the amount in moles?", "Q3": "Calculate the mass of 0.250 mol of calcium carbonate, CaCO₃ (M = 100.1 g mol⁻¹).", "Q4": "How many particles? (L = 6.02 × 10²³ mol⁻¹)", "Q5": "Explain what is wrong with the statement: ''one mole of oxygen contains 6.02 × 10²³ atoms''.", "Q6": "Calculate the mass, in g, of one molecule of carbon dioxide (M = 44.0 g mol⁻¹, L = 6.02 × 10²³ mol⁻¹).", "Q7": "A gold ring contains 3.94 g of gold (M = 197.0 g mol⁻¹). Calculate the number of gold atoms in the ring.", "Q8": "A tablet contains 0.324 g of aspirin, C₉H₈O₄. Calculate (a) the relative molecular mass of aspirin, (b) the amount of aspirin in moles, (c) the number of aspirin molecules and (d) the number of oxygen atoms in the tablet. (Ar: H 1.0, C 12.0, O 16.0)"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'd6aa204a-95b4-54c7-b423-083b40772915', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '2.3' limit 1), '2.3 Formulas: Ionic formulas and equations; empirical and molecular formulas; water of crystallisation', 'A Level Chemistry · 2 Atoms, molecules and stoichiometry', '/achem-2-3/', 'ACHEM-2-3', 31, 60, 2030 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-2-3', '2.3 Formulas: Ionic formulas and equations; empirical and molecular formulas; water of crystallisation', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 7, "n": 7, "ans": ["Al₂O₃", "Mg(NO₃)₂", "(NH₄)₂SO₄", "Zn₃(PO₄)₂", "Ag₂CO₃", "Fe(OH)₃", "Ca(HCO₃)₂"], "tip": "Write the two ions with their charges, then balance the charges."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["6", "5", "2", "3", "7"], "tip": "Count each kind of atom on both sides."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["ag aq cl aq", "cl aq ag aq"], ["agcl s"]], "tips": ["A white precipitate of silver chloride forms. Leave out the spectator ions."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 7, "n": 7, "ans": ["CH₂", "CH", "CH₂O", "CH₃", "HO", "P₂O₅", "NO₂"], "tip": "Divide every number by the largest number that goes into all of them."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 3, "pts": [["3.33", "3.3", "40 12", "40.0 12"], ["ch2o"], ["c2h4o2", "ch3cooh"]], "tips": ["Divide each percentage by Ar, then by the smallest answer. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["all the water", "all water", "no more water", "all of the water", "complete", "fully"], ["2.25"], ["0.125", "0.0251", "0.025"], ["x 5", "x is 5", "five", "5h2o", "5 h2o"]], "tips": ["Mass of water = mass lost on heating. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}, {"kind": "text", "id": "q5_1", "q": "Q8", "max": 3, "pts": [["0.04"], ["0.08"], ["ch2"]], "tips": ["Each CO₂ contains one C; each H₂O contains two H. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "The water molecules were part of the crystal structure, held in fixed positions in a fixed ratio (water of crystallisation), not present as liquid water. Heating removes them and leaves the white anhydrous salt."]], "2": [["Q2", "Al³⁺ and O²⁻: Al₂O₃. Mg²⁺ and NO₃⁻: Mg(NO₃)₂. NH₄⁺ and SO₄²⁻: (NH₄)₂SO₄. Zn²⁺ and PO₄³⁻: Zn₃(PO₄)₂. Ag⁺ and CO₃²⁻: Ag₂CO₃. Fe³⁺ and OH⁻: Fe(OH)₃. Ca²⁺ and HCO₃⁻: Ca(HCO₃)₂."]], "3": [["Q3", "6HCl; 5O₂; 2Na; 3CO; 7O₂."], ["Q4", "Ag⁺(aq) + Cl⁻(aq) [1] → AgCl(s) [1]. Na⁺ and NO₃⁻ are spectator ions."]], "4": [["Q5", "CH₂; CH; CH₂O; CH₃; HO; P₂O₅; NO₂."], ["Q6", "C 40.0 ÷ 12.0 = 3.33; H 6.7 ÷ 1.0 = 6.7; O 53.3 ÷ 16.0 = 3.33 [1]. Ratio 1 : 2 : 1, so the empirical formula is CH₂O [1]. Its mass is 30.0 and 60.0 ÷ 30.0 = 2, so the molecular formula is C₂H₄O₂ [1]."]], "5": [["Q7", "(a) To make sure all the water of crystallisation has been removed [1]. (b) Mass of water = 6.25 − 4.00 = 2.25 g [1]. Moles of CuSO₄ = 4.00 ÷ 159.6 = 0.0251; moles of H₂O = 2.25 ÷ 18.0 = 0.125 [1]. Ratio 0.125 ÷ 0.0251 = 5, so x = 5 [1]."], ["Q8", "Moles of CO₂ = 1.76 ÷ 44.0 = 0.0400, so 0.0400 mol of C [1]. Moles of H₂O = 0.720 ÷ 18.0 = 0.0400, so 0.0800 mol of H [1]. Ratio C : H = 1 : 2, so the empirical formula is CH₂ [1]."]], "6": [["Exit ticket", "The empirical formula is the simplest whole-number ratio of the atoms of each element; the molecular formula is the actual number of atoms of each element in one molecule."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q5_1": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Dry blue copper(II) sulfate crystals give off steam when heated and turn white. Suggest where the water was, and why the crystals did not feel wet.", "Q2": "Choose the correct formula.", "Q3": "Find the value of x that balances each equation.", "Q4": "Write the ionic equation, with state symbols, for the reaction between aqueous silver nitrate and aqueous sodium chloride. Type it like this: Ag+(aq) + …", "Q5": "What is the empirical formula?", "Q6": "A compound contains 40.0% carbon, 6.7% hydrogen and 53.3% oxygen by mass. Its relative molecular mass is 60.0. Find its empirical formula and its molecular formula. (Ar: H 1.0, C 12.0, O 16.0)", "Q7": "6.25 g of hydrated copper(II) sulfate, CuSO₄·xH₂O, is heated to constant mass. 4.00 g of anhydrous copper(II) sulfate remains. (a) Explain why the sample is heated to constant mass. (b) Calculate the value of x. (M: CuSO₄ 159.6, H₂O 18.0)", "Q8": "0.560 g of a hydrocarbon burns completely to give 1.76 g of carbon dioxide and 0.720 g of water. Find the empirical formula of the hydrocarbon. (M: CO₂ 44.0, H₂O 18.0)"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'd34ea84b-27b8-591a-b305-30367347df94', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '2.4' limit 1), '2.4 Reacting masses and volumes (of solutions and gases): Mole calculations: reacting masses, percentage yield, limiting reagents, gas volumes and solutions', 'A Level Chemistry · 2 Atoms, molecules and stoichiometry', '/achem-2-4/', 'ACHEM-2-4', 29, 60, 2040 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-2-4', '2.4 Reacting masses and volumes (of solutions and gases): Mole calculations: reacting masses, percentage yield, limiting reagents, gas volumes and solutions', '{"marks": {"2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["0.2"], ["8.06"]], "tips": ["Moles of Mg, ratio 2 : 2, then mass of MgO."]}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 1, "pts": [["85"]], "tips": ["Actual ÷ theoretical × 100."]}, {"kind": "choice", "id": "q2_2", "q": "Q4", "max": 4, "n": 4, "ans": ["H₂", "O₂", "Neither", "O₂"], "tip": "Divide the moles of each reactant by its number in the equation."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 6, "n": 6, "ans": ["12.0 dm³", "48.0 dm³", "2.40 dm³", "6.00 dm³", "12.0 dm³", "1.20 dm³"], "tip": "Moles × 24.0, or use volume ratios for gases."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["x 3", "3 carbon", "c3", "three carbon"], ["c3h8", "propane"]], "tips": ["Volume ratio = mole ratio. Find x from the CO₂, then y from the oxygen. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 6, "n": 6, "ans": ["0.00250 mol", "0.0250 mol", "0.200 mol dm⁻³", "0.500 mol dm⁻³", "4.00 g", "0.100 mol dm⁻³"], "tip": "n = c × V, with V in dm³."}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 3, "pts": [["0.002", "2 10", "2.00 10"], ["0.004", "4 10", "4.00 10"], ["0.16"]], "tips": ["Moles of acid, ratio 2 : 1, then concentration of the alkali."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 3, "pts": [["2.5"], ["1.67", "1.667", "1.66"], ["108"]], "tips": ["Volume to moles of N₂, ratio 3 : 2, then mass."]}, {"kind": "text", "id": "q5_1", "q": "Q10", "max": 2, "pts": [["0.02"], ["1 2", "m2", "two plus", "charge of 2", "group 2", "mco3"]], "tips": ["Find the moles of HCl first. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "Convert the volume of nitrogen to moles, use the 2 : 3 ratio in the equation to find the moles of sodium azide, then multiply by its molar mass to get the mass."]], "2": [["Q2", "Moles of Mg = 4.86 ÷ 24.3 = 0.200 mol; moles of MgO = 0.200 mol [1]. Mass = 0.200 × 40.3 = 8.06 g [1]."], ["Q3", "6.85 ÷ 8.06 × 100 = 85.0% [1]."], ["Q4", "2 mol H₂ needs only 1 mol O₂: H₂ is limiting. 4 mol H₂ needs 2 mol O₂: O₂ is limiting. 3 and 1.5 mol are in the exact ratio. 1.0 g H₂ is 0.50 mol but 1.0 g O₂ is only 0.031 mol: O₂ is limiting."]], "3": [["Q5", "0.500 × 24.0 = 12.0; 2.00 × 24.0 = 48.0; 0.100 mol gives 2.40; volume ratio 1 : 1 gives 6.00; ratio 1 : 2 gives 12.0; 0.0500 mol of Mg gives 0.0500 mol of H₂, 1.20 dm³."], ["Q6", "Ratio hydrocarbon : O₂ : CO₂ = 1 : 5 : 3, so x = 3 [1]. Oxygen: 3 O₂ are used for the CO₂, leaving 2 O₂ for water, which makes 4 H₂O, so y = 8: C₃H₈ [1]."]], "4": [["Q7", "0.100 × 0.0250 = 0.00250 mol; 0.100 × 0.250 = 0.0250 mol; 0.0500 ÷ 0.250 = 0.200; 0.100 mol ÷ 0.200 dm³ = 0.500; 0.100 mol × 40.0 = 4.00 g; 0.0250 mol ÷ 0.250 dm³ = 0.100 mol dm⁻³."], ["Q8", "Moles of H₂SO₄ = 0.100 × 0.0200 = 0.00200 mol [1]. Moles of NaOH = 2 × 0.00200 = 0.00400 mol [1]. Concentration = 0.00400 ÷ 0.0250 = 0.160 mol dm⁻³ [1]."]], "5": [["Q9", "Moles of N₂ = 60.0 ÷ 24.0 = 2.50 mol [1]. Moles of NaN₃ = 2.50 × 2 ÷ 3 = 1.67 mol [1]. Mass = 1.67 × 65.0 = 108 g [1]."], ["Q10", "Moles of HCl = 0.500 × 0.0400 = 0.0200 mol [1]. Ratio carbonate : HCl = 1 : 2, so the equation is MCO₃ + 2HCl → MCl₂ + CO₂ + H₂O and the metal ion is M²⁺ [1]."]], "6": [["Exit ticket", "The limiting reagent is the reactant that is completely used up first. When it has gone the reaction stops, so the amount of product depends only on how much of it there was."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q2_1": "Q3", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q5_1": "Q10", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "An airbag uses the reaction 2NaN₃(s) → 2Na(s) + 3N₂(g). Describe in words how you could work out the mass of sodium azide needed to make 60 dm³ of nitrogen.", "Q2": "Calculate the mass of magnesium oxide formed when 4.86 g of magnesium burns completely: 2Mg + O₂ → 2MgO. (Ar: Mg 24.3, O 16.0)", "Q3": "In the experiment above only 6.85 g of magnesium oxide was collected. Calculate the percentage yield.", "Q4": "For 2H₂ + O₂ → 2H₂O, which reagent is limiting?", "Q5": "What is the volume of gas at room conditions?", "Q6": "10 cm³ of a gaseous hydrocarbon, CxHy, needs 50 cm³ of oxygen for complete combustion and forms 30 cm³ of carbon dioxide (all volumes at the same temperature and pressure). Deduce the formula of the hydrocarbon.", "Q7": "Choose the answer.", "Q8": "25.0 cm³ of aqueous sodium hydroxide is exactly neutralised by 20.0 cm³ of 0.100 mol dm⁻³ sulfuric acid: 2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O. Calculate the concentration of the sodium hydroxide.", "Q9": "An airbag needs 60.0 dm³ of nitrogen at room conditions: 2NaN₃(s) → 2Na(s) + 3N₂(g). Calculate the mass of sodium azide required. (M of NaN₃ = 65.0 g mol⁻¹; molar gas volume 24.0 dm³ mol⁻¹)", "Q10": "0.0100 mol of a metal carbonate reacts exactly with 40.0 cm³ of 0.500 mol dm⁻³ hydrochloric acid. Deduce the mole ratio of carbonate to acid and suggest the charge on the metal ion."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '56cca942-d75a-5da5-bb9b-44b4dfe2f8f4', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '3.1' limit 1), '3.1 Electronegativity and bonding: What electronegativity is, what decides it, its trends, and how it predicts the type of bond', 'A Level Chemistry · 3 Chemical bonding', '/achem-3-1/', 'ACHEM-3-1', 32, 60, 3010 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-3-1', '3.1 Electronegativity and bonding: What electronegativity is, what decides it, its trends, and how it predicts the type of bond', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["O", "F", "Cl", "N", "S", "Na"], "tip": "Up and to the right in the Periodic Table means more electronegative."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["smaller", "fewer shells", "closer", "less distance", "one less shell", "shorter distance"], ["less shield", "fewer inner", "less screening", "shielding is less", "less shielded"], ["stronger attraction", "attract+more", "attract+stronger", "attracted more", "greater attraction", "pull+stronger"]], "tips": ["Radius, shielding, attraction for the bonding electrons."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 7, "n": 7, "ans": ["Ionic", "Non-polar covalent", "Polar covalent", "Ionic", "Polar covalent", "Ionic", "Non-polar covalent"], "tip": "Subtract the two values. Zero, small or large?"}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 6, "n": 6, "ans": ["Cl", "O", "F", "N", "O", "Cl"], "tip": "The more electronegative atom is δ−."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["power", "ability", "tendency"], ["attract+electrons", "attract+electron", "attract+bonding", "attract+shared", "pull+electrons", "attracts+electrons"]], "tips": ["The power of an atom to …"]}, {"kind": "text", "id": "q4_2", "q": "Q7", "max": 3, "pts": [["increase"], ["nuclear charge", "more protons", "number of protons", "proton number"], ["same shell", "similar shielding", "same shielding", "radius decreases", "smaller radius", "shielding stays", "shielding remains", "smaller atom"]], "tips": ["Trend first, then two reasons."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 5, "pts": [["1.8"], ["2.1"], ["mgo", "magnesium oxide", "magnesium"], ["radius", "further", "more shells", "larger atom", "extra shell", "bigger atom"], ["shield"]], "tips": ["(c) think about distance and shielding."]}]}, "models": {"1": [["Q1", "Chlorine attracts the bonding electrons more strongly than hydrogen (it is more electronegative), so the chlorine end becomes slightly negative and the hydrogen end slightly positive."]], "2": [["Q2", "O (further right), F (higher in the group), Cl (further right), N (higher), S (further right), Na (higher in the group)."], ["Q3", "A fluorine atom is smaller, so the bonding electrons are closer to the nucleus [1]. There is less shielding by inner shells [1]. The nucleus therefore has a stronger attraction for the bonding electrons [1]."]], "3": [["Q4", "NaCl 2.3 ionic; Cl₂ 0 non-polar; HCl 1.0 polar covalent; MgO 2.1 ionic; O–H 1.2 polar covalent; KF 3.2 ionic; F₂ 0 non-polar."]], "4": [["Q5", "Cl, O, F, N, O and Cl: in each bond the more electronegative atom attracts the electrons and is δ−."], ["Q6", "The power of an atom [1] to attract the electrons in a bond to itself [1]."], ["Q7", "Electronegativity increases from Na to Cl [1] because the nuclear charge increases [1] while the bonding electrons are in the same shell with similar shielding and the atomic radius decreases [1]."]], "5": [["Q8", "(a) BeO: 3.4 − 1.6 = 1.8 [1]; MgO: 3.4 − 1.3 = 2.1 [1]. (b) Magnesium oxide, because the difference in electronegativity is larger [1]. (c) Down the group the atomic radius increases, so the bonding electrons are further from the nucleus [1], and there is more shielding by inner shells, so the attraction for bonding electrons is weaker [1]."]], "6": [["Exit ticket", "Nuclear charge, atomic radius, and shielding by inner shells and sub-shells."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q4_1": "Q6", "q4_2": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "In a molecule of hydrogen chloride the shared pair of electrons spends more time near the chlorine atom. Suggest why, and what this does to each end of the molecule.", "Q2": "Which atom is more electronegative?", "Q3": "Explain why fluorine is more electronegative than chlorine.", "Q4": "Use the electronegativity values to predict the bonding.", "Q5": "Which atom carries the δ− charge?", "Q6": "Define electronegativity.", "Q7": "State and explain the trend in electronegativity across Period 3 from sodium to chlorine.", "Q8": "Use these values: Be 1.6, Mg 1.3, O 3.4. (a) Calculate the electronegativity difference in beryllium oxide and in magnesium oxide. (b) Predict which oxide is more ionic, giving a reason. (c) Explain why electronegativity decreases down Group 2."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '29ba7b30-207d-5e37-a29b-5bb187c6c179', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '3.2' limit 1), '3.2 Ionic bonding: Defining ionic bonding; sodium chloride, magnesium oxide and calcium fluoride; what makes it strong', 'A Level Chemistry · 3 Chemical bonding', '/achem-3-2/', 'ACHEM-3-2', 27, 60, 3020 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-3-2', '3.2 Ionic bonding: Defining ionic bonding; sodium chloride, magnesium oxide and calcium fluoride; what makes it strong', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Na⁺ and Cl⁻", "Mg²⁺ and O²⁻", "Ca²⁺ and F⁻", "Al³⁺ and O²⁻", "K⁺ and S²⁻"], "tip": "Use the group of each element to find the charge on its ion."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["electrostatic"], ["oppositely charged ions", "opposite charge", "cations and anions", "positive and negative ions", "positive ions and negative ions", "oppositely charged", "anions and cations"]], "tips": ["What kind of attraction, between what?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 7, "n": 7, "ans": ["2", "2", "1", "2", "1s² 2s² 2p⁶", "1s² 2s² 2p⁶", "1s² 2s² 2p⁶ 3s² 3p⁶"], "tip": "Mg is 2.8.2, O is 2.6, Ca is 2.8.8.2, F is 2.7."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 5, "n": 5, "ans": ["MgO", "NaF", "CaO", "LiF", "MgO"], "tip": "Higher charges and smaller ions give stronger attraction."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 3, "pts": [["higher charge", "greater charge", "charges are greater", "double", "larger charge", "more highly charged", "bigger charge", "mg2", "charge of 2"], ["smaller", "ionic radius", "radius"], ["stronger attraction", "stronger electrostatic", "stronger ionic", "more energy", "attract+stronger", "attract+more", "stronger bonding"]], "tips": ["Compare the charges, then the sizes, then the energy needed. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 5, "pts": [["4s2"], ["loses two", "loses 2", "lose two", "lose 2", "gives two", "gives 2", "donates two", "donates 2", "two electrons", "2 electrons"], ["gain", "accept", "receive"], ["charges balance", "neutral", "two fluoride", "2 fluoride", "one electron each", "total charge", "cancel", "two fluorine", "2 fluorine"], ["electrostatic"]], "tips": ["Calcium has two outer electrons; fluorine needs one."]}]}, "models": {"1": [["Q1", "Each sodium atom has lost its outer electron and each chlorine atom has gained one. The ions formed, Na⁺ and Cl⁻, have full outer shells and are strongly attracted to each other, so the compound is much more stable than the separate atoms."]], "2": [["Q2", "NaCl: Na⁺ and Cl⁻. MgO: Mg²⁺ and O²⁻. CaF₂: Ca²⁺ and F⁻. Al₂O₃: Al³⁺ and O²⁻. K₂S: K⁺ and S²⁻."], ["Q3", "The electrostatic attraction [1] between oppositely charged ions (cations and anions) [1]."]], "3": [["Q4", "Mg loses 2 and O gains 2. Each F gains 1, so two F⁻ form for each Ca²⁺. Mg²⁺ and O²⁻ are both 1s² 2s² 2p⁶; Ca²⁺ is 1s² 2s² 2p⁶ 3s² 3p⁶."]], "4": [["Q5", "MgO (2+ and 2− ions); NaF (F⁻ is smaller than Cl⁻); CaO (higher charges); LiF (Li⁺ is smaller than Cs⁺); MgO (Mg²⁺ is smaller than Ba²⁺)."], ["Q6", "The ions in MgO have higher charges (Mg²⁺ and O²⁻ compared with Na⁺ and Cl⁻) [1] and are smaller [1], so the electrostatic attraction is much stronger and more energy is needed to overcome it [1]."]], "5": [["Q7", "(a) 1s² 2s² 2p⁶ 3s² 3p⁶ 4s² [1]. (b) Each calcium atom loses two electrons to form Ca²⁺ [1]; each fluorine atom gains one electron to form F⁻ [1]. (c) Two fluoride ions are needed to balance the charge on one calcium ion, so the compound is neutral [1]. (d) Electrostatic attraction between the oppositely charged ions [1]."]], "6": [["Exit ticket", "The charges on the ions (higher charges attract more strongly) and the sizes of the ions (smaller ions are closer together and attract more strongly)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Sodium atoms and chlorine atoms are both very reactive, but sodium chloride is very stable. Suggest what has changed.", "Q2": "Which ions are present in the compound?", "Q3": "Define ionic bonding.", "Q4": "Complete the description.", "Q5": "Which compound has the stronger ionic bonding?", "Q6": "Explain why magnesium oxide has a much higher melting point than sodium chloride.", "Q7": "Calcium reacts with fluorine to form calcium fluoride. (a) Give the full electronic configuration of a calcium atom (Z = 20). Type it like this: 1s2 2s2 … (b) Describe, in terms of electrons, what happens to the calcium atoms and to the fluorine atoms. (c) Explain why the formula is CaF₂. (d) State what holds the ions together in the solid."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '261c45f6-eff0-5591-8c66-39a5859f7b78', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '3.3' limit 1), '3.3 Metallic bonding: Positive ions and delocalised electrons; explaining the properties of metals', 'A Level Chemistry · 3 Chemical bonding', '/achem-3-3/', 'ACHEM-3-3', 27, 60, 3030 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-3-3', '3.3 Metallic bonding: Positive ions and delocalised electrons; explaining the properties of metals', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["1", "2", "3", "1", "2"], "tip": "The outer-shell electrons become delocalised."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["positive ions", "positive metal ions", "cations", "metal ions"], ["delocalised", "delocalized", "sea of electrons"]], "tips": ["An attraction between which two things?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Delocalised electrons are free to move", "Layers of ions can slide while still attracted to the electrons", "Layers of ions can slide while still attracted to the electrons", "Strong attraction between ions and delocalised electrons", "Delocalised electrons are free to move"], "tip": "Moving charge, sliding layers or strong attraction?"}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["layers", "rows", "planes"], ["slide", "slip", "move over"]], "tips": ["What can the layers of ions do?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["Mg", "Al", "Li", "Na", "Ca"], "tip": "More delocalised electrons, higher charge, smaller ion."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["two delocalised", "2 delocalised", "more delocalised", "more electrons", "two electrons", "twice as many"], ["higher charge", "greater charge", "mg2", "larger charge", "smaller ion", "smaller radius", "charge of 2", "more highly charged", "smaller"], ["stronger attraction", "stronger metallic", "more energy", "attract+stronger", "stronger electrostatic", "stronger bonding"]], "tips": ["Electrons per atom, charge and size of the ion, then the attraction. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 5, "pts": [["positive ions", "cations", "copper ions", "metal ions", "lattice"], ["delocalised", "delocalized", "sea of electrons"], ["free to move", "mobile", "move through", "can move", "carry charge", "carry the current"], ["fixed", "cannot move", "held in", "can not move", "unable to move"], ["no delocalised", "no free electrons", "no mobile", "no charge carriers", "no electrons", "no charged particles"]], "tips": ["(c) what is free to move in each solid?"]}]}, "models": {"1": [["Q1", "Some electrons must be free to move through the solid and carry charge. They are not fixed to particular atoms or bonds: they are delocalised."]], "2": [["Q2", "Na and K give 1 each, Mg and Ca give 2 each, and Al gives 3."], ["Q3", "The electrostatic attraction between positive metal ions [1] and delocalised electrons [1]."]], "3": [["Q4", "Conduction (solid or molten): mobile delocalised electrons. Sheets and wires: layers slide. High melting point: strong attraction throughout the lattice."], ["Q5", "The layers of positive ions [1] can slide over each other without the metallic bonding being broken, because the delocalised electrons still attract the ions [1]."]], "4": [["Q6", "Mg (two delocalised electrons, 2+ ion); Al (three, 3+ ion); Li and Na (smaller ions than K); Ca (two electrons and a 2+ ion)."], ["Q7", "Each magnesium atom gives two delocalised electrons, sodium only one [1]. The Mg²⁺ ion has a higher charge and is smaller than Na⁺ [1]. The attraction between the ions and the delocalised electrons is stronger, so more energy is needed to melt magnesium [1]."]], "5": [["Q8", "(a) A giant lattice of positive copper ions [1] surrounded by delocalised electrons, held together by the attraction between them [1]. (b) The delocalised electrons are free to move through the lattice and carry charge [1]. (c) In solid sodium chloride the ions are held in fixed positions [1] and there are no delocalised electrons, so no charged particles are free to move [1]."]], "6": [["Exit ticket", "The electrostatic attraction between the positive metal ions and the delocalised electrons that move among them."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "A metal conducts electricity when it is solid, without any chemical change. What does this suggest about the electrons inside a metal?", "Q2": "How many delocalised electrons does each atom contribute?", "Q3": "Define metallic bonding.", "Q4": "Which feature of metallic bonding explains the property?", "Q5": "Explain why metals are malleable.", "Q6": "Which metal has the higher melting point?", "Q7": "Explain why magnesium has a higher melting point than sodium.", "Q8": "(a) Describe the bonding and structure in solid copper. (b) Explain why copper conducts electricity. (c) Solid sodium chloride also contains ions but does not conduct. Explain the difference."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'efeb52c2-093b-545a-bcae-28f8304dd326', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '3.4' limit 1), '3.4 Covalent bonding and coordinate (dative covalent) bonding · Lesson 1: Shared pairs, lone pairs, expanded octets and coordinate (dative covalent) bonds', 'A Level Chemistry · 3 Chemical bonding', '/achem-3-4/', 'ACHEM-3-4', 41, 60, 3041 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-3-4', '3.4 Covalent bonding and coordinate (dative covalent) bonding · Lesson 1: Shared pairs, lone pairs, expanded octets and coordinate (dative covalent) bonds', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 7, "n": 7, "ans": ["1", "2", "3", "2", "1", "2", "1"], "tip": "Single, double or triple?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 8, "n": 8, "ans": ["1", "2", "3", "0", "2", "1", "3", "0"], "tip": "Outer electrons minus the electrons used in bonds, divided by two."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["double", "two shared pairs", "2 shared pairs", "two pairs", "2 pairs"], ["single", "one shared pair", "1 shared pair", "one pair", "1 pair"]], "tips": ["Carbon forms four bonds."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 7, "n": 7, "ans": ["8", "8", "6", "6", "10", "10", "12"], "tip": "Count two electrons for each shared pair and for each lone pair."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["period 3", "third shell", "3d", "d orbital", "d sub"], ["period 2", "second shell", "no d", "only eight", "maximum of eight", "cannot expand", "8 electrons", "eight electrons"]], "tips": ["Compare the outer shells of sulfur and oxygen."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["both electrons", "both of the electrons", "both the electrons", "pair from one", "pair comes from", "lone pair"], ["nitrogen", "n atom", "ammonia", "nh3"], ["hydrogen ion", "proton", "h ion"]], "tips": ["Where do the two electrons come from? Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}, {"kind": "choice", "id": "q4_1", "q": "Q8", "max": 6, "n": 6, "ans": ["Yes", "No", "Yes", "No", "Yes", "No"], "tip": "Was one bond formed with both electrons from the same atom?"}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 6, "pts": [["electrostatic", "attraction"], ["shared pair", "shared electrons", "sharing", "nuclei"], ["coordinate", "dative"], ["lone pair", "chlorine", "cl atom"], ["10", "ten"], ["12", "twelve"]], "tips": ["(c) count two electrons for every bond."]}]}, "models": {"1": [["Q1", "The two electrons are shared between the two nuclei, and both nuclei attract the shared pair. Each atom now has a share of two electrons (a full first shell), which is a lower-energy, more stable arrangement."], ["Q2", "Single bonds (H–H, C–H, H–Cl): 1 pair. Double bonds (O=O, C=O, C=C): 2 pairs. The triple bond in N₂: 3 pairs."]], "2": [["Q3", "N in NH₃ 1; O in H₂O 2; Cl in HCl 3; C in CH₄ 0; each O in CO₂ 2; each N in N₂ 1; each Cl in Cl₂ 3; each C in C₂H₄ 0."], ["Q4", "The two carbon atoms share two pairs of electrons (a double bond) [1]. Each carbon atom also shares one pair with each of two hydrogen atoms (single bonds) [1]."]], "3": [["Q5", "CH₄ and NH₃: 8. BF₃ and AlCl₃: 6. PCl₅: 5 bonds, 10. SO₂: two double bonds and a lone pair, 10. SF₆: 6 bonds, 12."], ["Q6", "Sulfur is in Period 3: its outer (third) shell can hold more than eight electrons, using the 3d sub-shell [1]. Oxygen is in Period 2: its second shell can hold only eight electrons, so it cannot expand its octet [1]."]], "4": [["Q7", "A covalent bond in which both electrons of the shared pair come from the same atom [1]. The lone pair on the nitrogen atom of ammonia [1] is shared with a hydrogen ion (a proton), which has no electrons, to form NH₄⁺ [1]."], ["Q8", "NH₄⁺ (N lone pair to H⁺), Al₂Cl₆ (Cl lone pairs to Al) and H₃O⁺ (O lone pair to H⁺) contain coordinate bonds. NH₃, AlCl₃ and CH₄ do not."]], "5": [["Q9", "(a) The electrostatic attraction [1] between the nuclei of two atoms and a shared pair of electrons [1]. (b) A coordinate (dative covalent) bond [1]; a lone pair on a chlorine atom is shared with the aluminium atom of the other unit [1]. (c) 10 electrons around phosphorus [1] and 12 around sulfur [1]."]], "6": [["Exit ticket", "In an ordinary covalent bond each atom provides one electron of the shared pair; in a coordinate bond one atom provides both. After they have formed there is no difference: both are a shared pair attracted by two nuclei."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Two hydrogen atoms each have one electron. Suggest why they are more stable joined together as H₂ than as separate atoms.", "Q2": "How many shared pairs of electrons are there between the two atoms?", "Q3": "How many lone pairs are on the atom named?", "Q4": "Describe the covalent bonding in a molecule of ethene, C₂H₄. State how many pairs of electrons are shared between the two carbon atoms and between each carbon and hydrogen atom.", "Q5": "How many outer-shell electrons surround the central atom in the molecule?", "Q6": "Explain why sulfur can form SF₆ but oxygen cannot form OF₆.", "Q7": "Explain what is meant by a coordinate (dative covalent) bond, using the formation of the ammonium ion as an example.", "Q8": "Does the species contain a coordinate bond?", "Q9": "(a) Define covalent bonding. (b) Aluminium chloride forms Al₂Cl₆ molecules. Name the type of bond that joins the two AlCl₃ units and state which atom provides the electrons. (c) State the number of electrons around the phosphorus atom in PCl₅ and around the sulfur atom in SF₆."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '5ebb451c-4bfe-54a4-bfe6-50d5bff116a4', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '3.4' limit 1), '3.4 Covalent bonding and coordinate (dative covalent) bonding · Lesson 2: σ and π bonds, hybridisation, bond energy and bond length', 'A Level Chemistry · 3 Chemical bonding', '/achem-3-4-2/', 'ACHEM-3-4-2', 32, 60, 3042 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-3-4-2', '3.4 Covalent bonding and coordinate (dative covalent) bonding · Lesson 2: σ and π bonds, hybridisation, bond energy and bond length', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["1 σ and 0 π", "1 σ and 1 π", "1 σ and 2 π", "5 σ and 1 π", "7 σ and 0 π", "2 σ and 2 π"], "tip": "Every bond has one σ. Each extra bond between the same two atoms is a π."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["sideways", "side by side", "sideway", "lateral", "side on"], ["p orbital", "p orbitals", "above and below"]], "tips": ["Which orbitals, overlapping in which direction?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["sp³", "sp³", "sp²", "sp", "sp"], "tip": "Count the σ bonds on the carbon: four, three or two."}, {"kind": "choice", "id": "q3_1", "q": "Q5", "max": 5, "n": 5, "ans": ["109.5°", "120°", "180°", "180°", "109.5°"], "tip": "sp³ 109.5°, sp² 120°, sp 180°."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["C≡C", "C–C", "C–C", "C≡C", "C=C"], "tip": "More shared pairs pull the nuclei closer together."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["triple"], ["strong", "high bond energy", "large amount of energy", "a lot of energy", "lot of energy", "hard to break", "difficult to break", "much energy"]], "tips": ["What must happen to the bond before nitrogen can react?"]}, {"kind": "text", "id": "q4_2", "q": "Q8", "max": 1, "pts": [["nuclei", "internuclear", "nucleus"]], "tips": ["A distance between which two points?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 6, "pts": [["one mole", "1 mole", "1 mol", "per mole"], ["gaseous", "gas"], ["end on", "direct", "head on", "along the axis", "between the nuclei"], ["sideways", "side by side", "lateral", "side on"], ["2 sigma", "two sigma"], ["2 pi", "two pi"]], "tips": ["(c) O=C=O has two double bonds."]}]}, "models": {"1": [["Q1", "The two bonds are different. One is a strong bond like the single bond (a σ bond); the other is a weaker bond formed in a different way (a π bond)."]], "2": [["Q2", "H₂: 1 σ. C=C: 1 σ and 1 π. N₂: 1 σ and 2 π. C₂H₄: four C–H and one C–C σ bonds plus one π. C₂H₆: six C–H and one C–C σ bonds. HCN: H–C σ, C–N σ and two π."], ["Q3", "By the sideways overlap [1] of adjacent p orbitals, above and below the σ bond [1]."]], "3": [["Q4", "Four σ bonds: sp³ (CH₄, C₂H₆). Three σ bonds and one π: sp² (C₂H₄). Two σ bonds and two π: sp (HCN, CO₂)."], ["Q5", "sp³ carbons (ethane, CH₄): 109.5°. sp² carbon (ethene): 120°. sp carbons (HCN, CO₂): 180°."]], "4": [["Q6", "C≡C is the shortest and strongest (one σ, two π). C–C is the longest and weakest. C=C has one σ and one π bond."], ["Q7", "The two nitrogen atoms are joined by a triple bond [1], which is very strong, so a large amount of energy is needed to break it before nitrogen can react [1]."], ["Q8", "The distance between the nuclei of two covalently bonded atoms [1]."]], "5": [["Q9", "(a) The energy required to break one mole of a particular covalent bond [1] in the gaseous state [1]. (b) A σ bond is formed by the direct, end-on overlap of orbitals between the two atoms [1]; a π bond is formed by the sideways overlap of adjacent p orbitals, above and below the σ bond [1]. (c) 2 sigma bonds [1] and 2 pi bonds [1]."]], "6": [["Exit ticket", "A double bond is one σ bond and one π bond. The π bond, formed by sideways overlap, is weaker than the σ bond, so the total is less than twice the single bond."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q4_1": "Q7", "q4_2": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "The second bond in C=C adds only 260 kJ mol⁻¹, much less than the 350 kJ mol⁻¹ of the first bond. Suggest what this tells you about the two bonds in a double bond.", "Q2": "How many σ and π bonds are there?", "Q3": "Describe how a π bond is formed.", "Q4": "What is the hybridisation of the carbon atom?", "Q5": "What is the bond angle around the carbon atom?", "Q6": "Which carbon–carbon bond fits the description?", "Q7": "The bond energy of N≡N is 944 kJ mol⁻¹. Explain why nitrogen gas is very unreactive.", "Q8": "Define bond length.", "Q9": "(a) Define bond energy. (b) Describe how a σ bond and a π bond are formed. (c) State the number of σ bonds and the number of π bonds in a molecule of carbon dioxide (write sigma and pi in words)."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '07154077-11a1-59fb-93df-c14a729198e2', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '3.5' limit 1), '3.5 Shapes of molecules: Electron-pair repulsion: predicting the shapes and bond angles of molecules and ions', 'A Level Chemistry · 3 Chemical bonding', '/achem-3-5/', 'ACHEM-3-5', 34, 60, 3050 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-3-5', '3.5 Shapes of molecules: Electron-pair repulsion: predicting the shapes and bond angles of molecules and ions', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 7, "n": 7, "ans": ["Linear", "Trigonal planar", "Tetrahedral", "Trigonal bipyramidal", "Octahedral", "Tetrahedral", "Linear"], "tip": "Count the regions of electrons around the central atom."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 8, "n": 8, "ans": ["109.5°", "107°", "104.5°", "120°", "180°", "90°", "109.5°", "107°"], "tip": "Start from the angle for the number of electron pairs, then take off about 2.5° for each lone pair."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["lone pair"], ["repel+more", "repels+more", "greater repulsion", "more repulsion", "stronger repulsion", "repel+strongly", "repels+strongly", "repels+stronger"]], "tips": ["What does ammonia have that methane does not?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 8, "n": 8, "ans": ["Pyramidal", "Non-linear", "Trigonal planar", "Tetrahedral", "Linear", "Trigonal bipyramidal", "Trigonal planar", "Non-linear"], "tip": "Find a molecule you know with the same numbers of bonding pairs and lone pairs."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 3, "pts": [["pyramidal", "pyramid"], ["107"], ["three bonding", "3 bonding", "one lone", "1 lone", "lone pair"]], "tips": ["Oxygen has six outer electrons; take one off for the positive charge."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 6, "pts": [["trigonal planar", "planar"], ["120"], ["pyramidal", "pyramid"], ["107"], ["lone pair"], ["109", "tetrahedral", "four bonding", "4 bonding"]], "tips": ["(c) how many bonding pairs does boron have in the product? Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "Two balloons point in opposite directions (a line), three lie flat at 120° (a triangle) and four point to the corners of a tetrahedron. They push each other as far apart as possible, just as electron pairs repel each other."]], "2": [["Q2", "CO₂ and BeCl₂: 2 regions, linear. BF₃: 3, trigonal planar. CH₄ and NH₄⁺: 4, tetrahedral. PF₅: 5, trigonal bipyramidal. SF₆: 6, octahedral."]], "3": [["Q3", "CH₄ and NH₄⁺ 109.5°; NH₃ and H₃O⁺ 107° (one lone pair); H₂O 104.5° (two lone pairs); BF₃ 120°; CO₂ 180°; SF₆ 90°."], ["Q4", "Ammonia has a lone pair on the nitrogen atom; methane has only bonding pairs [1]. A lone pair repels more strongly than a bonding pair, so the bonding pairs are pushed closer together [1]."]], "4": [["Q5", "PH₃ like NH₃: pyramidal. H₂S and NH₂⁻ like H₂O: non-linear. BCl₃ and AlCl₃ like BF₃: trigonal planar. CCl₄ like CH₄: tetrahedral. CS₂ like CO₂: linear. PCl₅ like PF₅: trigonal bipyramidal."], ["Q6", "Pyramidal [1], with a bond angle of about 107° [1], because there are three bonding pairs and one lone pair around the oxygen atom, as in ammonia [1]."]], "5": [["Q7", "(a) BF₃ is trigonal planar [1], 120° [1]; NH₃ is pyramidal [1], 107° [1]. (b) Boron has three bonding pairs and no lone pair; nitrogen has three bonding pairs and one lone pair, which repels the bonding pairs [1]. (c) Boron now has four bonding pairs, so the arrangement around it is tetrahedral and the angle is about 109.5° [1]."]], "6": [["Exit ticket", "Lone pair–lone pair, then lone pair–bonding pair, then bonding pair–bonding pair."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Tie two, three or four balloons together at their necks. What shapes do they make, and how is this like the electron pairs around an atom?", "Q2": "What is the shape?", "Q3": "What is the bond angle?", "Q4": "Explain why the bond angle in ammonia (107°) is smaller than the bond angle in methane (109.5°).", "Q5": "Predict the shape.", "Q6": "Predict the shape and the bond angle of the H₃O⁺ ion, and explain your answer.", "Q7": "(a) State the shape and bond angle of BF₃ and of NH₃. (b) Explain why these molecules have different shapes although each has three bonds. (c) BF₃ reacts with NH₃ to form F₃B–NH₃. Predict the F–B–F bond angle in the product."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '7446cfd5-2534-5d49-aba3-be723b076977', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '3.6' limit 1), '3.6 Intermolecular forces, electronegativity and bond properties: Polar molecules, van der Waals'' forces, hydrogen bonding and the unusual properties of water', 'A Level Chemistry · 3 Chemical bonding', '/achem-3-6/', 'ACHEM-3-6', 36, 60, 3060 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-3-6', '3.6 Intermolecular forces, electronegativity and bond properties: Polar molecules, van der Waals'' forces, hydrogen bonding and the unusual properties of water', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Intermolecular forces", "Covalent bonds", "Intermolecular forces", "Covalent bonds", "Intermolecular forces"], "tip": "A change of state keeps the molecules whole."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 8, "n": 8, "ans": ["Polar", "Non-polar", "Polar", "Non-polar", "Polar", "Non-polar", "Polar", "Non-polar"], "tip": "Polar bonds and a shape in which they do not cancel."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["linear", "symmetr", "180"], ["cancel"]], "tips": ["Think about the shape."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 8, "n": 8, "ans": ["Instantaneous dipole–induced dipole only", "Permanent dipole–permanent dipole", "Hydrogen bonding", "Instantaneous dipole–induced dipole only", "Hydrogen bonding", "Permanent dipole–permanent dipole", "Hydrogen bonding", "Instantaneous dipole–induced dipole only"], "tip": "Non-polar: id–id only. Polar: pd–pd. N–H or O–H: hydrogen bonding."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["more electrons", "number of electrons increases", "greater number of electrons", "larger electron cloud", "increasing number of electrons"], ["instantaneous", "induced", "london", "dispersion", "id id", "van der waals", "temporary"], ["stronger", "more energy", "greater"]], "tips": ["Electrons, type of force, energy."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["electronegative", "polar", "delta", "partial", "slightly positive"], ["lone pair"], ["attract"]], "tips": ["Polarity of O–H, the lone pair, then the attraction."]}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 2, "pts": [["hydrogen bond"], ["open", "further apart", "lattice", "more space", "spaced", "fixed positions", "tetrahedral", "held apart"]], "tips": ["How are the molecules arranged in ice?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 5, "pts": [["more electrons", "number of electrons", "larger molecule", "bigger electron", "greater number of electrons"], ["instantaneous", "induced", "london", "dispersion", "id id", "van der waals"], ["hydrogen bond"], ["more energy", "stronger", "harder to overcome"], ["covalent", "o h bond", "bond inside"]], "tips": ["(a) electrons and id–id forces. (b) a stronger intermolecular force."]}]}, "models": {"1": [["Q1", "The forces between water molecules must be much stronger than the forces between methane molecules, so much more energy is needed to separate them."], ["Q2", "Changes of state (boiling, subliming, melting) overcome intermolecular forces. Chemical reactions (splitting water, burning methane) break covalent bonds."]], "2": [["Q3", "Polar: HCl, H₂O, NH₃, CH₃Cl. Non-polar: CO₂, CCl₄ and BF₃ (symmetrical, dipoles cancel) and Cl₂ (no difference in electronegativity)."], ["Q4", "The molecule is linear and symmetrical [1], so the two equal bond dipoles point in opposite directions and cancel [1]."]], "3": [["Q5", "Non-polar molecules (CH₄, I₂, CO₂): id–id only. Polar molecules without N–H or O–H (HCl, CH₃Cl): pd–pd. Molecules with O–H or N–H (H₂O, NH₃, C₂H₅OH): hydrogen bonding."], ["Q6", "The molecules have more electrons from Cl₂ to I₂ [1], so the instantaneous dipole–induced dipole forces between them [1] are stronger and more energy is needed to overcome them [1]."]], "4": [["Q7", "Oxygen is much more electronegative than hydrogen, so the O–H bond is polar and the hydrogen atom is δ+ [1]. A lone pair on the oxygen atom of another molecule [1] is attracted to this δ+ hydrogen atom [1]."], ["Q8", "In ice each water molecule is held by hydrogen bonds to four others [1] in a fixed, open lattice, so the molecules are further apart than in liquid water [1]."]], "5": [["Q9", "(a) From H₂S to H₂Te the molecules have more electrons [1], so the instantaneous dipole–induced dipole forces are stronger [1]. (b) Water molecules form hydrogen bonds with each other [1], which are much stronger than the other intermolecular forces, so more energy is needed to separate the molecules [1]. (c) The covalent O–H bond inside the molecule is much stronger [1]."]], "6": [["Exit ticket", "Instantaneous dipole–induced dipole forces, then permanent dipole–permanent dipole forces, then hydrogen bonds."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Methane and water have molecules of almost the same mass, but water boils 262 °C higher. What must be different?", "Q2": "What is broken or overcome?", "Q3": "Is the molecule polar or non-polar?", "Q4": "Explain why carbon dioxide is a non-polar molecule although each C=O bond is polar.", "Q5": "What is the strongest type of intermolecular force between molecules of the substance?", "Q6": "Explain why the boiling points of the halogens increase from chlorine to iodine.", "Q7": "Describe how a hydrogen bond forms between two water molecules.", "Q8": "Explain why ice is less dense than liquid water.", "Q9": "Use the boiling points in the note above. (a) Explain why the boiling point increases from H₂S to H₂Te. (b) Explain why water has a much higher boiling point than the trend predicts. (c) State which is stronger: a hydrogen bond between two water molecules or an O–H bond inside a water molecule."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'cc90ff9a-2e12-5b76-a004-52daacdc07ac', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '3.7' limit 1), '3.7 Dot-and-cross diagrams: Drawing ionic, covalent and coordinate bonding, including expanded octets and odd-electron species', 'A Level Chemistry · 3 Chemical bonding', '/achem-3-7/', 'ACHEM-3-7', 31, 60, 3070 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-3-7', '3.7 Dot-and-cross diagrams: Drawing ionic, covalent and coordinate bonding, including expanded octets and odd-electron species', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 7, "n": 7, "ans": ["2 bonding pairs, 2 lone pairs", "3 bonding pairs, 1 lone pair", "4 bonding pairs, 0 lone pairs", "3 bonding pairs, 0 lone pairs", "4 bonding pairs (two double bonds), 0 lone pairs", "5 bonding pairs, 0 lone pairs", "6 bonding pairs, 0 lone pairs"], "tip": "Outer electrons of the central atom: some are shared, the rest are lone pairs."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["three shared", "3 shared", "triple", "three pairs", "3 pairs", "six shared electrons", "6 shared"], ["one lone", "1 lone", "lone pair on each", "a lone pair"]], "tips": ["Each nitrogen atom has five outer electrons."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 7, "n": 7, "ans": ["8", "1", "8", "2", "2", "2−", "1−"], "tip": "The negative ion has a full outer shell; the transferred electrons use the other symbol."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 8, "n": 8, "ans": ["8", "8", "8", "8", "10", "11", "16", "18"], "tip": "Add the outer electrons of every atom, then adjust for any charge."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["both electrons", "same symbol", "two dots", "two crosses", "both dots", "both crosses", "same atom", "from nitrogen"], ["bracket", "outside", "top right"]], "tips": ["Where did both electrons of that bond come from?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 5, "pts": [["6 electrons", "six", "6"], ["coordinate", "dative"], ["lone pair", "both electrons", "same symbol", "from chlorine", "from the chlorine"], ["8", "eight"], ["12", "twelve"]], "tips": ["Aluminium has three outer electrons and forms three bonds in AlCl₃."]}]}, "models": {"1": [["Q1", "Oxygen in the middle with two hydrogen atoms. Each O–H bond is a shared pair: one dot (from hydrogen) and one cross (from oxygen). The oxygen atom also has two lone pairs, four crosses not shared with anything, making eight electrons around oxygen."]], "2": [["Q2", "H₂O 2 and 2; NH₃ 3 and 1; CH₄ 4 and 0; BF₃ 3 and 0 (only six electrons around boron); CO₂ two double bonds; PCl₅ five bonding pairs; SF₆ six bonding pairs."], ["Q3", "Three shared pairs between the two atoms (a triple bond) [1], and one lone pair on each nitrogen atom [1]."]], "3": [["Q4", "Cl⁻: 8 outer electrons, 1 from sodium. O²⁻: 8 outer electrons, 2 from magnesium. CaF₂: two F⁻ for each Ca²⁺. Charges: O²⁻ is 2−, F⁻ is 1−."]], "4": [["Q5", "H₂O 6 + 2 = 8; NH₃ 5 + 3 = 8; CH₄ 4 + 4 = 8; NH₄⁺ 5 + 4 − 1 = 8; N₂ 5 + 5 = 10; NO 5 + 6 = 11; CO₂ 4 + 12 = 16; SO₂ 6 + 12 = 18."], ["Q6", "In the coordinate bond both electrons have the same symbol, because both come from the nitrogen atom [1]. The whole ion is drawn in square brackets with the + charge outside [1]."]], "5": [["Q7", "(a) 6 electrons [1]. (b) A coordinate (dative covalent) bond [1], drawn as a shared pair in which both electrons come from a lone pair on a chlorine atom, so both have the same symbol [1]. (c) 8 electrons [1]. (d) 12 electrons [1]."]], "6": [["Exit ticket", "Check that the total number of electrons shown equals the outer electrons of all the atoms (adjusted for any charge), and check that ions are in brackets with their charges."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Draw in your book what you think the outer electrons look like in a molecule of water. Describe your drawing in words here.", "Q2": "What surrounds the central atom in the dot-and-cross diagram?", "Q3": "Describe the dot-and-cross diagram of a nitrogen molecule, N₂. State the number of shared pairs and the number of lone pairs on each atom.", "Q4": "Complete the description of the dot-and-cross diagram.", "Q5": "What is the total number of outer-shell electrons shown in the diagram?", "Q6": "In a dot-and-cross diagram of the ammonium ion, NH₄⁺, how is the coordinate bond shown differently from the other three bonds, and how is the charge shown?", "Q7": "Aluminium chloride exists as Al₂Cl₆ molecules at low temperatures. (a) How many outer-shell electrons surround the aluminium atom in a separate AlCl₃ molecule? (b) Name the type of bond that joins the two AlCl₃ units, and state how it is shown in a dot-and-cross diagram. (c) How many electrons surround each aluminium atom in Al₂Cl₆? (d) How many electrons surround the sulfur atom in SF₆?"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '1fccf9c9-9962-5f10-aeea-b733822de89c', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '4.1' limit 1), '4.1 The gaseous state: ideal and real gases and pV = nRT: Where gas pressure comes from, what makes a gas ideal, and calculations with pV = nRT', 'A Level Chemistry · 4 States of matter', '/achem-4-1/', 'ACHEM-4-1', 34, 60, 4010 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-4-1', '4.1 The gaseous state: ideal and real gases and pV = nRT: Where gas pressure comes from, what makes a gas ideal, and calculations with pV = nRT', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["Increases", "Increases", "Decreases", "Decreases"], "tip": "More frequent collisions with the walls means a higher pressure."}, {"kind": "text", "id": "q1_2", "q": "Q3", "max": 2, "pts": [["collide", "collision", "hit", "strike", "bombard"], ["wall", "force"]], "tips": ["What do the moving molecules do?"]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Ideal gas only", "Real gases only", "Both", "Ideal gas only", "Real gases only"], "tip": "The ideal gas is a model with no particle volume and no attractions."}, {"kind": "text", "id": "q2_1", "q": "Q5", "max": 3, "pts": [["high temperature"], ["low pressure"], ["far apart", "negligible", "forces are small", "weak", "little attraction", "overcome", "insignificant"]], "tips": ["When are the particles far apart and moving fast?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q6", "max": 6, "n": 6, "ans": ["298 K", "373 K", "1.00 × 10⁻³ m³", "2.50 × 10⁻⁴ m³", "2.4 × 10⁻² m³", "1.01 × 10⁵ Pa"], "tip": "Add 273 for kelvin. dm³ × 10⁻³ and cm³ × 10⁻⁶ give m³."}, {"kind": "text", "id": "q3_1", "q": "Q7", "max": 2, "pts": [["0.0123", "0.01226", "1.23 10", "1.226 10", "0.012"], ["12.3", "12.26", "12.2"]], "tips": ["V = nRT ÷ p gives m³. Multiply by 1000 for dm³."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q8", "max": 3, "pts": [["pv rt", "pv/rt", "8.31 300", "2493"], ["0.00802", "8.02 10", "0.0080", "8.0 10"], ["39.9", "39.89", "40"]], "tips": ["Find n from pV ÷ RT, then divide the mass by n."]}, {"kind": "text", "id": "q4_1", "q": "Q9", "max": 3, "pts": [["7.65 10", "76.5 10", "0.0000765"], ["0.00249", "2.49 10", "0.0025"], ["74.2", "74.1", "74"]], "tips": ["Convert cm³ to m³ first."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q10", "max": 6, "pts": [["zero volume", "no volume", "negligible volume"], ["no intermolecular", "no forces", "no attraction", "no attractive"], ["hydrogen bond", "stronger intermolecular", "stronger forces", "polar", "stronger attraction"], ["0.5"], ["300"], ["249", "2.49 10"]], "tips": ["(c) moles of helium, kelvin, m³, then p = nRT ÷ V."]}]}, "models": {"1": [["Q1", "The molecules gain kinetic energy and move faster. They hit the walls more often and with more force, so the pressure increases."], ["Q2", "More gas or a higher temperature: more frequent (and harder) collisions, pressure increases. A larger volume or less gas: fewer collisions on each area of wall, pressure decreases."], ["Q3", "The gas molecules are in constant random motion and collide with the walls of the container [1]. Each collision exerts a force on the wall, and the force on each unit area is the pressure [1]."]], "2": [["Q4", "Zero particle volume and exact obedience of pV = nRT: ideal gas only. Attractive forces and liquefying: real gases only. Constant random motion: both."], ["Q5", "High temperature [1] and low pressure [1]. The particles are far apart and have high kinetic energy, so their own volume and the intermolecular forces between them are negligible [1]."]], "3": [["Q6", "25 °C = 298 K; 100 °C = 373 K; 1.00 dm³ = 1.00 × 10⁻³ m³; 250 cm³ = 2.50 × 10⁻⁴ m³; 24 dm³ = 2.4 × 10⁻² m³; 101 kPa = 1.01 × 10⁵ Pa."], ["Q7", "V = nRT ÷ p = (0.500 × 8.31 × 298) ÷ (1.01 × 10⁵) = 0.0123 m³ [1] = 12.3 dm³ [1]."]], "4": [["Q8", "n = pV ÷ RT = (1.00 × 10⁵ × 2.00 × 10⁻⁴) ÷ (8.31 × 300) [1] = 0.00802 mol [1]. Mr = 0.320 ÷ 0.00802 = 39.9 [1]."], ["Q9", "V = 76.5 cm³ = 7.65 × 10⁻⁵ m³ [1]. n = (1.01 × 10⁵ × 7.65 × 10⁻⁵) ÷ (8.31 × 373) = 0.00249 mol [1]. Mr = 0.185 ÷ 0.00249 = 74.2 [1]."]], "5": [["Q10", "(a) The particles have zero volume [1] and there are no intermolecular forces of attraction between them [1]. (b) Ammonia molecules are polar and form hydrogen bonds, so the forces between them are much stronger than between nitrogen molecules [1]. (c) n = 2.00 ÷ 4.0 = 0.500 mol [1]; T = 300 K and V = 5.00 × 10⁻³ m³ [1]; p = (0.500 × 8.31 × 300) ÷ (5.00 × 10⁻³) = 249 000 Pa = 249 kPa [1]."]], "6": [["Exit ticket", "The volume of the particles themselves, and the intermolecular forces of attraction between them."]]}, "labels": {"q1_0": "Q1", "q1_2": "Q3", "q2_1": "Q5", "q3_1": "Q7", "q4_0": "Q8", "q4_1": "Q9", "q5_0": "Q10", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "A sealed can of air is heated. The can does not change size, but the pressure inside rises. Suggest why, in terms of the molecules.", "Q2": "What happens to the pressure, if nothing else changes?", "Q3": "Explain how a gas exerts a pressure on the walls of its container.", "Q4": "Is the statement true for an ideal gas, for real gases, or for both?", "Q5": "State and explain the conditions of temperature and pressure under which a real gas behaves most like an ideal gas.", "Q6": "Convert to the units used in pV = nRT.", "Q7": "Calculate the volume, in dm³, occupied by 0.500 mol of an ideal gas at 298 K and 1.01 × 10⁵ Pa. (R = 8.31 J K⁻¹ mol⁻¹)", "Q8": "0.320 g of a gas occupies 2.00 × 10⁻⁴ m³ at 300 K and 1.00 × 10⁵ Pa. Calculate the relative molecular mass of the gas. (R = 8.31 J K⁻¹ mol⁻¹)", "Q9": "0.185 g of a volatile liquid is vaporised at 373 K and 1.01 × 10⁵ Pa. The vapour occupies 76.5 cm³. Calculate the relative molecular mass of the liquid.", "Q10": "(a) State two assumptions of the ideal gas model. (b) At room temperature ammonia deviates from ideal behaviour more than nitrogen does. Suggest why. (c) Calculate the pressure, in kPa, of 2.00 g of helium (Ar = 4.0) in a 5.00 dm³ container at 27 °C. (R = 8.31 J K⁻¹ mol⁻¹)"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '0e109106-8397-5692-a6c5-b377a198eacc', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '4.2' limit 1), '4.2 Bonding and structure: Giant ionic, simple molecular, giant molecular and giant metallic lattices, and the properties they give', 'A Level Chemistry · 4 States of matter', '/achem-4-2/', 'ACHEM-4-2', 44, 60, 4020 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-4-2', '4.2 Bonding and structure: Giant ionic, simple molecular, giant molecular and giant metallic lattices, and the properties they give', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 9, "n": 9, "ans": ["Giant ionic", "Giant ionic", "Simple molecular", "Simple molecular", "Simple molecular", "Giant molecular", "Giant molecular", "Giant molecular", "Giant metallic"], "tip": "Metal with non-metal: ionic. Small molecules: simple molecular. Atoms bonded throughout: giant molecular. Metal: metallic."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["No", "Yes", "Yes", "Yes", "Yes", "No"], "tip": "Are there charged particles that are free to move?"}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["fixed", "cannot move", "held in", "can not move", "unable to move", "locked"], ["free to move", "mobile", "can move", "are able to move", "move freely"]], "tips": ["What can the ions do in each state?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 7, "n": 7, "ans": ["Weak intermolecular forces", "Weak intermolecular forces", "Weak intermolecular forces", "Strong covalent bonds", "Strong covalent bonds", "Strong ionic bonding", "Strong metallic bonding"], "tip": "What are the particles in the lattice, and what holds them together?"}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["intermolecular", "van der waals", "between molecules", "between the molecules", "london", "induced dipole"], ["weak", "little energy", "not much energy", "covalent bonds are not broken", "easily overcome"]], "tips": ["Which forces are overcome when iodine melts?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 7, "n": 7, "ans": ["Diamond", "Graphite", "Graphite", "Both", "Graphite", "Graphite", "Diamond"], "tip": "Four bonds or three? What happens to the fourth electron?"}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 3, "pts": [["three bonds", "3 bonds", "three covalent", "three other", "3 other", "bonded to three", "bonded to 3"], ["delocalised", "delocalized", "free electron"], ["four bonds", "4 bonds", "four covalent", "four other", "4 other", "bonded to four", "bonded to 4", "all four", "no delocalised", "no free electrons", "all the outer electrons"]], "tips": ["Count the bonds each carbon atom forms in each structure."]}], "5": [{"kind": "choice", "id": "q5_0", "q": "Q9", "max": 4, "n": 4, "ans": ["Giant ionic", "Simple molecular", "Giant metallic", "Giant molecular"], "tip": "Start with conductivity, then the melting point."}, {"kind": "text", "id": "q5_1", "q": "Q10", "max": 4, "pts": [["simple molecular", "molecules", "molecular"], ["intermolecular", "van der waals", "weak forces", "between the molecules", "between molecules"], ["giant"], ["strong covalent", "many covalent", "covalent bonds must", "break covalent", "breaking covalent", "covalent bonds have to", "covalent bonds are broken", "covalent bonds need"]], "tips": ["What are the particles in each lattice?"]}]}, "models": {"1": [["Q1", "The atoms are bonded and arranged differently. In diamond every atom is held by strong bonds in all directions; in graphite the atoms form flat layers that can slide, with some electrons free to move."], ["Q2", "Giant ionic: NaCl, MgO. Simple molecular: I₂, ice, C₆₀. Giant molecular: SiO₂, diamond, graphite. Giant metallic: copper."]], "2": [["Q3", "Solid ionic compounds do not conduct: the ions are fixed. Molten or dissolved, the ions can move. Copper conducts in both states because of its delocalised electrons."], ["Q4", "In the solid the ions are held in fixed positions in the lattice [1]. When molten the ions are free to move and carry charge [1]."]], "3": [["Q5", "Molecular solids (I₂, ice, C₆₀): intermolecular forces. Giant molecular solids (diamond, SiO₂): covalent bonds. MgO: ionic bonding. Copper: metallic bonding."], ["Q6", "Melting only overcomes the intermolecular forces between the I₂ molecules [1]. These are weak, so little energy is needed; the covalent bonds are not broken [1]."]], "4": [["Q7", "Diamond: four bonds per atom, very hard. Graphite: three bonds per atom, delocalised electrons, conducts, layers slide. Both have very high melting points because many strong covalent bonds must be broken."], ["Q8", "In graphite each carbon atom is bonded to three others [1], so one outer electron per atom is delocalised and free to move along the layers [1]. In diamond each carbon atom is bonded to four others, so all the outer electrons are used in bonds and none are free to move [1]."]], "5": [["Q9", "A conducts only when molten: giant ionic. B has a low melting point and never conducts: simple molecular. C conducts when solid: giant metallic. D has a very high melting point and never conducts: giant molecular."], ["Q10", "C₆₀ has a simple molecular lattice of separate C₆₀ molecules [1] held together by weak intermolecular forces, which need little energy to overcome and allow solvent molecules to separate them [1]. Diamond has a giant molecular lattice [1] in which every atom is held by strong covalent bonds, and many of these covalent bonds must be broken to melt or dissolve it [1]."]], "6": [["Exit ticket", "Giant ionic. The very high melting point shows strong bonding throughout a giant lattice, and conducting only when molten shows it contains ions that are fixed in the solid but free to move in the liquid."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_1": "Q8", "q5_1": "Q10", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Diamond and graphite contain exactly the same atoms. Suggest how they can have such different properties.", "Q2": "Which type of lattice does the solid have?", "Q3": "Does it conduct electricity?", "Q4": "Explain why sodium chloride conducts electricity when molten but not when solid.", "Q5": "What must be overcome or broken to melt the solid?", "Q6": "Explain why iodine has a low melting point although the covalent bond in an I₂ molecule is strong.", "Q7": "Is the statement true for diamond, for graphite, or for both?", "Q8": "Explain why graphite conducts electricity but diamond does not.", "Q9": "Use the data in the notes above to deduce the structure of each solid.", "Q10": "Buckminsterfullerene, C₆₀, and diamond are both forms of carbon. C₆₀ sublimes at about 600 °C and dissolves in some organic solvents. Diamond melts above 3500 °C and is insoluble. Explain these differences in terms of structure and bonding."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '2f73a00d-31f9-59b2-a2d1-5ad21b695cc2', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '5.1' limit 1), '5.1 Enthalpy change, ΔH · Lesson 1: Exothermic and endothermic reactions, reaction pathway diagrams and standard enthalpy changes', 'A Level Chemistry · 5 Chemical energetics', '/achem-5-1-1/', 'ACHEM-5-1-1', 32, 60, 5011 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-5-1-1', '5.1 Enthalpy change, ΔH · Lesson 1: Exothermic and endothermic reactions, reaction pathway diagrams and standard enthalpy changes', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["Exothermic", "Endothermic", "Exothermic", "Endothermic", "Exothermic", "Endothermic"], "tip": "Energy out: exothermic, ΔH negative."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 3, "pts": [["below", "lower"], ["peak", "hump", "barrier", "maximum", "top of the curve", "rises", "above the reactants"], ["200"]], "tips": ["Reverse reaction: climb from the products to the top of the curve."]}, {"kind": "choice", "id": "q2_1", "q": "Q4", "max": 5, "n": 5, "ans": ["Exothermic", "+50 kJ mol⁻¹", "−100 kJ mol⁻¹", "+150 kJ mol⁻¹", "Endothermic"], "tip": "Activation energy = peak − reactants. ΔH = products − reactants."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Combustion", "Formation", "Neutralisation", "Formation", "Combustion"], "tip": "One mole formed from elements, one mole burned, or one mole of water formed?"}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["one mole", "1 mole", "1 mol"], ["elements"]], "tips": ["How much is formed, and from what?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 5, "n": 5, "ans": ["H₂(g) + ½O₂(g) → H₂O(l)", "C(s) + 2H₂(g) → CH₄(g)", "C₃H₈(g) + 5O₂(g) → 3CO₂(g) + 4H₂O(l)", "½N₂(g) + 1½H₂(g) → NH₃(g)", "H₂(g) + ½O₂(g) → H₂O(l)"], "tip": "Formation: one mole of product. Combustion: one mole of fuel."}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 1, "pts": [["element", "already", "standard state", "no change", "itself"]], "tips": ["What would the equation be?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 5, "pts": [["one mole", "1 mole", "1 mol"], ["complete", "excess oxygen", "burned in oxygen", "burnt in oxygen", "burns in oxygen", "in oxygen"], ["298"], ["101", "100 kpa", "1 atm"], ["lower", "less", "rises", "increases", "hotter", "warmer"]], "tips": ["(c) exothermic: where does the energy go?"]}]}, "models": {"1": [["Q1", "The reaction is endothermic: it takes in energy from the surroundings, including your hand. The energy is now stored in the products, which have more enthalpy than the reactants."], ["Q2", "Combustion and neutralisation are exothermic, as is any reaction with a negative ΔH. Photosynthesis and thermal decomposition are endothermic, as is any reaction that cools its surroundings."]], "2": [["Q3", "The products are 120 kJ mol⁻¹ lower than the reactants [1]. The curve rises to a peak 80 kJ mol⁻¹ above the reactants before falling to the products [1]. Reverse activation energy = 80 + 120 = 200 kJ mol⁻¹ [1]."], ["Q4", "Products below reactants: exothermic. Activation energy 250 − 200 = +50. ΔH = 100 − 200 = −100. Reverse activation energy 250 − 100 = +150. Products above reactants: endothermic."]], "3": [["Q5", "One mole of methane or ethanol burned: combustion. One mole of ethanol or sodium chloride formed from its elements: formation. One mole of water formed from acid and alkali: neutralisation."], ["Q6", "The enthalpy change when one mole of a compound is formed [1] from its elements in their standard states under standard conditions [1]."]], "4": [["Q7", "Water: H₂ + ½O₂ → H₂O (this is also the combustion of hydrogen). Methane: C(s) + 2H₂ → CH₄. Propane: C₃H₈ + 5O₂ → 3CO₂ + 4H₂O. Ammonia: ½N₂ + 1½H₂ → NH₃."], ["Q8", "Oxygen gas is an element already in its standard state, so forming it from its element involves no change [1]."]], "5": [["Q9", "(a) The enthalpy change when one mole of a substance [1] is burned completely in oxygen under standard conditions [1]. (b) 298 K [1] and 101 kPa [1]. (c) The products have lower enthalpy than the reactants, and the temperature of the surroundings rises [1]."]], "6": [["Exit ticket", "Positive, because the system takes in energy from the surroundings, so the products have more enthalpy than the reactants."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "A cold pack feels cold when the chemicals inside it react. Where has the heat from your hand gone?", "Q2": "Exothermic or endothermic?", "Q3": "A reaction has ΔH = −120 kJ mol⁻¹ and an activation energy of +80 kJ mol⁻¹. Describe its reaction pathway diagram, and calculate the activation energy of the reverse reaction.", "Q4": "Read the pathway diagram described.", "Q5": "Which standard enthalpy change does the equation represent?", "Q6": "Define standard enthalpy change of formation.", "Q7": "Choose the equation that represents the enthalpy change.", "Q8": "Explain why the standard enthalpy change of formation of oxygen gas, O₂(g), is zero.", "Q9": "(a) Define standard enthalpy change of combustion. (b) State the standard conditions of temperature and pressure. (c) The combustion of carbon is exothermic, ΔH = −394 kJ mol⁻¹. State how the enthalpy of the products compares with that of the reactants, and what happens to the temperature of the surroundings."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'e36b10e4-ec16-57b6-bfdb-cfce90ba3db0', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '5.1' limit 1), '5.1 Enthalpy change, ΔH · Lesson 2: Bond energies and calorimetry: q = mcΔT', 'A Level Chemistry · 5 Chemical energetics', '/achem-5-1-2/', 'ACHEM-5-1-2', 31, 60, 5012 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-5-1-2', '5.1 Enthalpy change, ΔH · Lesson 2: Bond energies and calorimetry: q = mcΔT', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["Energy taken in", "Energy given out", "Energy taken in", "Energy given out"], "tip": "Breaking in, making out."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["678", "862"], ["184"]], "tips": ["Bonds broken: one H–H and one Cl–Cl. Bonds formed: two H–Cl."]}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 3, "pts": [["2632"], ["3450"], ["818"]], "tips": ["Broken: four C–H and two O=O. Formed: two C=O and four O–H."]}, {"kind": "choice", "id": "q2_2", "q": "Q5", "max": 5, "n": 5, "ans": ["Exact", "Average", "Exact", "Average", "Exact"], "tip": "Does the bond occur in only one molecule?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q6", "max": 3, "pts": [["2842", "2840", "2.84"], ["0.05"], ["56.8", "56.9", "57"]], "tips": ["Total mass of solution is 100 g. Moles of water formed = moles of HCl."]}, {"kind": "text", "id": "q3_1", "q": "Q7", "max": 3, "pts": [["10450", "10.45", "10.5"], ["0.01"], ["1045", "1050", "1040"]], "tips": ["q for the water, moles of ethanol, then divide."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q8", "max": 4, "n": 4, "ans": ["Smaller temperature rise", "Smaller temperature rise", "Smaller temperature rise", "No effect"], "tip": "Does the energy reach the water?"}, {"kind": "text", "id": "q4_1", "q": "Q9", "max": 2, "pts": [["heat loss", "heat lost", "lost to the surroundings", "escapes", "heat is lost", "energy lost", "energy is lost"], ["incomplete", "calorimeter absorbs", "heat capacity of the calorimeter", "evaporat", "not standard", "heats the calorimeter"]], "tips": ["Think about where the energy went, and how the fuel burned."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q10", "max": 5, "pts": [["2252"], ["2340"], ["88"], ["more energy", "greater", "released+more", "less energy"], ["different", "average", "many", "other compounds", "environment"]], "tips": ["Each NH₃ has three N–H bonds."]}]}, "models": {"1": [["Q1", "Energy is needed first to break C–H and O=O bonds (the spark provides it). Making the C=O and O–H bonds in the products releases more energy than was needed to break the bonds, so overall the reaction is exothermic."], ["Q2", "Breaking any bond takes energy in; forming any bond gives energy out."]], "2": [["Q3", "Bonds broken: 436 + 242 = 678 kJ; bonds formed: 2 × 431 = 862 kJ [1]. ΔH = 678 − 862 = −184 kJ mol⁻¹ [1]."], ["Q4", "Bonds broken: 4 × 410 + 2 × 496 = 2632 kJ [1]. Bonds formed: 2 × 805 + 4 × 460 = 3450 kJ [1]. ΔH = 2632 − 3450 = −818 kJ mol⁻¹ [1]."], ["Q5", "H–H, Cl–Cl and N≡N occur only in H₂, Cl₂ and N₂: exact. C–H and O–H occur in many compounds: averages."]], "3": [["Q6", "q = 100 × 4.18 × 6.8 = 2842 J [1]. Moles of water formed = 0.0500 × 1.00 = 0.0500 mol [1]. ΔH = −2842 ÷ 0.0500 = −56 800 J mol⁻¹ = −56.8 kJ mol⁻¹ [1]."], ["Q7", "q = 200 × 4.18 × 12.5 = 10 450 J [1]. Moles of ethanol = 0.460 ÷ 46.0 = 0.0100 mol [1]. ΔH = −10 450 ÷ 0.0100 = −1 045 000 J mol⁻¹ = −1045 kJ mol⁻¹ [1]."]], "4": [["Q8", "Heat loss, incomplete combustion and heating the calorimeter all mean less energy reaches the water, so the rise is smaller. Reading the thermometer more precisely does not change the rise."], ["Q9", "Heat is lost to the surroundings, so not all the energy heats the water [1]. Combustion is incomplete (and some heat is absorbed by the calorimeter) [1]."]], "5": [["Q10", "(a) Bonds broken: 944 + 3 × 436 = 2252 kJ [1]. Bonds formed: 6 × 390 = 2340 kJ [1]. ΔH = 2252 − 2340 = −88 kJ mol⁻¹ [1]. (b) More energy is released in forming the N–H bonds than is needed to break the N≡N and H–H bonds [1]. (c) N–H bonds occur in many different compounds, and the value is an average over them [1]."]], "6": [["Exit ticket", "m is the mass of water or solution heated, c is its specific heat capacity, ΔT is the temperature change and n is the amount in moles of the substance that reacted."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q2_1": "Q4", "q3_0": "Q6", "q3_1": "Q7", "q4_1": "Q9", "q5_0": "Q10", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Methane must be lit with a spark before it burns, but then it gives out a lot of heat. Explain both facts using bonds.", "Q2": "Energy taken in or given out?", "Q3": "Use the bond energies in the notes to calculate ΔH for H₂(g) + Cl₂(g) → 2HCl(g). Show your working.", "Q4": "Use the bond energies in the notes to calculate ΔH for CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(g). Show your working.", "Q5": "Is the bond energy exact or an average?", "Q6": "50.0 cm³ of 1.00 mol dm⁻³ HCl is mixed with 50.0 cm³ of 1.00 mol dm⁻³ NaOH. The temperature rises by 6.8 °C. Calculate the enthalpy change of neutralisation in kJ mol⁻¹. (c = 4.18 J g⁻¹ K⁻¹)", "Q7": "0.460 g of ethanol (M = 46.0 g mol⁻¹) is burned and heats 200 g of water by 12.5 °C. Calculate the enthalpy change of combustion of ethanol from these results.", "Q8": "What is the effect on the measured temperature rise?", "Q9": "Give two reasons why the experimental value for the enthalpy change of combustion of ethanol (−1045 kJ mol⁻¹) is less exothermic than the data-book value (−1367 kJ mol⁻¹).", "Q10": "Use the bond energies in the note above. (a) Calculate ΔH for N₂(g) + 3H₂(g) → 2NH₃(g). (b) Explain, in terms of bonds, why this reaction is exothermic. (c) State why the N–H bond energy is an average value."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '1b8bda13-0798-58b4-ab19-0be0f7630451', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '5.2' limit 1), '5.2 Hess''s law · Lesson 1: Hess''s law and energy cycles using enthalpy changes of formation', 'A Level Chemistry · 5 Chemical energetics', '/achem-5-2-1/', 'ACHEM-5-2-1', 20, 60, 5021 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-5-2-1', '5.2 Hess''s law · Lesson 1: Hess''s law and energy cycles using enthalpy changes of formation', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["0", "0", "−394 kJ mol⁻¹", "−286 kJ mol⁻¹"], "tip": "Formation is for one mole. Elements are zero."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["138"], ["176"]], "tips": ["Products minus reactants."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["966"], ["891"]], "tips": ["Oxygen is an element: zero."]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["1811"], ["1902"], ["91"]], "tips": ["Two moles of NaHCO₃ on the left."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 1, "n": 1, "ans": ["Right size, wrong sign"], "tip": "It is products minus reactants."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["1029"], ["178"], ["endothermic"]], "tips": ["Add the products first."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 5, "pts": [["independent", "does not depend", "same whichever", "regardless", "same by any", "not depend"], ["route", "path"], ["1092"], ["184"], ["908"]], "tips": ["Four NH₃, four NO, six H₂O. Oxygen is zero."]}]}, "models": {"1": [["Q1", "They are the same. The starting materials and the final products are identical, so by Hess''s law the total enthalpy change does not depend on the route. Otherwise energy could be created or destroyed by going round the two routes."]], "2": [["Q2", "Elements in their standard states: 0. CO₂: −394. The water equation makes two moles, so ΔHf = −572 ÷ 2 = −286 kJ mol⁻¹."], ["Q3", "Sum for reactants = −46 + (−92) = −138 kJ [1]. ΔH = −314 − (−138) = −176 kJ mol⁻¹ [1]."]], "3": [["Q4", "Products: −394 + 2 × (−286) = −966 kJ [1]. ΔH = −966 − (−75) = −891 kJ mol⁻¹ [1]."], ["Q5", "Products: −1131 + (−394) + (−286) = −1811 kJ [1]. Reactants: 2 × (−951) = −1902 kJ [1]. ΔH = −1811 − (−1902) = +91 kJ mol⁻¹ [1]."]], "4": [["Q6", "The answer has the correct size but the opposite sign, because the subtraction is the wrong way round."], ["Q7", "Products: −635 + (−394) = −1029 kJ [1]. ΔH = −1029 − (−1207) = +178 kJ mol⁻¹ [1]. The reaction is endothermic [1]."]], "5": [["Q8", "(a) The enthalpy change of a reaction is independent [1] of the route taken, provided the initial and final conditions are the same [1]. (b) Products: 4 × 90 + 6 × (−242) = −1092 kJ [1]. Reactants: 4 × (−46) = −184 kJ [1]. ΔH = −1092 − (−184) = −908 kJ mol⁻¹ [1]."]], "6": [["Exit ticket", "ΔH of reaction = sum of ΔHf of the products − sum of ΔHf of the reactants."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_0": "Q4", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Carbon can be burned straight to carbon dioxide, or first to carbon monoxide and then to carbon dioxide. Predict how the total enthalpy changes of the two routes compare, and explain.", "Q2": "What is the standard enthalpy change of formation?", "Q3": "Calculate ΔH for NH₃(g) + HCl(g) → NH₄Cl(s). ΔHf in kJ mol⁻¹: NH₃ −46, HCl −92, NH₄Cl −314.", "Q4": "Use the values in the notes to calculate ΔH for CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l).", "Q5": "Use the values in the notes to calculate ΔH for 2NaHCO₃(s) → Na₂CO₃(s) + CO₂(g) + H₂O(l).", "Q6": "A student calculates ΔH = sum of ΔHf (reactants) − sum of ΔHf (products). What happens?", "Q7": "Calculate ΔH for CaCO₃(s) → CaO(s) + CO₂(g). ΔHf in kJ mol⁻¹: CaCO₃ −1207, CaO −635, CO₂ −394. State whether the reaction is exothermic or endothermic.", "Q8": "(a) State Hess''s law. (b) Use the values in the note above to calculate ΔH for 4NH₃(g) + 5O₂(g) → 4NO(g) + 6H₂O(g)."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '2b213b00-ba72-54d6-bf43-52a6fc827a58', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '5.2' limit 1), '5.2 Hess''s law · Lesson 2: Energy cycles using enthalpy changes of combustion and bond energies', 'A Level Chemistry · 5 Chemical energetics', '/achem-5-2-2/', 'ACHEM-5-2-2', 20, 60, 5022 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-5-2-2', '5.2 Hess''s law · Lesson 2: Energy cycles using enthalpy changes of combustion and bond energies', '{"marks": {"2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["966"], ["76"]], "tips": ["Reactants minus products, with two H₂."]}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["1646"], ["279"]], "tips": ["Oxygen does not burn: its ΔHc is zero."]}, {"kind": "choice", "id": "q2_2", "q": "Q4", "max": 2, "n": 2, "ans": ["Products − reactants", "Reactants − products"], "tip": "Formation arrows go up from the elements; combustion arrows go down to the oxides."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 3, "pts": [["1046"], ["1170"], ["124"]], "tips": ["Broken: C=C and H–H. Formed: C–C and two C–H."]}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["803"], ["910"], ["107"]], "tips": ["Broken: C=C and Br–Br. Formed: C–C and two C–Br."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 1, "pts": [["391"]], "tips": ["How many N–H bonds are broken?"]}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 2, "pts": [["463"], ["average", "different compounds", "other compounds", "many compounds", "range of compounds", "different molecules"]], "tips": ["Two O–H bonds in water."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 5, "pts": [["other products", "mixture", "other hydrocarbons", "does not react", "do not react", "too slow", "not only propane", "many products"], ["2326"], ["107"], ["average"], ["gaseous", "not exact", "different compounds", "other compounds", "approximate"]], "tips": ["Three C and four H₂ on the left."]}]}, "models": {"1": [["Q1", "Burn each substance and measure its enthalpy change of combustion. Carbon plus hydrogen, and methane, both burn to the same products (CO₂ and H₂O), so the difference between the two routes to those products is the enthalpy change of formation of methane."]], "2": [["Q2", "Reactants: −394 + 2 × (−286) = −966 kJ [1]. ΔHf = −966 − (−890) = −76 kJ mol⁻¹ [1]."], ["Q3", "Reactants: 2 × (−394) + 3 × (−286) = −1646 kJ [1]. ΔHf = −1646 − (−1367) = −279 kJ mol⁻¹ [1]."], ["Q4", "Formation data: products − reactants. Combustion data: reactants − products."]], "3": [["Q5", "Bonds broken: 610 + 436 = 1046 kJ [1]. Bonds formed: 350 + 2 × 410 = 1170 kJ [1]. ΔH = 1046 − 1170 = −124 kJ mol⁻¹ [1]."], ["Q6", "Bonds broken: 610 + 193 = 803 kJ [1]. Bonds formed: 350 + 2 × 280 = 910 kJ [1]. ΔH = 803 − 910 = −107 kJ mol⁻¹ [1]."]], "4": [["Q7", "1173 ÷ 3 = 391 kJ mol⁻¹ [1]."], ["Q8", "926 ÷ 2 = 463 kJ mol⁻¹ [1]. The data-book value is an average over O–H bonds in many different compounds, not just water [1]."]], "5": [["Q9", "(a) Carbon and hydrogen do not react directly to give only propane: other hydrocarbons would form [1]. (b) Reactants: 3 × (−394) + 4 × (−286) = −2326 kJ [1]. ΔHf = −2326 − (−2219) = −107 kJ mol⁻¹ [1]. (c) Bond energies are average values [1] taken from many different compounds, so they are not exact for propane [1]."]], "6": [["Exit ticket", "In a formation cycle the arrows point from the elements up to the substances, so you go against the reactant arrows. In a combustion cycle the arrows point from the substances down to the combustion products, so you go along the reactant arrows and against the product arrows."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q2_1": "Q3", "q3_0": "Q5", "q3_1": "Q6", "q4_0": "Q7", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "The reaction C(s) + 2H₂(g) → CH₄(g) cannot be carried out cleanly in the laboratory. Suggest how burning carbon, hydrogen and methane could still give its enthalpy change.", "Q2": "Use the values in the notes to calculate the enthalpy change of formation of methane: C(s) + 2H₂(g) → CH₄(g).", "Q3": "Use the values in the notes to calculate the enthalpy change of formation of ethanol: 2C(s) + 3H₂(g) + ½O₂(g) → C₂H₅OH(l).", "Q4": "Which rule do you use?", "Q5": "Use the bond energies in the notes to calculate ΔH for C₂H₄(g) + H₂(g) → C₂H₆(g). Count only the bonds that change.", "Q6": "Use the bond energies in the notes to calculate ΔH for C₂H₄(g) + Br₂(g) → CH₂BrCH₂Br(g).", "Q7": "For NH₃(g) → N(g) + 3H(g), ΔH = +1173 kJ mol⁻¹. Calculate the average N–H bond energy.", "Q8": "For H₂O(g) → 2H(g) + O(g), ΔH = +926 kJ mol⁻¹. Calculate the average O–H bond energy, and explain why the data-book value for O–H (460 kJ mol⁻¹) is slightly different.", "Q9": "(a) Suggest why the enthalpy change of formation of propane cannot be measured directly. (b) Use the values in the note above to calculate the enthalpy change of formation of propane: 3C(s) + 4H₂(g) → C₃H₈(g). (c) A value calculated from bond energies is slightly different. Suggest why."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '11b2b8ed-427b-57e4-9b63-6375ff243649', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '6.1' limit 1), '6.1 Redox processes: electron transfer and changes in oxidation number · Lesson 1: Oxidation numbers, Roman numerals, and oxidation and reduction', 'A Level Chemistry · 6 Electrochemistry', '/achem-6-1-1/', 'ACHEM-6-1-1', 31, 60, 6011 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-6-1-1', '6.1 Redox processes: electron transfer and changes in oxidation number · Lesson 1: Oxidation numbers, Roman numerals, and oxidation and reduction', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 10, "n": 10, "ans": ["+6", "+4", "−2", "−3", "+5", "+7", "+6", "−1", "+1", "−1"], "tip": "Put in the fixed values, then make the total equal the overall charge."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 8, "n": 8, "ans": ["iron(III) chloride", "iron(II) chloride", "copper(I) oxide", "copper(II) oxide", "potassium manganate(VII)", "potassium dichromate(VI)", "sodium chlorate(I)", "sodium chlorate(V)"], "tip": "Work out the oxidation number of the metal, or of the chlorine, first."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 6, "n": 6, "ans": ["Oxidised", "Reduced", "Reduced", "Oxidised", "Oxidised", "Reduced"], "tip": "Oxidation number up: oxidised. Down: reduced."}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["loses", "lose", "loss", "lost"], ["0 to 2", "increases", "from 0", "rises", "goes up", "increase"]], "tips": ["Two different ways of saying the same thing."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 5, "pts": [["2 to 3", "ii to iii", "from 2", "2 and 3"], ["iron is oxidised", "iron oxidised", "fe is oxidised", "iron is oxidized", "iron"], ["chlorine is reduced", "chlorine reduced", "cl2 is reduced", "chlorine is the one reduced", "chlorine"], ["0 to 1", "0 and 1", "from 0", "zero", "0 in cl2", "is 0", "0 in"], ["iron iii chloride"]], "tips": ["(d) FeCl₃ contains Fe³⁺. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "Each iron atom has lost three electrons to become Fe³⁺ (it has been oxidised). Each oxygen atom has gained two electrons to become O²⁻ (it has been reduced). Electrons have been transferred from iron to oxygen."]], "2": [["Q2", "H₂SO₄: 2(+1) + S + 4(−2) = 0, S = +6. SO₂ +4. H₂S −2. NH₃ −3. HNO₃ +5. MnO₄⁻: Mn + 4(−2) = −1, Mn = +7. Cr₂O₇²⁻: 2Cr − 14 = −2, Cr = +6. Peroxide oxygen −1. ClO⁻ +1. Hydride hydrogen −1."]], "3": [["Q3", "FeCl₃: Fe +3. FeCl₂: Fe +2. Cu₂O: Cu +1. CuO: Cu +2. KMnO₄: Mn +7. K₂Cr₂O₇: Cr +6. NaClO: Cl +1. NaClO₃: Cl +5."]], "4": [["Q4", "Zn 0 to +2: oxidised. Cu²⁺ +2 to 0: reduced. Cl₂ 0 to −1: reduced. Br⁻ −1 to 0: oxidised. Fe²⁺ +2 to +3: oxidised. H⁺ +1 to 0: reduced."], ["Q5", "Each magnesium atom loses two electrons [1], and its oxidation number increases from 0 to +2 [1]."]], "5": [["Q6", "(a) Iron changes from +2 to +3 [1]. (b) Iron is oxidised [1]; chlorine is reduced [1]. (c) Chlorine is 0 in Cl₂ and −1 in FeCl₃ [1]. (d) Iron(III) chloride [1]."]], "6": [["Exit ticket", "Oxidation is loss of electrons, and it is an increase in oxidation number."]]}, "labels": {"q1_0": "Q1", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "When iron rusts it forms iron(III) oxide, which contains Fe³⁺ and O²⁻ ions. Describe what has happened to the electrons of the iron atoms and of the oxygen atoms.", "Q2": "What is the oxidation number of the element?", "Q3": "Choose the correct name.", "Q4": "Is the species oxidised or reduced?", "Q5": "In 2Mg + O₂ → 2MgO, explain why magnesium is oxidised, in terms of electrons and in terms of oxidation number.", "Q6": "Iron(II) chloride reacts with chlorine: 2FeCl₂ + Cl₂ → 2FeCl₃. (a) State the oxidation number of iron before and after the reaction. (b) State which element is oxidised and which is reduced. (c) Give the oxidation number of chlorine in Cl₂ and in FeCl₃. (d) Name the product using a Roman numeral."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '0b6653cb-a9ce-512c-8e4d-f2ad751923ac', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '6.1' limit 1), '6.1 Redox processes: electron transfer and changes in oxidation number · Lesson 2: Oxidising and reducing agents, disproportionation, and balancing redox equations', 'A Level Chemistry · 6 Electrochemistry', '/achem-6-1-2/', 'ACHEM-6-1-2', 29, 60, 6012 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-6-1-2', '6.1 Redox processes: electron transfer and changes in oxidation number · Lesson 2: Oxidising and reducing agents, disproportionation, and balancing redox equations', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Cu²⁺", "Cl₂", "O₂", "Fe₂O₃", "MnO₄⁻"], "tip": "The oxidising agent is the species that is reduced."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["donates electrons", "gives electrons", "loses electrons", "is oxidised", "itself oxidised", "donate electrons", "lose electrons", "donor"], ["iodide", "2i"]], "tips": ["What does it do to the other substance, and what happens to it?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 7, "n": 7, "ans": ["Disproportionation", "Disproportionation", "Not disproportionation", "Disproportionation", "Disproportionation", "Not disproportionation", "Disproportionation"], "tip": "Does one element end up with both a higher and a lower oxidation number?"}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["reduced", "reduction", "decreases"], ["oxidised", "oxidized", "oxidation", "increases"], ["same element", "same species", "both", "simultaneously", "same time"]], "tips": ["Follow the chlorine into each product."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["5", "6", "2", "5", "6"], "tip": "Total increase in oxidation number = total decrease."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["6 to 3", "from 6", "vi to iii", "decreases by 3", "down by 3", "decrease of 3"], ["2 to 3", "from 2", "increases by 1", "up by 1", "increase of 1"], ["total", "two chromium", "2 chromium", "2 cr", "6 electrons", "six electrons", "2 x 3", "2 3"]], "tips": ["There are two chromium atoms. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["4 to 2", "from 4", "iv to ii", "decreases by 2"], ["mno2", "manganese iv oxide", "manganese oxide", "manganese dioxide"], ["hcl", "chloride", "hydrochloric"], ["unchanged", "remain", "stays", "still", "not all", "two of", "does not change", "mncl2"]], "tips": ["(c) look at the chlorine in MnCl₂. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "Aluminium causes the reduction: it gives electrons to the Fe³⁺ ions. In doing so aluminium itself loses electrons and is oxidised to Al³⁺."]], "2": [["Q2", "Cu²⁺ (reduced to Cu), Cl₂ (reduced to Cl⁻), O₂ (reduced to O²⁻), Fe₂O₃ (iron reduced from +3 to 0) and MnO₄⁻ (manganese reduced from +7 to +2)."], ["Q3", "A reducing agent donates electrons to another species and is itself oxidised [1]. Here the reducing agent is the iodide ion, I⁻ [1]."]], "3": [["Q4", "Chlorine with alkali or water, hydrogen peroxide decomposing and Cu⁺ forming Cu and Cu²⁺ are disproportionations: one element goes up and down. In the other two reactions different elements are oxidised and reduced."], ["Q5", "Chlorine is reduced from 0 to −1 in NaCl [1] and oxidised from 0 to +1 in NaClO [1]. The same element is both oxidised and reduced in the same reaction [1]."]], "4": [["Q6", "Mn down 5: 5 Fe²⁺. Two Cr each down 3 (total 6): 6 Fe²⁺. Cu up 2: 2 Ag⁺. Two Mn each down 5 (total 10); each C₂O₄²⁻ goes up 2: 5. Two Al each up 3 (total 6): 6 H⁺."], ["Q7", "Each chromium goes from +6 to +3, a decrease of 3 [1]. Each iron goes from +2 to +3, an increase of 1 [1]. There are two chromium atoms, a total decrease of 6, so six Fe²⁺ are needed to give a total increase of 6 [1]."]], "5": [["Q8", "(a) Manganese changes from +4 to +2 [1]. (b) The oxidising agent is MnO₂ [1]; the reducing agent is HCl (the chloride ion) [1]. (c) Two of the four chloride ions remain as Cl⁻ in MnCl₂ with their oxidation number unchanged at −1; only the two that form Cl₂ are oxidised [1]."]], "6": [["Exit ticket", "It accepts electrons and is itself reduced (its oxidation number decreases)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "In 2Al + Fe₂O₃ → Al₂O₃ + 2Fe, which substance causes the iron(III) oxide to be reduced, and what happens to that substance itself?", "Q2": "Which is the oxidising agent?", "Q3": "Explain what is meant by a reducing agent, and identify the reducing agent in Cl₂ + 2I⁻ → 2Cl⁻ + I₂.", "Q4": "Is the reaction a disproportionation?", "Q5": "Explain, using oxidation numbers, why Cl₂ + 2NaOH → NaCl + NaClO + H₂O is a disproportionation reaction.", "Q6": "Use changes in oxidation number to find x.", "Q7": "In acid, dichromate(VI) ions oxidise iron(II) ions: Cr₂O₇²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H₂O. Show, using oxidation numbers, why six Fe²⁺ ions are needed for each Cr₂O₇²⁻ ion.", "Q8": "Manganese(IV) oxide reacts with concentrated hydrochloric acid: MnO₂ + 4HCl → MnCl₂ + Cl₂ + 2H₂O. (a) State the change in oxidation number of manganese. (b) Identify the oxidising agent and the reducing agent. (c) Explain why only half of the chlorine in the HCl is oxidised."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '3c3d6777-2d1f-5735-a64c-dc3d9e31a642', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '7.1' limit 1), '7.1 Chemical equilibria: reversible reactions, dynamic equilibrium · Lesson 1: Reversible reactions, dynamic equilibrium and Le Chatelier''s principle', 'A Level Chemistry · 7 Equilibria', '/achem-7-1-1/', 'ACHEM-7-1-1', 28, 60, 7011 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-7-1-1', '7.1 Chemical equilibria: reversible reactions, dynamic equilibrium · Lesson 1: Reversible reactions, dynamic equilibrium and Le Chatelier''s principle', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["False", "True", "True", "False", "True"], "tip": "Dynamic means still moving; equilibrium means balanced."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["rate", "rates"], ["concentration", "constant", "do not change", "remain the same", "closed"]], "tips": ["One about rates, one about concentrations."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["To the right", "To the left", "To the right", "To the right", "No change", "To the left"], "tip": "Four gas molecules on the left, two on the right. Forward reaction exothermic."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["change", "disturb"], ["minimise", "minimize", "oppose", "counteract", "reduce", "cancel"]], "tips": ["If a change is made … the position of equilibrium moves to …"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["To the right", "To the left", "No change", "To the right", "To the left"], "tip": "Count gas molecules only."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["darker", "more brown", "browner", "brown colour increases", "deeper"], ["left", "reverse", "backward", "towards no2", "more no2"], ["endothermic"]], "tips": ["Which direction absorbs heat? Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 5, "pts": [["increases", "higher yield", "more so3", "greater yield", "increase"], ["fewer", "less molecules", "fewer moles", "3 to 2", "smaller number"], ["decreases", "lower yield", "less so3", "decrease", "falls"], ["endothermic", "exothermic"], ["escape", "leave", "lost", "closed"]], "tips": ["Three gas molecules become two. The forward reaction is exothermic."]}]}, "models": {"1": [["Q1", "The reaction is reversible: it can go in either direction, and the proportions of brown NO₂ and colourless N₂O₄ depend on the temperature. Cooling favours N₂O₄; warming favours NO₂."]], "2": [["Q2", "Both reactions continue at equal rates, so the concentrations stay constant (but are not usually equal). The system must be closed."], ["Q3", "The rate of the forward reaction equals the rate of the reverse reaction [1]. The concentrations of the reactants and products remain constant [1]."]], "3": [["Q4", "Higher pressure: to the side with fewer molecules (right). Higher temperature: in the endothermic direction (left). Adding a reactant or removing the product: right. Catalyst: no change. Lower pressure: left."], ["Q5", "If a change is made to a system at dynamic equilibrium [1], the position of equilibrium moves to minimise this change [1]."]], "4": [["Q6", "3 to 2: right. 1 to 2: left. 2 to 2: no change. 3 to 1: right. 0 to 1 gas molecules: left."], ["Q7", "The mixture becomes darker brown [1] because the position of equilibrium moves to the left, forming more NO₂ [1]. This is the endothermic direction, which absorbs heat and so opposes the rise in temperature [1]."]], "5": [["Q8", "(a) The yield increases [1]: the position moves to the right, the side with fewer gas molecules, to reduce the pressure [1]. (b) The yield decreases [1]: the position moves to the left, in the endothermic direction, to absorb the extra heat [1]. (c) So that no reactants or products can escape; otherwise the reverse reaction could not keep up and equilibrium would never be reached [1]."]], "6": [["Exit ticket", "It increases the rates of the forward and reverse reactions by the same factor, so equilibrium is reached more quickly but in the same position."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "A sealed tube of brown NO₂ becomes paler in ice and darker again when warmed, as often as you like. What does this tell you about the reaction 2NO₂ ⇌ N₂O₄?", "Q2": "Is the statement true or false for a system at dynamic equilibrium?", "Q3": "State two features of a system at dynamic equilibrium.", "Q4": "For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), ΔH = −92 kJ mol⁻¹, which way does the position of equilibrium move?", "Q5": "State Le Chatelier''s principle.", "Q6": "What is the effect of increasing the pressure on the position of equilibrium?", "Q7": "For 2NO₂(g) ⇌ N₂O₄(g), ΔH = −57 kJ mol⁻¹ (NO₂ is brown, N₂O₄ is colourless). State and explain what is seen when the mixture is heated at constant volume.", "Q8": "For 2SO₂(g) + O₂(g) ⇌ 2SO₃(g), ΔH = −197 kJ mol⁻¹: (a) predict and explain the effect on the yield of SO₃ of increasing the pressure; (b) predict and explain the effect on the yield of SO₃ of increasing the temperature; (c) explain why the mixture must be in a closed container to reach equilibrium."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'b3c7e50f-f78a-5519-bd73-4621507f48cf', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '7.1' limit 1), '7.1 Chemical equilibria: reversible reactions, dynamic equilibrium · Lesson 2: The equilibrium constant Kc: expressions, units and calculations', 'A Level Chemistry · 7 Equilibria', '/achem-7-1-2/', 'ACHEM-7-1-2', 26, 60, 7012 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-7-1-2', '7.1 Chemical equilibria: reversible reactions, dynamic equilibrium · Lesson 2: The equilibrium constant Kc: expressions, units and calculations', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["mol⁻² dm⁶", "No units", "mol dm⁻³", "mol⁻¹ dm³", "No units", "mol dm⁻³"], "tip": "Count: (number of product concentrations) − (number of reactant concentrations) gives the power of mol dm⁻³."}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 3, "n": 3, "ans": ["[NO₂]² ÷ [N₂O₄]", "[SO₃]² ÷ ([SO₂]²[O₂])", "[HI]² ÷ ([H₂][I₂])"], "tip": "Products on top, powers from the equation."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["0.5476", "0.548", "0.74 2", "0.74 0.74"], ["54.8", "54.76", "55"]], "tips": ["Square the HI concentration."]}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["0.08"], ["0.04"], ["0.02 mol", "0.020", "0.02"]], "tips": ["Each N₂O₄ that dissociates gives two NO₂. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["0.333", "0.33"], ["4.0", "4.01", "kc 4", "4.00", "is 4"]], "tips": ["Each mole of ester formed uses one mole of acid and one of alcohol, and makes one mole of water."]}, {"kind": "choice", "id": "q4_1", "q": "Q7", "max": 5, "n": 5, "ans": ["Decreases", "Increases", "No change", "No change", "No change"], "tip": "Only one thing changes K."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 5, "pts": [["0.3"], ["0.15"], ["0.05"], ["0.0167", "0.017", "1.67 10", "1.7 10"], ["increase"]], "tips": ["Divide every amount by 2.00 dm³."]}]}, "models": {"1": [["Q1", "There is a fixed relationship between the equilibrium concentrations at a given temperature. However the mixture starts, it adjusts until this ratio reaches the same value, the equilibrium constant."]], "2": [["Q2", "2 − 4 = −2: mol⁻² dm⁶. 2 − 2 = 0: no units. 2 − 1 = 1: mol dm⁻³. 2 − 3 = −1: mol⁻¹ dm³. 2 − 2: no units. 2 − 1: mol dm⁻³."], ["Q3", "[NO₂]² ÷ [N₂O₄]; [SO₃]² ÷ ([SO₂]²[O₂]); [HI]² ÷ ([H₂][I₂])."]], "3": [["Q4", "Kc = 0.74² ÷ (0.10 × 0.10) = 0.5476 ÷ 0.010 [1] = 54.8 (no units) [1]."], ["Q5", "N₂O₄ remaining = 0.100 − 0.020 = 0.080 mol dm⁻³ [1]. NO₂ formed = 2 × 0.020 = 0.040 mol dm⁻³ [1]. Kc = 0.040² ÷ 0.080 = 0.020 mol dm⁻³ [1]."]], "4": [["Q6", "Acid left = 1.00 − 0.667 = 0.333 mol (and the same for ethanol); water formed = 0.667 mol [1]. Kc = (0.667 × 0.667) ÷ (0.333 × 0.333) = 4.0, no units [1]."], ["Q7", "Only temperature changes K: it decreases for an exothermic forward reaction and increases for an endothermic one. Concentration, pressure and catalysts do not change K."]], "5": [["Q8", "(a) PCl₅ = 0.400 − 0.100 = 0.300 mol [1]. (b) [PCl₅] = 0.300 ÷ 2.00 = 0.150 mol dm⁻³ [1]; [Cl₂] = [PCl₃] = 0.100 ÷ 2.00 = 0.0500 mol dm⁻³ [1]. (c) Kc = (0.0500 × 0.0500) ÷ 0.150 = 0.0167 mol dm⁻³ [1]. (d) Kc increases [1]."]], "6": [["Exit ticket", "A change in temperature. Changes in concentration or pressure, or adding a catalyst, do not change the value of K."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q4", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "For H₂ + I₂ ⇌ 2HI, different starting mixtures give different equilibrium concentrations, but [HI]² ÷ ([H₂][I₂]) is always about 55 at the same temperature. What does this suggest?", "Q2": "What are the units of Kc?", "Q3": "Choose the Kc expression.", "Q4": "At equilibrium in H₂ + I₂ ⇌ 2HI, the concentrations are [H₂] = 0.10, [I₂] = 0.10 and [HI] = 0.74 mol dm⁻³. Calculate Kc.", "Q5": "0.100 mol of N₂O₄ is placed in a 1.00 dm³ flask. At equilibrium 0.020 mol of the N₂O₄ has dissociated: N₂O₄ ⇌ 2NO₂. Calculate Kc, with units.", "Q6": "1.00 mol of ethanoic acid and 1.00 mol of ethanol react: CH₃COOH + C₂H₅OH ⇌ CH₃COOC₂H₅ + H₂O. At equilibrium 0.667 mol of ester is present. Calculate the moles of acid left and the value of Kc.", "Q7": "What happens to the value of the equilibrium constant?", "Q8": "0.400 mol of PCl₅ is heated in a 2.00 dm³ vessel: PCl₅(g) ⇌ PCl₃(g) + Cl₂(g). At equilibrium 0.100 mol of Cl₂ is present. (a) Calculate the equilibrium amount of PCl₅. (b) Calculate the equilibrium concentrations of PCl₅ and of Cl₂. (c) Calculate Kc. (d) The forward reaction is endothermic. State the effect on Kc of increasing the temperature."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'dd03bdee-deff-5679-98e4-d470fccac708', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '7.1' limit 1), '7.1 Chemical equilibria: reversible reactions, dynamic equilibrium · Lesson 3: Mole fraction, partial pressure and Kp; the Haber and Contact processes', 'A Level Chemistry · 7 Equilibria', '/achem-7-1-3/', 'ACHEM-7-1-3', 29, 60, 7013 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-7-1-3', '7.1 Chemical equilibria: reversible reactions, dynamic equilibrium · Lesson 3: Mole fraction, partial pressure and Kp; the Haber and Contact processes', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["0.25", "0.75", "100 kPa", "300 kPa", "400 kPa"], "tip": "Mole fraction = moles ÷ total moles. Partial pressure = mole fraction × total pressure."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["1600", "40 2", "40 40"], ["26.7", "26.6", "27"]], "tips": ["Kp = p(NO₂)² ÷ p(N₂O₄)."]}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 3, "pts": [["40"], ["140"], ["0.61", "0.613", "0.6125"]], "tips": ["Total moles = 1.00, so each mole fraction is easy."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 3, "n": 3, "ans": ["About 450 °C", "About 200 atm", "Iron"], "tip": "A compromise temperature, a high pressure and a transition metal catalyst."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["exothermic"], ["lower temperature", "low temperature", "higher yield", "yield decreases", "lower yield", "position+left"], ["rate", "slow", "fast", "speed"]], "tips": ["Yield pulls one way, rate pulls the other."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 6, "n": 6, "ans": ["Haber process", "Contact process", "Both", "Haber process", "Contact process", "Both"], "tip": "Same temperature, very different pressures."}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 2, "pts": [["already high", "97", "high yield", "yield is high", "very high", "already"], ["cost", "expensive", "not worth", "not economic", "uneconomic", "energy"]], "tips": ["How good is the yield without it?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 5, "pts": [["0.2", "0.20"], ["40"], ["nh3", "ammonia"], ["squared", "2", "cubed", "3"], ["cost", "expensive", "strong", "safety", "dangerous", "thick"]], "tips": ["Total moles = 10.0. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "Nitrogen about 80 kPa and oxygen about 20 kPa. Each gas contributes to the pressure in proportion to the number of its molecules, because every molecule collides with the walls."], ["Q2", "Mole fractions 1.0 ÷ 4.0 = 0.25 and 3.0 ÷ 4.0 = 0.75. Partial pressures 0.25 × 400 = 100 kPa and 0.75 × 400 = 300 kPa, which add up to 400 kPa."]], "2": [["Q3", "Kp = 40² ÷ 60 = 1600 ÷ 60 [1] = 26.7 kPa [1]."], ["Q4", "Partial pressures: SO₂ 0.20 × 200 = 40 kPa, O₂ 0.10 × 200 = 20 kPa [1], SO₃ 0.70 × 200 = 140 kPa [1]. Kp = 140² ÷ (40² × 20) = 19600 ÷ 32000 = 0.613 kPa⁻¹ [1]."]], "3": [["Q5", "About 450 °C, about 200 atm and an iron catalyst."], ["Q6", "The forward reaction is exothermic [1], so a lower temperature would give a higher yield of ammonia [1]. But at a low temperature the rate would be too slow, so 450 °C gives an acceptable yield at an acceptable rate [1]."]], "4": [["Q7", "Iron and 200 atm: Haber. Vanadium(V) oxide and near-atmospheric pressure: Contact. Both use about 450 °C and both forward reactions are exothermic."], ["Q8", "The yield of SO₃ is already very high (about 97%) at just above atmospheric pressure [1], so the extra cost of high-pressure equipment and compression is not worth it [1]."]], "5": [["Q9", "(a) Mole fraction of NH₃ = 2.0 ÷ 10.0 = 0.20 [1]; partial pressure = 0.20 × 200 = 40 atm [1]. (b) Kp = the partial pressure of NH₃ squared [1] divided by (the partial pressure of N₂ × the partial pressure of H₂ cubed) [1]. (c) Higher pressures need stronger, more expensive equipment and more energy for compression, and are less safe [1]."]], "6": [["Exit ticket", "About 450 °C, about 200 atm, and an iron catalyst."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q2_1": "Q4", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Air is about four-fifths nitrogen and one-fifth oxygen by moles, at a total pressure of 100 kPa. What share of the pressure would you expect each gas to provide, and why?", "Q2": "A mixture contains 1.0 mol of N₂ and 3.0 mol of H₂ at a total pressure of 400 kPa.", "Q3": "At equilibrium in N₂O₄(g) ⇌ 2NO₂(g), the partial pressure of N₂O₄ is 60 kPa and that of NO₂ is 40 kPa. Calculate Kp, with units.", "Q4": "An equilibrium mixture of 2SO₂(g) + O₂(g) ⇌ 2SO₃(g) contains 0.20 mol SO₂, 0.10 mol O₂ and 0.70 mol SO₃ at a total pressure of 200 kPa. Calculate the partial pressure of each gas and then Kp.", "Q5": "Choose the condition used in the Haber process.", "Q6": "Explain why a temperature of about 450 °C is described as a compromise in the Haber process.", "Q7": "Haber process, Contact process, or both?", "Q8": "Explain why the Contact process does not use a high pressure, although a high pressure would move the position of equilibrium to the right.", "Q9": "In the Haber process an equilibrium mixture at a total pressure of 200 atm contains 2.0 mol N₂, 6.0 mol H₂ and 2.0 mol NH₃. (a) Calculate the mole fraction and the partial pressure of ammonia. (b) Write the expression for Kp (describe it in words or symbols). (c) Explain why a pressure higher than 200 atm is not normally used."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '59b73390-efa0-56a7-9b55-8f684b315ad6', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '7.2' limit 1), '7.2 Brønsted–Lowry theory of acids and bases · Lesson 1: Proton donors and acceptors; strong and weak acids and bases; pH', 'A Level Chemistry · 7 Equilibria', '/achem-7-2-1/', 'ACHEM-7-2-1', 36, 60, 7021 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-7-2-1', '7.2 Brønsted–Lowry theory of acids and bases · Lesson 1: Proton donors and acceptors; strong and weak acids and bases; pH', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["H₂SO₄", "HNO₃", "CH₃COOH", "NH₃", "KOH"], "tip": "Learn these: they are named in the syllabus."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Acid", "Base", "Base", "Acid", "Acid", "Base"], "tip": "Which species loses H⁺, and which gains it?"}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["donor", "donates", "donate", "gives", "loses a proton"], ["acceptor", "accepts", "accept", "gains a proton", "receives"]], "tips": ["Protons."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 7, "n": 7, "ans": ["Strong acid", "Weak acid", "Strong base", "Weak base", "Strong acid", "Strong base", "Strong acid"], "tip": "Fully or partially dissociated?"}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["fully", "completely", "totally"], ["partial", "partly", "slightly", "incomplete", "not fully", "only some"]], "tips": ["How much of each dissociates in water?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 5, "n": 5, "ans": ["Lower for HCl", "Higher for HCl", "Higher for HCl", "Higher for HCl", "The same"], "tip": "More H⁺ ions at any moment, but the same total amount of acid."}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 4, "pts": [["ph meter", "universal indicator", "ph"], ["lower"], ["conductiv", "magnesium", "metal", "carbonate"], ["higher conductivity", "conducts better", "faster", "more vigorous", "more rapidly", "higher", "more bubbles", "quicker"]], "tips": ["A test and its result, twice."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 5, "pts": [["hcl+donates", "hcl+donor", "hcl is the acid", "hcl+acid"], ["ammonia+accepts", "nh3 is the base", "ammonia is the base", "ammonia+base"], ["nh4", "oh", "partial", "partly", "not fully"], ["faster", "slower", "higher rate", "more quickly"], ["same volume", "equal volume", "same amount", "same final"]], "tips": ["(b) NH₃ + H₂O ⇌ … (c) rate depends on H⁺ concentration; volume on total moles. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "In hydrochloric acid almost every molecule has split up to give H⁺ ions, so the concentration of H⁺ is high. In ethanoic acid only a small fraction of the molecules have done so, so the concentration of H⁺ is much lower."], ["Q2", "H₂SO₄, HNO₃, CH₃COOH, NH₃ and KOH."]], "2": [["Q3", "HCl and CH₃COOH donate protons: acids. NH₃ accepts a proton: base. Water accepts a proton from HCl (base) but donates one to NH₃ (acid)."], ["Q4", "An acid is a proton donor [1]. A base is a proton acceptor [1]."]], "3": [["Q5", "Strong acids: HCl, HNO₃, H₂SO₄. Weak acid: CH₃COOH. Strong bases: NaOH, KOH. Weak base: NH₃."], ["Q6", "A strong acid is fully dissociated in aqueous solution [1]; a weak acid is only partially dissociated [1]."]], "4": [["Q7", "HCl has more H⁺ ions: lower pH, higher conductivity, faster reaction. The total amount of acid is the same, so the final volume of hydrogen is the same."], ["Q8", "Measure the pH with a pH meter or universal indicator [1]: hydrochloric acid has the lower pH [1]. Measure the electrical conductivity, or add magnesium [1]: hydrochloric acid has the higher conductivity, or reacts faster [1]."]], "5": [["Q9", "(a) HCl is the acid because it donates a proton [1]; NH₃ is the base because it accepts a proton [1]. (b) NH₃ + H₂O ⇌ NH₄⁺ + OH⁻; ammonia is only partially dissociated (partly ionised) in water [1]. (c) HCl reacts faster because it has a higher concentration of H⁺ ions [1], but both give the same final volume of hydrogen because the amounts of acid are equal [1]."]], "6": [["Exit ticket", "A weak acid is only partially dissociated in water; a dilute acid has only a small amount of acid dissolved in a given volume. A weak acid can be concentrated and a strong acid can be dilute."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Vinegar (ethanoic acid) is safe to eat, but hydrochloric acid of the same concentration is not. Suggest what might be different about the two solutions.", "Q2": "Choose the formula.", "Q3": "In the forward reaction, is the species acting as an acid or a base?", "Q4": "Define a Brønsted–Lowry acid and a Brønsted–Lowry base.", "Q5": "Classify the substance.", "Q6": "Explain the difference between a strong acid and a weak acid.", "Q7": "Compare 0.1 mol dm⁻³ HCl with 0.1 mol dm⁻³ CH₃COOH.", "Q8": "You are given 0.1 mol dm⁻³ solutions of hydrochloric acid and ethanoic acid. Describe two tests to show which is the strong acid, giving the result of each.", "Q9": "Ammonia reacts with hydrogen chloride: NH₃ + HCl → NH₄⁺ + Cl⁻. (a) Identify the Brønsted–Lowry acid and base, explaining your choice. (b) Write an equation to show why aqueous ammonia is alkaline, and state why ammonia is a weak base. (c) Equal volumes of 0.1 mol dm⁻³ HCl and 0.1 mol dm⁻³ CH₃COOH react with excess magnesium. Compare the rates and the final volumes of hydrogen."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'cce4216d-c351-5ffe-9cd2-a3f83572f3ba', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '7.2' limit 1), '7.2 Brønsted–Lowry theory of acids and bases · Lesson 2: Neutralisation, salts, pH titration curves and choosing an indicator', 'A Level Chemistry · 7 Equilibria', '/achem-7-2-2/', 'ACHEM-7-2-2', 31, 60, 7022 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-7-2-2', '7.2 Brønsted–Lowry theory of acids and bases · Lesson 2: Neutralisation, salts, pH titration curves and choosing an indicator', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Sodium chloride", "Potassium sulfate", "Ammonium nitrate", "Sodium ethanoate", "Potassium nitrate"], "tip": "Metal (or ammonium) from the alkali, the rest from the acid."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["About pH 1", "pH 7", "About pH 13", "25 cm³"], "tip": "Equal concentrations react in equal volumes."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["Strong acid, strong alkali", "Weak acid, strong alkali", "Strong acid, weak alkali", "Weak acid, weak alkali", "Weak acid, strong alkali", "Strong acid, weak alkali"], "tip": "The weak partner pulls the equivalence point towards its own side of pH 7."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["ph 3", "about 3", "3"], ["7 to 11", "7 and 11", "above 7", "7 11", "8 to 10", "around 9", "about 9", "ph 7 to ph 11", "7 to ph 11"], ["13", "12"]], "tips": ["Weak acid, strong alkali. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["Either", "Phenolphthalein only", "Methyl orange only", "Neither", "Either"], "tip": "Does the indicator''s range lie inside the vertical section?"}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["7 to 11", "above 7", "7 and 11", "high ph", "7 11", "ph 7 to ph 11", "7 to ph 11"], ["8.3", "within", "inside", "lies in", "falls in", "in the vertical"], ["3.1", "4.4", "before", "too early", "outside", "below the vertical", "not in the vertical"]], "tips": ["Where is the vertical section, and where does each indicator change?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 5, "pts": [["h aq oh aq", "h oh h2o", "oh aq h aq"], ["h2o"], ["3 to 7", "3 and 7", "3 7", "below 7", "4 to 6", "ph 3 to ph 7", "3 to ph 7"], ["methyl orange"], ["no vertical", "no sharp", "gradual", "not sharp", "no steep", "no rapid"]], "tips": ["(b) strong acid, weak alkali. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "In both cases the reaction that actually happens is the same: H⁺(aq) + OH⁻(aq) → H₂O(l). The other ions (Na⁺, Cl⁻, K⁺, NO₃⁻) are spectator ions and take no part."], ["Q2", "Sodium chloride, potassium sulfate, ammonium nitrate, sodium ethanoate and potassium nitrate."]], "2": [["Q3", "It starts at about pH 1, the equivalence point is at pH 7 after 25 cm³, and the curve levels off at about pH 13."]], "3": [["Q4", "Long vertical section 3 to 11: strong–strong. Equivalence above 7: weak acid–strong alkali (ethanoic acid with NaOH). Equivalence below 7: strong acid–weak alkali (HCl with ammonia). No sharp section: weak–weak."], ["Q5", "The curve starts at about pH 3 [1], rises gradually, then has a vertical section from about pH 7 to pH 11 at 25 cm³, with the equivalence point above pH 7 [1], and levels off at about pH 13 [1]."]], "4": [["Q6", "Strong–strong (HCl/NaOH, HNO₃/KOH): either. Weak acid–strong alkali: phenolphthalein. Strong acid–weak alkali: methyl orange. Weak–weak: neither."], ["Q7", "The vertical section of this curve is from about pH 7 to pH 11 [1]. Phenolphthalein changes colour at pH 8.3–10.0, within the vertical section [1]. Methyl orange changes at pH 3.1–4.4, outside the vertical section, so it would change colour too early, before the equivalence point [1]."]], "5": [["Q8", "(a) H⁺(aq) + OH⁻(aq) [1] → H₂O(l) [1]. (b) The vertical section is from about pH 3 to pH 7 [1], so methyl orange is the most suitable [1]. (c) With a weak acid and a weak alkali there is no sharp vertical section: the pH changes gradually, so no indicator gives a sharp colour change [1]."]], "6": [["Exit ticket", "The pH range over which the indicator changes colour must lie within the vertical section of the titration curve."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Neutralising hydrochloric acid with sodium hydroxide and neutralising nitric acid with potassium hydroxide give almost exactly the same enthalpy change per mole of water formed. Suggest why.", "Q2": "Which salt is formed?", "Q3": "For the titration of 25 cm³ of 0.1 mol dm⁻³ HCl with 0.1 mol dm⁻³ NaOH, choose the answer.", "Q4": "Match the description to the titration.", "Q5": "Describe the pH curve when 0.1 mol dm⁻³ sodium hydroxide is added to 25 cm³ of 0.1 mol dm⁻³ ethanoic acid until in excess. Give the starting pH, the vertical section and the final pH.", "Q6": "Which indicator is suitable?", "Q7": "Explain why phenolphthalein is suitable for titrating ethanoic acid with sodium hydroxide, but methyl orange is not.", "Q8": "Use the indicator ranges in the note above. (a) Write the ionic equation for neutralisation. (b) Hydrochloric acid is titrated with aqueous ammonia. State the approximate pH range of the vertical section, and which of the three indicators is most suitable. (c) Explain why no indicator is suitable for titrating ethanoic acid with aqueous ammonia."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'ee41a0aa-ed74-556d-85fd-99e3d6963276', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '8.1' limit 1), '8.1 Rate of reaction: Collision theory, the effect of concentration and pressure, and calculating rates from data', 'A Level Chemistry · 8 Reaction kinetics', '/achem-8-1/', 'ACHEM-8-1', 25, 60, 8010 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-8-1', '8.1 Rate of reaction: Collision theory, the effect of concentration and pressure, and calculating rates from data', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Non-effective collision", "Effective collision", "Non-effective collision", "Effective collision"], "tip": "Did the collision lead to a reaction?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["reaction", "react", "products"], ["activation energy", "enough energy", "sufficient energy", "minimum energy"]], "tips": ["What does it lead to, and what do the particles need?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Increases", "Increases", "No change", "Decreases", "Decreases"], "tip": "How many particles are there in each unit of volume?"}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["more particles", "more ions", "more h", "more acid particles", "particles per unit volume", "more molecules", "closer together"], ["more frequent", "more often", "more collisions", "collide more", "frequency"], ["effective", "successful"]], "tips": ["Particles, collisions, effective collisions."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 1, "pts": [["2.4"]], "tips": ["Volume ÷ time."]}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["0.024"], ["4.0 10", "4 10", "0.0004", "0.00040"]], "tips": ["Change in concentration ÷ time."]}, {"kind": "choice", "id": "q4_2", "q": "Q8", "max": 3, "n": 3, "ans": ["The reaction is fastest", "The reaction is slowing down", "The reaction has finished"], "tip": "Gradient = rate."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 5, "pts": [["gas syringe", "volume of gas", "mass", "balance", "collect the gas"], ["concentration+decreases", "concentration+falls", "used up", "less acid", "fewer particles", "concentration of acid decreases", "lower concentration"], ["less frequent", "fewer collisions", "collide less", "less often", "fewer effective"], ["2.0", "2 cm3", "2 cm"], ["0.5", "0.50"]], "tips": ["(c) the second period produces 30 cm³ in 60 s. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "The colliding molecules do not have enough energy to break their bonds, so they simply bounce apart. A spark gives some molecules enough energy for their collisions to be effective."]], "2": [["Q2", "A collision is effective only if the particles have at least the activation energy (and a suitable orientation) so that products form; otherwise they bounce apart."], ["Q3", "A collision that leads to a reaction [1], because the particles collide with at least the activation energy [1]."]], "3": [["Q4", "More particles per unit volume (higher concentration or pressure): faster. Fewer per unit volume (larger container, dilution): slower. More acid at the same concentration: no change in rate."], ["Q5", "There are more acid particles (H⁺ ions) in the same volume [1], so collisions with the magnesium are more frequent [1], and so effective collisions are more frequent [1]."]], "4": [["Q6", "48 ÷ 20 = 2.4 cm³ s⁻¹ [1]."], ["Q7", "Change in concentration = 0.100 − 0.076 = 0.024 mol dm⁻³ [1]. Rate = 0.024 ÷ 60 = 4.0 × 10⁻⁴ mol dm⁻³ s⁻¹ [1]."], ["Q8", "Steepest: fastest (highest concentration of reactants). Less steep: slowing as reactants are used up. Horizontal: finished."]], "5": [["Q9", "(a) Measure the volume of gas with a gas syringe (or the loss in mass on a balance) at regular times [1]. (b) The concentration of the acid decreases as it is used up [1], so effective collisions are less frequent [1]. (c) First 30 s: 60 ÷ 30 = 2.0 cm³ s⁻¹ [1]. Next 60 s: (90 − 60) ÷ 60 = 0.50 cm³ s⁻¹ [1]."]], "6": [["Exit ticket", "There are more particles in the same volume, so effective collisions happen more frequently."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q4_1": "Q7", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "In a mixture of hydrogen and oxygen at room temperature each molecule collides billions of times a second, yet nothing happens until there is a spark. Suggest why most collisions do not cause a reaction.", "Q2": "Effective or non-effective?", "Q3": "State what is meant by an effective collision.", "Q4": "What happens to the rate of reaction?", "Q5": "Explain why increasing the concentration of hydrochloric acid increases the rate of its reaction with magnesium.", "Q6": "In a reaction 48 cm³ of gas is collected in the first 20 s. Calculate the average rate of reaction over this time, with units.", "Q7": "The concentration of a reactant falls from 0.100 mol dm⁻³ to 0.076 mol dm⁻³ in 60 s. Calculate the average rate of reaction, with units.", "Q8": "On a graph of volume of gas against time, what does each feature show?", "Q9": "Calcium carbonate reacts with hydrochloric acid, giving carbon dioxide. (a) Suggest one way to follow the rate of this reaction. (b) Explain why the rate decreases as the reaction goes on. (c) In one experiment 60 cm³ of gas forms in the first 30 s and 90 cm³ in total after 90 s. Calculate the average rate in the first 30 s and in the next 60 s."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '8f0220ff-791a-5d07-a8b4-193970eb2850', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '8.2' limit 1), '8.2 Effect of temperature on reaction rates and the concept of activation energy: Activation energy and the Boltzmann distribution', 'A Level Chemistry · 8 Reaction kinetics', '/achem-8-2/', 'ACHEM-8-2', 24, 60, 8020 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-8-2', '8.2 Effect of temperature on reaction rates and the concept of activation energy: Activation energy and the Boltzmann distribution', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["The total number of molecules", "The most probable energy", "The molecules that can react", "No molecules have zero energy"], "tip": "Area means number of molecules."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["minimum"], ["collision+effective", "collision+react", "react", "reaction", "effective"]], "tips": ["The … energy required for …"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["Decreases", "Increases", "No change", "Increases", "No change", "Increases"], "tip": "Same molecules, more energy."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["more molecules", "greater proportion", "larger proportion", "more particles", "higher proportion", "many more"], ["activation energy"], ["effective", "successful"]], "tips": ["Proportion of molecules, activation energy, effective collisions."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 1, "n": 1, "ans": ["Activation energy 30 kJ mol⁻¹"], "tip": "A lower barrier is easier to cross."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["fewer", "smaller proportion", "less molecules", "lower proportion", "less particles"], ["activation energy"], ["effective", "successful", "slower", "less frequent", "rate decreases"]], "tips": ["The reverse of heating."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 5, "pts": [["origin", "starts at zero", "0 0", "zero"], ["not touch", "never touch", "does not touch", "approaches", "asymptot", "never reaches", "without touching", "approach"], ["lower", "flatter"], ["right", "higher energy", "broader", "wider"], ["area", "same number of molecules", "total number"]], "tips": ["(c) think about the number of molecules."]}]}, "models": {"1": [["Q1", "The energy of the collisions must matter. At the higher temperature a much larger proportion of the molecules have enough energy (at least the activation energy) for their collisions to be effective."]], "2": [["Q2", "Whole area: total number of molecules. Peak: most probable energy. Area beyond the activation energy: molecules with enough energy to react. Starting at the origin: no molecules have zero energy."], ["Q3", "The minimum energy [1] required for a collision to be effective, so that the particles react [1]."]], "3": [["Q4", "The peak is lower and at a higher energy; the total area and the activation energy are unchanged; the area beyond the activation energy, and so the frequency of effective collisions, increases."], ["Q5", "At the higher temperature a much greater proportion of the molecules [1] have energy equal to or greater than the activation energy [1], so effective collisions are much more frequent [1]."]], "4": [["Q6", "The reaction with the lower activation energy: a much greater proportion of molecules have at least 30 kJ mol⁻¹ than have 150 kJ mol⁻¹."], ["Q7", "At the lower temperature a smaller proportion of the molecules [1] have at least the activation energy [1], so effective collisions are less frequent and the reactions that spoil food are slower [1]."]], "5": [["Q8", "(a) It starts at the origin [1], rises to a peak and then falls, approaching the x-axis without touching it [1]. (b) The peak becomes lower [1] and moves to the right, to a higher energy [1]. (c) The total area under the curve does not change, because the number of molecules is the same [1]."]], "6": [["Exit ticket", "A much greater proportion of the molecules have at least the activation energy, so effective collisions are much more frequent."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Raising the temperature from 20 °C to 30 °C makes molecules collide only about 2% more often, yet the rate of many reactions doubles. Suggest what else must change.", "Q2": "What does each feature of a Boltzmann distribution show?", "Q3": "Define activation energy.", "Q4": "What happens when the temperature is increased?", "Q5": "Explain, using the Boltzmann distribution, why a small increase in temperature causes a large increase in the rate of a reaction.", "Q6": "Which reaction would you expect to be faster at room temperature, if everything else is the same?", "Q7": "Food keeps for longer in a refrigerator. Explain why, in terms of activation energy and collisions.", "Q8": "(a) Describe the shape of a Boltzmann distribution, including where it starts and how it ends. (b) Describe two ways in which the curve changes when the temperature is raised. (c) State what does not change about the curve, and why."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '65758df3-99cd-5039-b0f7-4f5918bfc804', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '8.3' limit 1), '8.3 Homogeneous and heterogeneous catalysts: How catalysts work: a different mechanism with a lower activation energy', 'A Level Chemistry · 8 Reaction kinetics', '/achem-8-3/', 'ACHEM-8-3', 30, 60, 8030 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-8-3', '8.3 Homogeneous and heterogeneous catalysts: How catalysts work: a different mechanism with a lower activation energy', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["Decreases", "Increases", "No change", "No change", "No change", "Increases"], "tip": "A lower barrier on a different route; the start and finish stay the same."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["lower peak", "peak is lower", "lower hump", "lower maximum", "smaller barrier", "lower barrier", "70"], ["reactants and products", "same level", "start and end", "unchanged", "same position", "same energies"], ["50", "enthalpy change", "delta h", "h is the same"]], "tips": ["Peak, levels, ΔH."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Raising the temperature", "Adding a catalyst", "Both", "Both", "Adding a catalyst"], "tip": "One changes the molecules'' energies; the other changes the barrier."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["lower activation energy", "activation energy is lower", "lowers the activation energy", "reduces the activation energy", "lower ea"], ["more molecules", "greater proportion", "larger proportion", "more particles", "higher proportion"], ["effective", "successful"]], "tips": ["Lower activation energy, proportion of molecules, effective collisions."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["Heterogeneous", "Heterogeneous", "Heterogeneous", "Homogeneous", "Homogeneous"], "tip": "Same phase or different phase?"}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["same phase", "same state", "same physical state"], ["different phase", "different state", "different physical state"]], "tips": ["Compare the phase of the catalyst with the phase of the reactants."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["increases the rate", "speeds up", "faster", "increase the rate"], ["unchanged", "not used up", "regenerated", "remains", "not consumed"], ["heterogeneous"], ["different mechanism", "different route", "alternative", "different pathway", "another route"], ["lower activation energy", "activation energy is lower", "lowers the activation energy", "lower ea", "reduces the activation energy"], ["no effect", "no change", "unchanged", "same", "does not change", "not affected"]], "tips": ["(b) a solid in a liquid."]}]}, "models": {"1": [["Q1", "The catalyst takes part in the reaction but is re-formed, so it is chemically unchanged and not used up. A small amount can therefore catalyse the reaction of a very large amount of reactants."]], "2": [["Q2", "The activation energy is lower, so a greater proportion of molecules can react and the rate increases. ΔH, the position of equilibrium and the amount of catalyst are unchanged."], ["Q3", "The peak of the curve is lower: 70 instead of 120 kJ mol⁻¹ above the reactants [1]. The levels of the reactants and products are unchanged [1], so ΔH is still −50 kJ mol⁻¹ [1]."]], "3": [["Q4", "Temperature changes the curve; a catalyst lowers the activation energy by providing a different mechanism. Both increase the proportion of molecules that can react, and so the rate."], ["Q5", "The catalysed route has a lower activation energy [1], so a greater proportion of the molecules have at least this energy [1], and effective collisions are more frequent [1]."]], "4": [["Q6", "Solid catalysts with gaseous reactants are heterogeneous. A catalyst in the same phase as the reactants (aqueous H⁺ with aqueous reactants, a gas with gases) is homogeneous."], ["Q7", "A homogeneous catalyst is in the same phase as the reactants [1]; a heterogeneous catalyst is in a different phase [1]."]], "5": [["Q8", "(a) A substance that increases the rate of a reaction [1] and is chemically unchanged at the end [1]. (b) Heterogeneous: it is a solid and the reactant is in solution, a different phase [1]. (c) It provides a different mechanism [1] with a lower activation energy, so a greater proportion of molecules have enough energy to react [1]. (d) No effect: ΔH is unchanged [1]."]], "6": [["Exit ticket", "The enthalpy change (the energies of the reactants and products) and the position of equilibrium. The catalyst itself is also unchanged at the end."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "The metals in a catalytic converter last for the whole life of the car. What does this tell you about what happens to a catalyst during a reaction?", "Q2": "What is the effect of adding a catalyst?", "Q3": "A reaction has an activation energy of +120 kJ mol⁻¹ and ΔH = −50 kJ mol⁻¹. With a catalyst the activation energy is +70 kJ mol⁻¹. Describe how the reaction pathway diagram changes when the catalyst is used, and what stays the same.", "Q4": "Raising the temperature or adding a catalyst?", "Q5": "Explain, using the Boltzmann distribution, how a catalyst increases the rate of a reaction.", "Q6": "Is the catalyst homogeneous or heterogeneous?", "Q7": "State the difference between a homogeneous catalyst and a heterogeneous catalyst.", "Q8": "Hydrogen peroxide decomposes slowly: 2H₂O₂ → 2H₂O + O₂. Solid manganese(IV) oxide catalyses the reaction. (a) State what is meant by a catalyst. (b) State whether manganese(IV) oxide is a homogeneous or a heterogeneous catalyst here, with a reason. (c) Explain how the catalyst increases the rate. (d) State the effect of the catalyst on ΔH."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'bc83d297-cdef-58ac-a28b-8eac8f3afc20', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '9.1' limit 1), '9.1 Periodicity of physical properties of the elements in Period 3: Atomic and ionic radius, melting point and electrical conductivity from sodium to argon', 'A Level Chemistry · 9 The Periodic Table: chemical periodicity', '/achem-9-1/', 'ACHEM-9-1', 40, 60, 9010 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-9-1', '9.1 Periodicity of physical properties of the elements in Period 3: Atomic and ionic radius, melting point and electrical conductivity from sodium to argon', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 8, "n": 8, "ans": ["Giant metallic", "Giant metallic", "Giant metallic", "Giant molecular", "Simple molecular", "Simple molecular", "Simple molecular", "Separate atoms"], "tip": "Metals on the left, one giant covalent element, then small molecules."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Na", "Na⁺", "P³⁻", "S²⁻", "Na", "Cl⁻"], "tip": "Same shell: more protons means smaller. An extra shell means larger."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["extra shell", "more shells", "one more shell", "another shell", "three shells", "third shell", "more occupied", "three occupied", "3 shells", "3 occupied", "extra occupied"], ["lost", "two shells", "second shell", "outer shell", "fewer shells", "only two"]], "tips": ["Write the electronic configuration of each ion. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 6, "n": 6, "ans": ["Metallic bonding", "Metallic bonding", "Covalent bonds", "Weak intermolecular forces", "Weak intermolecular forces", "Weak intermolecular forces"], "tip": "Use the structure of each element."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["more delocalised", "more electrons", "three delocalised", "3 delocalised", "number of delocalised"], ["higher charge", "greater charge", "charge increases", "al3", "smaller"], ["stronger metallic", "stronger attraction", "more energy", "attract+stronger", "stronger bonding"]], "tips": ["Electrons per atom, the ion, then the attraction."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 6, "n": 6, "ans": ["Mg", "Si", "Si", "S", "S", "Cl"], "tip": "Structure first; for the molecular elements count the electrons in the molecule."}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 3, "pts": [["s8", "p4", "larger molecule", "bigger molecule", "eight atoms"], ["more electrons"], ["stronger", "more energy", "greater"]], "tips": ["Compare the molecules S₈ and P₄. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 6, "pts": [["decrease"], ["nuclear charge", "more protons", "number of protons"], ["giant"], ["covalent bonds"], ["more delocalised", "three delocalised", "3 delocalised", "more electrons"], ["no delocalised", "no free electrons", "no mobile", "no charge carriers"]], "tips": ["(c) what carries the current in a metal? Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "In silicon every atom is held to its neighbours by strong covalent bonds throughout a giant lattice, so melting means breaking covalent bonds. Phosphorus is made of small P₄ molecules held together only by weak intermolecular forces."], ["Q2", "Na, Mg, Al: giant metallic. Si: giant molecular. P₄, S₈, Cl₂: simple molecular. Ar: separate atoms."]], "2": [["Q3", "Na > Cl (smaller nuclear charge). Na⁺ > Mg²⁺. P³⁻ > Al³⁺ (an extra shell). S²⁻ > Cl⁻ (fewer protons, same electrons). Na > Na⁺ (outer shell lost). Cl⁻ > Cl (extra repulsion)."], ["Q4", "P³⁻ (2.8.8) has three occupied shells [1], while Al³⁺ (2.8) has lost its outer shell and has only two [1]."]], "3": [["Q5", "Metals: metallic bonding. Silicon: covalent bonds throughout the lattice. P₄, S₈ and Ar: only weak forces between molecules or atoms."], ["Q6", "From Na to Al each atom gives more delocalised electrons [1], and the ions have a higher charge and a smaller radius [1], so the attraction between the ions and the delocalised electrons is stronger and more energy is needed [1]."]], "4": [["Q7", "Mg > Na; Si > Al; Si > P; S₈ > P₄ (more electrons per molecule); S > Cl; Cl₂ > Ar."], ["Q8", "Sulfur exists as S₈ molecules and phosphorus as P₄ molecules [1]. An S₈ molecule has more electrons [1], so the instantaneous dipole–induced dipole forces between the molecules are stronger and need more energy to overcome [1]."]], "5": [["Q9", "(a) Atomic radius decreases [1] because the nuclear charge increases while the outer electrons are in the same shell with similar shielding [1]. (b) Silicon has a giant molecular structure [1]; many strong covalent bonds must be broken to melt it [1]. (c) Each aluminium atom gives three delocalised electrons and each sodium atom only one, so aluminium has more electrons to carry the charge [1]. Sulfur is made of S₈ molecules with no delocalised electrons [1]."]], "6": [["Exit ticket", "It rises from Na to Al, peaks at Si, then drops sharply to P, rises a little to S and falls through Cl to Ar. The peak is at silicon because it has a giant molecular lattice held by strong covalent bonds."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Silicon melts at 1410 °C but phosphorus, the next element, melts at 44 °C. Suggest what must be different about the two solids.", "Q2": "What is the structure of the element?", "Q3": "Which particle is larger?", "Q4": "Explain why the P³⁻ ion is much larger than the Al³⁺ ion.", "Q5": "What must be overcome or broken to melt the element?", "Q6": "Explain why the melting point increases from sodium to aluminium.", "Q7": "Which element has the higher melting point?", "Q8": "Explain why sulfur has a higher melting point than phosphorus.", "Q9": "(a) State and explain the trend in atomic radius across Period 3. (b) Explain why silicon has the highest melting point in Period 3. (c) Explain why aluminium is a better electrical conductor than sodium, and why sulfur does not conduct."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '1a51856f-1e84-555a-97b7-37209e07a7e6', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '9.2' limit 1), '9.2 Periodicity of chemical properties of the elements in Period 3 · Lesson 1: Reactions of the elements with oxygen, chlorine and water; oxidation numbers of the oxides and chlorides', 'A Level Chemistry · 9 The Periodic Table: chemical periodicity', '/achem-9-2-1/', 'ACHEM-9-2-1', 35, 60, 9021 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-9-2-1', '9.2 Periodicity of chemical properties of the elements in Period 3 · Lesson 1: Reactions of the elements with oxygen, chlorine and water; oxidation numbers of the oxides and chlorides', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["Na₂O", "MgO", "Al₂O₃", "SiO₂", "P₄O₁₀", "SO₂"], "tip": "Sulfur stops at SO₂ without a catalyst."}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 4, "n": 4, "ans": ["Sodium", "Magnesium", "Phosphorus", "Sulfur"], "tip": "Smoke is a solid oxide; a choking gas is SO₂."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["NaCl", "MgCl₂", "Al₂Cl₆", "SiCl₄", "PCl₅"], "tip": "The number of chlorine atoms per atom equals the number of outer electrons."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["2al 3cl2", "3cl2 2al"], ["is 3", "of 3", "number 3", "plus 3", "three"]], "tips": ["Two aluminium atoms need six chlorine atoms."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["NaOH and H₂", "Mg(OH)₂ and H₂", "MgO and H₂", "About pH 13 to 14", "About pH 9 to 10"], "tip": "Cold water gives the hydroxide; steam gives the oxide."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["soluble", "dissolves", "solubility"], ["hydroxide ions", "oh", "more alkaline", "higher concentration"]], "tips": ["Compare how well the two hydroxides dissolve."]}], "5": [{"kind": "choice", "id": "q5_0", "q": "Q8", "max": 8, "n": 8, "ans": ["+1", "+2", "+3", "+4", "+5", "+4", "+6", "+5"], "tip": "Oxygen is −2 and chlorine is −1."}, {"kind": "text", "id": "q5_1", "q": "Q9", "max": 3, "pts": [["increase", "rises", "goes up"], ["outer", "valence", "group"], ["all", "bonding", "lost", "shared", "used"]], "tips": ["Link the oxidation number to the outer electrons."]}]}, "models": {"1": [["Q1", "Magnesium combines with oxygen from the air to form solid magnesium oxide, which stays behind, so the mass increases. The products of a burning candle, carbon dioxide and water vapour, are gases that escape."]], "2": [["Q2", "Na₂O, MgO, Al₂O₃, SiO₂, P₄O₁₀ and SO₂."], ["Q3", "Sodium: yellow flame. Magnesium: bright white flame. Phosphorus: white smoke of P₄O₁₀. Sulfur: blue flame, SO₂ gas."]], "3": [["Q4", "NaCl, MgCl₂, Al₂Cl₆ (AlCl₃ units joined in pairs), SiCl₄ and PCl₅."], ["Q5", "2Al + 3Cl₂ → Al₂Cl₆ [1]. The oxidation number of aluminium is +3 [1]."]], "4": [["Q6", "Na + cold water: NaOH and H₂, pH 13 to 14. Mg + cold water: Mg(OH)₂ and H₂, pH 9 to 10. Mg + steam: MgO and H₂."], ["Q7", "Sodium hydroxide is very soluble, but magnesium hydroxide is only slightly soluble [1], so the sodium hydroxide solution contains a much higher concentration of hydroxide ions [1]."]], "5": [["Q8", "Na +1; Mg +2; Al +3; Si +4; P +5 in both P₄O₁₀ and PCl₅; S +4 in SO₂ and +6 in SO₃."], ["Q9", "The highest oxidation number increases by one each time, from +1 in Na₂O to +6 in SO₃ [1]. It equals the number of outer-shell electrons of the element [1], because all of these electrons are used in bonding to oxygen [1]."]], "6": [["Exit ticket", "With cold water the reaction is very slow and the slightly soluble magnesium hydroxide that forms coats the metal. With steam the temperature is much higher, the reaction is fast and magnesium oxide forms instead of the hydroxide."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q5", "q4_1": "Q7", "q5_1": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Magnesium gains mass when it burns, but a candle loses mass. Suggest why, in terms of the products.", "Q2": "What is the formula of the oxide formed when the element burns in excess oxygen?", "Q3": "Which element burns as described?", "Q4": "What is the formula of the chloride formed with excess chlorine?", "Q5": "Write the equation for the reaction of aluminium with chlorine to form Al₂Cl₆, and state the oxidation number of aluminium in the product. Type it like this: 2Al + …", "Q6": "Choose the correct answer.", "Q7": "Explain why the solution formed when sodium reacts with water has a higher pH than the solution formed when magnesium reacts with water.", "Q8": "What is the oxidation number of the Period 3 element?", "Q9": "State and explain the pattern in the highest oxidation number of the elements in their oxides from sodium to sulfur."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '730e4fc6-23d2-54a6-950a-02ab96b7757d', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '9.2' limit 1), '9.2 Periodicity of chemical properties of the elements in Period 3 · Lesson 2: The oxides of Period 3: reactions with water, acid–base behaviour and amphoteric aluminium', 'A Level Chemistry · 9 The Periodic Table: chemical periodicity', '/achem-9-2-2/', 'ACHEM-9-2-2', 37, 60, 9022 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-9-2-2', '9.2 Periodicity of chemical properties of the elements in Period 3 · Lesson 2: The oxides of Period 3: reactions with water, acid–base behaviour and amphoteric aluminium', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 7, "n": 7, "ans": ["About 13 to 14", "About 9 to 10", "7 (no reaction)", "7 (no reaction)", "About 1 to 2", "About 1 to 2", "About 0 to 1"], "tip": "Alkaline on the left, nothing in the middle, acidic on the right."}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 5, "n": 5, "ans": ["NaOH", "Mg(OH)₂", "H₃PO₄", "H₂SO₃", "H₂SO₄"], "tip": "Metal oxides give hydroxides; non-metal oxides give acids."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 7, "n": 7, "ans": ["Basic", "Basic", "Amphoteric", "Amphoteric", "Acidic", "Acidic", "Acidic"], "tip": "Metal oxide, the one in between, or non-metal oxide."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["both"], ["acid", "hcl", "hydrochloric"], ["alkali", "base", "naoh", "sodium hydroxide"]], "tips": ["Two reactions are needed."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 6, "n": 6, "ans": ["Giant ionic", "Giant ionic", "Giant molecular", "Simple molecular", "Simple molecular", "Simple molecular"], "tip": "High melting point and basic, or low melting point and acidic?"}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["ionic"], ["oxide ion", "o2", "hydroxide", "accepts"], ["covalent"]], "tips": ["What particles does each oxide contain? Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["aluminium oxide", "al2o3"], ["amphoteric"], ["alcl3", "aluminium chloride"], ["naal oh 4", "naal(oh)4", "aluminate"], ["p4o10", "phosphorus"], ["phosphoric", "h3po4"]], "tips": ["Only one Period 3 oxide reacts with both acids and alkalis. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "Oxides of the metals (Na₂O, MgO) give alkaline solutions because they contain oxide ions, which react with water to form hydroxide ions. Oxides of the non-metals (P₄O₁₀, SO₂, SO₃) are covalent and react with water to form acids."]], "2": [["Q2", "Na₂O 13 to 14; MgO 9 to 10; Al₂O₃ and SiO₂ no reaction, 7; P₄O₁₀ and SO₂ 1 to 2; SO₃ 0 to 1."], ["Q3", "Na₂O gives NaOH; MgO gives Mg(OH)₂; P₄O₁₀ gives H₃PO₄; SO₂ gives H₂SO₃; SO₃ gives H₂SO₄."]], "3": [["Q4", "Na₂O and MgO are basic. Al₂O₃ and Al(OH)₃ are amphoteric. SiO₂, P₄O₁₀ and SO₃ are acidic."], ["Q5", "Amphoteric means reacting with both acids and bases [1]. Aluminium oxide dissolves in hydrochloric acid to form aluminium chloride [1] and also dissolves in aqueous sodium hydroxide to form sodium aluminate, NaAl(OH)₄ [1]."]], "4": [["Q6", "Na₂O and MgO: giant ionic. SiO₂: giant molecular. P₄O₁₀, SO₂ and SO₃: simple molecular."], ["Q7", "Sodium oxide is ionic [1]; its oxide ions react with water to form hydroxide ions (they accept protons) [1]. Sulfur trioxide is covalent and reacts with water to form an acid, H₂SO₄ [1]."]], "5": [["Q8", "(a) Aluminium oxide, Al₂O₃ [1]. (b) Amphoteric [1]. (c) With acid: AlCl₃ [1]; with alkali: NaAl(OH)₄, sodium aluminate [1]. (d) Y is P₄O₁₀, phosphorus(V) oxide [1], which forms phosphoric(V) acid, H₃PO₄ [1]."]], "6": [["Exit ticket", "Na₂O, MgO, Al₂O₃, P₄O₁₀, SO₃."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Predict which Period 3 oxides give alkaline solutions and which give acidic solutions. What is your reasoning?", "Q2": "What is the likely pH when the oxide is added to water?", "Q3": "What is formed when the oxide reacts with water?", "Q4": "Classify the oxide or hydroxide.", "Q5": "Explain what is meant by amphoteric, and describe how you could show that aluminium oxide is amphoteric.", "Q6": "What is the bonding and structure of the oxide?", "Q7": "Explain, in terms of bonding, why sodium oxide is basic but sulfur trioxide is acidic.", "Q8": "An oxide X of a Period 3 element is a white solid with a very high melting point. It does not dissolve in water, but it dissolves in both hydrochloric acid and aqueous sodium hydroxide. (a) Identify X. (b) Give the term used for this behaviour. (c) Give the formula of the aluminium-containing product in each reaction. (d) A different oxide, Y, is a white solid that reacts violently with water to give a solution of pH 1. Identify Y and name the acid formed."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '6298fb69-82ac-5611-a85b-d5fb00d1ac84', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '9.2' limit 1), '9.2 Periodicity of chemical properties of the elements in Period 3 · Lesson 3: The chlorides of Period 3: reactions with water, pH, and deducing bonding from properties', 'A Level Chemistry · 9 The Periodic Table: chemical periodicity', '/achem-9-2-3/', 'ACHEM-9-2-3', 24, 60, 9023 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-9-2-3', '9.2 Periodicity of chemical properties of the elements in Period 3 · Lesson 3: The chlorides of Period 3: reactions with water, pH, and deducing bonding from properties', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 2, "n": 2, "ans": ["Dissolves, pH 7", "Dissolves, pH about 6.5"], "tip": "Both are ionic."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["ionic", "ions"], ["no reaction", "not react", "no hydrolysis", "not hydrolysed", "do not react", "does not react", "neither ion", "neither reacts", "neither of"]], "tips": ["What happens to the ions in water?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["SiO₂ and HCl", "H₃PO₄ and HCl", "[Al(H₂O)₆]³⁺ and Cl⁻", "Na⁺(aq) and Cl⁻(aq)"], "tip": "The covalent chlorides are hydrolysed."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["sicl4 2h2o", "2h2o sicl4"], ["fumes", "steamy", "misty", "white gas"], ["white solid", "precipitate", "solid", "heat", "exothermic", "violent", "vigorous"]], "tips": ["One product is a gas that fumes in moist air; the other is a solid."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["Ionic", "Covalent", "Ionic", "Covalent", "Covalent"], "tip": "High melting point and neutral, or low melting point and acidic?"}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["large difference", "big difference", "greater difference", "much less electronegative", "larger difference", "difference is large"], ["small difference", "smaller difference", "similar", "closer", "difference is small", "less difference"]], "tips": ["Compare each element with chlorine."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["mgcl2", "magnesium chloride"], ["pcl5", "phosphorus"], ["ionic"], ["covalent"], ["pcl5 4h2o", "4h2o pcl5"], ["hydrogen chloride", "hcl"]], "tips": ["A is one of the two ionic chlorides; B is a solid covalent chloride. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "Sodium chloride is ionic with a giant lattice; silicon tetrachloride is made of small covalent molecules. Ions can simply separate and dissolve, but covalent molecules are likely to react with water (be hydrolysed) instead."]], "2": [["Q2", "NaCl dissolves to give a neutral solution. MgCl₂ dissolves to give a very slightly acidic solution, about pH 6.5."], ["Q3", "Sodium chloride is ionic: it simply separates into hydrated Na⁺ and Cl⁻ ions [1]. Neither ion reacts with water, so no H⁺ or OH⁻ ions are produced [1]."]], "3": [["Q4", "SiCl₄ gives SiO₂ and HCl. PCl₅ gives H₃PO₄ and HCl. Al₂Cl₆ gives the hydrated aluminium ion and chloride ions. NaCl just dissolves."], ["Q5", "SiCl₄ + 2H₂O → SiO₂ + 4HCl [1]. Steamy fumes of hydrogen chloride are given off [1] and a white solid forms in a violent, exothermic reaction [1]."]], "4": [["Q6", "High melting points, conduction when molten and neutral solutions: ionic (NaCl, MgCl₂). Low melting or boiling points, fuming and acidic solutions: covalent (Al₂Cl₆, SiCl₄, PCl₅)."], ["Q7", "There is a large difference in electronegativity between sodium and chlorine, so electrons are transferred [1]. Silicon is much closer to chlorine in electronegativity, so the difference is small and the electrons are shared [1]."]], "5": [["Q8", "(a) A is magnesium chloride, MgCl₂ [1]; B is phosphorus(V) chloride, PCl₅ [1]. (b) A is ionic [1]; B is covalent [1]. (c) PCl₅ + 4H₂O → H₃PO₄ + 5HCl [1]. (d) Hydrogen chloride [1]."]], "6": [["Exit ticket", "An ionic chloride dissolves, separating into hydrated ions, to give a neutral (or nearly neutral) solution. A covalent chloride is hydrolysed, reacting with water to give hydrogen chloride and an acidic solution."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Sodium chloride melts at 801 °C; silicon tetrachloride is a liquid that boils at 58 °C. What does this suggest about the bonding in each, and how might that affect what happens in water?", "Q2": "Choose the correct answer.", "Q3": "Explain why aqueous sodium chloride is neutral.", "Q4": "What are the products when the chloride reacts with excess water?", "Q5": "Write the equation for the reaction of silicon tetrachloride with water and describe two observations. Type it like this: SiCl4 + …", "Q6": "Use the properties to suggest the bonding in the chloride.", "Q7": "Explain, in terms of electronegativity, why sodium chloride is ionic but silicon tetrachloride is covalent.", "Q8": "Chloride A is a white solid that melts at 714 °C and dissolves in water to give a solution of pH 6.5. Chloride B is a pale yellow solid that reacts violently with water, giving steamy fumes and a solution of pH 1. (a) Identify A and B. (b) Suggest the type of bonding in each. (c) Write the equation for the reaction of B with water. (d) Identify the steamy fumes."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'cad6c6d8-6cae-5ab6-998a-c319f2ccf2b7', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '9.3' limit 1), '9.3 Chemical periodicity of other elements: Using periodic trends to predict the properties of an element and to identify an unknown element', 'A Level Chemistry · 9 The Periodic Table: chemical periodicity', '/achem-9-3/', 'ACHEM-9-3', 27, 60, 9030 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-9-3', '9.3 Chemical periodicity of other elements: Using periodic trends to predict the properties of an element and to identify an unknown element', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["RbCl", "SrO", "GeCl₄", "H₂Se", "NaAt"], "tip": "Copy the formula of the compound of the element above."}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 5, "n": 5, "ans": ["More vigorous than sodium", "Basic", "Acidic", "Hydrolysed, giving an acidic solution", "Dissolves, giving a neutral solution"], "tip": "Metal or non-metal? Ionic or covalent?"}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["Group 1", "Group 2", "Group 13", "Group 14", "Group 16", "Group 17"], "tip": "Use the formula of the oxide or chloride to find the oxidation number."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["magnesium", "mg"], ["qcl2", "oxidation number of 2", "two outer", "group 2", "2 outer"], ["metal", "conducts", "ionic", "6.5", "high melting"]], "tips": ["QCl₂ gives the oxidation number. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["phosphorus"], ["p4o10", "p2o5"]], "tips": ["Five outer electrons. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 6, "pts": [["ga2o3"], ["gacl3", "ga2cl6"], ["amphoteric"], ["fumes", "hydrolys", "reacts", "steamy"], ["acidic", "ph 3", "ph 2", "ph 1", "below 7", "less than 7"], ["metal", "delocalised"]], "tips": ["Reason from aluminium each time. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "GeO₂ and GeCl₄. Germanium has four outer electrons, like silicon, so its highest oxidation number is +4 and its compounds have the same formulas as SiO₂ and SiCl₄."]], "2": [["Q2", "RbCl (like NaCl), SrO (like MgO), GeCl₄ (like SiCl₄), H₂Se (like H₂S), NaAt (like NaCl)."], ["Q3", "Rubidium is more reactive than sodium. SrO is a basic metal oxide. SeO₃ is an acidic non-metal oxide, like SO₃. GeCl₄ is covalent and hydrolysed, like SiCl₄. RbCl is ionic and simply dissolves."]], "3": [["Q4", "MCl and violent reaction with water: Group 1. Basic MO: Group 2. Amphoteric M₂O₃: Group 13. Giant molecular with XO₂: Group 14. Acidic XO₂ and XO₃: Group 16. X₂ molecules forming X⁻: Group 17."]], "4": [["Q5", "Q is magnesium [1]. The formula QCl₂ shows an oxidation number of +2, so Q is in Group 2 [1]. It conducts, so it is a metal, and its chloride is ionic (high melting point, nearly neutral solution) [1]."], ["Q6", "Five outer electrons, so R is in Group 15: phosphorus [1]. Its highest oxide is P₄O₁₀ [1]."]], "5": [["Q7", "(a) Ga₂O₃ [1] and GaCl₃ (or Ga₂Cl₆) [1]. (b) Amphoteric, like aluminium oxide, the oxide of the element above it [1]. (c) It reacts with water (is hydrolysed), giving steamy fumes [1] and an acidic solution, about pH 3 [1]. (d) It conducts, because it is a metal with delocalised electrons [1]."]], "6": [["Exit ticket", "Group 16: the oxidation number is +6, so it has six outer electrons. The acidic oxide shows that it is a non-metal."]]}, "labels": {"q1_0": "Q1", "q4_0": "Q5", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Germanium is below silicon in Group 14. Predict the formula of its oxide and of its chloride, and say how you decided.", "Q2": "Predict the formula.", "Q3": "Predict the behaviour.", "Q4": "In which group is the element most likely to be?", "Q5": "Element Q is in Period 3. It is a solid that conducts electricity. Its chloride, QCl₂, is a white solid with a high melting point that dissolves in water to give a solution of pH 6.5. Identify Q and give two reasons.", "Q6": "Element R is in Period 3. Its successive ionisation energies show the first large jump after the fifth electron. Its chloride reacts violently with water. Identify R and predict the formula of its highest oxide.", "Q7": "Gallium, Ga, is below aluminium in Group 13. (a) Predict the formula of gallium oxide and of gallium chloride. (b) Predict whether gallium oxide is basic, amphoteric or acidic, and give your reason. (c) Predict what you would observe when gallium chloride is added to water, and the approximate pH. (d) Predict whether gallium conducts electricity, with a reason."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'ae4de3c6-bddb-546f-a3fc-0ab2d3c5f0b3', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '10.1' limit 1), '10.1 Similarities and trends in the properties of the Group 2 metals and their compounds · Lesson 1: The elements magnesium to barium: reactions with oxygen, water and dilute acids, and the trend in reactivity', 'A Level Chemistry · 10 Group 2', '/achem-10-1-1/', 'ACHEM-10-1-1', 28, 60, 10011 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-10-1-1', '10.1 Similarities and trends in the properties of the Group 2 metals and their compounds · Lesson 1: The elements magnesium to barium: reactions with oxygen, water and dilute acids, and the trend in reactivity', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["Bright white", "Brick red", "Crimson", "Pale green", "MgO", "BaO"], "tip": "One M²⁺ ion needs one O²⁻ ion."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["2ca o2", "o2 2ca"], ["0 to 2", "0 to plus 2", "zero to", "from 0"]], "tips": ["Two calcium atoms react with one oxygen molecule."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["MgO and H₂", "Mg(OH)₂ and H₂", "Ca(OH)₂ and H₂", "Ba(OH)₂ and H₂"], "tip": "Cold water gives the hydroxide; steam gives the oxide."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["fizz", "bubbl", "efferves", "gas"], ["white", "cloudy", "milky", "disappears", "dissolves", "gets smaller", "sinks", "warm", "heat"], ["ca 2h2o", "2h2o ca"]], "tips": ["A gas, the appearance of the liquid, then the equation."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["Rapid fizzing; the metal dissolves completely", "Rapid fizzing; the metal dissolves completely", "Rapid fizzing; the metal dissolves completely", "Fizzing soon slows or stops as a white solid coats the metal", "Fizzing soon slows or stops as a white solid coats the metal"], "tip": "Is the salt that forms soluble?"}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["insoluble"], ["layer", "coat", "cover", "barrier", "surface", "prevents", "stops the acid"]], "tips": ["Think about the solubility of the two salts."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["increase", "more reactive", "more vigorous"], ["radius", "larger atom", "bigger atom", "more shells", "further from"], ["shielding", "shielded", "screening"], ["ionisation energ", "weaker attraction", "less attraction", "lost more easily", "lose electrons more easily", "easier to lose", "less energy"], ["very vigorous", "violent", "more vigorous", "faster", "rapid", "explosive"], ["ra oh 2"]], "tips": ["(b) radius, shielding, then the effect on losing electrons. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "Barium reacts quickly with oxygen and water vapour in the air, so it must be kept away from them. Magnesium reacts so slowly at room temperature that a thin oxide layer is enough to protect it. Barium is much more reactive."]], "2": [["Q2", "Mg bright white; Ca brick red; Sr crimson; Ba pale green. The oxides are MgO and BaO."], ["Q3", "2Ca + O₂ → 2CaO [1]. The oxidation number of calcium changes from 0 to +2 [1]."]], "3": [["Q4", "Steam gives MgO and H₂. Cold water gives the hydroxide and hydrogen: Mg(OH)₂, Ca(OH)₂ or Ba(OH)₂."], ["Q5", "The calcium fizzes steadily as bubbles of hydrogen form [1], and the water turns cloudy white as calcium hydroxide forms [1]. Ca + 2H₂O → Ca(OH)₂ + H₂ [1]."]], "4": [["Q6", "All the chlorides and magnesium sulfate are soluble, so those reactions go to completion. Strontium and barium sulfates are insoluble and coat the metal."], ["Q7", "Barium chloride is soluble, but barium sulfate is insoluble [1]. The barium sulfate forms a layer on the surface of the metal that stops the acid reaching it [1]."]], "5": [["Q8", "(a) Reactivity increases down the group [1]. (b) The atomic radius increases [1] and there is more shielding by inner shells [1], so the ionisation energies decrease and the two outer electrons are lost more easily [1]. (c) Radium reacts very vigorously, faster than barium [1], forming Ra(OH)₂ and hydrogen [1]."]], "6": [["Exit ticket", "M + 2H₂O → M(OH)₂ + H₂. Calcium: it reacts steadily enough to see in a lesson, unlike magnesium, which is far too slow, and it is less violent than strontium or barium."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Barium is stored under oil, but magnesium ribbon is kept in an ordinary jar. Suggest what this tells you about the two metals.", "Q2": "Choose the correct answer.", "Q3": "Write the equation for the burning of calcium in oxygen and state the change in oxidation number of calcium. Type it like this: 2Ca + …", "Q4": "What are the products?", "Q5": "Describe what you would see when a small piece of calcium is added to cold water, and write the equation. Type it like this: Ca + …", "Q6": "What happens?", "Q7": "Explain why barium reacts rapidly with dilute hydrochloric acid, but its reaction with dilute sulfuric acid soon stops.", "Q8": "(a) State the trend in reactivity of the Group 2 metals with water from magnesium to barium. (b) Explain the trend. (c) Predict how radium, the element below barium, reacts with cold water, and give the formula of the radium-containing product."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '80138584-022b-5c77-8db1-c8f02866e2da', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '10.1' limit 1), '10.1 Similarities and trends in the properties of the Group 2 metals and their compounds · Lesson 2: The oxides, hydroxides, carbonates and nitrates: reactions, thermal decomposition and solubility trends', 'A Level Chemistry · 10 Group 2', '/achem-10-1-2/', 'ACHEM-10-1-2', 28, 60, 10012 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-10-1-2', '10.1 Similarities and trends in the properties of the Group 2 metals and their compounds · Lesson 2: The oxides, hydroxides, carbonates and nitrates: reactions, thermal decomposition and solubility trends', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["Mg(OH)₂", "Ba(OH)₂", "About pH 9 to 10", "About pH 13", "A salt and water only", "A salt and water only"], "tip": "Hydroxides: more soluble down the group."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["more soluble", "solubility increases", "less soluble", "insoluble", "sparingly"], ["hydroxide ions", "oh", "higher concentration", "more alkaline"]], "tips": ["Compare the solubility of the two hydroxides."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["No change", "Fizzing; the solid dissolves completely", "Fizzing; the solid dissolves completely", "Fizzing that soon stops, with solid left"], "tip": "Is the sulfate soluble?"}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 1, "pts": [["srco3 2hcl", "2hcl srco3"]], "tips": ["Salt, carbon dioxide and water."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 6, "n": 6, "ans": ["MO and CO₂", "MO, NO₂ and O₂", "Brown gas", "Colourless gas that turns limewater milky", "Magnesium carbonate", "Barium carbonate"], "tip": "Stability increases down the group."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["2mgo"], ["4no2"], ["brown"]], "tips": ["Three products; one is a coloured gas."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["hydroxides increase", "hydroxides become more", "hydroxides get more", "hydroxide increases", "hydroxides more soluble", "hydroxides: increase", "solubility of the hydroxides increases"], ["sulfates decrease", "sulfates become less", "sulfates get less", "sulfate decreases", "sulfates less soluble", "solubility of the sulfates decreases"], ["white precipitate", "white solid", "white ppt"], ["baso4"], ["higher"], ["caco3 cao", "cao co2"]], "tips": ["The two trends go in opposite directions. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "They are bases, so they neutralise the acid in the soil and raise its pH. Calcium carbonate and calcium hydroxide are cheap and only slightly soluble, so they act slowly and safely; sodium hydroxide is very soluble and corrosive and would make the soil far too alkaline."]], "2": [["Q2", "Mg(OH)₂ is the least soluble and Ba(OH)₂ the most. MgO in water gives about pH 9 to 10; BaO gives about pH 13. Oxides and hydroxides with acids give a salt and water only."], ["Q3", "Barium hydroxide is much more soluble than magnesium hydroxide [1], so the solution contains a much higher concentration of hydroxide ions [1]."]], "3": [["Q4", "Carbonates do not dissolve in water. With hydrochloric acid, and magnesium carbonate with sulfuric acid, the salt is soluble so the reaction finishes. Barium sulfate is insoluble and coats the barium carbonate."], ["Q5", "SrCO₃ + 2HCl → SrCl₂ + CO₂ + H₂O [1]."]], "4": [["Q6", "Carbonates give the oxide and CO₂; nitrates give the oxide, brown NO₂ and O₂. Magnesium carbonate decomposes most easily; barium carbonate is the most stable."], ["Q7", "2Mg(NO₃)₂ → 2MgO [1] + 4NO₂ + O₂ [1]. A brown gas, nitrogen dioxide, is given off [1]."]], "5": [["Q8", "(a) The solubility of the hydroxides increases down the group [1]; the solubility of the sulfates decreases [1]. (b) A white precipitate forms [1] of BaSO₄ [1]. (c) Higher, because thermal stability increases down the group [1]. CaCO₃ → CaO + CO₂ [1]."]], "6": [["Exit ticket", "Barium hydroxide is much more soluble, so it would give a strongly alkaline, corrosive solution (and soluble barium compounds are poisonous). Magnesium hydroxide is almost insoluble, so the mixture is only weakly alkaline and safe to swallow."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Farmers spread powdered limestone or slaked lime on acidic soil. Suggest what these compounds do, and why a carbonate or hydroxide is chosen instead of sodium hydroxide.", "Q2": "Choose the correct answer.", "Q3": "Explain why the solution formed when barium oxide is added to water has a higher pH than the mixture formed when magnesium oxide is added to water.", "Q4": "What would you observe?", "Q5": "Write the equation for the reaction of strontium carbonate with dilute hydrochloric acid. Type it like this: SrCO3 + …", "Q6": "Choose the correct answer.", "Q7": "Write the equation for the thermal decomposition of magnesium nitrate, and describe one observation. Type it like this: 2Mg(NO3)2 → …", "Q8": "(a) State the trend in solubility of the Group 2 hydroxides and of the Group 2 sulfates down the group. (b) Aqueous barium chloride is added to dilute sulfuric acid. State what is seen and give the formula of the solid. (c) Predict whether radium carbonate decomposes at a higher or lower temperature than barium carbonate, and write the equation for the decomposition of calcium carbonate."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'b678609b-7c33-5811-b7da-6ecc3fe45a67', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '11.1' limit 1), '11.1 Physical properties of the Group 17 elements: Colours, volatility and bond strength of chlorine, bromine and iodine', 'A Level Chemistry · 11 Group 17', '/achem-11-1/', 'ACHEM-11-1', 28, 60, 11010 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-11-1', '11.1 Physical properties of the Group 17 elements: Colours, volatility and bond strength of chlorine, bromine and iodine', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["Chlorine", "Bromine", "Iodine", "Iodine", "Bromine", "Iodine"], "tip": "The colours darken down the group."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Chlorine", "Iodine", "Iodine", "Forces between molecules", "Covalent bonds within molecules"], "tip": "Boiling separates molecules; it does not split them."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 3, "pts": [["more electrons"], ["instantaneous", "induced dipole", "id-id", "london", "dispersion", "van der waals", "intermolecular"], ["stronger", "more energy"]], "tips": ["Electrons, the name of the forces, then the energy needed."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Cl₂", "Br₂", "I₂", "I₂", "Br₂"], "tip": "Bond strength falls down the group; boiling point rises."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 3, "pts": [["larger", "bigger", "greater radius", "longer bond", "more shells"], ["further", "shield", "distance", "farther"], ["weaker attraction", "less attraction", "attraction is weaker", "attracted less", "less strongly", "weaker force", "attraction+weaker", "attraction+less"]], "tips": ["Size, the position of the bonding pair, then the attraction."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 6, "pts": [["solid"], ["black", "dark", "darker"], ["less volatile", "lower volatility", "higher boiling"], ["more electrons"], ["weaker", "lower", "smaller", "less than"], ["larger", "bigger", "further", "shield"]], "tips": ["Continue each trend one step further."]}]}, "models": {"1": [["Q1", "The molecules get larger down the group and contain more electrons, so the forces of attraction between the molecules get stronger. More energy is needed to separate them, so the melting and boiling points rise."]], "2": [["Q2", "Chlorine: pale green gas. Bromine: red-brown liquid, orange in solution. Iodine: grey-black solid, purple vapour, brown in solution."]], "3": [["Q3", "Chlorine is the most volatile, iodine the least. Iodine has the most electrons per molecule. Boiling overcomes forces between molecules; splitting into atoms breaks the covalent bond."], ["Q4", "An iodine molecule has more electrons than a chlorine molecule [1], so the instantaneous dipole–induced dipole forces between iodine molecules [1] are stronger and need more energy to overcome [1]."]], "4": [["Q5", "Bond energy: Cl₂ > Br₂ > I₂. Bond length: I₂ is longest. Boiling point and intermolecular forces: I₂ > Br₂ > Cl₂."], ["Q6", "Bromine atoms are larger than chlorine atoms [1], so the bonding pair is further from the nuclei and more shielded [1]. The attraction between the nuclei and the bonding pair is weaker [1]."]], "5": [["Q7", "(a) A solid [1], black or very dark [1]. (b) Less volatile than iodine [1], because an At₂ molecule has more electrons, so the instantaneous dipole–induced dipole forces are stronger [1]. (c) The At–At bond is weaker [1], because the atoms are larger, so the bonding pair is further from the nuclei and more shielded [1]."]], "6": [["Exit ticket", "The I–I bond is actually the weakest of the three, and it is not broken when iodine boils. Iodine has the highest boiling point because its molecules have the most electrons, so the instantaneous dipole–induced dipole forces between the molecules are the strongest."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Chlorine, bromine and iodine are all X₂ molecules. Suggest why they have different states at room temperature.", "Q2": "Match the description to the halogen.", "Q3": "Choose the correct answer.", "Q4": "Explain why iodine is less volatile than chlorine.", "Q5": "Which has the larger value?", "Q6": "Explain why the Br–Br bond is weaker than the Cl–Cl bond.", "Q7": "Astatine, At, is below iodine in Group 17. (a) Predict the state and appearance of astatine at room temperature. (b) Predict whether astatine is more or less volatile than iodine, and explain your answer. (c) Predict how the At–At bond energy compares with the I–I bond energy, and explain your answer."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '3a46a46b-195d-5148-9236-af4aa5a28808', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '11.2' limit 1), '11.2 The chemical properties of the halogen elements and the hydrogen halides: Halogens as oxidising agents, their reactions with hydrogen, and the thermal stability of the hydrogen halides', 'A Level Chemistry · 11 Group 17', '/achem-11-2/', 'ACHEM-11-2', 31, 60, 11020 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-11-2', '11.2 The chemical properties of the halogen elements and the hydrogen halides: Halogens as oxidising agents, their reactions with hydrogen, and the thermal stability of the hydrogen halides', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["Turns orange", "Turns brown", "Turns brown", "No reaction", "No reaction", "No reaction"], "tip": "A halogen displaces only those below it."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 4, "pts": [["cl2 2br", "2br cl2"], ["smaller"], ["shielding", "shielded", "fewer shells", "closer to the nucleus", "nearer"], ["attract", "gain"]], "tips": ["Size, shielding, then the attraction for an extra electron."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Chlorine", "Bromine", "Iodine", "Chlorine", "Iodine"], "tip": "Reactivity falls down the group."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["h2 br2", "br2 h2"], ["0 to", "from 0", "zero to"]], "tips": ["Bromine is reduced."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["HCl", "HI", "Purple fumes", "No change", "HI"], "tip": "The weaker the bond, the easier the decomposition."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["larger", "bigger", "longer"], ["weaker", "lower bond energy", "smaller bond energy", "299"], ["less energy", "easier to break", "more easily broken", "breaks more easily"]], "tips": ["Size of the atom, strength of the bond, energy needed."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["brown"], ["br2 2i", "2i br2"], ["bromine is the oxidising", "oxidising agent is bromine", "oxidising agent: bromine", "br2 is the oxidising", "oxidising agent is br2", "bromine oxidises"], ["iodide"], ["no reaction", "nothing", "no change", "does not react"], ["weaker oxidising", "less reactive", "less oxidising", "cannot oxidise", "not strong enough", "chlorine is a stronger", "chlorine is more reactive"]], "tips": ["(d) compare bromine with chlorine."]}]}, "models": {"1": [["Q1", "Bromine has been formed, which is orange in solution. Chlorine has taken electrons from the bromide ions: it has oxidised them to bromine and has itself been reduced to chloride ions."]], "2": [["Q2", "Chlorine displaces bromine (orange) and iodine (brown). Bromine displaces iodine (brown). Bromine cannot displace chlorine, and iodine displaces neither."], ["Q3", "Cl₂ + 2Br⁻ → 2Cl⁻ + Br₂ [1]. A chlorine atom is smaller than a bromine atom [1] and its outer shell has less shielding [1], so its nucleus attracts an extra electron more strongly [1]."]], "3": [["Q4", "Chlorine explodes in sunlight and forms the strongest H–X bond. Bromine needs heat and a catalyst. Iodine reacts slowly and reversibly and forms the weakest H–X bond."], ["Q5", "H₂ + Br₂ → 2HBr [1]. The oxidation number of bromine changes from 0 to −1 [1]."]], "4": [["Q6", "HCl is the most stable and does not change with a hot wire. HI has the longest, weakest bond, is the least stable and gives purple iodine vapour."], ["Q7", "An iodine atom is larger than a chlorine atom, so the H–I bond is longer [1] and weaker (299 compared with 431 kJ mol⁻¹) [1]. Less energy is needed to break it [1]."]], "5": [["Q8", "(a) The solution turns brown [1]. (b) Br₂ + 2I⁻ → 2Br⁻ + I₂ [1]. (c) Bromine is the oxidising agent [1]; iodide ions are oxidised [1]. (d) No reaction [1], because bromine is a weaker oxidising agent than chlorine, so it cannot oxidise chloride ions [1]."]], "6": [["Exit ticket", "Fluorine is the strongest oxidising agent of all the halogens, so it reacts explosively with hydrogen, even in the cold and dark. The H–F bond is the shortest and strongest, so hydrogen fluoride is the most thermally stable hydrogen halide."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Chlorine water turns a colourless solution of potassium bromide orange. Suggest what has been formed and what the chlorine has done.", "Q2": "What is observed when the solutions are mixed?", "Q3": "Write the ionic equation for the reaction of chlorine with bromide ions, and explain why chlorine is a stronger oxidising agent than bromine. Type the equation like this: Cl2 + …", "Q4": "Which halogen reacts with hydrogen in this way?", "Q5": "Write the equation for the reaction of hydrogen with bromine, and state the oxidation number of bromine before and after. Type the equation like this: H2 + …", "Q6": "Choose the correct answer.", "Q7": "Explain why hydrogen iodide decomposes much more easily than hydrogen chloride when heated.", "Q8": "Bromine water is added to aqueous potassium iodide. (a) State what is seen. (b) Write the ionic equation. Type it like this: Br2 + … (c) Identify the oxidising agent and the species that is oxidised. (d) State and explain what happens when bromine water is added to aqueous potassium chloride."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '7bb6abe8-0a00-562d-b9ad-f1f4579ee3cb', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '11.3' limit 1), '11.3 Some reactions of the halide ions · Lesson 1: Halide ions as reducing agents, and the silver nitrate and ammonia test', 'A Level Chemistry · 11 Group 17', '/achem-11-3-1/', 'ACHEM-11-3-1', 28, 60, 11031 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-11-3-1', '11.3 Some reactions of the halide ions · Lesson 1: Halide ions as reducing agents, and the silver nitrate and ammonia test', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Iodide", "Chloride", "Iodide", "Chloride", "Bromide"], "tip": "Larger ion, electron lost more easily."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["larger", "bigger", "more shells", "greater radius"], ["further", "shield", "farther", "distance"], ["lost more easily", "lose electrons more easily", "loses an electron more easily", "easier to lose", "weaker attraction", "less attraction", "more easily lost", "more readily", "lose an electron more easily", "loses electrons more easily"]], "tips": ["Size, distance and shielding, then losing the electron."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["White precipitate", "Cream precipitate", "Yellow precipitate", "No precipitate"], "tip": "The colours darken from chloride to iodide."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["ag aq br aq", "br aq ag aq"], ["agbr s"], ["carbonate", "other ions", "interfer", "false", "hydroxide", "impurit"]], "tips": ["Two aqueous ions make one solid."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["Dissolves", "Does not dissolve", "Dissolves", "Does not dissolve", "Does not dissolve"], "tip": "Solubility in ammonia falls from chloride to iodide."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["complex", "soluble ion"], ["ag nh3 2"]], "tips": ["Two ammonia molecules bond to each silver ion. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["ammonia", "nh3"], ["chloride dissolves", "agcl dissolves", "dissolves in dilute", "dissolves if chloride", "chloride: dissolves", "white precipitate dissolves", "dissolve in dilute"], ["concentrated", "does not dissolve in dilute", "insoluble in dilute", "not dissolve in dilute"], ["agbr"], ["iodide"], ["no change", "does not dissolve", "insoluble", "remains", "stays", "not dissolve"]], "tips": ["Dilute ammonia first, then concentrated."]}]}, "models": {"1": [["Q1", "Iodide. Chlorine holds on to an extra electron most strongly, so chloride gives it up least easily. Iodide ions are the largest, their outer electrons are furthest from the nucleus and most shielded, so they lose an electron most easily."]], "2": [["Q2", "Iodide is the largest ion and the strongest reducing agent. Chloride is the weakest. Bromide reduces chlorine only."], ["Q3", "An iodide ion is larger than a chloride ion [1], so its outer electrons are further from the nucleus and more shielded [1]. The attraction is weaker, so an electron is lost more easily [1]."]], "3": [["Q4", "Chloride: white. Bromide: cream. Iodide: yellow. Nitrate ions give no precipitate."], ["Q5", "Ag⁺(aq) + Br⁻(aq) [1] → AgBr(s) [1]. Nitric acid removes ions such as carbonate, which would also give a precipitate with silver ions [1]."]], "4": [["Q6", "AgCl dissolves in dilute ammonia. AgBr dissolves only in concentrated ammonia. AgI dissolves in neither."], ["Q7", "Ammonia reacts with the silver ions to form a soluble complex ion [1], [Ag(NH₃)₂]⁺ [1]."]], "5": [["Q8", "(a) Add dilute aqueous ammonia [1]. If the precipitate dissolves in dilute ammonia, X contains chloride [1]; if it dissolves only in concentrated ammonia, X contains bromide [1]. (b) AgBr [1]. (c) Iodide [1]; the precipitate does not dissolve [1]."]], "6": [["Exit ticket", "Iodide. Silver iodide is yellow and is insoluble in both dilute and concentrated aqueous ammonia."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Chlorine is the strongest oxidising agent of the three halogens. Predict which halide ion is the strongest reducing agent, and say why.", "Q2": "Choose the correct answer.", "Q3": "Explain why iodide ions are stronger reducing agents than chloride ions.", "Q4": "What is seen when acidified aqueous silver nitrate is added?", "Q5": "Write the ionic equation, with state symbols, for the reaction of aqueous silver nitrate with aqueous sodium bromide, and explain why dilute nitric acid is added first. Type the equation like this: Ag+(aq) + …", "Q6": "What happens to the precipitate?", "Q7": "Explain why silver chloride dissolves in aqueous ammonia, and give the formula of the silver-containing ion formed.", "Q8": "A solution X contains one sodium halide. Dilute nitric acid and aqueous silver nitrate are added, and a pale precipitate forms that could be white or cream. (a) Describe a further test, with the result for each possibility, that shows whether X contains chloride or bromide ions. (b) Give the formula of the precipitate if X is sodium bromide. (c) A different solution, Y, gives a yellow precipitate. Identify the halide ion in Y and state the effect of concentrated aqueous ammonia on the precipitate."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '1973c091-929e-5805-888f-7314b9b00ea5', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '11.3' limit 1), '11.3 Some reactions of the halide ions · Lesson 2: Reactions of solid halides with concentrated sulfuric acid', 'A Level Chemistry · 11 Group 17', '/achem-11-3-2/', 'ACHEM-11-3-2', 27, 60, 11032 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-11-3-2', '11.3 Some reactions of the halide ions · Lesson 2: Reactions of solid halides with concentrated sulfuric acid', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Steamy fumes", "HCl", "Acid–base only"], "tip": "Chloride is the weakest reducing agent."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["nacl h2so4", "h2so4 nacl"], ["weak reducing", "not strong enough", "too weak", "cannot reduce", "weakest reducing", "not a strong enough", "poor reducing", "not oxidised", "cannot be oxidised"]], "tips": ["The other product is sodium hydrogensulfate."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["HBr", "Br₂", "SO₂", "+6 to +4", "−1 to 0"], "tip": "Bromide reduces the sulfur by two."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["2hbr h2so4", "h2so4 2hbr"], ["hbr is the reducing", "bromide", "reducing agent is hbr", "hydrogen bromide is the reducing", "reducing agent is hydrogen bromide", "reducing agent: hbr"]], "tips": ["The products are bromine, sulfur dioxide and water."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["HI", "I₂", "S", "H₂S"], "tip": "Sulfur is yellow; hydrogen sulfide smells of bad eggs."}, {"kind": "choice", "id": "q4_1", "q": "Q7", "max": 5, "n": 5, "ans": ["+6", "+4", "0", "−2", "+6"], "tip": "Hydrogen +1, oxygen −2."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["steamy", "misty", "white fumes"], ["purple", "black solid", "violet"], ["yellow solid", "bad egg", "rotten egg", "smell", "sulfur"], ["8hi h2so4", "h2so4 8hi"], ["stronger reducing", "better reducing", "more powerful reducing", "weaker reducing", "strong reducing"], ["reduce", "oxidised"]], "tips": ["(d) compare the reducing power of the two ions."]}]}, "models": {"1": [["Q1", "Chloride ions are too weak to reduce the acid, so only an acid–base reaction happens and hydrogen chloride is given off. Iodide ions are strong enough to reduce the sulfur in the acid, so iodine forms together with reduction products of sulfur."]], "2": [["Q2", "Steamy fumes of HCl in an acid–base reaction. No chlorine is formed."], ["Q3", "NaCl + H₂SO₄ → NaHSO₄ + HCl [1]. Chloride ions are too weak as reducing agents to reduce sulfuric acid, so they are not oxidised to chlorine [1]."]], "3": [["Q4", "Steamy fumes of HBr, brown fumes of Br₂, and SO₂. Sulfur goes from +6 to +4; bromine from −1 to 0."], ["Q5", "2HBr + H₂SO₄ → Br₂ + SO₂ + 2H₂O [1]. The reducing agent is HBr (the bromide ion) [1]."]], "4": [["Q6", "Steamy fumes: HI. Purple fumes and black solid: I₂. Yellow solid: sulfur. Bad-egg smell: H₂S."], ["Q7", "H₂SO₄ and NaHSO₄: +6. SO₂: +4. S: 0. H₂S: −2."]], "5": [["Q8", "(a) Steamy fumes [1]. (b) Purple fumes or a black solid [1]; a yellow solid or a smell of bad eggs [1]. (c) 8HI + H₂SO₄ → 4I₂ + H₂S + 4H₂O [1]. (d) Iodide ions are much stronger reducing agents than chloride ions [1], so they reduce the sulfuric acid and are oxidised to iodine, while chloride ions cannot [1]."]], "6": [["Exit ticket", "Chloride ions do not reduce the acid, so hydrogen chloride comes off unchanged. Iodide ions are strong reducing agents: the hydrogen iodide formed is immediately oxidised to iodine by the sulfuric acid, so very little hydrogen iodide escapes."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Iodide ions are much stronger reducing agents than chloride ions. Predict how this might change what happens with concentrated sulfuric acid.", "Q2": "Sodium chloride with concentrated sulfuric acid: choose the correct answer.", "Q3": "Write the equation for the reaction of solid sodium chloride with concentrated sulfuric acid, and explain why no chlorine is formed. Type the equation like this: NaCl + …", "Q4": "Sodium bromide with concentrated sulfuric acid: choose the correct answer.", "Q5": "Write the equation for the reaction in which hydrogen bromide reduces concentrated sulfuric acid, and identify the reducing agent. Type the equation like this: 2HBr + …", "Q6": "Sodium iodide with concentrated sulfuric acid: what causes the observation?", "Q7": "What is the oxidation number of sulfur?", "Q8": "Concentrated sulfuric acid is added to separate samples of solid sodium chloride and solid sodium iodide. (a) State one observation that is the same for both. (b) State two observations seen only with sodium iodide. (c) Write the equation for the reaction of hydrogen iodide with sulfuric acid in which hydrogen sulfide is formed. Type it like this: 8HI + … (d) Explain the difference between the two halides."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'af30860f-78bb-51d2-b55a-b33f393461e7', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '11.4' limit 1), '11.4 The reactions of chlorine: Disproportionation of chlorine in cold and hot aqueous sodium hydroxide, and chlorine in water purification', 'A Level Chemistry · 11 Group 17', '/achem-11-4/', 'ACHEM-11-4', 28, 60, 11040 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-11-4', '11.4 The reactions of chlorine: Disproportionation of chlorine in cold and hot aqueous sodium hydroxide, and chlorine in water purification', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["0", "−1", "+1", "+1", "−1"], "tip": "Sodium is +1 and oxygen is −2."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["cl2 2naoh", "2naoh cl2", "cl2 2oh"], ["oxidised"], ["reduced"]], "tips": ["Give the oxidation number of chlorine in each product."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["NaClO", "NaClO₃", "+5", "Sodium chlorate(V)", "Sodium chlorate(I)"], "tip": "The Roman numeral is the oxidation number of chlorine."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["0 to 5", "increases by 5", "up by 5", "goes up by 5", "loses 5", "plus 5", "rises by 5"], ["0 to 1", "decreases by 1", "down by 1", "each gain", "gains 1", "goes down by 1", "five chlorine", "5 chlorine", "falls by 1"]], "tips": ["The total increase must equal the total decrease."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["HCl and HOCl", "HOCl and ClO⁻", "+1", "−1"], "tip": "Water behaves like cold dilute alkali."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["cl2 h2o", "h2o cl2"], ["hocl", "hclo", "chloric"], ["clo-", "ocl", "chlorate i", "chlorate(i)", "clo "]], "tips": ["One product is hydrochloric acid."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["same element", "same species", "one element", "same substance"], ["oxidised and reduced", "reduced and oxidised", "both oxidised", "oxidation and reduction", "reduction and oxidation"], ["nacl "], ["naclo3"], ["is 5", "at 5", "plus 5", "of 5", "5 in", "naclo3 5", "number 5", "to 5"], ["cold", "lower temperature", "dilute", "cool", "room temperature"]], "tips": ["(b) one product has chlorine at −1, the other at +5. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "The concentration used is very low, too low to harm people but high enough to kill the bacteria that cause diseases such as cholera and typhoid. The benefit of preventing these diseases is far greater than the small risk."]], "2": [["Q2", "Cl₂: 0. NaCl and HCl: −1. NaClO and ClO⁻: +1."], ["Q3", "Cl₂ + 2NaOH → NaCl + NaClO + H₂O [1]. Chlorine is oxidised from 0 to +1 in NaClO [1] and reduced from 0 to −1 in NaCl in the same reaction [1]."]], "3": [["Q4", "Cold: NaClO, sodium chlorate(I), chlorine +1. Hot: NaClO₃, sodium chlorate(V), chlorine +5."], ["Q5", "One chlorine atom is oxidised from 0 to +5, an increase of 5 [1]. Each chlorine atom that is reduced goes from 0 to −1, so five of them are needed to balance it [1]."]], "4": [["Q6", "Cl₂ + H₂O ⇌ HCl + HOCl. HOCl and ClO⁻ kill bacteria. Chlorine is +1 in HOCl and −1 in HCl."], ["Q7", "Cl₂ + H₂O ⇌ HCl + HOCl [1]. The active species are HOCl, chloric(I) acid [1], and the chlorate(I) ion, ClO⁻ [1]."]], "5": [["Q8", "(a) A reaction in which the same element [1] is both oxidised and reduced [1]. (b) NaCl, with chlorine at −1 [1], and NaClO₃ [1], with chlorine at +5 [1]. (c) Use cold, dilute sodium hydroxide [1]."]], "6": [["Exit ticket", "Chlorine with cold, dilute aqueous sodium hydroxide: Cl₂ + 2NaOH → NaCl + NaClO + H₂O. The oxidation number of chlorine in NaClO is +1."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Chlorine is toxic. Suggest why adding it to drinking water is still considered a good idea.", "Q2": "What is the oxidation number of chlorine?", "Q3": "Write the equation for the reaction of chlorine with cold aqueous sodium hydroxide, and explain why it is a disproportionation reaction. Type the equation like this: Cl2 + …", "Q4": "Choose the correct answer.", "Q5": "In the reaction 3Cl₂ + 6NaOH → 5NaCl + NaClO₃ + 3H₂O, explain in terms of oxidation numbers why five NaCl form for every one NaClO₃.", "Q6": "Choose the correct answer.", "Q7": "Write the equation for the reaction of chlorine with water, and name the two species that kill bacteria. Type the equation like this: Cl2 + …", "Q8": "(a) Define disproportionation. (b) Chlorine is bubbled into hot, concentrated aqueous sodium hydroxide. Give the formulas of the two chlorine-containing products and the oxidation number of chlorine in each. (c) State one condition that must be changed to make NaClO instead."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '0c25453d-63b8-5f37-8b00-d5b99225e1c5', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '12.1' limit 1), '12.1 Nitrogen and sulfur · Lesson 1: The unreactivity of nitrogen, ammonia as a base, the ammonium ion and the displacement of ammonia', 'A Level Chemistry · 12 Nitrogen and sulfur', '/achem-12-1-1/', 'ACHEM-12-1-1', 28, 60, 12011 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-12-1-1', '12.1 Nitrogen and sulfur · Lesson 1: The unreactivity of nitrogen, ammonia as a base, the ammonium ion and the displacement of ammonia', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Triple", "Non-polar", "Very high", "Very high"], "tip": "Strong bond, no polarity."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["triple"], ["strong", "944", "high bond energy", "large amount of energy", "lot of energy", "high activation"], ["non-polar", "not polar", "no dipole", "nonpolar", "no polarity", "lack of polarity"]], "tips": ["Two reasons: the bond and the polarity."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 3, "n": 3, "ans": ["NH₃", "NH₃", "OH⁻"], "tip": "The base accepts the proton."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["proton acceptor", "accepts a proton", "accepts protons", "accepts h", "accept a proton", "accepts an h", "accepts a hydrogen ion", "gains a proton"], ["lone pair"], ["nh3 h2o", "h2o nh3"]], "tips": ["What does the nitrogen atom use to bond to H⁺?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 6, "n": 6, "ans": ["NH₃", "NH₄⁺", "NH₃", "NH₄⁺", "NH₄⁺", "Both"], "tip": "Four bonding pairs and no lone pairs give a tetrahedron."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["coordinate", "dative", "lone pair"], ["tetrahedral"], ["109"]], "tips": ["What does the lone pair do?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["ammonia", "nh3"], ["ammonium", "nh4"], ["nh4 oh", "oh nh4"], ["ammonium ion is the acid", "nh4 is the acid", "acid is nh4", "acid is the ammonium", "acid: nh4", "acid is ammonium", "ammonium is the acid", "nh4 acid"], ["hydroxide ion is the base", "oh is the base", "base is oh", "base is the hydroxide", "base: oh", "base is hydroxide", "hydroxide is the base", "oh base"], ["lost", "escapes", "wasted", "given off", "released", "displace"]], "tips": ["(d) what would the two substances do to each other?"]}]}, "models": {"1": [["Q1", "Nitrogen is very unreactive, so it does not react with the food. Air contains oxygen, which would oxidise the fats in the crisps and make them go stale. Nitrogen is also cheap, because it is obtained from the air."]], "2": [["Q2", "N₂ has a triple bond with a very high bond energy, so reactions have a very high activation energy. The molecule is non-polar."], ["Q3", "The nitrogen atoms are joined by a triple bond [1], which is very strong (944 kJ mol⁻¹), so a large amount of energy is needed to break it [1]. The molecule is also non-polar, so it does not attract other reagents [1]."]], "3": [["Q4", "Ammonia accepts a proton from water and from HCl. In the third reaction the hydroxide ion accepts a proton from the ammonium ion."], ["Q5", "Ammonia is a proton acceptor [1]: the lone pair on the nitrogen atom forms a bond to an H⁺ ion [1]. NH₃ + H₂O ⇌ NH₄⁺ + OH⁻ [1]."]], "4": [["Q6", "NH₃: lone pair, pyramidal, 107°. NH₄⁺: tetrahedral, 109.5°, one coordinate bond. Both contain N–H covalent bonds."], ["Q7", "The lone pair on the nitrogen atom of ammonia forms a coordinate bond to an H⁺ ion [1]. The ammonium ion is tetrahedral [1] with bond angles of 109.5° [1]."]], "5": [["Q8", "(a) The gas is ammonia [1]; the solid contains the ammonium ion [1]. (b) NH₄⁺ + OH⁻ → NH₃ + H₂O [1]. (c) The ammonium ion is the acid (proton donor) [1]; the hydroxide ion is the base (proton acceptor) [1]. (d) The lime would react with the ammonium salt and ammonia gas would be given off, so the nitrogen is lost from the soil [1]."]], "6": [["Exit ticket", "N₂ is unreactive because its triple bond is very strong and the molecule is non-polar. NH₃ is a base because the lone pair on its nitrogen atom accepts a proton."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Crisp packets are filled with nitrogen instead of air. Suggest why nitrogen is chosen.", "Q2": "Choose the correct answer.", "Q3": "Explain why nitrogen gas is very unreactive.", "Q4": "In each reaction, which species is the Brønsted–Lowry base?", "Q5": "Explain, using the Brønsted–Lowry theory, why ammonia is a base. Include an equation for its reaction with water. Type the equation like this: NH3 + …", "Q6": "Ammonia or the ammonium ion?", "Q7": "Describe how the ammonium ion is formed from ammonia, and state its shape and bond angle.", "Q8": "A white solid is warmed with aqueous sodium hydroxide. A gas is given off that turns damp red litmus paper blue. (a) Identify the gas and the ion present in the solid. (b) Write the ionic equation for the reaction. Type it like this: NH4+ + … (c) Identify the Brønsted–Lowry acid and base in this reaction. (d) Explain why a farmer should not add lime, Ca(OH)₂, to soil at the same time as an ammonium fertiliser."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '93c12bd9-4f1f-538d-acee-39d3703caea9', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '12.1' limit 1), '12.1 Nitrogen and sulfur · Lesson 2: Oxides of nitrogen and sulfur: sources, catalytic converters, photochemical smog and acid rain', 'A Level Chemistry · 12 Nitrogen and sulfur', '/achem-12-1-2/', 'ACHEM-12-1-2', 28, 60, 12012 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-12-1-2', '12.1 Nitrogen and sulfur · Lesson 2: Oxides of nitrogen and sulfur: sources, catalytic converters, photochemical smog and acid rain', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Natural", "Man-made", "NO", "NO₂", "Brown"], "tip": "Both sources need a very high temperature."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["n2 o2", "o2 n2"], ["triple bond", "strong bond", "activation energy", "high temperature", "bond energy", "lot of energy", "very strong"]], "tips": ["Think about the bond in N₂."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["NO", "CO", "N₂ and CO₂", "+2 to 0", "+2 to +4", "Large surface area"], "tip": "Oxygen is −2 in NO, CO and CO₂."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["2no 2co", "2co 2no"], ["not toxic", "non-toxic", "harmless", "unreactive", "in the air", "not poisonous", "less toxic", "nontoxic", "do not cause"]], "tips": ["Both reactants are pollutants."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 4, "n": 4, "ans": ["Oxides of nitrogen and unburned hydrocarbons", "Sunlight", "Peroxyacetyl nitrate", "Irritates eyes and lungs"], "tip": "Photo means light."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["oxides of nitrogen", "no2", "nox", "nitrogen dioxide", "nitrogen monoxide", "nitrogen oxide"], ["hydrocarbon"], ["sunlight", "light", "sunny", "uv"]], "tips": ["Two pollutants and one condition."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["4no2 2h2o", "2h2o o2", "4no2 o2", "2no2 h2o"], ["so2 no2", "no2 so2"], ["2no o2", "o2 2no"], ["regenerated", "reformed", "re-formed", "not used up", "formed again", "made again", "regenerate", "unchanged"], ["sulfuric", "h2so4", "sulphuric"], ["so3 no", "no so3"]], "tips": ["(b) NO₂ is used in the first equation and made again in the second."]}]}, "models": {"1": [["Q1", "The nitrogen comes from the air drawn into the engine. The temperature inside the engine is high enough to break the strong N≡N bond, so nitrogen and oxygen from the air combine."]], "2": [["Q2", "Lightning is natural; engines are man-made. NO forms first and is then oxidised to brown NO₂."], ["Q3", "N₂ + O₂ → 2NO [1]. The N≡N triple bond is very strong, so the activation energy is very high and the reaction needs a very high temperature [1]."]], "3": [["Q4", "NO is reduced (+2 to 0) and CO is oxidised (+2 to +4), giving N₂ and CO₂. The honeycomb gives a large surface area."], ["Q5", "2NO + 2CO → N₂ + 2CO₂ [1]. Nitrogen is the unreactive gas already in the air and carbon dioxide is not toxic, unlike NO and CO [1]."]], "4": [["Q6", "Oxides of nitrogen react with unburned hydrocarbons in sunlight to form peroxyacetyl nitrate, which irritates the eyes and lungs."], ["Q7", "Oxides of nitrogen from vehicle exhausts [1] react with unburned hydrocarbons [1] in the presence of sunlight to form peroxyacetyl nitrate, PAN [1]."]], "5": [["Q8", "(a) 4NO₂ + 2H₂O + O₂ → 4HNO₃ [1]. (b) SO₂ + NO₂ [1] → SO₃ + NO [1]; then 2NO + O₂ → 2NO₂ [1]. (c) The NO₂ is regenerated, so it is not used up overall [1]. (d) Sulfuric acid, H₂SO₄ [1]."]], "6": [["Exit ticket", "Natural: lightning. Man-made: internal combustion engines. They cause photochemical smog (PAN) and acid rain, both directly as nitric acid and by catalysing the oxidation of sulfur dioxide."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Petrol contains almost no nitrogen, yet car exhausts contain oxides of nitrogen. Suggest where the nitrogen comes from and why it reacts.", "Q2": "Choose the correct answer.", "Q3": "Write the equation for the formation of nitrogen monoxide in a car engine, and explain why this reaction does not happen in air at room temperature. Type the equation like this: N2 + …", "Q4": "In the reaction 2NO + 2CO → N₂ + 2CO₂, choose the correct answer.", "Q5": "Write the equation for the removal of nitrogen monoxide in a catalytic converter and explain why the products are less harmful. Type the equation like this: 2NO + …", "Q6": "Choose the correct answer.", "Q7": "Explain how photochemical smog containing PAN forms in a city.", "Q8": "(a) Write an equation to show how nitrogen dioxide forms nitric acid in the atmosphere. Type it like this: 4NO2 + … (b) Write the two equations that show how NO₂ acts as a catalyst in the oxidation of sulfur dioxide. (c) Explain why NO₂ is described as a catalyst in this process. (d) Name the acid formed when the sulfur trioxide dissolves in rain."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'ea5b7f7c-e0a8-542b-a384-9ecdc752ce37', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '13.1' limit 1), '13.1 Formulas, functional groups and the naming of organic compounds · Lesson 1: Hydrocarbons, functional groups, and general, structural, displayed and skeletal formulas', 'A Level Chemistry · 13 An introduction to AS Level organic chemistry', '/achem-13-1-1/', 'ACHEM-13-1-1', 39, 60, 13011 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-13-1-1', '13.1 Formulas, functional groups and the naming of organic compounds · Lesson 1: Hydrocarbons, functional groups, and general, structural, displayed and skeletal formulas', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 8, "n": 8, "ans": ["Alkene", "Alcohol", "Aldehyde", "Carboxylic acid", "Amine", "Nitrile", "Halogenoalkane", "Ester"], "tip": "An aldehyde has its C=O at the end of the chain."}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 8, "n": 8, "ans": ["Alkane", "Alkene", "Halogenoalkane", "Alcohol", "Aldehyde", "Ketone", "Carboxylic acid", "Ester"], "tip": "CHO is an aldehyde; CO between two carbons is a ketone."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["C₅H₁₂", "C₅H₁₀", "C₆H₁₄", "C₆H₁₂", "C₃H₇OH"], "tip": "Alkanes: 2n + 2 hydrogens. Alkenes: 2n."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["c4h10"], ["ch3ch2ch2ch3", "ch3 ch2 2ch3", "h3cch2ch2ch3"]], "tips": ["Write each carbon with the hydrogens attached to it. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["Molecular", "General", "Structural", "Displayed", "Skeletal"], "tip": "Skeletal formulas leave out C and H symbols."}, {"kind": "choice", "id": "q4_1", "q": "Q7", "max": 5, "n": 5, "ans": ["2", "3", "4", "5", "6"], "tip": "Count the line ends and the corners."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["alkene", "c=c", "carbon-carbon double", "double bond"], ["alcohol", "hydroxyl", "hydroxy", "oh group"], ["c3h6o"], ["not a hydrocarbon", "is not", "no ", "isn t"], ["oxygen", "only carbon and hydrogen", "carbon and hydrogen only"], ["every bond", "all the bonds", "all bonds", "each bond", "all of the bonds", "c-h bond", "o-h bond", "the bonds"]], "tips": ["(c) check which elements are present. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "The –OH group is polar and can form hydrogen bonds. Ethanol molecules hydrogen-bond to each other, so more energy is needed to separate them and it is a liquid; they also hydrogen-bond to water, so ethanol dissolves. Ethane has only weak forces between its non-polar molecules."]], "2": [["Q2", "C=C alkene; –OH alcohol; –CHO aldehyde; –COOH carboxylic acid; –NH₂ amine; –C≡N nitrile; C–Br halogenoalkane; –COO– ester."], ["Q3", "Propane is an alkane; propene an alkene; chloroethane a halogenoalkane; propan-1-ol an alcohol; ethanal an aldehyde; propanone a ketone; ethanoic acid a carboxylic acid; ethyl ethanoate an ester."]], "3": [["Q4", "C₅H₁₂ and C₆H₁₄ are alkanes; C₅H₁₀ and C₆H₁₂ are alkenes; the alcohol is C₃H₇OH."], ["Q5", "Molecular formula C₄H₁₀ [1]; structural formula CH₃CH₂CH₂CH₃ [1]."]], "4": [["Q6", "C₂H₆O is molecular; CₙH₂ₙ₊₂ general; CH₃CH₂OH structural; all atoms and bonds is displayed; a zig-zag line is skeletal."], ["Q7", "One line: 2 carbons. Two lines: 3. Three lines: 4. Four lines: 5. A hexagon has six corners: 6 carbons (cyclohexane)."]], "5": [["Q8", "(a) An alkene (C=C) group [1] and an alcohol (–OH) group [1]. (b) C₃H₆O [1]. (c) It is not a hydrocarbon [1], because it contains oxygen as well as carbon and hydrogen [1]. (d) Every bond, including each C–H bond and the O–H bond [1]."]], "6": [["Exit ticket", "CH₃CH₂CH₃. Its skeletal formula is two lines joined at an angle: two line ends and one corner, three carbon atoms."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q5", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Ethane is a gas at room temperature but ethanol is a liquid that mixes with water. Suggest how the –OH group causes this.", "Q2": "Which class of compound has this functional group?", "Q3": "Classify the compound.", "Q4": "Use the general formula to choose the molecular formula.", "Q5": "Butane is the alkane with four carbon atoms in an unbranched chain. Write its molecular formula and its structural formula.", "Q6": "Which type of formula is described?", "Q7": "How many carbon atoms does the skeletal formula show?", "Q8": "A compound has the structural formula CH₂=CHCH₂OH. (a) Name the two functional groups it contains. (b) Give its molecular formula. (c) State whether it is a hydrocarbon and explain your answer. (d) State what a displayed formula of this compound would show that the structural formula does not."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'ea6d4f5c-0a2c-5c6d-8172-d664c0342e0e', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '13.1' limit 1), '13.1 Formulas, functional groups and the naming of organic compounds · Lesson 2: Systematic names of organic compounds, and deducing molecular and empirical formulas', 'A Level Chemistry · 13 An introduction to AS Level organic chemistry', '/achem-13-1-2/', 'ACHEM-13-1-2', 34, 60, 13012 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-13-1-2', '13.1 Formulas, functional groups and the naming of organic compounds · Lesson 2: Systematic names of organic compounds, and deducing molecular and empirical formulas', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 7, "n": 7, "ans": ["2-methylbutane", "but-1-ene", "but-2-ene", "2-chloropropane", "1-chloropropane", "2,2-dimethylpropane", "1,2-dibromoethane"], "tip": "Number from the end that gives the lowest numbers."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["3-methylpentane", "3 methyl pentane"], ["longest chain", "five carbon", "5 carbon", "longest carbon"]], "tips": ["Count the longest chain first."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 9, "n": 9, "ans": ["propan-1-ol", "propan-2-ol", "propanal", "propanone", "propanoic acid", "ethylamine", "propanenitrile", "ethyl ethanoate", "methyl propanoate"], "tip": "In a nitrile and an acid, the carbon of the functional group counts in the chain."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["ch3ch oh ch2ch3", "ch3ch2ch oh ch3", "ch3chohch2ch3", "ch3ch2chohch3"], ["ch3ch2ch2cho", "ch3 ch2 2cho"]], "tips": ["But- means four carbon atoms. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 6, "n": 6, "ans": ["C₂H₄O₂", "C₃H₆O", "C₃H₈O", "C₄H₈", "C₄H₁₀", "C₆H₁₂"], "tip": "Each carbon makes four bonds."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["c3h6o3"], ["ch2o "]], "tips": ["Count the atoms, then divide by the largest common factor. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["butanoic acid"], ["2-bromobutane", "2 bromo butane"], ["ch3 3coh", "ch3 2c oh ch3", "ch3c ch3 oh ch3", "ch3c oh ch3 ch3", "c ch3 3oh", "ch3c ch3 2oh"], ["c4h10o"], ["methyl ethanoate"], ["c3h6o2"]], "tips": ["(c) a three-carbon chain with CH₃ and OH both on carbon 2. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "All three have five carbon atoms, because they share the stem pent-. Pentane is an alkane with only single bonds, pentene is an alkene with a C=C double bond, and pentanol is an alcohol with an –OH group."]], "2": [["Q2", "2-methylbutane; but-1-ene; but-2-ene; 2-chloropropane; 1-chloropropane; 2,2-dimethylpropane; 1,2-dibromoethane."], ["Q3", "3-methylpentane [1]. The longest carbon chain has five carbon atoms, so the stem is pent-, with a methyl group on carbon 3 [1]."]], "3": [["Q4", "propan-1-ol; propan-2-ol; propanal; propanone; propanoic acid; ethylamine; propanenitrile; ethyl ethanoate; methyl propanoate."], ["Q5", "Butan-2-ol: CH₃CH(OH)CH₂CH₃ [1]. Butanal: CH₃CH₂CH₂CHO [1]."]], "4": [["Q6", "Ethanoic acid C₂H₄O₂; propanone C₃H₆O; propan-2-ol C₃H₈O; but-2-ene C₄H₈; butane C₄H₁₀; cyclohexane C₆H₁₂."], ["Q7", "Molecular formula C₃H₆O₃ [1]; empirical formula CH₂O [1]."]], "5": [["Q8", "(a) Butanoic acid [1]. (b) 2-bromobutane [1]. (c) (CH₃)₃COH [1]. (d) C₄H₁₀O [1]. (e) Methyl ethanoate [1]. (f) C₃H₆O₂ [1] (it cannot be simplified)."]], "6": [["Exit ticket", "The carbon atom of the –CN group is counted as part of the chain, so the chain has three carbon atoms and the stem is prop-."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "From the names alone, what can you say about pentane, pentene and pentanol?", "Q2": "Choose the correct name.", "Q3": "Name the compound CH₃CH₂CH(CH₃)CH₂CH₃ and explain how you chose the stem.", "Q4": "Choose the correct name.", "Q5": "Write the structural formula of butan-2-ol and of butanal.", "Q6": "What is the molecular formula?", "Q7": "Give the molecular formula and the empirical formula of CH₃CH(OH)COOH.", "Q8": "(a) Name CH₃CH₂CH₂COOH. (b) Name CH₃CHBrCH₂CH₃. (c) Write the structural formula of 2-methylpropan-2-ol. (d) Give the molecular formula of 2-methylpropan-2-ol. (e) Name the ester CH₃COOCH₃. (f) Give the empirical formula of the ester in (e)."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '657f23f4-2ea4-5567-aef7-9870bede26cc', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '13.2' limit 1), '13.2 Characteristic organic reactions: The language of organic reactions: fission, free radicals, nucleophiles, electrophiles and types of reaction', 'A Level Chemistry · 13 An introduction to AS Level organic chemistry', '/achem-13-2/', 'ACHEM-13-2', 34, 60, 13020 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-13-2', '13.2 Characteristic organic reactions: The language of organic reactions: fission, free radicals, nucleophiles, electrophiles and types of reaction', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Saturated", "Unsaturated", "Unsaturated", "Saturated", "Saturated"], "tip": "Look only at the carbon–carbon bonds."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["same functional group", "same general formula"], ["ch2"], ["similar chemical", "same chemical", "trend in physical", "gradual", "boiling point"]], "tips": ["Think about formula, the difference between members, and properties. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 7, "n": 7, "ans": ["Free radical", "Free radical", "Nucleophile", "Nucleophile", "Nucleophile", "Electrophile", "Electrophile"], "tip": "A nucleophile has a lone pair to donate."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["one electron", "evenly", "equally", "each atom"], ["radical"], ["both electrons", "two electrons", "ions", "ion"]], "tips": ["Where do the two bonding electrons go in each case?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 7, "n": 7, "ans": ["Addition", "Substitution", "Elimination", "Hydrolysis", "Condensation", "Oxidation", "Reduction"], "tip": "Count the products: one product means addition."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["substitution"], ["oh", "hydroxide"], ["lone pair", "donates", "donate", "electron pair", "pair of electrons"]], "tips": ["What has replaced what?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["pair of electrons", "electron pair", "two electrons", "2 electrons"], ["lone pair"], ["carbon", "c atom"], ["heterolytic"], ["bromide", "br-", "br ion"], ["nucleophilic substitution"]], "tips": ["(b) arrows start where the electrons are."]}]}, "models": {"1": [["Q1", "Each chlorine atom could take one electron, giving two chlorine atoms that each have an unpaired electron (free radicals). Or one chlorine could take both electrons, giving a Cl⁻ ion and a Cl⁺ ion."]], "2": [["Q2", "Propane, cyclohexane and ethanol have only single C–C bonds: saturated. Ethene and but-2-ene have C=C: unsaturated."], ["Q3", "The members have the same functional group and general formula [1], each differs from the next by CH₂ [1], and they have similar chemical properties with a gradual trend in physical properties [1]."]], "3": [["Q4", "Cl• and •CH₃ are free radicals. OH⁻, CN⁻ and NH₃ have lone pairs: nucleophiles. H⁺ and the δ+ hydrogen of HBr accept an electron pair: electrophiles."], ["Q5", "In homolytic fission the bond breaks evenly, with one electron going to each atom [1], so two free radicals form [1]. In heterolytic fission both electrons go to the same atom, so a positive ion and a negative ion form [1]."]], "4": [["Q6", "Addition; substitution; elimination; hydrolysis; condensation; oxidation; reduction."], ["Q7", "It is a substitution reaction: OH replaces Br [1]. The nucleophile is the hydroxide ion [1], because it donates a lone pair of electrons to the δ+ carbon atom [1]."]], "5": [["Q8", "(a) The movement of a pair of electrons [1]. (b) It starts at a lone pair on the oxygen of OH⁻ [1] and ends at the δ+ carbon atom bonded to bromine [1]. (c) Heterolytic fission [1], forming a bromide ion [1]. (d) Nucleophilic substitution [1]."]], "6": [["Exit ticket", "A nucleophile is an electron-pair donor that attacks an electron-poor (δ+) atom. An electrophile is an electron-pair acceptor that attacks an electron-rich region."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "A Cl–Cl bond breaks. Describe the two possible ways the bonding electrons could be shared out, and what particles would form in each case.", "Q2": "Saturated or unsaturated?", "Q3": "State three features of a homologous series.", "Q4": "Classify the species.", "Q5": "Explain the difference between homolytic fission and heterolytic fission of a covalent bond.", "Q6": "What type of reaction is this?", "Q7": "Bromoethane reacts with hydroxide ions: CH₃CH₂Br + OH⁻ → CH₃CH₂OH + Br⁻. State the type of reaction and identify the nucleophile, with a reason.", "Q8": "(a) State what a curly arrow represents. (b) In the reaction of OH⁻ with CH₃CH₂Br, state where the curly arrow from the hydroxide ion starts and where it ends. (c) A second curly arrow shows the C–Br bond breaking. State the type of fission and name the ion formed. (d) Name the mechanism."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'e89057a5-3e0e-5c22-a3ae-ca76014e4ff4', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '13.3' limit 1), '13.3 Shapes of organic molecules; σ and π bonds: Straight, branched and cyclic molecules; sp³, sp² and sp hybridised carbon; bond angles and planarity', 'A Level Chemistry · 13 An introduction to AS Level organic chemistry', '/achem-13-3/', 'ACHEM-13-3', 30, 60, 13030 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-13-3', '13.3 Shapes of organic molecules; σ and π bonds: Straight, branched and cyclic molecules; sp³, sp² and sp hybridised carbon; bond angles and planarity', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["4", "0", "109.5°", "Tetrahedral"], "tip": "Four single bonds."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["109"], ["four bonding pairs", "4 bonding pairs", "repel", "four pairs", "4 pairs", "four electron pairs"]], "tips": ["How many electron pairs are around each carbon?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["sp²", "120°", "5", "1", "Planar"], "tip": "Four C–H bonds plus the σ part of C=C."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["same plane", "one plane", "flat"], ["pi bond", "π bond", "p orbitals", "overlap"]], "tips": ["Rotation would break something."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 6, "n": 6, "ans": ["sp³", "sp²", "sp", "sp³", "sp²", "sp"], "tip": "Count the atoms bonded to the carbon: 4, 3 or 2."}, {"kind": "choice", "id": "q4_1", "q": "Q7", "max": 5, "n": 5, "ans": ["109.5°", "120°", "180°", "120°", "180°"], "tip": "sp³ 109.5°, sp² 120°, sp 180°."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["sp3"], ["sp2"], ["109"], ["120"], ["8 sigma", "8 σ", "eight sigma", "eight σ", "8 s", "sigma bonds 8", "σ bonds 8", "8 are sigma", "sigma: 8", "sigma 8", "σ: 8", "σ 8"], ["1 pi", "one pi", "1 π", "one π", "pi: 1", "pi 1", "π: 1", "π 1", "pi bonds 1", "π bonds 1", "a pi", "single pi"]], "tips": ["(c) six C–H bonds, one C–C and the two parts of C=C. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "Each carbon atom has four bonds that point to the corners of a tetrahedron, with angles of about 109.5° between them. The C–C–C angle is therefore 109.5°, not 180°, so the chain zig-zags."]], "2": [["Q2", "Four σ bonds, no π bonds, 109.5°, tetrahedral."], ["Q3", "109.5° [1]. Each carbon has four bonding pairs of electrons, which repel each other equally and get as far apart as possible [1]."]], "3": [["Q4", "sp² carbons, 120°, five σ bonds (four C–H and one C–C), one π bond, planar."], ["Q5", "All six atoms lie in the same plane [1]. Rotation would break the π bond, because the sideways overlap of the p orbitals would be lost [1]."]], "4": [["Q6", "Four atoms attached: sp³. Three attached (C=C or C=O): sp². Two attached (C≡C or C≡N): sp."], ["Q7", "Propane 109.5°; C=C in propene 120°; ethyne 180°; C=O in propanone 120°; nitrile carbon 180°."]], "5": [["Q8", "(a) The CH₃ carbon is sp3 [1]; the two C=C carbons are sp2 [1]. (b) 109.5° around the CH₃ carbon [1]; 120° around the central carbon [1]. (c) 8 sigma bonds (six C–H, one C–C and one in the C=C) [1] and 1 pi bond [1]."]], "6": [["Exit ticket", "sp²; three σ bonds and one π bond; 120°, trigonal planar."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Look at the model of butane. Suggest why a ''straight'' carbon chain is actually a zig-zag.", "Q2": "For an sp³ carbon atom, choose the correct answer.", "Q3": "State the H–C–H bond angle in ethane and explain it.", "Q4": "For ethene, CH₂=CH₂, choose the correct answer.", "Q5": "Explain what is meant by describing ethene as planar, and why there is no rotation about the C=C bond.", "Q6": "What is the hybridisation of the carbon atom shown in bold capitals?", "Q7": "What is the bond angle around the carbon atom?", "Q8": "Propene has the structural formula CH₃CH=CH₂. (a) State the hybridisation of the CH₃ carbon and of the two C=C carbons. (b) State the bond angle around the CH₃ carbon and around the central carbon. (c) State the total number of σ bonds and of π bonds in one molecule."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '607974ce-4d58-58ab-91f5-3f607ae7a3c8', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '13.4' limit 1), '13.4 Isomerism: structural isomerism and stereoisomerism · Lesson 1: Structural isomerism: chain, positional and functional group isomers', 'A Level Chemistry · 13 An introduction to AS Level organic chemistry', '/achem-13-4-1/', 'ACHEM-13-4-1', 27, 60, 13041 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-13-4-1', '13.4 Isomerism: structural isomerism and stereoisomerism · Lesson 1: Structural isomerism: chain, positional and functional group isomers', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["1", "2", "3", "5"], "tip": "Shorten the chain one carbon at a time."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["pentane "], ["2-methylbutane", "2 methyl butane", "methylbutane"], ["2,2-dimethylpropane", "2 2 dimethyl propane", "dimethylpropane"]], "tips": ["Chains of five, four and three carbon atoms."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Yes", "Yes", "No: they are chain isomers", "No: they are the same compound", "No: different molecular formulas"], "tip": "Turning a molecule round does not make a new compound."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["ch3ch2ch2br", "brch2ch2ch3", "ch2brch2ch3"], ["ch3chbrch3", "ch3ch br ch3"]], "tips": ["The bromine can be on an end carbon or on the middle carbon. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 7, "n": 7, "ans": ["Functional group", "Chain", "Positional", "Functional group", "Functional group", "Positional", "Chain"], "tip": "Ask: is the skeleton, the position or the group different?"}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 6, "pts": [["same molecular formula", "different structural"], ["butan-1-ol", "butan 1 ol", "1-butanol"], ["butan-2-ol", "butan 2 ol", "2-butanol"], ["2-methylpropan-1-ol", "2 methyl propan 1 ol", "methylpropan-1-ol"], ["2-methylpropan-2-ol", "2 methyl propan 2 ol", "methylpropan-2-ol"], ["chain"]], "tips": ["(b) two with a four-carbon chain and two with a three-carbon chain and a methyl branch."]}]}, "models": {"1": [["Q1", "Butane molecules are long and can lie close together, so there is a large area of contact and stronger instantaneous dipole–induced dipole forces. 2-Methylpropane is more compact and spherical, with less contact between molecules, so its intermolecular forces are weaker."]], "2": [["Q2", "C₃H₈: 1. C₄H₁₀: 2. C₅H₁₂: 3. C₆H₁₄: 5 (hexane, 2-methylpentane, 3-methylpentane, 2,2-dimethylbutane and 2,3-dimethylbutane)."], ["Q3", "Pentane [1], 2-methylbutane [1] and 2,2-dimethylpropane [1]."]], "3": [["Q4", "The alcohols and the butenes are positional isomers. Butane and 2-methylpropane are chain isomers. CH₃CH₂CH₂Cl written backwards is the same compound. Propan-1-ol and butan-1-ol have different formulas."], ["Q5", "CH₃CH₂CH₂Br, 1-bromopropane [1], and CH₃CHBrCH₃, 2-bromopropane [1]."]], "4": [["Q6", "Aldehyde and ketone, acid and ester, alkene and cycloalkane: functional group isomers. Pentane and 2-methylbutane, but-1-ene and methylpropene: chain. The alcohols and the chlorobutanes: positional."]], "5": [["Q7", "(a) Compounds with the same molecular formula but different structural formulas [1]. (b) Butan-1-ol [1], butan-2-ol [1], 2-methylpropan-1-ol [1] and 2-methylpropan-2-ol [1]. (c) Chain isomerism [1]."]], "6": [["Exit ticket", "Chain: butane and 2-methylpropane. Positional: propan-1-ol and propan-2-ol. Functional group: propanal and propanone."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Butane and 2-methylpropane are both C₄H₁₀, but butane has the higher boiling point. Suggest why.", "Q2": "How many structural isomers are alkanes with this molecular formula?", "Q3": "Name the three structural isomers with the molecular formula C₅H₁₂.", "Q4": "Are the two compounds positional isomers of each other?", "Q5": "Give the structural formulas of the two positional isomers of bromopropane, C₃H₇Br.", "Q6": "What type of structural isomerism do the two compounds show?", "Q7": "(a) Define structural isomerism. (b) There are four alcohols with the molecular formula C₄H₁₀O. Name them. (c) State the type of isomerism shown by butan-1-ol and 2-methylpropan-1-ol."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '980e8f5d-8f73-5aed-b9ef-3c9dc031865f', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '13.4' limit 1), '13.4 Isomerism: structural isomerism and stereoisomerism · Lesson 2: Stereoisomerism: geometrical (cis/trans) isomers and optical isomers with chiral centres', 'A Level Chemistry · 13 An introduction to AS Level organic chemistry', '/achem-13-4-2/', 'ACHEM-13-4-2', 36, 60, 13042 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-13-4-2', '13.4 Isomerism: structural isomerism and stereoisomerism · Lesson 2: Stereoisomerism: geometrical (cis/trans) isomers and optical isomers with chiral centres', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 7, "n": 7, "ans": ["Yes", "No", "Yes", "No", "Yes", "No", "No"], "tip": "Each carbon of the C=C needs two different groups."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["restricted rotation", "cannot rotate", "no rotation", "no free rotation", "pi bond", "π bond", "prevents rotation"], ["two different groups", "different groups on each", "2 different groups"], ["two hydrogen", "identical", "two h", "the same", "2 hydrogen", "same group"]], "tips": ["Look at what is attached to each carbon of the C=C. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 7, "n": 7, "ans": ["Yes", "No", "Yes", "Yes", "No", "Yes", "No"], "tip": "Look for a carbon with four different groups."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["four different", "4 different"], ["mirror image"], ["non-superimposable", "not superimposable", "cannot be superimposed", "nonsuperimposable", "non superimposable"]], "tips": ["Think about your hands."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["1", "2", "0", "0", "1"], "tip": "Two ethyl groups on the same carbon are identical."}, {"kind": "choice", "id": "q4_1", "q": "Q7", "max": 5, "n": 5, "ans": ["Geometrical only", "Optical only", "Both", "Neither", "Optical only"], "tip": "Check the C=C and each sp³ carbon separately."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["same structural formula", "same structural"], ["different arrangement", "arrangement in space", "spatial", "arranged differently in space", "different spatial"], ["two different groups", "different groups on each", "restricted rotation", "2 different groups"], ["oh", "hydroxyl"], ["ch3 ", "methyl"], ["4 stereoisomers", "four stereoisomers", "4 isomers", "four isomers", "total 4", "total of 4", "is 4", "are 4", "d 4"]], "tips": ["(d) two geometrical forms, each with two optical forms. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "They cannot be superimposed: if you place one hand on top of the other, both palms facing down, the thumbs point in opposite directions. A left-hand glove does not fit a right hand. They are mirror images but not the same shape."]], "2": [["Q2", "But-2-ene, 1,2-dichloroethene and pent-2-ene: yes. But-1-ene, 1,1-dichloroethene and 2-methylbut-2-ene have two identical groups on one carbon of the C=C: no. Butane has no double bond."], ["Q3", "The π bond causes restricted rotation about the C=C bond [1]. In but-2-ene each carbon of the C=C has two different groups (H and CH₃) [1], but in but-1-ene one carbon has two identical hydrogen atoms, so only one arrangement exists [1]."]], "3": [["Q4", "Butan-2-ol, 2-chlorobutane, 2-hydroxypropanoic acid and 2-aminopropanoic acid each have a carbon with four different groups. Propan-2-ol and 2-bromopropane have two identical CH₃ groups; butan-1-ol has no carbon with four different groups."], ["Q5", "A chiral centre is a carbon atom bonded to four different atoms or groups [1]. The two optical isomers are mirror images of each other [1] that are non-superimposable [1]."]], "4": [["Q6", "CH₃CH₂CH(CH₃)CH₂OH has 1. CH₃CH(OH)CH(OH)CH₂CH₃ has 2. (CH₃)₂CHCH₂OH has 0. 3-Bromopentane has 0, because the central carbon has two ethyl groups. CH₃CH(OH)CH=CH₂ has 1."], ["Q7", "But-2-ene: geometrical only. Butan-2-ol: optical only. CH₃CH=CHCH(OH)CH₃ has a suitable C=C and a chiral centre: both. Propan-1-ol: neither. CH₂=CHCH(Cl)CH₃ has =CH₂, so no cis/trans, but it has a chiral centre: optical only."]], "5": [["Q8", "(a) Compounds with the same structural formula [1] but a different arrangement of atoms in space [1]. (b) There is restricted rotation about the C=C bond and each carbon of the C=C has two different groups [1]. (c) The carbon bonded to H, OH [1], CH₃ and the CH=CHCH₃ group [1]. (d) 4 stereoisomers: cis and trans, each as two optical isomers [1]."]], "6": [["Exit ticket", "(a) A C=C double bond in which each carbon atom has two different groups attached. (b) A chiral centre: a carbon atom bonded to four different atoms or groups."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Your two hands are mirror images of each other. Explain why they are not identical, and how you could show this.", "Q2": "Does the compound show geometrical (cis/trans) isomerism?", "Q3": "Explain why but-2-ene has geometrical isomers but but-1-ene does not.", "Q4": "Does the compound have a chiral centre?", "Q5": "Explain what is meant by a chiral centre, and state the relationship between the two optical isomers it gives rise to.", "Q6": "How many chiral centres does the molecule have?", "Q7": "Which type of stereoisomerism does the compound show?", "Q8": "A compound has the structural formula CH₃CH=CHCH(OH)CH₃. (a) Define stereoisomerism. (b) Explain why this compound shows geometrical isomerism. (c) Identify the chiral centre by naming the four different groups attached to it. (d) State the total number of stereoisomers of this compound."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '22c12882-60f2-568b-a4f6-a2a795507fe9', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '14.1' limit 1), '14.1 Alkanes · Lesson 1: Why alkanes are unreactive; making alkanes; combustion, pollution and cracking', 'A Level Chemistry · 14 Hydrocarbons', '/achem-14-1-1/', 'ACHEM-14-1-1', 28, 60, 14011 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-14-1-1', '14.1 Alkanes · Lesson 1: Why alkanes are unreactive; making alkanes; combustion, pollution and cracking', '{"marks": {"1": [{"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["strong"], ["non-polar", "not polar", "nonpolar", "similar electronegativ", "same electronegativ", "no dipole", "lack of polarity"]], "tips": ["Two reasons: strength and polarity."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Pt or Ni, heat", "Al₂O₃, heat", "Propane", "An alkane and an alkene"], "tip": "Hydrogenation needs a metal catalyst."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 1, "pts": [["c3h6 h2", "h2 c3h6", "ch3ch ch2 h2", "ch2 chch3 h2"]], "tips": ["One molecule of hydrogen adds across the double bond."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Complete", "Incomplete", "Incomplete", "Complete", "Incomplete"], "tip": "Limited oxygen gives CO or C."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["c3h8 5o2", "5o2 c3h8"], ["3co2 4h2o", "4h2o 3co2"]], "tips": ["Three carbons give three CO₂; eight hydrogens give four H₂O."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 5, "n": 5, "ans": ["Carbon monoxide", "Oxides of nitrogen", "Oxides of nitrogen", "Unburned hydrocarbons", "Oxides of nitrogen"], "tip": "The nitrogen comes from the air, not the fuel."}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 3, "pts": [["2no 2co", "2co 2no"], ["nitrogen", "n2"], ["carbon dioxide", "co2"]], "tips": ["The two pollutants react with each other."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 6, "pts": [["heat", "high temperature", "hot"], ["al2o3", "aluminium oxide", "catalyst", "alumina"], ["c8h18 c2h4", "c2h4 c8h18"], ["shorter", "smaller", "petrol", "fuel", "demand"], ["alkene", "polymer", "plastic", "feedstock"], ["ethene", "c2h4"]], "tips": ["(d) subtract C₆H₁₄ from C₁₂H₂₆ and divide what is left by three."]}]}, "models": {"1": [["Q1", "Alkanes are very unreactive: their C–C and C–H bonds are strong and non-polar, so they do not react with sodium. The oil also keeps air and water away from the metal."], ["Q2", "The C–C and C–H bonds are strong [1] and non-polar, because carbon and hydrogen have similar electronegativities, so there is no δ+ or δ− site to attract the reagent [1]."]], "2": [["Q3", "Hydrogenation: Pt or Ni and heat; propene gives propane. Cracking: heat with Al₂O₃, giving a shorter alkane and an alkene."], ["Q4", "C₃H₆ + H₂ → C₃H₈ [1]."]], "3": [["Q5", "Excess oxygen: complete, giving CO₂ and H₂O with a blue flame. Limited oxygen: incomplete, giving CO or soot and a yellow smoky flame."], ["Q6", "C₃H₈ + 5O₂ [1] → 3CO₂ + 4H₂O [1]."]], "4": [["Q7", "CO: incomplete combustion, toxic. NOₓ: from air at high temperature, acid rain, reduced to N₂ in the converter. Unburned hydrocarbons: fuel that did not burn."], ["Q8", "2NO + 2CO → N₂ + 2CO₂ [1]. The products are nitrogen [1] and carbon dioxide [1]."]], "5": [["Q9", "(a) Heat [1] with an aluminium oxide catalyst [1]. (b) C₁₀H₂₂ → C₈H₁₈ + C₂H₄ [1]. (c) It makes shorter alkanes, which are in greater demand as fuels [1], and alkenes, which are used to make polymers [1]. (d) C₁₂H₂₆ − C₆H₁₄ leaves C₆H₁₂, which is three molecules of ethene, C₂H₄ [1]."]], "6": [["Exit ticket", "Their C–C and C–H bonds are strong and non-polar, so polar reagents do not attack them. They burn in oxygen (combustion), and they can be cracked or substituted by halogens in ultraviolet light."]]}, "labels": {"q1_0": "Q1", "q1_1": "Q2", "q2_1": "Q4", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Sodium is stored under oil, a mixture of alkanes. Suggest why alkanes are suitable for this.", "Q2": "Explain why alkanes do not react with polar reagents such as aqueous sodium hydroxide.", "Q3": "Choose the correct answer.", "Q4": "Write the equation for the reaction of propene with hydrogen. Type it like this: C3H6 + …", "Q5": "Complete or incomplete combustion?", "Q6": "Write the equation for the complete combustion of propane. Type it like this: C3H8 + …", "Q7": "Match the pollutant to its source or effect.", "Q8": "Write an equation for a reaction in a catalytic converter that removes both carbon monoxide and nitrogen monoxide, and name the two products. Type it like this: 2NO + …", "Q9": "(a) State the conditions for cracking. (b) One molecule of decane, C₁₀H₂₂, is cracked to give one molecule of octane and one other product. Write the equation. Type it like this: C10H22 → … (c) Give two reasons why cracking is carried out. (d) One molecule of C₁₂H₂₆ gives one molecule of hexane, C₆H₁₄, and three identical molecules of an alkene. Identify the alkene."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '954757f1-b354-537e-b06a-48cd41389559', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '14.1' limit 1), '14.1 Alkanes · Lesson 2: Free-radical substitution of alkanes by chlorine and bromine: initiation, propagation and termination', 'A Level Chemistry · 14 Hydrocarbons', '/achem-14-1-2/', 'ACHEM-14-1-2', 25, 60, 14012 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-14-1-2', '14.1 Alkanes · Lesson 2: Free-radical substitution of alkanes by chlorine and bromine: initiation, propagation and termination', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Ultraviolet light", "Substitution", "HCl", "Excess methane", "Excess chlorine"], "tip": "Each substitution releases one HCl."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["c2h6 br2", "br2 c2h6", "ch3ch3 br2"], ["ultraviolet", "uv", "sunlight", "light"]], "tips": ["One hydrogen is replaced."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Initiation", "Propagation", "Propagation", "Initiation", "Propagation"], "tip": "Propagation: one radical in, one radical out."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["cl ch4", "ch4 cl "], ["ch3 cl2", "cl2 ch3 "]], "tips": ["First the chlorine radical attacks methane; then the methyl radical attacks chlorine. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 3, "n": 3, "ans": ["Cl₂", "CH₃Cl", "C₂H₆"], "tip": "Two radicals join to make one molecule."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["two methyl", "2 methyl", "ch3 ch3", "methyl radicals", "two ch3", "2ch3"], ["evidence", "shows", "termination", "supports", "proves", "confirms"]], "tips": ["Which two radicals would give C₂H₆? Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["homolytic"], ["br2 2br", "br2 br br"], ["br c2h6", "c2h6 br ", "br ch3ch3"], ["c2h5 br2", "br2 c2h5 ", "ch3ch2 br2"], ["c2h5 c2h5", "2c2h5", "ch3ch2 ch3ch2", "2ch3ch2"], ["further substitution", "another hydrogen", "second hydrogen", "more substitution", "bromoethane reacts", "substituted again", "further reaction", "another h", "reacts again", "more hydrogen"]], "tips": ["Follow the pattern for methane and chlorine, with C₂H₅• in place of •CH₃. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "The Cl–Cl bond, because it is much weaker than the C–H bond, so less energy is needed. The energy of ultraviolet light is enough to break Cl–Cl but not C–H."]], "2": [["Q2", "Ultraviolet light; substitution; HCl. Excess methane gives mainly CH₃Cl; excess chlorine gives mainly CCl₄."], ["Q3", "C₂H₆ + Br₂ → C₂H₅Br + HBr [1], in ultraviolet light [1]."]], "3": [["Q4", "Cl₂ → 2Cl• is initiation and needs ultraviolet light. The other two steps are propagation: a radical is used and another is formed."], ["Q5", "Cl• + CH₄ → •CH₃ + HCl [1]. •CH₃ + Cl₂ → CH₃Cl + Cl• [1]."]], "4": [["Q6", "Two chlorine radicals give Cl₂; a methyl and a chlorine radical give CH₃Cl; two methyl radicals give ethane, C₂H₆."], ["Q7", "Two methyl radicals combine in a termination step: •CH₃ + •CH₃ → C₂H₆ [1]. This is evidence that methyl radicals are formed, supporting the free-radical mechanism [1]."]], "5": [["Q8", "(a) Homolytic fission [1]: Br₂ → 2Br• [1]. (b) Br• + C₂H₆ → •C₂H₅ + HBr [1]; •C₂H₅ + Br₂ → C₂H₅Br + Br• [1]. (c) •C₂H₅ + •C₂H₅ → C₄H₁₀ [1]. (d) Further substitution: a bromine radical removes another hydrogen from bromoethane, and the radical formed reacts with Br₂ [1]."]], "6": [["Exit ticket", "Initiation: radicals are made (the number goes up). Propagation: one radical is used and one is formed (the number stays the same). Termination: two radicals combine (the number goes down)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "The Cl–Cl bond energy is 242 kJ mol⁻¹ and the C–H bond energy is 410 kJ mol⁻¹. Suggest which bond ultraviolet light breaks first, and why.", "Q2": "Choose the correct answer.", "Q3": "Write the equation for the reaction of ethane with bromine to form bromoethane, and state the condition needed. Type the equation like this: C2H6 + …", "Q4": "Initiation or propagation?", "Q5": "Write the two propagation steps for the reaction of methane with chlorine. Type a radical as a symbol followed by a dot, for example Cl.", "Q6": "What is formed in the termination step?", "Q7": "A small amount of ethane is found among the products when methane reacts with chlorine. Explain how it forms and what this shows.", "Q8": "Ethane reacts with bromine in ultraviolet light. (a) Name the type of bond fission in the initiation step and write its equation. (b) Write the two propagation steps. (c) Write a termination step that forms butane. (d) Explain why some dibromoethane is also formed. Type a radical as a symbol followed by a dot, for example Br."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '67cffd43-a4ff-55db-bd2a-eceee214c3fa', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '14.2' limit 1), '14.2 Alkenes · Lesson 1: Making alkenes; addition of hydrogen, steam, hydrogen halides and halogens; the bromine test', 'A Level Chemistry · 14 Hydrocarbons', '/achem-14-2-1/', 'ACHEM-14-2-1', 28, 60, 14021 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-14-2-1', '14.2 Alkenes · Lesson 1: Making alkenes; addition of hydrogen, steam, hydrogen halides and halogens; the bromine test', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["NaOH in ethanol, heat", "Heated Al₂O₃ or concentrated H₂SO₄", "Al₂O₃, high temperature (cracking)", "Heated Al₂O₃ or concentrated H₂SO₄", "NaOH in ethanol, heat"], "tip": "Halogenoalkane: ethanolic alkali. Alcohol: acid or Al₂O₃."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["c2h4 h2o", "ch2 ch2 h2o", "h2o c2h4"], ["elimination", "dehydration"]], "tips": ["Water is removed."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Ethane", "Ethanol", "Pt or Ni catalyst, heat", "H₃PO₄ catalyst", "Alcohol"], "tip": "Steam adds H and OH."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["c2h4 h2o", "h2o c2h4", "ch2 ch2 h2o"], ["h3po4", "phosphoric"]], "tips": ["The product is an alcohol."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 6, "n": 6, "ans": ["CH₃CH₂Br", "CH₂BrCH₂Br", "CH₃CH₂Cl", "CH₂ClCH₂Cl", "CH₃CHBrCH₂Br", "CH₃CH₂CH₃"], "tip": "One atom adds to each carbon of the C=C."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["1,2-dibromopropane", "1 2 dibromo propane", "dibromopropane"], ["addition"]], "tips": ["Bromine atoms add to carbons 1 and 2."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["bromine"], ["colourless", "decolourise", "decolorise", "decolourised", "loses its colour"], ["no change", "stays orange", "remains orange", "no reaction", "stays the same", "does not change"], ["addition"], ["hydrogen+nickel", "hydrogen+platinum", "h2 ni", "h2 pt", "h2 and ni", "h2 and pt", "h2 with ni", "h2 with pt", "hydrogen+catalyst"], ["alcohol"]], "tips": ["(a) only one of them has a C=C bond."]}]}, "models": {"1": [["Q1", "The π bond is a region of high electron density, and its electrons are held less tightly than σ electrons and are exposed above and below the molecule. Positive or δ+ species (electrophiles) are attracted to this electron-rich region."]], "2": [["Q2", "Halogenoalkanes lose HX with NaOH in ethanol. Alcohols lose water over heated Al₂O₃ or with concentrated acid. Decane is cracked."], ["Q3", "C₂H₅OH → C₂H₄ + H₂O [1]. It is an elimination (dehydration) reaction [1]."]], "3": [["Q4", "Hydrogen with Pt or Ni gives ethane. Steam with H₃PO₄ gives ethanol, an alcohol."], ["Q5", "C₂H₄ + H₂O → C₂H₅OH [1], with a phosphoric(V) acid, H₃PO₄, catalyst [1]."]], "4": [["Q6", "HBr gives bromoethane; Br₂ gives 1,2-dibromoethane; HCl gives chloroethane; Cl₂ gives 1,2-dichloroethane. Propene with Br₂ gives 1,2-dibromopropane and with H₂ gives propane."], ["Q7", "1,2-dibromopropane [1], formed in an addition reaction [1]."]], "5": [["Q8", "(a) Shake each with aqueous bromine [1]. Hex-1-ene turns it from orange to colourless [1]; with hexane there is no change [1]. (b) Addition [1]. (c) Hydrogen with a nickel catalyst and heat [1]. (d) An alcohol [1]."]], "6": [["Exit ticket", "Hydrogen gives ethane; steam gives ethanol; hydrogen bromide gives bromoethane; bromine gives 1,2-dibromoethane."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Suggest why the π bond in ethene makes it attractive to reagents such as H⁺ or the δ+ end of H–Br.", "Q2": "Which reagent and conditions make the alkene?", "Q3": "Write the equation for the dehydration of ethanol and name the type of reaction. Type the equation like this: C2H5OH → …", "Q4": "Choose the correct answer.", "Q5": "Write the equation for the reaction of ethene with steam, and state the catalyst. Type the equation like this: C2H4 + …", "Q6": "What is the product?", "Q7": "Name the product of the reaction between propene and bromine, and state the type of reaction.", "Q8": "A student has two colourless liquids, hexane and hex-1-ene. (a) Describe a chemical test, with the result for each liquid, that tells them apart. (b) Name the type of reaction that takes place with hex-1-ene. (c) Give the reagent and conditions needed to convert hex-1-ene into hexane. (d) Name the class of compound formed when hex-1-ene reacts with steam."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'df14b193-2f8e-5fad-9cbd-ce0cd23d3331', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '14.2' limit 1), '14.2 Alkenes · Lesson 2: The mechanism of electrophilic addition, carbocation stability and Markovnikov addition', 'A Level Chemistry · 14 Hydrocarbons', '/achem-14-2-2/', 'ACHEM-14-2-2', 28, 60, 14022 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-14-2-2', '14.2 Alkenes · Lesson 2: The mechanism of electrophilic addition, carbocation stability and Markovnikov addition', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Br^δ+", "Induced by the π electrons", "Heterolytic", "A carbocation", "Br⁻"], "tip": "Ions form, not radicals."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["high electron density", "electron-rich", "electron rich", "pi bond", "π bond", "pi electrons", "π electrons", "double bond"], ["induce", "repel", "polaris", "delta positive", "partial positive"]], "tips": ["What do the π electrons do to the electrons in Br–Br?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["First", "Second", "Third", "Fourth"], "tip": "The carbocation is formed before bromide attacks."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["ch3ch2 ", "c2h5 ", "ch3ch2"], ["double bond", "c=c", "pi bond", "π bond", "c c bond"], ["h-br bond", "h br bond", "hbr bond", "bond between h", "bond in hbr", "bond in h-br", "bond of hbr", "bond in h br"]], "tips": ["Curly arrows start where the electron pair is. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["Primary", "Secondary", "Tertiary", "Primary", "Secondary"], "tip": "Count the alkyl groups on the positive carbon."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 3, "pts": [["three alkyl", "more alkyl", "3 alkyl", "three methyl", "more methyl"], ["electron-donating", "electron donating", "donate", "inductive", "push electron", "release electron", "electron-releasing"], ["spread", "delocalis", "reduce the positive", "reduces the positive", "stabilis", "less positive"]], "tips": ["Number of alkyl groups, what they do, and the effect on the charge."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["electrophilic addition"], ["ch3 3c", "ch3 2c ch3", "c ch3 3"], ["ch3 2chch2", "ch3 2ch ch2", "ch2ch ch3 2"], ["tertiary"], ["2-bromo-2-methylpropane", "2 bromo 2 methyl propane", "2-bromomethylpropane"], ["more stable", "most stable", "stability", "forms faster", "formed faster"]], "tips": ["(b) the H can add to either carbon of the C=C. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "The hydrogen end. Bromine pulls the bonding electrons towards itself, so hydrogen is δ+. The δ+ hydrogen is attracted to the high electron density of the π bond."]], "2": [["Q2", "The π electrons induce a dipole in Br₂; Br^δ+ is the electrophile; Br–Br breaks heterolytically to give a carbocation and Br⁻, which then attacks the carbocation."], ["Q3", "The high electron density of the π bond [1] repels the electrons in the Br–Br bond, inducing a dipole, so the nearer bromine atom becomes δ+ [1]."]], "3": [["Q4", "The π pair attacks H^δ+; H–Br breaks heterolytically; a carbocation forms; Br⁻ attacks it."], ["Q5", "The carbocation is CH₃CH₂⁺ [1]. One arrow starts at the C=C double bond [1]; the other starts at the H–Br bond [1]."]], "4": [["Q6", "CH₃CH₂⁺ and CH₃CH₂CH₂⁺ are primary; CH₃CH⁺CH₃ and CH₃CH₂CH⁺CH₃ are secondary; (CH₃)₃C⁺ is tertiary."], ["Q7", "A tertiary carbocation has three alkyl groups on the positive carbon, a primary has only one [1]. Alkyl groups are electron-donating (the inductive effect) [1], so more of them spread out the positive charge and stabilise the ion [1]."]], "5": [["Q8", "(a) Electrophilic addition [1]. (b) (CH₃)₃C⁺ [1] and (CH₃)₂CHCH₂⁺ [1]. (c) (CH₃)₃C⁺, a tertiary carbocation [1]. (d) 2-bromo-2-methylpropane [1]. (e) It forms through the more stable tertiary carbocation, which is formed faster than the primary one [1]."]], "6": [["Exit ticket", "2-bromobutane, because it forms through the secondary carbocation, CH₃CH₂CH⁺CH₃, which is more stable than the primary carbocation that would give 1-bromobutane."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "In H–Br, bromine is more electronegative than hydrogen. Predict which end of the molecule approaches the C=C bond first, and why.", "Q2": "Bromine with ethene: choose the correct answer.", "Q3": "Explain how a non-polar bromine molecule can act as an electrophile towards ethene.", "Q4": "Put the events of HBr adding to ethene in order.", "Q5": "Give the formula of the carbocation formed when HBr reacts with ethene, and state where each of the two curly arrows in step 1 starts.", "Q6": "Classify the carbocation.", "Q7": "Explain why a tertiary carbocation is more stable than a primary carbocation.", "Q8": "2-Methylpropene, (CH₃)₂C=CH₂, reacts with hydrogen bromide. (a) Name the mechanism. (b) Give the formulas of the two possible carbocations. (c) State which carbocation is more stable and classify it. (d) Name the major product. (e) Explain why it is the major product."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '3444b157-e3e5-5d64-8ebc-3478bf51ce78', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '14.2' limit 1), '14.2 Alkenes · Lesson 3: Oxidation of alkenes by cold and hot acidified manganate(VII); addition polymerisation', 'A Level Chemistry · 14 Hydrocarbons', '/achem-14-2-3/', 'ACHEM-14-2-3', 30, 60, 14023 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-14-2-3', '14.2 Alkenes · Lesson 3: Oxidation of alkenes by cold and hot acidified manganate(VII); addition polymerisation', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Ethane-1,2-diol", "Propane-1,2-diol", "Butane-2,3-diol", "Butane-1,2-diol", "No reaction"], "tip": "The OH groups go on the two carbons of the C=C."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["hoch2ch2oh", "ch2ohch2oh", "ch2 oh ch2 oh", "c2h4 oh 2", "c2h6o2", "ho ch2 2oh"], ["purple to colourless", "purple+colourless", "decolourise", "decolorise"]], "tips": ["One OH on each carbon."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["CO₂", "A carboxylic acid", "A ketone", "A carboxylic acid", "A ketone"], "tip": "Count the hydrogens on the carbon: 2, 1 or 0."}, {"kind": "choice", "id": "q3_1", "q": "Q5", "max": 5, "n": 5, "ans": ["CH₃COOH and CO₂", "Two CH₃COOH", "CH₃COCH₃ and CO₂", "CH₃COCH₃ and CH₃COOH", "CH₃CH₂COOH and CO₂"], "tip": "Cut at the double bond and treat each half separately."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q6", "max": 5, "n": 5, "ans": ["But-2-ene", "But-1-ene", "2-Methylpropene", "Pent-2-ene", "2-Methylbut-2-ene"], "tip": "Join the two fragments at their oxidised carbons."}, {"kind": "text", "id": "q4_1", "q": "Q7", "max": 2, "pts": [["but-2-ene", "but 2 ene", "ch3ch chch3", "2-butene"], ["symmetrical", "same on both", "two identical", "both halves", "each half", "two ch3ch", "both ends", "two molecules", "ch3ch ", "same fragment"]], "tips": ["Both halves of the molecule must be the same. Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 6, "pts": [["breaks", "broken", "opens"], ["poly(propene)", "polypropene", "poly propene", "polypropylene"], ["two", "2"], ["methyl", "ch3"], ["no double bond", "no c=c", "saturated", "no c c double", "does not contain a double", "no carbon-carbon double", "only single"], ["addition", "cannot add", "no reaction", "not react", "does not react"]], "tips": ["(d) what is left of the double bonds after polymerisation? Type formulas and symbols with ordinary numbers, for example 27Al3+ or C3H8."]}]}, "models": {"1": [["Q1", "Both reagents attack the electron-rich C=C double bond, which alkanes do not have. In each case the π bond breaks and two new groups become attached to the two carbon atoms."]], "2": [["Q2", "Ethene gives ethane-1,2-diol; propene gives propane-1,2-diol; but-2-ene gives butane-2,3-diol; but-1-ene gives butane-1,2-diol. Butane does not react."], ["Q3", "C₂H₄ + H₂O + [O] → HOCH₂CH₂OH [1]. The solution changes from purple to colourless [1]."]], "3": [["Q4", "Two hydrogens: CO₂. One hydrogen: a carboxylic acid. No hydrogens: a ketone."], ["Q5", "Propene: ethanoic acid and CO₂. But-2-ene: two ethanoic acid. 2-Methylpropene: propanone and CO₂. 2-Methylbut-2-ene: propanone and ethanoic acid. But-1-ene: propanoic acid and CO₂."]], "4": [["Q6", "Ethanoic acid only: but-2-ene. Propanoic acid and CO₂: but-1-ene. Propanone and CO₂: 2-methylpropene. Ethanoic and propanoic acids: pent-2-ene. Propanone and ethanoic acid: 2-methylbut-2-ene."], ["Q7", "But-2-ene, CH₃CH=CHCH₃ [1]. The molecule is symmetrical: each half is a CH₃CH= group, which is oxidised to CH₃COOH, so two molecules of ethanoic acid form [1]."]], "5": [["Q8", "(a) The π bond breaks, and the electrons form new σ bonds to the neighbouring monomers [1]. (b) Poly(propene) [1]. (c) Two carbon atoms in the chain [1], with a methyl group, CH₃, as the side group [1]. (d) The polymer is saturated: it has no C=C double bonds left [1], so no addition reaction with bromine can take place [1]."]], "6": [["Exit ticket", "Cold and dilute: the double bond gains two –OH groups to give propane-1,2-diol. Hot and concentrated: the double bond is broken, giving ethanoic acid from the CH₃CH= end and carbon dioxide from the =CH₂ end."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q4_1": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Both aqueous bromine and cold acidified KMnO₄ lose their colour with an alkene but not with an alkane. Suggest what the two reactions have in common.", "Q2": "What is formed with cold, dilute acidified KMnO₄?", "Q3": "Write the equation, using [O], for the oxidation of ethene by cold dilute acidified KMnO₄, and state the colour change. Type the equation like this: C2H4 + H2O + [O] → …", "Q4": "What does this end of the double bond become with hot, concentrated acidified KMnO₄?", "Q5": "What are the products with hot, concentrated acidified KMnO₄?", "Q6": "Which alkene gave these products with hot, concentrated acidified KMnO₄?", "Q7": "An alkene C₄H₈ gives only one organic product, ethanoic acid, with hot concentrated acidified KMnO₄. Identify the alkene and explain your reasoning.", "Q8": "(a) State what happens to the π bond in each monomer during addition polymerisation. (b) Name the polymer formed from propene. (c) State how many carbon atoms are in the chain of one repeat unit of poly(propene), and what group is attached as a side group. (d) Explain why poly(ethene) does not decolourise aqueous bromine."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'ac1f2487-efcd-5da8-87df-3cdd89a3396f', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '15.1' limit 1), '15.1 Halogenoalkanes · Lesson 1: Making and classifying halogenoalkanes; nucleophilic substitution reactions', 'A Level Chemistry · 15 Halogen compounds', '/achem-15-1-1/', 'ACHEM-15-1-1', 24, 60, 15011 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-15-1-1', '15.1 Halogenoalkanes · Lesson 1: Making and classifying halogenoalkanes; nucleophilic substitution reactions', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Primary", "Secondary", "Tertiary", "Primary"], "tip": "Count the carbons joined to the C–X carbon."}, {"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["HBr", "Cl₂ with UV light", "SOCl₂", "Br₂"], "tip": "Match the starting compound."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["polar", "electronegative", "δ+", "partial positive", "delta"], ["lone pair", "electron pair", "nucleophile", "donor"]], "tips": ["Think about the bond and about OH⁻."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Ethanol", "Propanenitrile", "Ethylamine", "Ethene"], "tip": "Water or ethanol as the solvent matters."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["ch3ch2ch2cl naoh", "ch3ch2ch2cl oh"], ["ch3ch2ch2oh"]], "tips": ["OH replaces Cl."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["ethylamine", "amine", "product"], ["further", "secondary", "more", "again", "nucleophile"]], "tips": ["The product has a lone pair too."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 6, "pts": [["naoh", "koh", "hydroxide"], ["aqueous", "reflux", "heat"], ["kcn", "nacn", "cyanide"], ["ethanol", "alcoholic", "heat"], ["ammonia", "nh3"], ["sealed", "excess", "pressure", "ethanol"]], "tips": ["Three different nucleophiles."]}]}, "models": {"1": [["Q1", "Primary; secondary; tertiary; chloromethane is treated as primary."], ["Q2", "HBr; Cl₂ / UV; SOCl₂; Br₂."]], "2": [["Q3", "Br is more electronegative, so the C–Br bond is polar and the carbon is δ+ [1]; OH⁻ is a nucleophile that donates a lone pair to that carbon [1]."]], "3": [["Q4", "Ethanol; propanenitrile (adds a carbon); ethylamine; ethene (elimination, next lesson)."], ["Q5", "CH₃CH₂CH₂Cl + NaOH (or OH⁻) [1] → CH₃CH₂CH₂OH + NaCl (or Cl⁻) [1]."]], "4": [["Q6", "The ethylamine produced is also a nucleophile [1], so it could react further with bromoethane to form secondary/tertiary amines; excess NH₃ makes this less likely [1]."]], "5": [["Q7", "(a) NaOH [1], aqueous, heat under reflux [1]; (b) KCN [1] in ethanol, heat [1]; (c) NH₃ [1], excess, in ethanol, heated in a sealed tube [1]."]], "6": [["Exit ticket", "Aqueous sodium hydroxide, heated under reflux."]]}, "labels": {"q2_0": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Classify the halogenoalkane.", "Q2": "Which reagent makes the halogenoalkane?", "Q3": "Explain why hydroxide ions attack the carbon atom bonded to the bromine in bromoethane.", "Q4": "Name the organic product with bromoethane.", "Q5": "Write the equation for 1-chloropropane reacting with aqueous sodium hydroxide. Type it like this: CH3CH2CH2Cl + …", "Q6": "Explain why excess ammonia is used to make ethylamine from bromoethane.", "Q7": "1-bromopropane is used to make (a) propan-1-ol, (b) butanenitrile and (c) propylamine. For each, give the reagent and the condition."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '9fe341c9-6c05-5ca5-b7b7-278a94b9f5b2', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '15.1' limit 1), '15.1 Halogenoalkanes · Lesson 2: SN1 and SN2 mechanisms, reactivity and C–X bond strength, and elimination', 'A Level Chemistry · 15 Halogen compounds', '/achem-15-1-2/', 'ACHEM-15-1-2', 19, 60, 15012 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-15-1-2', '15.1 Halogenoalkanes · Lesson 2: SN1 and SN2 mechanisms, reactivity and C–X bond strength, and elimination', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["True", "False", "True", "False"], "tip": "Bimolecular, one step."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["tertiary", "three alkyl", "3 alkyl"], ["carbocation", "stable", "stabilis", "inductive", "push electrons"], ["hinder", "crowd", "bulky", "steric", "blocked"]], "tips": ["Stability of the intermediate and crowding."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["c–i", "c-i", "c i", "carbon iodine", "iodine bond"], ["weaker", "lower bond energy", "less energy", "breaks more easily", "longer"]], "tips": ["Compare bond energies."]}, {"kind": "choice", "id": "q3_1", "q": "Q4", "max": 3, "n": 3, "ans": ["Yellow precipitate first", "Cream precipitate second", "White precipitate last"], "tip": "Weakest bond first."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["but-1-ene", "but 1 ene", "1-butene"], ["but-2-ene", "but 2 ene", "2-butene"]], "tips": ["H can be removed from either side."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 5, "pts": [["sn2", "nucleophilic substitution"], ["lone pair", "oh to c", "attacks carbon", "arrow from oh"], ["c–br", "c-br", "bond to br", "arrow from bond", "br leaves"], ["ethanol", "alcoholic", "heat"], ["base", "removes h", "proton"]], "tips": ["Two arrows for SN2; OH⁻ as a base for elimination."]}]}, "models": {"1": [["Q1", "True; false; true; false."]], "2": [["Q2", "It is a tertiary halogenoalkane [1]; the three alkyl groups donate electrons and stabilise the tertiary carbocation formed [1]; they also crowd the carbon, so attack from the back (SN2) is hindered [1]."]], "3": [["Q3", "The C–I bond is weaker (lower bond energy) than C–Cl [1], so less energy is needed to break it and it breaks more easily [1]."], ["Q4", "AgI yellow first; AgBr cream; AgCl white last."]], "4": [["Q5", "But-1-ene [1] and but-2-ene (cis and trans) [1]."]], "5": [["Q6", "(a) SN2 (nucleophilic substitution) [1]: an arrow from the lone pair on OH⁻ to the δ+ carbon [1] and from the C–Br bond to Br, which leaves as Br⁻ [1]. (b) NaOH dissolved in ethanol, heat [1]; OH⁻ acts as a base, removing H⁺ [1]."]], "6": [["Exit ticket", "SN1, because the tertiary carbocation is stabilised by three electron-donating alkyl groups."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "True or false for SN2?", "Q2": "Explain why 2-bromo-2-methylpropane reacts with hydroxide ions by the SN1 mechanism.", "Q3": "Explain why 1-iodobutane is hydrolysed faster than 1-chlorobutane.", "Q4": "With AgNO₃ in ethanol, which forms a precipitate first?", "Q5": "2-bromobutane is heated with NaOH in ethanol. Name two possible organic products.", "Q6": "Bromoethane reacts with hydroxide ions in two different ways. (a) Name the mechanism with aqueous NaOH and draw the curly arrows in words. (b) Give the conditions that make ethene instead, and the role of OH⁻."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'd2f11b2f-755c-5fa8-a870-2b52817ff403', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '16.1' limit 1), '16.1 Alcohols · Lesson 1: Making alcohols; combustion, sodium, substitution to halogenoalkanes, esterification and dehydration', 'A Level Chemistry · 16 Hydroxy compounds', '/achem-16-1-1/', 'ACHEM-16-1-1', 19, 60, 16011 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-16-1-1', '16.1 Alcohols · Lesson 1: Making alcohols; combustion, sodium, substitution to halogenoalkanes, esterification and dehydration', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Primary", "Secondary", "Tertiary", "Primary"], "tip": "Count carbons on the C–OH carbon."}, {"kind": "choice", "id": "q1_1", "q": "Q2", "max": 3, "n": 3, "ans": ["Steam, H₃PO₄ catalyst", "NaOH(aq), heat", "NaBH₄"], "tip": "Hydration, substitution, reduction."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["2c2h5oh 2na", "c2h5ona", "h2", "hydrogen"], ["ethoxide"]], "tips": ["Like water, but slower."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["ch3ch2ch2cl", "c3h7cl", "pocl3"], ["steamy", "white fumes", "misty", "fumes"]], "tips": ["Products: chloroalkane, POCl₃, HCl."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Ethyl ethanoate", "Ethene", "Methyl propanoate", "Propene"], "tip": "Alcohol part names first."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["oh", "hydroxyl", "alcohol"], ["propan-1-ol", "ch3ch2ch2oh"], ["propan-2-ol", "ch3choh", "ch3ch(oh)ch3"], ["propyl ethanoate"]], "tips": ["Both C₃ alcohols give only propene."]}]}, "models": {"1": [["Q1", "Primary; secondary; tertiary; primary."], ["Q2", "Hydration; substitution; reduction."]], "2": [["Q3", "2C₂H₅OH + 2Na → 2C₂H₅ONa + H₂ [1]; sodium ethoxide [1]."]], "3": [["Q4", "CH₃CH₂CH₂OH + PCl₅ → CH₃CH₂CH₂Cl + POCl₃ + HCl [1]; steamy white fumes (of HCl) [1]."]], "4": [["Q5", "Ethyl ethanoate; ethene; methyl propanoate; propene."]], "5": [["Q6", "(a) An –OH group (alcohol) [1]. (b) Propan-1-ol, CH₃CH₂CH₂OH [1], or propan-2-ol, CH₃CH(OH)CH₃ [1]. (c) Propyl ethanoate [1]."]], "6": [["Exit ticket", "PCl₅ (the fumes are HCl)."]]}, "labels": {"q2_0": "Q3", "q3_0": "Q4", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Classify.", "Q2": "Which method makes the alcohol?", "Q3": "Write the equation for sodium reacting with ethanol, and name the organic product.", "Q4": "Write the equation for propan-1-ol with PCl₅ and state what is observed.", "Q5": "Name the organic product.", "Q6": "Compound X, C₃H₈O, gives steamy fumes with PCl₅. With concentrated H₃PO₄ and heat it forms propene only. It reacts with ethanoic acid to form an ester. (a) What do the fumes show? (b) Give two possible structures for X. (c) Name the ester formed from propan-1-ol."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '0dff7ea6-6cbc-5d6e-97d0-2c92ace16528', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '16.1' limit 1), '16.1 Alcohols · Lesson 2: Oxidation of primary, secondary and tertiary alcohols; the tri-iodomethane test; acidity of alcohols', 'A Level Chemistry · 16 Hydroxy compounds', '/achem-16-1-2/', 'ACHEM-16-1-2', 21, 60, 16012 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-16-1-2', '16.1 Alcohols · Lesson 2: Oxidation of primary, secondary and tertiary alcohols; the tri-iodomethane test; acidity of alcohols', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Turns green", "Turns green", "Stays orange", "Turns green"], "tip": "Tertiary alcohols resist."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["distil", "distillation"], ["further", "acid", "oxidised again", "removed", "as it forms"]], "tips": ["Remove the product quickly."]}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 1, "pts": [["ch3ch2ch2oh 2 o", "ch3ch2cooh h2o", "ch3ch2cooh"]], "tips": ["Two [O]."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Propanone", "Butanone", "Propanoic acid", "No reaction"], "tip": "Primary, secondary, tertiary."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Yellow precipitate", "No precipitate", "Yellow precipitate", "No precipitate"], "tip": "Look for CH₃CH(OH)–."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["alkyl", "ethyl", "c2h5", "electron donating", "inductive", "push"], ["less stable", "destabilis", "negative charge", "concentrat", "ethoxide"]], "tips": ["Look at the anion."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["2-methylpropan-2-ol+orange", "tertiary+orange", "stays orange", "no change"], ["butan-1-ol+green", "butan-2-ol+green", "both green", "turn green"], ["butan-2-ol+yellow", "yellow precipitate"], ["butan-1-ol+no precipitate", "no yellow", "no precipitate"]], "tips": ["Dichromate first, then iodoform."]}]}, "models": {"1": [["Q1", "Green; green; stays orange; green."]], "2": [["Q2", "Heat with acidified dichromate and distil the ethanal off as it forms [1], so it is not oxidised further to ethanoic acid [1]."], ["Q3", "CH₃CH₂CH₂OH + 2[O] → CH₃CH₂COOH + H₂O [1]."]], "3": [["Q4", "Propanone; butanone; propanoic acid; no reaction."]], "4": [["Q5", "Yes; no; yes; no."], ["Q6", "The ethyl group donates electrons to the oxygen [1], so the ethoxide ion is less stable than the hydroxide ion and ethanol loses H⁺ less easily [1]."]], "5": [["Q7", "Acidified dichromate stays orange with 2-methylpropan-2-ol (tertiary) [1] but turns green with butan-1-ol and butan-2-ol [1]; with alkaline iodine, butan-2-ol gives a pale yellow precipitate [1] and butan-1-ol gives no precipitate [1]."]], "6": [["Exit ticket", "Distil the aldehyde off as it forms."]]}, "labels": {"q2_0": "Q2", "q2_1": "Q3", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Does acidified dichromate turn green?", "Q2": "Explain how to make ethanal, not ethanoic acid, from ethanol.", "Q3": "Write the equation for the oxidation of propan-1-ol to propanoic acid using [O].", "Q4": "Product of oxidation with acidified dichromate.", "Q5": "Positive tri-iodomethane test?", "Q6": "Explain why ethanol is a weaker acid than water.", "Q7": "Three isomers of C₄H₁₀O are butan-1-ol, butan-2-ol and 2-methylpropan-2-ol. Describe how acidified dichromate and the tri-iodomethane test tell them apart, with results."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '720946a6-3f4e-547d-9ad3-1f00574f468b', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '17.1' limit 1), '17.1 Aldehydes and ketones · Lesson 1: Making aldehydes and ketones; reduction; nucleophilic addition of HCN', 'A Level Chemistry · 17 Carbonyl compounds', '/achem-17-1-1/', 'ACHEM-17-1-1', 18, 60, 17011 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-17-1-1', '17.1 Aldehydes and ketones · Lesson 1: Making aldehydes and ketones; reduction; nucleophilic addition of HCN', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Aldehyde", "Ketone", "Ketone", "Aldehyde"], "tip": "Where is C=O?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Propan-1-ol", "Propan-2-ol", "Butan-2-ol", "Ethanol"], "tip": "Aldehyde → primary; ketone → secondary."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 1, "pts": [["ch3ch2ch2ch2oh", "c4h9oh", "butan-1-ol"]], "tips": ["Two [H]."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["2-hydroxy-2-methylpropanenitrile", "hydroxy methylpropanenitrile", "hydroxynitrile"], ["(ch3)2c(oh)cn", "ch3 2c oh cn", "c(oh)cn"]], "tips": ["OH on the old C=O carbon, CN added."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["lone pair", "cn attacks", "cn- attacks", "arrow from cn"], ["δ+", "partial positive", "carbon of c=o", "carbonyl carbon", "c o carbon"], ["h+", "hcn", "proton", "water"]], "tips": ["Attack, then protonate."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["nucleophilic addition"], ["ch3ch2ch(oh)cn", "2-hydroxybutanenitrile"], ["planar", "flat", "trigonal"], ["both sides", "either side", "equal", "racemic", "50"]], "tips": ["Planar C=O."]}]}, "models": {"1": [["Q1", "Aldehyde; ketone; ketone; aldehyde."]], "2": [["Q2", "Propan-1-ol; propan-2-ol; butan-2-ol; ethanol."], ["Q3", "CH₃CH₂CH₂CHO + 2[H] → CH₃CH₂CH₂CH₂OH [1]."]], "3": [["Q4", "2-hydroxy-2-methylpropanenitrile [1]; (CH₃)₂C(OH)CN [1]."]], "4": [["Q5", "The lone pair on the carbon of CN⁻ attacks [1] the δ+ carbonyl carbon, and the π electrons move to oxygen, forming O⁻ [1]; the O⁻ then gains H⁺ from HCN (or water) [1]."]], "5": [["Q6", "(a) Nucleophilic addition [1]. (b) CH₃CH₂CH(OH)CN, 2-hydroxybutanenitrile [1]. (c) The C=O group is planar [1], so CN⁻ attacks equally from both sides, giving equal amounts of the two optical isomers (a racemic mixture) [1]."]], "6": [["Exit ticket", "Nucleophilic addition."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Aldehyde or ketone?", "Q2": "Product of reduction with NaBH₄.", "Q3": "Write the equation for the reduction of butanal using [H].", "Q4": "Name the product of propanone with HCN, and give its structural formula.", "Q5": "Describe the two steps of the mechanism for CN⁻ adding to ethanal.", "Q6": "Propanal reacts with HCN/KCN. (a) Name the type of reaction. (b) Draw (describe) the product. (c) Explain why the product mixture is not optically active."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '9720319e-1144-556a-a8e8-7a909576bab8', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '17.1' limit 1), '17.1 Aldehydes and ketones · Lesson 2: Tests: 2,4-DNPH, Tollens'' reagent, Fehling''s solution and the tri-iodomethane test', 'A Level Chemistry · 17 Carbonyl compounds', '/achem-17-1-2/', 'ACHEM-17-1-2', 18, 60, 17012 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-17-1-2', '17.1 Aldehydes and ketones · Lesson 2: Tests: 2,4-DNPH, Tollens'' reagent, Fehling''s solution and the tri-iodomethane test', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Orange precipitate", "Orange precipitate", "No precipitate", "No precipitate"], "tip": "Only aldehydes and ketones."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["oxidis", "ethanoic", "carboxylic", "ethanoate"], ["ag+ reduced", "silver ions reduced", "reduced to silver", "ag"]], "tips": ["Two half-reactions."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Red-brown precipitate", "Stays blue", "Red-brown precipitate", "Stays blue"], "tip": "Aldehydes reduce Cu²⁺."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Yes", "No", "Yes", "No"], "tip": "Look for CH₃C=O."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["tollens", "fehling"], ["butanone+no", "butanone+no change", "ketone+no", "butanone+blue"], ["iodine", "iodoform", "tri-iodomethane"], ["butanone+yellow", "butanone+precipitate"]], "tips": ["Aldehydes vs ketone first."]}]}, "models": {"1": [["Q1", "Yes; yes; no; no (the C=O in acids does not react)."]], "2": [["Q2", "Ethanal is oxidised to ethanoic acid (ethanoate) [1]; silver ions are reduced to silver metal, which coats the tube [1]."]], "3": [["Q3", "Aldehydes: red-brown; ketones: blue."]], "4": [["Q4", "Yes; no; yes; no."]], "5": [["Q5", "Tollens'' (or Fehling''s) [1]: butanal and 2-methylpropanal give a silver mirror (red-brown precipitate); butanone gives no change [1]. Alkaline iodine [1]: butanone gives a yellow precipitate of CHI₃ (and the two aldehydes are told apart by melting point of the 2,4-DNPH derivative) [1]."]], "6": [["Exit ticket", "Tollens'' reagent."]]}, "labels": {"q2_0": "Q2", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "With 2,4-DNPH?", "Q2": "Explain the silver mirror formed when ethanal is warmed with Tollens'' reagent.", "Q3": "Result with warm Fehling''s solution.", "Q4": "Yellow precipitate with alkaline iodine?", "Q5": "All three give an orange precipitate with 2,4-DNPH. Describe how two further tests identify each one."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'da7a7cb3-10ba-58fc-b0e2-87f0628f9944', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '18.1' limit 1), '18.1 Carboxylic acids: Making carboxylic acids, and their reactions as acids, with alcohols and with LiAlH₄', 'A Level Chemistry · 18 Carboxylic acids and derivatives', '/achem-18-1/', 'ACHEM-18-1', 17, 60, 18010 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-18-1', '18.1 Carboxylic acids: Making carboxylic acids, and their reactions as acids, with alcohols and with LiAlH₄', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Propanoic acid", "Propanoic acid", "Ethanoic acid", "Butanoic acid"], "tip": "Count carbons; CN carbon becomes COOH."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["2ch3ch2cooh na2co3", "2 ch3ch2cooh na2co3", "na2co3"], ["2ch3ch2coona", "ch3ch2coona co2", "co2 h2o"]], "tips": ["Salt, CO₂ and water."]}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 3, "n": 3, "ans": ["Sodium ethanoate", "Magnesium propanoate", "Potassium methanoate"], "tip": "–oic acid → –oate."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["ch3ch2cooh c2h5oh", "ch3ch2cooch2ch3", "ch3ch2cooc2h5"], ["sulfuric", "h2so4", "reflux"]], "tips": ["Acid + alcohol."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 3, "n": 3, "ans": ["LiAlH₄ only", "NaBH₄ or LiAlH₄", "NaBH₄ or LiAlH₄"], "tip": "Acids need the stronger one."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["carbonate", "na2co3", "nahco3", "hydrogencarbonate"], ["propanoic+fizz", "acid+fizz", "effervescence", "bubbles", "co2"], ["propan-1-ol+no", "alcohol+no", "no fizz", "no effervescence", "no bubbles", "no change"]], "tips": ["Carbonates."]}]}, "models": {"1": [["Q1", "Propanoic; propanoic; ethanoic; butanoic."]], "2": [["Q2", "2CH₃CH₂COOH + Na₂CO₃ [1] → 2CH₃CH₂COONa + CO₂ + H₂O [1]."], ["Q3", "As listed."]], "3": [["Q4", "CH₃CH₂COOH + C₂H₅OH ⇌ CH₃CH₂COOC₂H₅ + H₂O [1]; concentrated H₂SO₄ catalyst, heat under reflux [1]."]], "4": [["Q5", "LiAlH₄ only; either; either."]], "5": [["Q6", "Add sodium carbonate (or hydrogencarbonate) [1]; propanoic acid fizzes, giving CO₂ [1]; propan-1-ol gives no effervescence [1]."]], "6": [["Exit ticket", "LiAlH₄ in dry ether."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q4", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which acid is made?", "Q2": "Write the equation for propanoic acid with sodium carbonate. Type it like this: 2CH3CH2COOH + …", "Q3": "Name the salt.", "Q4": "Write the equation for the formation of ethyl propanoate and give the conditions.", "Q5": "Which reducing agent works?", "Q6": "Describe a chemical test to distinguish propanoic acid from propan-1-ol, giving the result for each."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '98ae7d64-086d-571f-9281-6b4ffde03536', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '18.2' limit 1), '18.2 Esters: Naming esters, making them, and hydrolysis by acid and by alkali', 'A Level Chemistry · 18 Carboxylic acids and derivatives', '/achem-18-2/', 'ACHEM-18-2', 15, 60, 18020 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-18-2', '18.2 Esters: Naming esters, making them, and hydrolysis by acid and by alkali', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Ethyl ethanoate", "Methyl propanoate", "Propyl methanoate", "Ethyl butanoate"], "tip": "The alkyl group is the part after the O."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["ethanoic"], ["ethanol"]], "tips": ["Split the name."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 1, "pts": [["ch3ch2cooh ch3oh", "ch3oh ch3ch2cooh", "propanoic acid methanol"]], "tips": ["Acid + alcohol."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["carboxylate", "salt", "coo-", "ion"], ["not react", "cannot react", "not reversible", "irreversible", "removed"]], "tips": ["What happens to the acid formed?"]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 2, "n": 2, "ans": ["Propane-1,2,3-triol", "Sodium salts of fatty acids"], "tip": "Alkaline hydrolysis."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["ethanoic acid"], ["propan-1-ol", "propanol"], ["sodium ethanoate"], ["propan-1-ol", "propanol"]], "tips": ["Acid vs salt."]}]}, "models": {"1": [["Q1", "As listed."], ["Q2", "Ethanoic acid [1] and ethanol [1]."]], "2": [["Q3", "CH₃CH₂COOCH₃ + H₂O ⇌ CH₃CH₂COOH + CH₃OH [1]."]], "3": [["Q4", "The carboxylic acid formed is converted into a carboxylate ion (salt) [1], which does not react with the alcohol, so the reverse reaction cannot happen [1]."]], "4": [["Q5", "Glycerol and soap."]], "5": [["Q6", "(a) Ethanoic acid [1] and propan-1-ol [1]. (b) Sodium ethanoate [1] and propan-1-ol [1]."]], "6": [["Exit ticket", "Methyl ethanoate."]]}, "labels": {"q1_1": "Q2", "q2_0": "Q3", "q3_0": "Q4", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Name the ester.", "Q2": "Ethyl ethanoate is made from which acid and which alcohol?", "Q3": "Write the equation for the acid hydrolysis of methyl propanoate.", "Q4": "Explain why alkaline hydrolysis of an ester goes to completion.", "Q5": "Products of boiling a fat with NaOH(aq).", "Q6": "Propyl ethanoate is hydrolysed (a) by heating with dilute H₂SO₄ and (b) by heating with NaOH(aq). Name the organic products in each case."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'd84a8341-7be7-51c7-9643-afc140b4b7a3', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '19.1' limit 1), '19.1 Primary amines: Making amines from halogenoalkanes and ammonia, and why a mixture of amines forms', 'A Level Chemistry · 19 Nitrogen compounds', '/achem-19-1/', 'ACHEM-19-1', 15, 60, 19010 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-19-1', '19.1 Primary amines: Making amines from halogenoalkanes and ammonia, and why a mixture of amines forms', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Primary", "Secondary", "Tertiary", "Primary"], "tip": "Count alkyl groups on N."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["ch3ch2ch2br 2nh3", "2nh3", "2 nh3"], ["ch3ch2ch2nh2 nh4br", "nh4br"]], "tips": ["Two NH₃."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["ethylamine", "amine", "product"], ["lone pair", "nucleophile", "react further", "reacts with more"]], "tips": ["The product is also a nucleophile."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 3, "n": 3, "ans": ["Ethylammonium chloride", "Methylammonium sulfate", "Propylammonium chloride"], "tip": "Amine → ammonium."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["ammonia", "nh3"], ["ethanol", "sealed", "pressure", "heat"], ["excess", "more likely", "collide with ammonia"], ["dimethylamine", "trimethylamine"]], "tips": ["Excess is the key."]}]}, "models": {"1": [["Q1", "Primary; secondary; tertiary; primary."]], "2": [["Q2", "CH₃CH₂CH₂Br + 2NH₃ [1] → CH₃CH₂CH₂NH₂ + NH₄Br [1]."]], "3": [["Q3", "The ethylamine formed has a lone pair on N, so it is also a nucleophile [1] and reacts further with bromoethane to give secondary and tertiary amines [1]."]], "4": [["Q4", "As listed."]], "5": [["Q5", "(a) Ammonia [1] in ethanol, heated in a sealed tube [1]. (b) Excess ammonia makes chloromethane more likely to collide with NH₃ than with methylamine [1]. (c) Dimethylamine (or trimethylamine) [1]."]], "6": [["Exit ticket", "So that the halogenoalkane reacts with ammonia rather than with the amine already formed."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Classify.", "Q2": "Write the overall equation for making propylamine from 1-bromopropane and ammonia.", "Q3": "Explain why the reaction of bromoethane with ammonia gives a mixture of products.", "Q4": "Name the salt.", "Q5": "A student wants to make mainly methylamine from chloromethane. (a) Give the reagent and conditions. (b) Explain why the conditions favour methylamine. (c) Name one other amine that may form."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '9a1fa5aa-d03d-5f9d-ab8c-81882115630e', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '19.2' limit 1), '19.2 Nitriles and hydroxynitriles: Making nitriles and hydroxynitriles, and hydrolysing them to carboxylic acids', 'A Level Chemistry · 19 Nitrogen compounds', '/achem-19-2/', 'ACHEM-19-2', 15, 60, 19020 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-19-2', '19.2 Nitriles and hydroxynitriles: Making nitriles and hydroxynitriles, and hydrolysing them to carboxylic acids', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Ethanenitrile", "Propanenitrile", "Butanenitrile", "2-hydroxypropanenitrile"], "tip": "The CN carbon counts."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["pentanenitrile"], ["ethanol", "reflux", "heat"]], "tips": ["Four carbons + 1."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["2-hydroxypropanenitrile", "2-hydroxy-2-methylpropanenitrile", "2-hydroxybutanenitrile"], "tip": "Add one carbon."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["ch3cn 2h2o hcl", "ch3cn", "2h2o"], ["ch3cooh nh4cl", "nh4cl"]], "tips": ["Acid and ammonium chloride."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["kcn", "cyanide"], ["ethanol", "reflux"], ["propanenitrile", "ch3ch2cn"], ["dilute acid", "hcl", "h2so4", "hydrolys"]], "tips": ["Add C, then hydrolyse."]}]}, "models": {"1": [["Q1", "As listed."]], "2": [["Q2", "Pentanenitrile [1]; KCN in ethanol, heat under reflux [1]."]], "3": [["Q3", "As listed."]], "4": [["Q4", "CH₃CN + 2H₂O + HCl [1] → CH₃COOH + NH₄Cl [1]."]], "5": [["Q5", "Step 1: KCN [1] in ethanol, heat under reflux [1], giving propanenitrile [1]. Step 2: heat under reflux with dilute HCl (acid hydrolysis) to give propanoic acid [1]."]], "6": [["Exit ticket", "Three, including the carbon of the CN group."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Name.", "Q2": "Name the nitrile made from 1-bromobutane and KCN, and give the conditions.", "Q3": "Product with HCN/KCN.", "Q4": "Write the equation for the acid hydrolysis of ethanenitrile with HCl.", "Q5": "Describe a two-step synthesis of propanoic acid from bromoethane. Give reagents, conditions and the intermediate."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'bcec90a2-122b-541c-972f-ed5f4d15ad19', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '20.1' limit 1), '20.1 Addition polymerisation: Monomers and repeat units, and the problems of disposing of poly(alkenes)', 'A Level Chemistry · 20 Polymerisation', '/achem-20-1/', 'ACHEM-20-1', 17, 60, 20010 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-20-1', '20.1 Addition polymerisation: Monomers and repeat units, and the problems of disposing of poly(alkenes)', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Poly(ethene)", "Poly(propene)", "Poly(chloroethene)", "Poly(phenylethene)"], "tip": "poly(monomer)."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["ch(ch3)", "ch ch3", "chch3"], ["two", "both carbons", "–ch(ch3)–ch(ch3)–", "ch(ch3)ch(ch3)"]], "tips": ["Each double-bond carbon carries a CH₃."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["CH₂=CHCN", "CF₂=CF₂", "CH₂=CHCl", "CH₂=C(CH₃)COOCH₃"], "tip": "Two carbons, add C=C."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["landfill", "non-biodegradable", "not biodegrad", "persist"], ["burn", "combust", "incinerat"], ["hcl", "hydrogen chloride", "toxic", "acid", "dioxin", "inert", "strong bonds", "non-polar"]], "tips": ["Landfill and burning."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["addition"], ["–cf2–cf2–", "cf2cf2", "cf2 cf2", "cf2"], ["c–f", "c-f", "c f", "carbon fluorine"], ["strong", "high bond energy", "hard to break"]], "tips": ["Same rules as ethene."]}]}, "models": {"1": [["Q1", "As listed."]], "2": [["Q2", "The two carbons that were the C=C form the chain [1], each carrying one CH₃ side group: –CH(CH₃)–CH(CH₃)– [1]."]], "3": [["Q3", "As listed."]], "4": [["Q4", "It is non-biodegradable, so it stays in landfill [1]; burning it [1] releases toxic HCl (and dioxins); it lasts because its C–C and C–H bonds are strong and non-polar, so microbes cannot break it down [1]."]], "5": [["Q5", "(a) Addition [1]. (b) –CF₂–CF₂– [1]. (c) The C–F bonds [1] (and C–C bonds) are very strong, so they are hard to break [1]."]], "6": [["Exit ticket", "–CH₂–CH(CH₃)–"]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Name the polymer.", "Q2": "Draw (describe) the repeat unit of the polymer made from but-2-ene, CH₃CH=CHCH₃.", "Q3": "Which monomer made this polymer?", "Q4": "Give two problems of disposing of poly(chloroethene) and explain one.", "Q5": "Non-stick pans are coated with PTFE, made from tetrafluoroethene, CF₂=CF₂. (a) Name the type of polymerisation. (b) Give the repeat unit. (c) Explain why this polymer is very unreactive."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '312a9bbd-cbdf-5303-aa9d-5348a78c1263', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '21.1' limit 1), '21.1 Organic synthesis: Identifying functional groups and planning two- and three-step synthetic routes', 'A Level Chemistry · 21 Organic synthesis', '/achem-21-1/', 'ACHEM-21-1', 22, 60, 21010 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-21-1', '21.1 Organic synthesis: Identifying functional groups and planning two- and three-step synthetic routes', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 6, "n": 6, "ans": ["Alcohol", "Aldehyde", "Ketone", "Ester", "Nitrile", "Amine"], "tip": "Recall the list."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["NaOH(aq), heat under reflux", "KCN in ethanol, heat", "Steam, H₃PO₄ catalyst", "NaBH₄"], "tip": "Use the map."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 4, "pts": [["steam", "h2o", "water"], ["h3po4", "phosphoric", "catalyst"], ["dichromate", "k2cr2o7", "cr2o7"], ["acid", "h+", "h2so4", "heat", "reflux"]], "tips": ["Propene → propan-2-ol → propanone."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["hcn", "kcn"], ["hydrolys", "dilute acid", "hcl", "h2so4"]], "tips": ["Add CN, then hydrolyse."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 6, "pts": [["ethanol"], ["bromoethane", "chloroethane", "hbr"], ["propanenitrile", "kcn"], ["propanoic acid", "hydrolys"], ["ethanol+conc", "h2so4", "sulfuric"], ["steam", "h3po4"]], "tips": ["You need both ethanol and propanoic acid, both from ethene."]}]}, "models": {"1": [["Q1", "As listed."]], "2": [["Q2", "As listed."]], "3": [["Q3", "Step 1: steam [1] with an H₃PO₄ catalyst (high temperature and pressure), giving propan-2-ol [1]. Step 2: acidified potassium dichromate(VI) [1], heat [1]."]], "4": [["Q4", "Step 1: HCN with KCN, giving 2-hydroxypropanenitrile [1]. Step 2: heat under reflux with dilute acid (hydrolysis) [1]."]], "5": [["Q5", "Make ethanol from ethene with steam/H₃PO₄ [1] [1]. Make bromoethane from ethene with HBr [1]; KCN in ethanol gives propanenitrile [1]; hydrolysis with dilute acid gives propanoic acid [1]; propanoic acid + ethanol with concentrated H₂SO₄, heat, gives ethyl propanoate [1]."]], "6": [["Exit ticket", "Cyanide: KCN (or HCN/KCN)."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Name the functional group.", "Q2": "Give the reagent and conditions.", "Q3": "Suggest a two-step route from propene to propanone. Give reagents and conditions for each step.", "Q4": "Ethanal is converted into 2-hydroxypropanoic acid (lactic acid). Give the two steps with reagents.", "Q5": "Plan a three-step synthesis of ethyl propanoate using ethene as the only organic starting material. Name each intermediate."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select '83f83dcf-bf68-5490-a8fc-b0a01cb273c5', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '22.1' limit 1), '22.1 Infrared spectroscopy: Reading an infrared spectrum to identify functional groups', 'A Level Chemistry · 22 Analytical techniques', '/achem-22-1/', 'ACHEM-22-1', 17, 60, 22010 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-22-1', '22.1 Infrared spectroscopy: Reading an infrared spectrum to identify functional groups', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["True", "True", "False"], "tip": "Units: cm⁻¹."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["O–H (alcohol)", "O–H (acid)", "C=O", "C–H", "N–H"], "tip": "Learn the ranges."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Alcohol", "Ketone", "Carboxylic acid", "Ester"], "tip": "Combine evidence."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["c=o", "c o", "1700", "1710", "carbonyl"], ["2500", "3000", "broader", "very broad"]], "tips": ["Product is propanoic acid."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["c=o", "carbonyl", "c o"], ["no o–h", "no oh", "not an alcohol", "no alcohol", "no o-h"], ["propanone", "acetone", "ch3coch3"]], "tips": ["Ketone with three carbons."]}]}, "models": {"1": [["Q1", "True; true; false."]], "2": [["Q2", "As listed."]], "3": [["Q3", "As listed."]], "4": [["Q4", "A strong C=O absorption appears near 1700 cm⁻¹ [1]; the O–H absorption moves to 2500–3000 cm⁻¹ and becomes very broad [1]."]], "5": [["Q5", "(a) C=O [1]. (b) There is no O–H, so P is not an alcohol [1]. (c) Propanone, CH₃COCH₃ [1]."]], "6": [["Exit ticket", "About 1670–1740 cm⁻¹."]]}, "labels": {"q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "True or false?", "Q2": "Which bond?", "Q3": "Identify the type of compound.", "Q4": "Propan-1-ol is heated under reflux with acidified dichromate. Describe how the IR spectrum of the product differs from that of propan-1-ol.", "Q5": "Compound P, C₃H₆O, has a strong absorption at 1720 cm⁻¹ and no absorption between 3200 and 3600 cm⁻¹. It gives an orange precipitate with 2,4-DNPH but no silver mirror with Tollens'' reagent. (a) Which bond causes the 1720 cm⁻¹ peak? (b) What does the absence of 3200–3600 show? (c) Identify P."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) select 'e2bde83c-8d64-5444-8342-6fdee8fccf3e', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'AS & A Level Chemistry' and t.code = '22.2' limit 1), '22.2 Mass spectrometry: Molecular ion, M+1 peak, M+2 for chlorine and bromine, and fragmentation', 'A Level Chemistry · 22 Analytical techniques', '/achem-22-2/', 'ACHEM-22-2', 18, 60, 22020 on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ACHEM-22-2', '22.2 Mass spectrometry: Molecular ion, M+1 peak, M+2 for chlorine and bromine, and fragmentation', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["46", "58", "60", "74"], "tip": "Add the Ar values (C 12, H 1, O 16)."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["264", "44", "100 × 2.64", "1.1 × 40"], ["6"]], "tips": ["Use the formula."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["One bromine atom", "One chlorine atom", "Two chlorine atoms"], "tip": "Isotope ratios."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 5, "n": 5, "ans": ["CH₃⁺", "C₂H₅⁺", "CH₃CO⁺", "COOH⁺", "CH₂OH⁺"], "tip": "Add the masses."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 4, "pts": [["bromine", "br"], ["1:1", "equal", "79", "81"], ["bromoethane", "c2h5br", "ch3ch2br"], ["c2h5", "ethyl"]], "tips": ["Mr 108 = C₂H₅⁷⁹Br."]}]}, "models": {"1": [["Q1", "46; 58; 60; 74."]], "2": [["Q2", "n = (100 × 2.64) ÷ (1.1 × 40.0) = 264 ÷ 44 [1] = 6 [1]."]], "3": [["Q3", "As listed."]], "4": [["Q4", "As listed."]], "5": [["Q5", "(a) The molecule contains one bromine atom [1], because ⁷⁹Br and ⁸¹Br give M and M+2 peaks in a 1:1 ratio [1]. (b) Bromoethane, C₂H₅Br (12×2 + 5 + 79 = 108) [1]. (c) C₂H₅⁺ [1]."]], "6": [["Exit ticket", "One chlorine atom in the molecule."]]}, "labels": {"q2_0": "Q2", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Give the m/e of the molecular ion.", "Q2": "A compound has M⁺ abundance 40.0% and M+1 abundance 2.64%. Calculate the number of carbon atoms.", "Q3": "Which halogen is present?", "Q4": "Identify the fragment.", "Q5": "Compound Q has peaks at m/e 108 and 110 of equal height, an M+1 peak showing two carbon atoms, and a fragment at m/e 29. (a) What do the 108/110 peaks show? (b) Use the data to identify Q. (c) Identify the m/e 29 fragment."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
