insert into public.quizzes (id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '1 Atomic structure · Topic quiz', 'Topical quiz for A Level Chemistry, topic 1 Atomic structure (subtopics 1.1 to 1.4). Questions come from the interactive lessons. Written answers are marked against the mark scheme; your teacher checks every mark.', null, 2, false, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions;
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f2330c81-4dd0-52eb-a683-6390b60b6183', 'mcq', 'Which part of the atom?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('f2330c81-4dd0-52eb-a683-6390b60b6183', 0, 'Mass, positive charge and nucleons: nucleus. Almost all of the volume: the electron shells around the nucleus.', 'Nucleus') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', 'f2330c81-4dd0-52eb-a683-6390b60b6183', 1);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('4394d6e7-32fd-598d-9a7f-2aa5e716c40c', 'mcq', 'How many of each particle? Use Z and A.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('4394d6e7-32fd-598d-9a7f-2aa5e716c40c', 3, '²³Na: 11 protons, 12 neutrons; Na⁺ has 10 electrons. ²⁷Al: 14 neutrons; Al³⁺ has 10 electrons. S²⁻ has 16 + 2 = 18 electrons. ³⁷Cl has 37 − 17 = 20 neutrons.', '14') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '4394d6e7-32fd-598d-9a7f-2aa5e716c40c', 2);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e3614c5b-07fd-545d-8261-88d0f5142c59', 'short', 'An ion has 20 protons, 20 neutrons and 18 electrons. Identify the ion, giving its symbol, mass number and charge.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Helium_atom_QM.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e3614c5b-07fd-545d-8261-88d0f5142c59', '20 protons, so the element is calcium [1]. Mass number = 20 + 20 = 40 and there are two fewer electrons than protons, so the ion is ⁴⁰Ca²⁺ [1].', '20 protons, so the element is calcium [1]. Mass number = 20 + 20 = 40 and there are two fewer electrons than protons, so the ion is ⁴⁰Ca²⁺ [1].', '[{"text": "Marking point 1", "any": ["calcium", "ca2", "40ca", "ca 2"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["40"], "all": [], "marks": 1}]'::jsonb, '20 protons, so the element is calcium [1]. Mass number = 20 + 20 = 40 and there are two fewer electrons than protons, so the ion is ⁴⁰Ca²⁺ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', 'e3614c5b-07fd-545d-8261-88d0f5142c59', 3);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('519ba9f7-cd7d-5190-9d8a-f7f156dcb31f', 'mcq', 'Beams of these particles travel at the same velocity between a positive plate and a negative plate. What happens to each beam?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('519ba9f7-cd7d-5190-9d8a-f7f156dcb31f', 0, 'Positive particles (protons, alpha particles) go towards the negative plate; negative particles (electrons, chloride ions) go towards the positive plate; neutrons carry no charge and go straight on.', 'Deflected towards the positive plate') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '519ba9f7-cd7d-5190-9d8a-f7f156dcb31f', 4);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('58fe30ff-b32a-53e4-a418-f0a673726c65', 'short', 'Protons, ¹H⁺, and alpha particles, ⁴He²⁺, travel at the same velocity through the same electric field. Deduce which beam is deflected more. Show your reasoning.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('58fe30ff-b32a-53e4-a418-f0a673726c65', 'Charge-to-mass ratio: proton 1/1 = 1; alpha particle 2/4 = 0.5 [1]. The proton has the larger ratio, so the proton beam is deflected more (about twice as much) [1].', 'Charge-to-mass ratio: proton 1/1 = 1; alpha particle 2/4 = 0.5 [1]. The proton has the larger ratio, so the proton beam is deflected more (about twice as much) [1].', '[{"text": "Marking point 1", "any": ["charge to mass", "charge/mass", "ratio", "2/4", "1/1", "0.5", "half"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["proton", "1h"], "all": [], "marks": 1}]'::jsonb, 'Charge-to-mass ratio: proton 1/1 = 1; alpha particle 2/4 = 0.5 [1]. The proton has the larger ratio, so the proton beam is deflected more (about twice as much) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '58fe30ff-b32a-53e4-a418-f0a673726c65', 5);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('07422245-b428-556b-844c-9a7c2967da52', 'mcq', 'Larger or smaller?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('07422245-b428-556b-844c-9a7c2967da52', 1, 'Mg is smaller than Na (more protons, same shell). K is larger than Na (extra shell). Na⁺ is smaller than Na (outer shell lost). Cl⁻ is larger than Cl (more repulsion, same nuclear charge). Mg²⁺ is smaller than O²⁻ (same electrons, 12 protons instead of 8).', 'Smaller') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '07422245-b428-556b-844c-9a7c2967da52', 6);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('9420c290-cad9-5446-bad1-78049440510d', 'short', 'The ions S²⁻, Cl⁻, K⁺ and Ca²⁺ are isoelectronic. (a) State what isoelectronic means. (b) Arrange the four ions in order of increasing radius and explain your order.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('9420c290-cad9-5446-bad1-78049440510d', '(a) They have the same number of electrons (18) [1]. (b) Ca²⁺ < K⁺ < Cl⁻ < S²⁻ [1]. The number of protons increases from S (16) to Ca (20) while the number of electrons and the shielding stay the same [1], so the electrons are attracted more strongly and the ion is smaller [1].', '(a) They have the same number of electrons (18) [1]. (b) Ca²⁺ < K⁺ < Cl⁻ < S²⁻ [1]. The number of protons increases from S (16) to Ca (20) while the number of electrons and the shielding stay the same [1], so the electrons are attracted more strongly and the ion is smaller [1].', '[{"text": "Marking point 1", "any": ["same number of electrons", "same electron", "same electronic configuration", "18 electrons"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ca k cl s", "ca2 k cl s2", "calcium potassium chlor", "ca 2 k cl s 2"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["more protons", "nuclear charge", "proton number", "number of protons", "20 protons"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["attract", "pulled closer", "held more"], "all": [], "marks": 1}]'::jsonb, '(a) They have the same number of electrons (18) [1]. (b) Ca²⁺ < K⁺ < Cl⁻ < S²⁻ [1]. The number of protons increases from S (16) to Ca (20) while the number of electrons and the shielding stay the same [1], so the electrons are attracted more strongly and the ion is smaller [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '9420c290-cad9-5446-bad1-78049440510d', 7);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ebf59364-1b63-5e20-9e06-a983c9c2bd94', 'mcq', 'How many?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('ebf59364-1b63-5e20-9e06-a983c9c2bd94', 4, '¹H 0, ²H 1, ³H 2 neutrons; every hydrogen isotope has 1 proton. ¹⁴C has 14 − 6 = 8 neutrons. ²³⁵U has 143 and ²³⁸U has 146 neutrons.', '143') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', 'ebf59364-1b63-5e20-9e06-a983c9c2bd94', 8);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('37ec7d82-94c4-5f2b-9830-ee6d09a1f76e', 'short', 'Define the term isotopes.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hydrogen_Deuterium_Tritium_Nuclei_Schematic.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('37ec7d82-94c4-5f2b-9830-ee6d09a1f76e', 'Atoms of the same element with the same number of protons [1] but different numbers of neutrons [1].', 'Atoms of the same element with the same number of protons [1] but different numbers of neutrons [1].', '[{"text": "Marking point 1", "any": ["same number of protons", "same proton number", "same atomic number", "same element", "same protons"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["different number of neutrons", "different numbers of neutrons", "different neutron", "different mass number", "different nucleon number", "different amount of neutrons"], "all": [], "marks": 1}]'::jsonb, 'Atoms of the same element with the same number of protons [1] but different numbers of neutrons [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '37ec7d82-94c4-5f2b-9830-ee6d09a1f76e', 9);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('985e4322-b92a-5423-9616-1739faed7e23', 'mcq', 'Same or different for atoms of ³⁵Cl and ³⁷Cl?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('985e4322-b92a-5423-9616-1739faed7e23', 1, 'Protons, electronic configuration and reactions are the same. Neutrons, mass and density are different.', 'Different') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '985e4322-b92a-5423-9616-1739faed7e23', 10);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('13674e92-702f-57a1-8a65-6936d89c6919', 'mcq', 'Are the two particles isotopes of each other?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('13674e92-702f-57a1-8a65-6936d89c6919', 1, 'Isotopes: ¹²C/¹⁴C, ¹⁶O/¹⁸O and ²³⁵U/²³⁸U (same protons, different neutrons). ¹⁴C/¹⁴N and ⁴⁰Ar/⁴⁰Ca are different elements. O₂ and O₃ are different molecules of oxygen, not isotopes.', 'Not isotopes') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '13674e92-702f-57a1-8a65-6936d89c6919', 11);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('0eb0a12e-d346-5e5e-b3f5-15c3b2b85cd5', 'short', 'State the numbers of protons, neutrons and electrons in a ⁵⁶Fe³⁺ ion (Z = 26).', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0eb0a12e-d346-5e5e-b3f5-15c3b2b85cd5', '26 protons [1], 56 − 26 = 30 neutrons [1], 26 − 3 = 23 electrons [1].', '26 protons [1], 56 − 26 = 30 neutrons [1], 26 − 3 = 23 electrons [1].', '[{"text": "Marking point 1", "any": ["26"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["30"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["23"], "all": [], "marks": 1}]'::jsonb, '26 protons [1], 56 − 26 = 30 neutrons [1], 26 − 3 = 23 electrons [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '0eb0a12e-d346-5e5e-b3f5-15c3b2b85cd5', 12);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('96e95e1b-b3c6-516c-b0b0-5fa373004669', 'mcq', 'How many?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('96e95e1b-b3c6-516c-b0b0-5fa373004669', 2, 'p: 3 orbitals; one orbital: 2 electrons; d: 5 orbitals, so 10 electrons. n = 2: 2s + 2p = 2 + 6 = 8. n = 3: 3s + 3p + 3d = 2 + 6 + 10 = 18, in three sub-shells.', '3') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '96e95e1b-b3c6-516c-b0b0-5fa373004669', 13);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ebb6ba6f-b9b4-5846-8e83-97135f2e8c6f', 'mcq', 'Choose the electronic configuration.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('ebb6ba6f-b9b4-5846-8e83-97135f2e8c6f', 1, 'N 1s² 2s² 2p³; Na 1s² 2s² 2p⁶ 3s¹; Cl 1s² 2s² 2p⁶ 3s² 3p⁵; K … 3p⁶ 4s¹; Sc … 3p⁶ 3d¹ 4s². Na⁺ and F⁻ both have 10 electrons: 1s² 2s² 2p⁶.', '1s² 2s² 2p⁶') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', 'ebb6ba6f-b9b4-5846-8e83-97135f2e8c6f', 14);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a09acce6-1db9-5a27-966a-92b930f27158', 'short', 'Write the full electronic configuration of a sulfur atom (Z = 16) and state how many unpaired electrons it has.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Klechkowski_rule_2.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a09acce6-1db9-5a27-966a-92b930f27158', '1s² 2s² 2p⁶ 3s² 3p⁴ [1]. The four 3p electrons occupy three orbitals: one pair and two unpaired electrons [1].', '1s² 2s² 2p⁶ 3s² 3p⁴ [1]. The four 3p electrons occupy three orbitals: one pair and two unpaired electrons [1].', '[{"text": "Marking point 1", "any": ["3s2 3p4", "3p4"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["two unpaired", "2 unpaired", "two", "unpaired electrons 2", "2 electrons are unpaired"], "all": [], "marks": 1}]'::jsonb, '1s² 2s² 2p⁶ 3s² 3p⁴ [1]. The four 3p electrons occupy three orbitals: one pair and two unpaired electrons [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', 'a09acce6-1db9-5a27-966a-92b930f27158', 15);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3f59dcda-aed0-5639-a028-27f6f883aaa8', 'mcq', 'How many unpaired electrons does the atom have in its ground state?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('3f59dcda-aed0-5639-a028-27f6f883aaa8', 1, 'H 1; He 0; C 2; N 3; O 2 (one pair, two single); F 1; Ne 0; P 3.', '1') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '3f59dcda-aed0-5639-a028-27f6f883aaa8', 16);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('b76efd64-de24-5ce2-9b15-5c6ed4608e80', 'short', 'Explain why the three electrons in the 2p sub-shell of a nitrogen atom occupy three separate orbitals rather than pairing up.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Orbital_diagram_nitrogen.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b76efd64-de24-5ce2-9b15-5c6ed4608e80', 'Electrons repel each other [1]. Occupying separate orbitals (with parallel spins) minimises this repulsion and gives a lower-energy, more stable arrangement [1].', 'Electrons repel each other [1]. Occupying separate orbitals (with parallel spins) minimises this repulsion and gives a lower-energy, more stable arrangement [1].', '[{"text": "Marking point 1", "any": ["repel", "repulsion"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["separate orbitals", "singly", "single", "lower energy", "more stable", "minimis", "minimiz", "less repulsion", "reduce"], "all": [], "marks": 1}]'::jsonb, 'Electrons repel each other [1]. Occupying separate orbitals (with parallel spins) minimises this repulsion and gives a lower-energy, more stable arrangement [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', 'b76efd64-de24-5ce2-9b15-5c6ed4608e80', 17);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('eb6aa094-a0ff-5ba7-9770-3dd881a6872b', 'mcq', 'Choose the shorthand electronic configuration.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('eb6aa094-a0ff-5ba7-9770-3dd881a6872b', 4, 'K [Ar] 4s¹; Ca [Ar] 4s²; Sc [Ar] 3d¹ 4s²; Ti [Ar] 3d² 4s².', '[Ar] 3d² 4s²') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', 'eb6aa094-a0ff-5ba7-9770-3dd881a6872b', 18);
