insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('896f73aa-1bc8-50d3-83eb-83427ff80d46', 6, 'V 3d³ 4s²; Mn 3d⁵ 4s²; Fe 3d⁶ 4s²; Co 3d⁷ 4s²; Ni 3d⁸ 4s²; Zn 3d¹⁰ 4s²; Ga 3d¹⁰ 4s² 4p¹ (each after [Ar]).', '[Ar] 3d¹⁰ 4s² 4p¹') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '896f73aa-1bc8-50d3-83eb-83427ff80d46', 19);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('08eff034-5804-594e-98d1-1f1ce7fbd6bc', 'short', 'State the number of unpaired electrons in an iron atom, [Ar] 3d⁶ 4s², and explain your answer.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Simple_Periodic_Table_Chart-blocks.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('08eff034-5804-594e-98d1-1f1ce7fbd6bc', 'Four unpaired electrons [1]. The six 3d electrons occupy five orbitals: all five singly, then one pair, which leaves four unpaired; the two 4s electrons are paired [1].', 'Four unpaired electrons [1]. The six 3d electrons occupy five orbitals: all five singly, then one pair, which leaves four unpaired; the two 4s electrons are paired [1].', '[{"text": "Marking point 1", "any": ["four unpaired", "4 unpaired", "four", "4 electrons"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["five orbitals", "5 orbitals", "singly", "one pair", "one orbital", "separate orbitals"], "all": [], "marks": 1}]'::jsonb, 'Four unpaired electrons [1]. The six 3d electrons occupy five orbitals: all five singly, then one pair, which leaves four unpaired; the two 4s electrons are paired [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '08eff034-5804-594e-98d1-1f1ce7fbd6bc', 20);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3811f968-0fe4-5089-87dc-2b5f6e518f58', 'mcq', 'How many unpaired electrons does the atom have?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('3811f968-0fe4-5089-87dc-2b5f6e518f58', 1, 'Cr: five in 3d and one in 4s, 6. Cu: only the 4s electron, 1. Mn: five in 3d, 5. Zn: all paired, 0.', '1') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '3811f968-0fe4-5089-87dc-2b5f6e518f58', 21);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('b40c7e31-d00f-56ec-aa60-4cea21549c41', 'mcq', 'Choose the configuration of the ion.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('b40c7e31-d00f-56ec-aa60-4cea21549c41', 4, 'Fe²⁺ 3d⁶; Fe³⁺ 3d⁵; Mn²⁺ 3d⁵; Cu²⁺ 3d⁹; Cu⁺ 3d¹⁰; Zn²⁺ 3d¹⁰; Sc³⁺ [Ar].', '[Ar] 3d¹⁰') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', 'b40c7e31-d00f-56ec-aa60-4cea21549c41', 22);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a5922ffa-f9a4-5343-b804-53109b9d01dc', 'short', 'A student writes the configuration of Fe²⁺ as [Ar] 3d⁴ 4s². Explain the mistake and give the correct configuration.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a5922ffa-f9a4-5343-b804-53109b9d01dc', 'The 4s electrons are lost first, not the 3d electrons [1], so Fe²⁺ is [Ar] 3d⁶ [1].', 'The 4s electrons are lost first, not the 3d electrons [1], so Fe²⁺ is [Ar] 3d⁶ [1].', '[{"text": "Marking point 1", "any": ["4s electrons", "4s first", "lost from 4s", "from the 4s", "4s sub", "4s is lost", "loses 4s", "lose 4s", "4s are lost"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["3d6"], "all": [], "marks": 1}]'::jsonb, 'The 4s electrons are lost first, not the 3d electrons [1], so Fe²⁺ is [Ar] 3d⁶ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', 'a5922ffa-f9a4-5343-b804-53109b9d01dc', 23);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5f7612d2-d075-57ed-9728-238364f572bb', 'mcq', 'Is the species a free radical?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('5f7612d2-d075-57ed-9728-238364f572bb', 0, 'Cl, •CH₃ and H each have an unpaired electron: free radicals. Cl⁻, Cl₂ and Ne have all their electrons paired.', 'Free radical') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '5f7612d2-d075-57ed-9728-238364f572bb', 24);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('bfd92e9f-ab1f-517b-9a44-dad00684f5d7', 'mcq', 'What is the effect on the first ionisation energy?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('bfd92e9f-ab1f-517b-9a44-dad00684f5d7', 1, 'Greater nuclear charge increases it. Greater distance, more shielding and spin-pair repulsion all decrease it.', 'Decreases it') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', 'bfd92e9f-ab1f-517b-9a44-dad00684f5d7', 25);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a4975c90-bda3-5fce-99e6-65e1aec811da', 'short', 'Explain why the first ionisation energy of potassium is lower than that of sodium.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/First_Ionization_Energy.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a4975c90-bda3-5fce-99e6-65e1aec811da', 'The outer electron of potassium is in a shell further from the nucleus [1] and is more shielded by inner shells [1]. These outweigh the greater nuclear charge, so the attraction is weaker and less energy is needed [1].', 'The outer electron of potassium is in a shell further from the nucleus [1] and is more shielded by inner shells [1]. These outweigh the greater nuclear charge, so the attraction is weaker and less energy is needed [1].', '[{"text": "Marking point 1", "any": ["further", "larger radius", "bigger radius", "greater distance", "more shells", "extra shell", "larger atomic radius", "bigger atom", "larger atom", "greater atomic radius"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["shield", "screen"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["weaker attraction", "less attraction", "less strongly", "held less"], "all": [], "marks": 1}]'::jsonb, 'The outer electron of potassium is in a shell further from the nucleus [1] and is more shielded by inner shells [1]. These outweigh the greater nuclear charge, so the attraction is weaker and less energy is needed [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', 'a4975c90-bda3-5fce-99e6-65e1aec811da', 26);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('0e6f96bd-1c47-587f-9556-ed67c4352e2a', 'mcq', 'Which element has the higher first ionisation energy?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('0e6f96bd-1c47-587f-9556-ed67c4352e2a', 7, 'Mg > Na (greater nuclear charge). Mg > Al (Al loses a 3p electron). P > S (spin-pair repulsion in S). Cl > S. Ne > Na (Na starts a new shell). Li > Na (Na''s outer electron is further away and more shielded).', 'Cl') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '0e6f96bd-1c47-587f-9556-ed67c4352e2a', 27);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d26bc00c-ebf3-54d1-9b8c-ca4e52b82a3c', 'short', 'Explain why the first ionisation energy of sulfur is lower than that of phosphorus.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d26bc00c-ebf3-54d1-9b8c-ca4e52b82a3c', 'In sulfur (3p⁴) the electron removed is one of a pair in the same 3p orbital [1]. The repulsion between the two paired electrons (spin-pair repulsion) makes it easier to remove [1].', 'In sulfur (3p⁴) the electron removed is one of a pair in the same 3p orbital [1]. The repulsion between the two paired electrons (spin-pair repulsion) makes it easier to remove [1].', '[{"text": "Marking point 1", "any": ["pair", "spin"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["repel", "repulsion"], "all": [], "marks": 1}]'::jsonb, 'In sulfur (3p⁴) the electron removed is one of a pair in the same 3p orbital [1]. The repulsion between the two paired electrons (spin-pair repulsion) makes it easier to remove [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', 'd26bc00c-ebf3-54d1-9b8c-ca4e52b82a3c', 28);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5400aa43-f634-5d20-b8b5-8f8cc3939a48', 'mcq', 'Successive ionisation energies in kJ mol⁻¹ are given. In which group is the element?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('5400aa43-f634-5d20-b8b5-8f8cc3939a48', 4, 'Large jump after 1 electron: Group 1. After 2: Group 2. After 3: Group 13. After 4: Group 14. After 5: Group 15.', 'Group 15') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '5400aa43-f634-5d20-b8b5-8f8cc3939a48', 29);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8411f038-eff3-5b00-88a1-0b64720db13b', 'short', 'An element X in Period 3 has the successive ionisation energies 1000, 2260, 3390, 4540, 6990, 8490 and 27100 kJ mol⁻¹. (a) Deduce the group of X and identify X. (b) Write an equation, with state symbols, for the third ionisation energy of X, using its real symbol. (c) Explain why successive ionisation energies always increase.', '[]'::jsonb, 5, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('8411f038-eff3-5b00-88a1-0b64720db13b', '(a) The large jump comes after the sixth electron, so X has six outer electrons and is in Group 16 [1]: X is sulfur [1]. (b) S²⁺(g) → S³⁺(g) + e⁻ [1]. (c) Each electron is removed from a more positive ion with the same nuclear charge and fewer electrons [1], so the remaining electrons are closer and attracted more strongly [1].', '(a) The large jump comes after the sixth electron, so X has six outer electrons and is in Group 16 [1]: X is sulfur [1]. (b) S²⁺(g) → S³⁺(g) + e⁻ [1]. (c) Each electron is removed from a more positive ion with the same nuclear charge and fewer electrons [1], so the remaining electrons are closer and attracted more strongly [1].', '[{"text": "Marking point 1", "any": ["group 16", "16", "six outer", "6 outer", "group vi"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["sulfur", "sulphur"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["s2 g s3 g e", "s 2 g s 3 g e"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["positive ion", "increasingly positive", "more positive", "fewer electrons", "same number of protons", "same nuclear charge"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["stronger attraction", "greater attraction", "less repulsion", "smaller radius", "closer", "held more"], "all": [], "marks": 1}]'::jsonb, '(a) The large jump comes after the sixth electron, so X has six outer electrons and is in Group 16 [1]: X is sulfur [1]. (b) S²⁺(g) → S³⁺(g) + e⁻ [1]. (c) Each electron is removed from a more positive ion with the same nuclear charge and fewer electrons [1], so the remaining electrons are closer and attracted more strongly [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8afe9e78-be5c-5052-af97-9da5706ffda6', '8411f038-eff3-5b00-88a1-0b64720db13b', 30);
