insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c5302577-2be9-5849-be3d-70a0d171ee4b', 'short', 'Magnesium has three isotopes: ²⁴Mg (79.0%), ²⁵Mg (10.0%) and ²⁶Mg (11.0%). Calculate the relative atomic mass of magnesium to three significant figures.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mass_Spectrometer_Schematic.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c5302577-2be9-5849-be3d-70a0d171ee4b', '(24 × 79.0 + 25 × 10.0 + 26 × 11.0) ÷ 100 [1] = 2432 ÷ 100 = 24.3 [1].', '(24 × 79.0 + 25 × 10.0 + 26 × 11.0) ÷ 100 [1] = 2432 ÷ 100 = 24.3 [1].', '[{"text": "Marking point 1", "any": ["2432", "1896", "24 79", "79 24", "79.0 24"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["24.3"], "all": [], "marks": 1}]'::jsonb, '(24 × 79.0 + 25 × 10.0 + 26 × 11.0) ÷ 100 [1] = 2432 ÷ 100 = 24.3 [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
