insert into public.questions (id, kind, prompt, options, marks, image_url) values ('926532d4-074c-554f-a61c-31fdf2b23d06', 'short', 'Copper has two isotopes, ⁶³Cu and ⁶⁵Cu, and a relative atomic mass of 63.5. Calculate the percentage abundance of each isotope. Show your working.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('926532d4-074c-554f-a61c-31fdf2b23d06', 'Let the abundance of ⁶³Cu be x%: 63x + 65(100 − x) = 6350 [1]. 6500 − 2x = 6350, so x = 75: ⁶³Cu is 75% [1] and ⁶⁵Cu is 25% [1].', 'Let the abundance of ⁶³Cu be x%: 63x + 65(100 − x) = 6350 [1]. 6500 − 2x = 6350, so x = 75: ⁶³Cu is 75% [1] and ⁶⁵Cu is 25% [1].', '[{"text": "Marking point 1", "any": ["100 x", "100-x", "6350", "63x"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["75"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["25"], "all": [], "marks": 1}]'::jsonb, 'Let the abundance of ⁶³Cu be x%: 63x + 65(100 − x) = 6350 [1]. 6500 − 2x = 6350, so x = 75: ⁶³Cu is 75% [1] and ⁶⁵Cu is 25% [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
