insert into public.questions (id, kind, prompt, options, marks, image_url) values ('492a610b-a2e2-5aed-88a3-4e9c9a7e6e65', 'short', 'A tablet contains 0.324 g of aspirin, C₉H₈O₄. Calculate (a) the relative molecular mass of aspirin, (b) the amount of aspirin in moles, (c) the number of aspirin molecules and (d) the number of oxygen atoms in the tablet. (Ar: H 1.0, C 12.0, O 16.0)', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('492a610b-a2e2-5aed-88a3-4e9c9a7e6e65', '(a) 9 × 12.0 + 8 × 1.0 + 4 × 16.0 = 180.0 [1]. (b) 0.324 ÷ 180.0 = 1.80 × 10⁻³ mol [1]. (c) 1.80 × 10⁻³ × 6.02 × 10²³ = 1.08 × 10²¹ molecules [1]. (d) 4 × 1.08 × 10²¹ = 4.33 × 10²¹ oxygen atoms [1].', '(a) 9 × 12.0 + 8 × 1.0 + 4 × 16.0 = 180.0 [1]. (b) 0.324 ÷ 180.0 = 1.80 × 10⁻³ mol [1]. (c) 1.80 × 10⁻³ × 6.02 × 10²³ = 1.08 × 10²¹ molecules [1]. (d) 4 × 1.08 × 10²¹ = 4.33 × 10²¹ oxygen atoms [1].', '[{"text": "Marking point 1", "any": ["180"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["1.8", "0.0018"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["1.08"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["4.33", "4.3"], "all": [], "marks": 1}]'::jsonb, '(a) 9 × 12.0 + 8 × 1.0 + 4 × 16.0 = 180.0 [1]. (b) 0.324 ÷ 180.0 = 1.80 × 10⁻³ mol [1]. (c) 1.80 × 10⁻³ × 6.02 × 10²³ = 1.08 × 10²¹ molecules [1]. (d) 4 × 1.08 × 10²¹ = 4.33 × 10²¹ oxygen atoms [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
