insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c386052c-400c-5691-a97b-27cda1c86f90', 'Ag⁺(aq) + Cl⁻(aq) [1] → AgCl(s) [1]. Na⁺ and NO₃⁻ are spectator ions.', 'Ag⁺(aq) + Cl⁻(aq) [1] → AgCl(s) [1]. Na⁺ and NO₃⁻ are spectator ions.', '[{"text": "Marking point 1", "any": ["ag aq cl aq", "cl aq ag aq"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["agcl s"], "all": [], "marks": 1}]'::jsonb, 'Ag⁺(aq) + Cl⁻(aq) [1] → AgCl(s) [1]. Na⁺ and NO₃⁻ are spectator ions.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
