insert into public.questions (id, kind, prompt, options, marks, image_url) values ('108d47cc-e074-5359-869e-1b9965cb5ca0', 'short', '6.25 g of hydrated copper(II) sulfate, CuSO₄·xH₂O, is heated to constant mass. 4.00 g of anhydrous copper(II) sulfate remains. (a) Explain why the sample is heated to constant mass. (b) Calculate the value of x. (M: CuSO₄ 159.6, H₂O 18.0)', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('108d47cc-e074-5359-869e-1b9965cb5ca0', '(a) To make sure all the water of crystallisation has been removed [1]. (b) Mass of water = 6.25 − 4.00 = 2.25 g [1]. Moles of CuSO₄ = 4.00 ÷ 159.6 = 0.0251; moles of H₂O = 2.25 ÷ 18.0 = 0.125 [1]. Ratio 0.125 ÷ 0.0251 = 5, so x = 5 [1].', '(a) To make sure all the water of crystallisation has been removed [1]. (b) Mass of water = 6.25 − 4.00 = 2.25 g [1]. Moles of CuSO₄ = 4.00 ÷ 159.6 = 0.0251; moles of H₂O = 2.25 ÷ 18.0 = 0.125 [1]. Ratio 0.125 ÷ 0.0251 = 5, so x = 5 [1].', '[{"text": "Marking point 1", "any": ["all the water", "all water", "no more water", "all of the water", "complete", "fully"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["2.25"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["0.125", "0.0251", "0.025"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["x 5", "x is 5", "five", "5h2o", "5 h2o"], "all": [], "marks": 1}]'::jsonb, '(a) To make sure all the water of crystallisation has been removed [1]. (b) Mass of water = 6.25 − 4.00 = 2.25 g [1]. Moles of CuSO₄ = 4.00 ÷ 159.6 = 0.0251; moles of H₂O = 2.25 ÷ 18.0 = 0.125 [1]. Ratio 0.125 ÷ 0.0251 = 5, so x = 5 [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('1af1cfe1-b2b8-508a-ac1d-8e6b6c610a7d', '108d47cc-e074-5359-869e-1b9965cb5ca0', 21);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('7dbbae32-9e32-5c8c-a472-f1c24b715f18', 'short', 'Calculate the mass of magnesium oxide formed when 4.86 g of magnesium burns completely: 2Mg + O₂ → 2MgO. (Ar: Mg 24.3, O 16.0)', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7dbbae32-9e32-5c8c-a472-f1c24b715f18', 'Moles of Mg = 4.86 ÷ 24.3 = 0.200 mol; moles of MgO = 0.200 mol [1]. Mass = 0.200 × 40.3 = 8.06 g [1].', 'Moles of Mg = 4.86 ÷ 24.3 = 0.200 mol; moles of MgO = 0.200 mol [1]. Mass = 0.200 × 40.3 = 8.06 g [1].', '[{"text": "Marking point 1", "any": ["0.2"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["8.06"], "all": [], "marks": 1}]'::jsonb, 'Moles of Mg = 4.86 ÷ 24.3 = 0.200 mol; moles of MgO = 0.200 mol [1]. Mass = 0.200 × 40.3 = 8.06 g [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('1af1cfe1-b2b8-508a-ac1d-8e6b6c610a7d', '7dbbae32-9e32-5c8c-a472-f1c24b715f18', 22);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('25b5562d-002b-5363-adf0-190dfb587b84', 'mcq', 'For 2H₂ + O₂ → 2H₂O, which reagent is limiting?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('25b5562d-002b-5363-adf0-190dfb587b84', 1, '2 mol H₂ needs only 1 mol O₂: H₂ is limiting. 4 mol H₂ needs 2 mol O₂: O₂ is limiting. 3 and 1.5 mol are in the exact ratio. 1.0 g H₂ is 0.50 mol but 1.0 g O₂ is only 0.031 mol: O₂ is limiting.', 'O₂') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('1af1cfe1-b2b8-508a-ac1d-8e6b6c610a7d', '25b5562d-002b-5363-adf0-190dfb587b84', 23);
