insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('52cf4672-e570-522f-ab1c-06e3c3a230b9', 4, '0.500 × 24.0 = 12.0; 2.00 × 24.0 = 48.0; 0.100 mol gives 2.40; volume ratio 1 : 1 gives 6.00; ratio 1 : 2 gives 12.0; 0.0500 mol of Mg gives 0.0500 mol of H₂, 1.20 dm³.', '48.0 dm³') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
