insert into public.questions (id, kind, prompt, options, marks, image_url) values ('9f77dc3b-50a7-5313-a0bd-787c7f953555', 'short', '10 cm³ of a gaseous hydrocarbon, CxHy, needs 50 cm³ of oxygen for complete combustion and forms 30 cm³ of carbon dioxide (all volumes at the same temperature and pressure). Deduce the formula of the hydrocarbon.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('9f77dc3b-50a7-5313-a0bd-787c7f953555', 'Ratio hydrocarbon : O₂ : CO₂ = 1 : 5 : 3, so x = 3 [1]. Oxygen: 3 O₂ are used for the CO₂, leaving 2 O₂ for water, which makes 4 H₂O, so y = 8: C₃H₈ [1].', 'Ratio hydrocarbon : O₂ : CO₂ = 1 : 5 : 3, so x = 3 [1]. Oxygen: 3 O₂ are used for the CO₂, leaving 2 O₂ for water, which makes 4 H₂O, so y = 8: C₃H₈ [1].', '[{"text": "Marking point 1", "any": ["x 3", "3 carbon", "c3", "three carbon"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["c3h8", "propane"], "all": [], "marks": 1}]'::jsonb, 'Ratio hydrocarbon : O₂ : CO₂ = 1 : 5 : 3, so x = 3 [1]. Oxygen: 3 O₂ are used for the CO₂, leaving 2 O₂ for water, which makes 4 H₂O, so y = 8: C₃H₈ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
