insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e4c7a64a-b4c9-53b4-ad48-38684ad9b65d', 'short', '25.0 cm³ of aqueous sodium hydroxide is exactly neutralised by 20.0 cm³ of 0.100 mol dm⁻³ sulfuric acid: 2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O. Calculate the concentration of the sodium hydroxide.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Titration.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e4c7a64a-b4c9-53b4-ad48-38684ad9b65d', 'Moles of H₂SO₄ = 0.100 × 0.0200 = 0.00200 mol [1]. Moles of NaOH = 2 × 0.00200 = 0.00400 mol [1]. Concentration = 0.00400 ÷ 0.0250 = 0.160 mol dm⁻³ [1].', 'Moles of H₂SO₄ = 0.100 × 0.0200 = 0.00200 mol [1]. Moles of NaOH = 2 × 0.00200 = 0.00400 mol [1]. Concentration = 0.00400 ÷ 0.0250 = 0.160 mol dm⁻³ [1].', '[{"text": "Marking point 1", "any": ["0.002", "2 10", "2.00 10"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["0.004", "4 10", "4.00 10"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["0.16"], "all": [], "marks": 1}]'::jsonb, 'Moles of H₂SO₄ = 0.100 × 0.0200 = 0.00200 mol [1]. Moles of NaOH = 2 × 0.00200 = 0.00400 mol [1]. Concentration = 0.00400 ÷ 0.0250 = 0.160 mol dm⁻³ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('1af1cfe1-b2b8-508a-ac1d-8e6b6c610a7d', 'e4c7a64a-b4c9-53b4-ad48-38684ad9b65d', 29);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e18a1621-dccf-52b1-a642-e6439069fb20', 'short', '0.0100 mol of a metal carbonate reacts exactly with 40.0 cm³ of 0.500 mol dm⁻³ hydrochloric acid. Deduce the mole ratio of carbonate to acid and suggest the charge on the metal ion.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e18a1621-dccf-52b1-a642-e6439069fb20', 'Moles of HCl = 0.500 × 0.0400 = 0.0200 mol [1]. Ratio carbonate : HCl = 1 : 2, so the equation is MCO₃ + 2HCl → MCl₂ + CO₂ + H₂O and the metal ion is M²⁺ [1].', 'Moles of HCl = 0.500 × 0.0400 = 0.0200 mol [1]. Ratio carbonate : HCl = 1 : 2, so the equation is MCO₃ + 2HCl → MCl₂ + CO₂ + H₂O and the metal ion is M²⁺ [1].', '[{"text": "Marking point 1", "any": ["0.02"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["1 2", "m2", "two plus", "charge of 2", "group 2", "mco3"], "all": [], "marks": 1}]'::jsonb, 'Moles of HCl = 0.500 × 0.0400 = 0.0200 mol [1]. Ratio carbonate : HCl = 1 : 2, so the equation is MCO₃ + 2HCl → MCl₂ + CO₂ + H₂O and the metal ion is M²⁺ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('1af1cfe1-b2b8-508a-ac1d-8e6b6c610a7d', 'e18a1621-dccf-52b1-a642-e6439069fb20', 30);
insert into public.quiz_classes (quiz_id, class_id) select '1af1cfe1-b2b8-508a-ac1d-8e6b6c610a7d', c.id from public.classes c where c.site_slug = 'alevel-chem' and c.owner_kind = 'main' on conflict do nothing;
insert into public.quizzes (id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '3 Chemical bonding · Topic quiz', 'Topical quiz for A Level Chemistry, topic 3 Chemical bonding (subtopics 3.1 to 3.7). Questions come from the interactive lessons. Written answers are marked against the mark scheme; your teacher checks every mark.', null, 2, false, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions;
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('88e21154-88b1-5edc-b723-dcae3cc3f13a', 'mcq', 'Which atom is more electronegative?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('88e21154-88b1-5edc-b723-dcae3cc3f13a', 1, 'O (further right), F (higher in the group), Cl (further right), N (higher), S (further right), Na (higher in the group).', 'O') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '88e21154-88b1-5edc-b723-dcae3cc3f13a', 1);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8c9f4ea8-b667-5510-87d5-4306cb555fb5', 'short', 'Explain why fluorine is more electronegative than chlorine.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Periodic_trends.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('8c9f4ea8-b667-5510-87d5-4306cb555fb5', 'A fluorine atom is smaller, so the bonding electrons are closer to the nucleus [1]. There is less shielding by inner shells [1]. The nucleus therefore has a stronger attraction for the bonding electrons [1].', 'A fluorine atom is smaller, so the bonding electrons are closer to the nucleus [1]. There is less shielding by inner shells [1]. The nucleus therefore has a stronger attraction for the bonding electrons [1].', '[{"text": "Marking point 1", "any": ["smaller", "fewer shells", "closer", "less distance", "one less shell", "shorter distance"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["less shield", "fewer inner", "less screening", "shielding is less", "less shielded"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["stronger attraction", "attracted more", "greater attraction"], "all": [], "marks": 1}]'::jsonb, 'A fluorine atom is smaller, so the bonding electrons are closer to the nucleus [1]. There is less shielding by inner shells [1]. The nucleus therefore has a stronger attraction for the bonding electrons [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '8c9f4ea8-b667-5510-87d5-4306cb555fb5', 2);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c0756906-8704-5e0d-b301-8fd406bb5842', 'mcq', 'Use the electronegativity values to predict the bonding.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('c0756906-8704-5e0d-b301-8fd406bb5842', 1, 'NaCl 2.3 ionic; Cl₂ 0 non-polar; HCl 1.0 polar covalent; MgO 2.1 ionic; O–H 1.2 polar covalent; KF 3.2 ionic; F₂ 0 non-polar.', 'Polar covalent') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'c0756906-8704-5e0d-b301-8fd406bb5842', 3);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('23f9ed7b-5aa6-5d18-ad97-9cfd700f78e1', 'short', 'Use these values: Be 1.6, Mg 1.3, O 3.4. (a) Calculate the electronegativity difference in beryllium oxide and in magnesium oxide. (b) Predict which oxide is more ionic, giving a reason. (c) Explain why electronegativity decreases down Group 2.', '[]'::jsonb, 5, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('23f9ed7b-5aa6-5d18-ad97-9cfd700f78e1', '(a) BeO: 3.4 − 1.6 = 1.8 [1]; MgO: 3.4 − 1.3 = 2.1 [1]. (b) Magnesium oxide, because the difference in electronegativity is larger [1]. (c) Down the group the atomic radius increases, so the bonding electrons are further from the nucleus [1], and there is more shielding by inner shells, so the attraction for bonding electrons is weaker [1].', '(a) BeO: 3.4 − 1.6 = 1.8 [1]; MgO: 3.4 − 1.3 = 2.1 [1]. (b) Magnesium oxide, because the difference in electronegativity is larger [1]. (c) Down the group the atomic radius increases, so the bonding electrons are further from the nucleus [1], and there is more shielding by inner shells, so the attraction for bonding electrons is weaker [1].', '[{"text": "Marking point 1", "any": ["1.8"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["2.1"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["mgo", "magnesium oxide", "magnesium"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["radius", "further", "more shells", "larger atom", "extra shell", "bigger atom"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["shield"], "all": [], "marks": 1}]'::jsonb, '(a) BeO: 3.4 − 1.6 = 1.8 [1]; MgO: 3.4 − 1.3 = 2.1 [1]. (b) Magnesium oxide, because the difference in electronegativity is larger [1]. (c) Down the group the atomic radius increases, so the bonding electrons are further from the nucleus [1], and there is more shielding by inner shells, so the attraction for bonding electrons is weaker [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '23f9ed7b-5aa6-5d18-ad97-9cfd700f78e1', 4);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d3446378-9f2a-5f03-abd6-a007e60d19ac', 'mcq', 'Which ions are present in the compound?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('d3446378-9f2a-5f03-abd6-a007e60d19ac', 0, 'NaCl: Na⁺ and Cl⁻. MgO: Mg²⁺ and O²⁻. CaF₂: Ca²⁺ and F⁻. Al₂O₃: Al³⁺ and O²⁻. K₂S: K⁺ and S²⁻.', 'Na⁺ and Cl⁻') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'd3446378-9f2a-5f03-abd6-a007e60d19ac', 5);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6a693e75-78bb-56df-b183-0e081dc9d5e6', 'mcq', 'Complete the description.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('6a693e75-78bb-56df-b183-0e081dc9d5e6', 3, 'Mg loses 2 and O gains 2. Each F gains 1, so two F⁻ form for each Ca²⁺. Mg²⁺ and O²⁻ are both 1s² 2s² 2p⁶; Ca²⁺ is 1s² 2s² 2p⁶ 3s² 3p⁶.', '1s² 2s² 2p⁶') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '6a693e75-78bb-56df-b183-0e081dc9d5e6', 6);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('b7258225-3620-5152-8fe4-3287afa46de8', 'short', 'Explain why magnesium oxide has a much higher melting point than sodium chloride.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sodium-chloride-3D-ionic.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b7258225-3620-5152-8fe4-3287afa46de8', 'The ions in MgO have higher charges (Mg²⁺ and O²⁻ compared with Na⁺ and Cl⁻) [1] and are smaller [1], so the electrostatic attraction is much stronger and more energy is needed to overcome it [1].', 'The ions in MgO have higher charges (Mg²⁺ and O²⁻ compared with Na⁺ and Cl⁻) [1] and are smaller [1], so the electrostatic attraction is much stronger and more energy is needed to overcome it [1].', '[{"text": "Marking point 1", "any": ["higher charge", "greater charge", "charges are greater", "double", "larger charge", "more highly charged", "bigger charge", "mg2", "charge of 2"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["smaller", "ionic radius", "radius"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["stronger attraction", "stronger electrostatic", "stronger ionic", "more energy", "stronger bonding"], "all": [], "marks": 1}]'::jsonb, 'The ions in MgO have higher charges (Mg²⁺ and O²⁻ compared with Na⁺ and Cl⁻) [1] and are smaller [1], so the electrostatic attraction is much stronger and more energy is needed to overcome it [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'b7258225-3620-5152-8fe4-3287afa46de8', 7);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5356f038-d90b-5d1d-917f-1e66c80f60df', 'mcq', 'How many delocalised electrons does each atom contribute?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('5356f038-d90b-5d1d-917f-1e66c80f60df', 0, 'Na and K give 1 each, Mg and Ca give 2 each, and Al gives 3.', '1') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '5356f038-d90b-5d1d-917f-1e66c80f60df', 8);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('bf903271-1fe2-5d10-b17c-184cebcf2fd3', 'short', 'Explain why metals are malleable.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('bf903271-1fe2-5d10-b17c-184cebcf2fd3', 'The layers of positive ions [1] can slide over each other without the metallic bonding being broken, because the delocalised electrons still attract the ions [1].', 'The layers of positive ions [1] can slide over each other without the metallic bonding being broken, because the delocalised electrons still attract the ions [1].', '[{"text": "Marking point 1", "any": ["layers", "rows", "planes"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["slide", "slip", "move over"], "all": [], "marks": 1}]'::jsonb, 'The layers of positive ions [1] can slide over each other without the metallic bonding being broken, because the delocalised electrons still attract the ions [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'bf903271-1fe2-5d10-b17c-184cebcf2fd3', 9);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c24046df-844b-511f-8566-a045ebb79b49', 'mcq', 'Which metal has the higher melting point?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('c24046df-844b-511f-8566-a045ebb79b49', 1, 'Mg (two delocalised electrons, 2+ ion); Al (three, 3+ ion); Li and Na (smaller ions than K); Ca (two electrons and a 2+ ion).', 'Na') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'c24046df-844b-511f-8566-a045ebb79b49', 10);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('bc1e8bbe-f2d1-5868-a39c-c991dd6bb30f', 'mcq', 'How many lone pairs are on the atom named?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('bc1e8bbe-f2d1-5868-a39c-c991dd6bb30f', 1, 'N in NH₃ 1; O in H₂O 2; Cl in HCl 3; C in CH₄ 0; each O in CO₂ 2; each N in N₂ 1; each Cl in Cl₂ 3; each C in C₂H₄ 0.', '1') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'bc1e8bbe-f2d1-5868-a39c-c991dd6bb30f', 11);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('0dec5725-1715-5dfb-890e-bfa5b12a637c', 'short', 'Describe the covalent bonding in a molecule of ethene, C₂H₄. State how many pairs of electrons are shared between the two carbon atoms and between each carbon and hydrogen atom.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0dec5725-1715-5dfb-890e-bfa5b12a637c', 'The two carbon atoms share two pairs of electrons (a double bond) [1]. Each carbon atom also shares one pair with each of two hydrogen atoms (single bonds) [1].', 'The two carbon atoms share two pairs of electrons (a double bond) [1]. Each carbon atom also shares one pair with each of two hydrogen atoms (single bonds) [1].', '[{"text": "Marking point 1", "any": ["double", "two shared pairs", "2 shared pairs", "two pairs", "2 pairs"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["single", "one shared pair", "1 shared pair", "one pair", "1 pair"], "all": [], "marks": 1}]'::jsonb, 'The two carbon atoms share two pairs of electrons (a double bond) [1]. Each carbon atom also shares one pair with each of two hydrogen atoms (single bonds) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '0dec5725-1715-5dfb-890e-bfa5b12a637c', 12);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('93150970-95e9-5d5d-b213-a5175356d81a', 'mcq', 'How many outer-shell electrons surround the central atom in the molecule?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('93150970-95e9-5d5d-b213-a5175356d81a', 0, 'CH₄ and NH₃: 8. BF₃ and AlCl₃: 6. PCl₅: 5 bonds, 10. SO₂: two double bonds and a lone pair, 10. SF₆: 6 bonds, 12.', '6') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '93150970-95e9-5d5d-b213-a5175356d81a', 13);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('2a067db4-33dc-5a08-8e9f-6ef3db9c222f', 'short', 'Explain what is meant by a coordinate (dative covalent) bond, using the formation of the ammonium ion as an example.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ammonium-2D.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2a067db4-33dc-5a08-8e9f-6ef3db9c222f', 'A covalent bond in which both electrons of the shared pair come from the same atom [1]. The lone pair on the nitrogen atom of ammonia [1] is shared with a hydrogen ion (a proton), which has no electrons, to form NH₄⁺ [1].', 'A covalent bond in which both electrons of the shared pair come from the same atom [1]. The lone pair on the nitrogen atom of ammonia [1] is shared with a hydrogen ion (a proton), which has no electrons, to form NH₄⁺ [1].', '[{"text": "Marking point 1", "any": ["both electrons", "both of the electrons", "both the electrons", "pair from one", "pair comes from", "lone pair"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["nitrogen", "n atom", "ammonia", "nh3"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["hydrogen ion", "proton", "h ion"], "all": [], "marks": 1}]'::jsonb, 'A covalent bond in which both electrons of the shared pair come from the same atom [1]. The lone pair on the nitrogen atom of ammonia [1] is shared with a hydrogen ion (a proton), which has no electrons, to form NH₄⁺ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '2a067db4-33dc-5a08-8e9f-6ef3db9c222f', 14);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a9a4bb53-dc5e-5b6e-a2ff-8c6fc794e744', 'mcq', 'Does the species contain a coordinate bond?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a9a4bb53-dc5e-5b6e-a2ff-8c6fc794e744', 1, 'NH₄⁺ (N lone pair to H⁺), Al₂Cl₆ (Cl lone pairs to Al) and H₃O⁺ (O lone pair to H⁺) contain coordinate bonds. NH₃, AlCl₃ and CH₄ do not.', 'No') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'a9a4bb53-dc5e-5b6e-a2ff-8c6fc794e744', 15);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a0fdd9fe-dcf7-51fc-842b-0dde6f5f9465', 'mcq', 'What is the hybridisation of the carbon atom?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a0fdd9fe-dcf7-51fc-842b-0dde6f5f9465', 1, 'Four σ bonds: sp³ (CH₄, C₂H₆). Three σ bonds and one π: sp² (C₂H₄). Two σ bonds and two π: sp (HCN, CO₂).', 'sp²') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'a0fdd9fe-dcf7-51fc-842b-0dde6f5f9465', 16);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('eec14010-feec-5a6a-91bb-96ea7a527676', 'mcq', 'Which carbon–carbon bond fits the description?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('eec14010-feec-5a6a-91bb-96ea7a527676', 0, 'C≡C is the shortest and strongest (one σ, two π). C–C is the longest and weakest. C=C has one σ and one π bond.', 'C–C') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'eec14010-feec-5a6a-91bb-96ea7a527676', 17);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6a673da7-9e35-51ba-8c74-9c2db41a64ab', 'short', 'The bond energy of N≡N is 944 kJ mol⁻¹. Explain why nitrogen gas is very unreactive.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6a673da7-9e35-51ba-8c74-9c2db41a64ab', 'The two nitrogen atoms are joined by a triple bond [1], which is very strong, so a large amount of energy is needed to break it before nitrogen can react [1].', 'The two nitrogen atoms are joined by a triple bond [1], which is very strong, so a large amount of energy is needed to break it before nitrogen can react [1].', '[{"text": "Marking point 1", "any": ["triple"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["strong", "high bond energy", "large amount of energy", "a lot of energy", "lot of energy", "hard to break", "difficult to break", "much energy"], "all": [], "marks": 1}]'::jsonb, 'The two nitrogen atoms are joined by a triple bond [1], which is very strong, so a large amount of energy is needed to break it before nitrogen can react [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '6a673da7-9e35-51ba-8c74-9c2db41a64ab', 18);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e6074e99-7786-59ab-ad14-18631fb8e3d6', 'short', '(a) Define bond energy. (b) Describe how a σ bond and a π bond are formed. (c) State the number of σ bonds and the number of π bonds in a molecule of carbon dioxide (write sigma and pi in words).', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e6074e99-7786-59ab-ad14-18631fb8e3d6', '(a) The energy required to break one mole of a particular covalent bond [1] in the gaseous state [1]. (b) A σ bond is formed by the direct, end-on overlap of orbitals between the two atoms [1]; a π bond is formed by the sideways overlap of adjacent p orbitals, above and below the σ bond [1]. (c) 2 sigma bonds [1] and 2 pi bonds [1].', '(a) The energy required to break one mole of a particular covalent bond [1] in the gaseous state [1]. (b) A σ bond is formed by the direct, end-on overlap of orbitals between the two atoms [1]; a π bond is formed by the sideways overlap of adjacent p orbitals, above and below the σ bond [1]. (c) 2 sigma bonds [1] and 2 pi bonds [1].', '[{"text": "Marking point 1", "any": ["one mole", "1 mole", "1 mol", "per mole"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["gaseous", "gas"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["end on", "direct", "head on", "along the axis", "between the nuclei"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["sideways", "side by side", "lateral", "side on"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["2 sigma", "two sigma"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["2 pi", "two pi"], "all": [], "marks": 1}]'::jsonb, '(a) The energy required to break one mole of a particular covalent bond [1] in the gaseous state [1]. (b) A σ bond is formed by the direct, end-on overlap of orbitals between the two atoms [1]; a π bond is formed by the sideways overlap of adjacent p orbitals, above and below the σ bond [1]. (c) 2 sigma bonds [1] and 2 pi bonds [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'e6074e99-7786-59ab-ad14-18631fb8e3d6', 19);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('bac012a9-22cb-514d-af85-65340bf962e4', 'mcq', 'What is the bond angle?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('bac012a9-22cb-514d-af85-65340bf962e4', 3, 'CH₄ and NH₄⁺ 109.5°; NH₃ and H₃O⁺ 107° (one lone pair); H₂O 104.5° (two lone pairs); BF₃ 120°; CO₂ 180°; SF₆ 90°.', '109.5°') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'bac012a9-22cb-514d-af85-65340bf962e4', 20);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('63c329bf-fe68-5e28-adee-b777afc6f700', 'mcq', 'Predict the shape.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('63c329bf-fe68-5e28-adee-b777afc6f700', 1, 'PH₃ like NH₃: pyramidal. H₂S and NH₂⁻ like H₂O: non-linear. BCl₃ and AlCl₃ like BF₃: trigonal planar. CCl₄ like CH₄: tetrahedral. CS₂ like CO₂: linear. PCl₅ like PF₅: trigonal bipyramidal.', 'Non-linear') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '63c329bf-fe68-5e28-adee-b777afc6f700', 21);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('933dc4cf-1dc8-5fe0-b70f-40c92f7a7af3', 'short', '(a) State the shape and bond angle of BF₃ and of NH₃. (b) Explain why these molecules have different shapes although each has three bonds. (c) BF₃ reacts with NH₃ to form F₃B–NH₃. Predict the F–B–F bond angle in the product.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('933dc4cf-1dc8-5fe0-b70f-40c92f7a7af3', '(a) BF₃ is trigonal planar [1], 120° [1]; NH₃ is pyramidal [1], 107° [1]. (b) Boron has three bonding pairs and no lone pair; nitrogen has three bonding pairs and one lone pair, which repels the bonding pairs [1]. (c) Boron now has four bonding pairs, so the arrangement around it is tetrahedral and the angle is about 109.5° [1].', '(a) BF₃ is trigonal planar [1], 120° [1]; NH₃ is pyramidal [1], 107° [1]. (b) Boron has three bonding pairs and no lone pair; nitrogen has three bonding pairs and one lone pair, which repels the bonding pairs [1]. (c) Boron now has four bonding pairs, so the arrangement around it is tetrahedral and the angle is about 109.5° [1].', '[{"text": "Marking point 1", "any": ["trigonal planar", "planar"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["120"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["pyramidal", "pyramid"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["107"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["lone pair"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["109", "tetrahedral", "four bonding", "4 bonding"], "all": [], "marks": 1}]'::jsonb, '(a) BF₃ is trigonal planar [1], 120° [1]; NH₃ is pyramidal [1], 107° [1]. (b) Boron has three bonding pairs and no lone pair; nitrogen has three bonding pairs and one lone pair, which repels the bonding pairs [1]. (c) Boron now has four bonding pairs, so the arrangement around it is tetrahedral and the angle is about 109.5° [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '933dc4cf-1dc8-5fe0-b70f-40c92f7a7af3', 22);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ff617a15-bf16-5c9f-bda9-b244d65d241d', 'mcq', 'What is broken or overcome?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('ff617a15-bf16-5c9f-bda9-b244d65d241d', 1, 'Changes of state (boiling, subliming, melting) overcome intermolecular forces. Chemical reactions (splitting water, burning methane) break covalent bonds.', 'Covalent bonds') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'ff617a15-bf16-5c9f-bda9-b244d65d241d', 23);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e40ca71d-5640-592f-a7d7-27fcdb21e6d1', 'mcq', 'What is the strongest type of intermolecular force between molecules of the substance?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('e40ca71d-5640-592f-a7d7-27fcdb21e6d1', 0, 'Non-polar molecules (CH₄, I₂, CO₂): id–id only. Polar molecules without N–H or O–H (HCl, CH₃Cl): pd–pd. Molecules with O–H or N–H (H₂O, NH₃, C₂H₅OH): hydrogen bonding.', 'Instantaneous dipole–induced dipole only') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'e40ca71d-5640-592f-a7d7-27fcdb21e6d1', 24);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('eedbf7d7-632c-5dc7-b6ea-8b48210760c0', 'short', 'Describe how a hydrogen bond forms between two water molecules.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hydrogen-bonding-in-water-2D.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('eedbf7d7-632c-5dc7-b6ea-8b48210760c0', 'Oxygen is much more electronegative than hydrogen, so the O–H bond is polar and the hydrogen atom is δ+ [1]. A lone pair on the oxygen atom of another molecule [1] is attracted to this δ+ hydrogen atom [1].', 'Oxygen is much more electronegative than hydrogen, so the O–H bond is polar and the hydrogen atom is δ+ [1]. A lone pair on the oxygen atom of another molecule [1] is attracted to this δ+ hydrogen atom [1].', '[{"text": "Marking point 1", "any": ["electronegative", "polar", "delta", "partial", "slightly positive"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["lone pair"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["attract"], "all": [], "marks": 1}]'::jsonb, 'Oxygen is much more electronegative than hydrogen, so the O–H bond is polar and the hydrogen atom is δ+ [1]. A lone pair on the oxygen atom of another molecule [1] is attracted to this δ+ hydrogen atom [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'eedbf7d7-632c-5dc7-b6ea-8b48210760c0', 25);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('cd59de80-5d18-5ae0-9ea3-68ecec21eb66', 'short', 'Boiling points of the hydrides of Group 16: H₂O 100 °C, H₂S −60 °C, H₂Se −41 °C, H₂Te −2 °C.
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cd59de80-5d18-5ae0-9ea3-68ecec21eb66', '(a) From H₂S to H₂Te the molecules have more electrons [1], so the instantaneous dipole–induced dipole forces are stronger [1]. (b) Water molecules form hydrogen bonds with each other [1], which are much stronger than the other intermolecular forces, so more energy is needed to separate the molecules [1]. (c) The covalent O–H bond inside the molecule is much stronger [1].', '(a) From H₂S to H₂Te the molecules have more electrons [1], so the instantaneous dipole–induced dipole forces are stronger [1]. (b) Water molecules form hydrogen bonds with each other [1], which are much stronger than the other intermolecular forces, so more energy is needed to separate the molecules [1]. (c) The covalent O–H bond inside the molecule is much stronger [1].', '[{"text": "Marking point 1", "any": ["more electrons", "number of electrons", "larger molecule", "bigger electron", "greater number of electrons"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["instantaneous", "induced", "london", "dispersion", "id id", "van der waals"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["hydrogen bond"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["more energy", "stronger", "harder to overcome"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["covalent", "o h bond", "bond inside"], "all": [], "marks": 1}]'::jsonb, '(a) From H₂S to H₂Te the molecules have more electrons [1], so the instantaneous dipole–induced dipole forces are stronger [1]. (b) Water molecules form hydrogen bonds with each other [1], which are much stronger than the other intermolecular forces, so more energy is needed to separate the molecules [1]. (c) The covalent O–H bond inside the molecule is much stronger [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'cd59de80-5d18-5ae0-9ea3-68ecec21eb66', 26);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('58624a1f-95fb-5e5c-b74d-a2e2fce8de02', 'mcq', 'What surrounds the central atom in the dot-and-cross diagram?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('58624a1f-95fb-5e5c-b74d-a2e2fce8de02', 3, 'H₂O 2 and 2; NH₃ 3 and 1; CH₄ 4 and 0; BF₃ 3 and 0 (only six electrons around boron); CO₂ two double bonds; PCl₅ five bonding pairs; SF₆ six bonding pairs.', '4 bonding pairs, 0 lone pairs') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '58624a1f-95fb-5e5c-b74d-a2e2fce8de02', 27);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5e184853-e6b3-5251-aebb-33ee93d3b981', 'mcq', 'Complete the description of the dot-and-cross diagram.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('5e184853-e6b3-5251-aebb-33ee93d3b981', 1, 'Cl⁻: 8 outer electrons, 1 from sodium. O²⁻: 8 outer electrons, 2 from magnesium. CaF₂: two F⁻ for each Ca²⁺. Charges: O²⁻ is 2−, F⁻ is 1−.', '2') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', '5e184853-e6b3-5251-aebb-33ee93d3b981', 28);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f3dc2b4f-92ff-5209-a72d-c449d5dfaad5', 'mcq', 'What is the total number of outer-shell electrons shown in the diagram?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('f3dc2b4f-92ff-5209-a72d-c449d5dfaad5', 4, 'H₂O 6 + 2 = 8; NH₃ 5 + 3 = 8; CH₄ 4 + 4 = 8; NH₄⁺ 5 + 4 − 1 = 8; N₂ 5 + 5 = 10; NO 5 + 6 = 11; CO₂ 4 + 12 = 16; SO₂ 6 + 12 = 18.', '18') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'f3dc2b4f-92ff-5209-a72d-c449d5dfaad5', 29);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('b94b7dbb-2eed-534c-9659-7e02ddffb3fb', 'short', 'Aluminium chloride exists as Al₂Cl₆ molecules at low temperatures. (a) How many outer-shell electrons surround the aluminium atom in a separate AlCl₃ molecule? (b) Name the type of bond that joins the two AlCl₃ units, and state how it is shown in a dot-and-cross diagram. (c) How many electrons surround each aluminium atom in Al₂Cl₆? (d) How many electrons surround the sulfur atom in SF₆?', '[]'::jsonb, 5, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b94b7dbb-2eed-534c-9659-7e02ddffb3fb', '(a) 6 electrons [1]. (b) A coordinate (dative covalent) bond [1], drawn as a shared pair in which both electrons come from a lone pair on a chlorine atom, so both have the same symbol [1]. (c) 8 electrons [1]. (d) 12 electrons [1].', '(a) 6 electrons [1]. (b) A coordinate (dative covalent) bond [1], drawn as a shared pair in which both electrons come from a lone pair on a chlorine atom, so both have the same symbol [1]. (c) 8 electrons [1]. (d) 12 electrons [1].', '[{"text": "Marking point 1", "any": ["6 electrons", "six", "6"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["coordinate", "dative"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["lone pair", "both electrons", "same symbol", "from chlorine", "from the chlorine"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["8", "eight"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["12", "twelve"], "all": [], "marks": 1}]'::jsonb, '(a) 6 electrons [1]. (b) A coordinate (dative covalent) bond [1], drawn as a shared pair in which both electrons come from a lone pair on a chlorine atom, so both have the same symbol [1]. (c) 8 electrons [1]. (d) 12 electrons [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', 'b94b7dbb-2eed-534c-9659-7e02ddffb3fb', 30);
insert into public.quiz_classes (quiz_id, class_id) select 'e516b9ab-0a9c-59ff-b160-9f9d9bb978e1', c.id from public.classes c where c.site_slug = 'alevel-chem' and c.owner_kind = 'main' on conflict do nothing;
insert into public.quizzes (id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by) values ('a5fbd954-0d29-516e-bf65-0a4b10ba75c1', '4 States of matter · Topic quiz', 'Topical quiz for A Level Chemistry, topic 4 States of matter (subtopics 4.1 to 4.2). Questions come from the interactive lessons. Written answers are marked against the mark scheme; your teacher checks every mark.', null, 2, false, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions;
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8043c5da-5b39-531c-ada1-95439e8924e9', 'mcq', 'What happens to the pressure, if nothing else changes?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('8043c5da-5b39-531c-ada1-95439e8924e9', 0, 'More gas or a higher temperature: more frequent (and harder) collisions, pressure increases. A larger volume or less gas: fewer collisions on each area of wall, pressure decreases.', 'Increases') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a5fbd954-0d29-516e-bf65-0a4b10ba75c1', '8043c5da-5b39-531c-ada1-95439e8924e9', 1);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5fa98a34-9622-503a-83e4-f39c77b682ca', 'mcq', 'What happens to the pressure, if nothing else changes?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('5fa98a34-9622-503a-83e4-f39c77b682ca', 1, 'More gas or a higher temperature: more frequent (and harder) collisions, pressure increases. A larger volume or less gas: fewer collisions on each area of wall, pressure decreases.', 'Decreases') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a5fbd954-0d29-516e-bf65-0a4b10ba75c1', '5fa98a34-9622-503a-83e4-f39c77b682ca', 2);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ba93e5d5-8a39-564e-8b33-a4f312d9df0a', 'short', 'Explain how a gas exerts a pressure on the walls of its container.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kinetic_theory_of_gases.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ba93e5d5-8a39-564e-8b33-a4f312d9df0a', 'The gas molecules are in constant random motion and collide with the walls of the container [1]. Each collision exerts a force on the wall, and the force on each unit area is the pressure [1].', 'The gas molecules are in constant random motion and collide with the walls of the container [1]. Each collision exerts a force on the wall, and the force on each unit area is the pressure [1].', '[{"text": "Marking point 1", "any": ["collide", "collision", "hit", "strike", "bombard"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["wall", "force"], "all": [], "marks": 1}]'::jsonb, 'The gas molecules are in constant random motion and collide with the walls of the container [1]. Each collision exerts a force on the wall, and the force on each unit area is the pressure [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a5fbd954-0d29-516e-bf65-0a4b10ba75c1', 'ba93e5d5-8a39-564e-8b33-a4f312d9df0a', 3);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('1989380e-4f13-5440-a09c-a050deb2a770', 'mcq', 'Is the statement true for an ideal gas, for real gases, or for both?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('1989380e-4f13-5440-a09c-a050deb2a770', 1, 'Zero particle volume and exact obedience of pV = nRT: ideal gas only. Attractive forces and liquefying: real gases only. Constant random motion: both.', 'Real gases only') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
