insert into public.questions (id, kind, prompt, options, marks, image_url) values ('cdf2d2e9-d026-5c23-95dc-d7cdde7aa325', 'short', 'State and explain the conditions of temperature and pressure under which a real gas behaves most like an ideal gas.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cdf2d2e9-d026-5c23-95dc-d7cdde7aa325', 'High temperature [1] and low pressure [1]. The particles are far apart and have high kinetic energy, so their own volume and the intermolecular forces between them are negligible [1].', 'High temperature [1] and low pressure [1]. The particles are far apart and have high kinetic energy, so their own volume and the intermolecular forces between them are negligible [1].', '[{"text": "Marking point 1", "any": ["high temperature"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["low pressure"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["far apart", "negligible", "forces are small", "weak", "little attraction", "overcome", "insignificant"], "all": [], "marks": 1}]'::jsonb, 'High temperature [1] and low pressure [1]. The particles are far apart and have high kinetic energy, so their own volume and the intermolecular forces between them are negligible [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
