insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c9d06852-6bce-5b0b-a912-f0d8b3590d70', 'short', 'Calculate the volume, in dm³, occupied by 0.500 mol of an ideal gas at 298 K and 1.01 × 10⁵ Pa. (R = 8.31 J K⁻¹ mol⁻¹)', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c9d06852-6bce-5b0b-a912-f0d8b3590d70', 'V = nRT ÷ p = (0.500 × 8.31 × 298) ÷ (1.01 × 10⁵) = 0.0123 m³ [1] = 12.3 dm³ [1].', 'V = nRT ÷ p = (0.500 × 8.31 × 298) ÷ (1.01 × 10⁵) = 0.0123 m³ [1] = 12.3 dm³ [1].', '[{"text": "Marking point 1", "any": ["0.0123", "0.01226", "1.23 10", "1.226 10", "0.012"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["12.3", "12.26", "12.2"], "all": [], "marks": 1}]'::jsonb, 'V = nRT ÷ p = (0.500 × 8.31 × 298) ÷ (1.01 × 10⁵) = 0.0123 m³ [1] = 12.3 dm³ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
