insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6f598006-70fd-5782-91ea-1055be65784f', 'short', '0.320 g of a gas occupies 2.00 × 10⁻⁴ m³ at 300 K and 1.00 × 10⁵ Pa. Calculate the relative molecular mass of the gas. (R = 8.31 J K⁻¹ mol⁻¹)', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6f598006-70fd-5782-91ea-1055be65784f', 'n = pV ÷ RT = (1.00 × 10⁵ × 2.00 × 10⁻⁴) ÷ (8.31 × 300) [1] = 0.00802 mol [1]. Mr = 0.320 ÷ 0.00802 = 39.9 [1].', 'n = pV ÷ RT = (1.00 × 10⁵ × 2.00 × 10⁻⁴) ÷ (8.31 × 300) [1] = 0.00802 mol [1]. Mr = 0.320 ÷ 0.00802 = 39.9 [1].', '[{"text": "Marking point 1", "any": ["pv rt", "pv/rt", "8.31 300", "2493"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["0.00802", "8.02 10", "0.0080", "8.0 10"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["39.9", "39.89", "40"], "all": [], "marks": 1}]'::jsonb, 'n = pV ÷ RT = (1.00 × 10⁵ × 2.00 × 10⁻⁴) ÷ (8.31 × 300) [1] = 0.00802 mol [1]. Mr = 0.320 ÷ 0.00802 = 39.9 [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
