insert into public.questions (id, kind, prompt, options, marks, image_url) values ('9eebe024-3c5f-5320-8e52-9a3c5b42b5b1', 'short', '0.185 g of a volatile liquid is vaporised at 373 K and 1.01 × 10⁵ Pa. The vapour occupies 76.5 cm³. Calculate the relative molecular mass of the liquid.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('9eebe024-3c5f-5320-8e52-9a3c5b42b5b1', 'V = 76.5 cm³ = 7.65 × 10⁻⁵ m³ [1]. n = (1.01 × 10⁵ × 7.65 × 10⁻⁵) ÷ (8.31 × 373) = 0.00249 mol [1]. Mr = 0.185 ÷ 0.00249 = 74.2 [1].', 'V = 76.5 cm³ = 7.65 × 10⁻⁵ m³ [1]. n = (1.01 × 10⁵ × 7.65 × 10⁻⁵) ÷ (8.31 × 373) = 0.00249 mol [1]. Mr = 0.185 ÷ 0.00249 = 74.2 [1].', '[{"text": "Marking point 1", "any": ["7.65 10", "76.5 10", "0.0000765"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["0.00249", "2.49 10", "0.0025"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["74.2", "74.1", "74"], "all": [], "marks": 1}]'::jsonb, 'V = 76.5 cm³ = 7.65 × 10⁻⁵ m³ [1]. n = (1.01 × 10⁵ × 7.65 × 10⁻⁵) ÷ (8.31 × 373) = 0.00249 mol [1]. Mr = 0.185 ÷ 0.00249 = 74.2 [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
