insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6b9f1444-fc50-5bf3-b1da-2b14349026b2', 'short', '(a) State two assumptions of the ideal gas model. (b) At room temperature ammonia deviates from ideal behaviour more than nitrogen does. Suggest why. (c) Calculate the pressure, in kPa, of 2.00 g of helium (Ar = 4.0) in a 5.00 dm³ container at 27 °C. (R = 8.31 J K⁻¹ mol⁻¹)', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6b9f1444-fc50-5bf3-b1da-2b14349026b2', '(a) The particles have zero volume [1] and there are no intermolecular forces of attraction between them [1]. (b) Ammonia molecules are polar and form hydrogen bonds, so the forces between them are much stronger than between nitrogen molecules [1]. (c) n = 2.00 ÷ 4.0 = 0.500 mol [1]; T = 300 K and V = 5.00 × 10⁻³ m³ [1]; p = (0.500 × 8.31 × 300) ÷ (5.00 × 10⁻³) = 249 000 Pa = 249 kPa [1].', '(a) The particles have zero volume [1] and there are no intermolecular forces of attraction between them [1]. (b) Ammonia molecules are polar and form hydrogen bonds, so the forces between them are much stronger than between nitrogen molecules [1]. (c) n = 2.00 ÷ 4.0 = 0.500 mol [1]; T = 300 K and V = 5.00 × 10⁻³ m³ [1]; p = (0.500 × 8.31 × 300) ÷ (5.00 × 10⁻³) = 249 000 Pa = 249 kPa [1].', '[{"text": "Marking point 1", "any": ["zero volume", "no volume", "negligible volume"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["no intermolecular", "no forces", "no attraction", "no attractive"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["hydrogen bond", "stronger intermolecular", "stronger forces", "polar", "stronger attraction"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["0.5"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["300"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["249", "2.49 10"], "all": [], "marks": 1}]'::jsonb, '(a) The particles have zero volume [1] and there are no intermolecular forces of attraction between them [1]. (b) Ammonia molecules are polar and form hydrogen bonds, so the forces between them are much stronger than between nitrogen molecules [1]. (c) n = 2.00 ÷ 4.0 = 0.500 mol [1]; T = 300 K and V = 5.00 × 10⁻³ m³ [1]; p = (0.500 × 8.31 × 300) ÷ (5.00 × 10⁻³) = 249 000 Pa = 249 kPa [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a5fbd954-0d29-516e-bf65-0a4b10ba75c1', '6b9f1444-fc50-5bf3-b1da-2b14349026b2', 12);
