insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c34289ec-0693-529d-a64a-380d76ab97d0', 'In the solid the ions are held in fixed positions in the lattice [1]. When molten the ions are free to move and carry charge [1].', 'In the solid the ions are held in fixed positions in the lattice [1]. When molten the ions are free to move and carry charge [1].', '[{"text": "Marking point 1", "any": ["fixed", "cannot move", "held in", "can not move", "unable to move", "locked"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["free to move", "mobile", "can move", "are able to move", "move freely"], "all": [], "marks": 1}]'::jsonb, 'In the solid the ions are held in fixed positions in the lattice [1]. When molten the ions are free to move and carry charge [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
