insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1c779905-7b56-5ef1-b62a-c03468fad021', 'Melting only overcomes the intermolecular forces between the I₂ molecules [1]. These are weak, so little energy is needed; the covalent bonds are not broken [1].', 'Melting only overcomes the intermolecular forces between the I₂ molecules [1]. These are weak, so little energy is needed; the covalent bonds are not broken [1].', '[{"text": "Marking point 1", "any": ["intermolecular", "van der waals", "between molecules", "between the molecules", "london", "induced dipole"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["weak", "little energy", "not much energy", "covalent bonds are not broken", "easily overcome"], "all": [], "marks": 1}]'::jsonb, 'Melting only overcomes the intermolecular forces between the I₂ molecules [1]. These are weak, so little energy is needed; the covalent bonds are not broken [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a5fbd954-0d29-516e-bf65-0a4b10ba75c1', '1c779905-7b56-5ef1-b62a-c03468fad021', 23);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('34e50197-7a90-5baf-b2db-73df2a06dbe9', 'mcq', 'Is the statement true for diamond, for graphite, or for both?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('34e50197-7a90-5baf-b2db-73df2a06dbe9', 0, 'Diamond: four bonds per atom, very hard. Graphite: three bonds per atom, delocalised electrons, conducts, layers slide. Both have very high melting points because many strong covalent bonds must be broken.', 'Diamond') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a5fbd954-0d29-516e-bf65-0a4b10ba75c1', '34e50197-7a90-5baf-b2db-73df2a06dbe9', 24);
