insert into public.questions (id, kind, prompt, options, marks, image_url) values ('2de5e415-1718-5d36-bb3c-b129c715ca09', 'short', 'Explain why graphite conducts electricity but diamond does not.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Graphite-layers-side-3D-balls.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2de5e415-1718-5d36-bb3c-b129c715ca09', 'In graphite each carbon atom is bonded to three others [1], so one outer electron per atom is delocalised and free to move along the layers [1]. In diamond each carbon atom is bonded to four others, so all the outer electrons are used in bonds and none are free to move [1].', 'In graphite each carbon atom is bonded to three others [1], so one outer electron per atom is delocalised and free to move along the layers [1]. In diamond each carbon atom is bonded to four others, so all the outer electrons are used in bonds and none are free to move [1].', '[{"text": "Marking point 1", "any": ["three bonds", "3 bonds", "three covalent", "three other", "3 other", "bonded to three", "bonded to 3"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["delocalised", "delocalized", "free electron"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["four bonds", "4 bonds", "four covalent", "four other", "4 other", "bonded to four", "bonded to 4", "all four", "no delocalised", "no free electrons", "all the outer electrons"], "all": [], "marks": 1}]'::jsonb, 'In graphite each carbon atom is bonded to three others [1], so one outer electron per atom is delocalised and free to move along the layers [1]. In diamond each carbon atom is bonded to four others, so all the outer electrons are used in bonds and none are free to move [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a5fbd954-0d29-516e-bf65-0a4b10ba75c1', '2de5e415-1718-5d36-bb3c-b129c715ca09', 27);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c396be5e-4d7e-5246-b409-033eb866e9ca', 'mcq', 'A: melts at 801 °C; does not conduct when solid; conducts when molten; dissolves in water.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('c396be5e-4d7e-5246-b409-033eb866e9ca', 1, 'A conducts only when molten: giant ionic. B has a low melting point and never conducts: simple molecular. C conducts when solid: giant metallic. D has a very high melting point and never conducts: giant molecular.', 'Simple molecular') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a5fbd954-0d29-516e-bf65-0a4b10ba75c1', 'c396be5e-4d7e-5246-b409-033eb866e9ca', 28);
