insert into public.questions (id, kind, prompt, options, marks, image_url) values ('fdf70a43-6664-5697-b2f1-c2cbdeee8c8f', 'short', 'Buckminsterfullerene, C₆₀, and diamond are both forms of carbon. C₆₀ sublimes at about 600 °C and dissolves in some organic solvents. Diamond melts above 3500 °C and is insoluble. Explain these differences in terms of structure and bonding.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('fdf70a43-6664-5697-b2f1-c2cbdeee8c8f', 'C₆₀ has a simple molecular lattice of separate C₆₀ molecules [1] held together by weak intermolecular forces, which need little energy to overcome and allow solvent molecules to separate them [1]. Diamond has a giant molecular lattice [1] in which every atom is held by strong covalent bonds, and many of these covalent bonds must be broken to melt or dissolve it [1].', 'C₆₀ has a simple molecular lattice of separate C₆₀ molecules [1] held together by weak intermolecular forces, which need little energy to overcome and allow solvent molecules to separate them [1]. Diamond has a giant molecular lattice [1] in which every atom is held by strong covalent bonds, and many of these covalent bonds must be broken to melt or dissolve it [1].', '[{"text": "Marking point 1", "any": ["simple molecular", "molecules", "molecular"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["intermolecular", "van der waals", "weak forces", "between the molecules", "between molecules"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["giant"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["strong covalent", "many covalent", "covalent bonds must", "break covalent", "breaking covalent", "covalent bonds have to", "covalent bonds are broken", "covalent bonds need"], "all": [], "marks": 1}]'::jsonb, 'C₆₀ has a simple molecular lattice of separate C₆₀ molecules [1] held together by weak intermolecular forces, which need little energy to overcome and allow solvent molecules to separate them [1]. Diamond has a giant molecular lattice [1] in which every atom is held by strong covalent bonds, and many of these covalent bonds must be broken to melt or dissolve it [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a5fbd954-0d29-516e-bf65-0a4b10ba75c1', 'fdf70a43-6664-5697-b2f1-c2cbdeee8c8f', 30);
