insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d6f4387d-e247-522a-a1d6-c1429e0b03d5', 'mcq', 'Exothermic or endothermic?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('d6f4387d-e247-522a-a1d6-c1429e0b03d5', 0, 'Combustion and neutralisation are exothermic, as is any reaction with a negative ΔH. Photosynthesis and thermal decomposition are endothermic, as is any reaction that cools its surroundings.', 'Exothermic') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46db39b6-181e-5e6e-be16-515cfe5bed6c', 'd6f4387d-e247-522a-a1d6-c1429e0b03d5', 1);
