insert into public.questions (id, kind, prompt, options, marks, image_url) values ('634a9894-5ef6-5646-bf6e-661a3d21d76c', 'short', 'A reaction has ΔH = −120 kJ mol⁻¹ and an activation energy of +80 kJ mol⁻¹. Describe its reaction pathway diagram, and calculate the activation energy of the reverse reaction.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('634a9894-5ef6-5646-bf6e-661a3d21d76c', 'The products are 120 kJ mol⁻¹ lower than the reactants [1]. The curve rises to a peak 80 kJ mol⁻¹ above the reactants before falling to the products [1]. Reverse activation energy = 80 + 120 = 200 kJ mol⁻¹ [1].', 'The products are 120 kJ mol⁻¹ lower than the reactants [1]. The curve rises to a peak 80 kJ mol⁻¹ above the reactants before falling to the products [1]. Reverse activation energy = 80 + 120 = 200 kJ mol⁻¹ [1].', '[{"text": "Marking point 1", "any": ["below", "lower"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["peak", "hump", "barrier", "maximum", "top of the curve", "rises", "above the reactants"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["200"], "all": [], "marks": 1}]'::jsonb, 'The products are 120 kJ mol⁻¹ lower than the reactants [1]. The curve rises to a peak 80 kJ mol⁻¹ above the reactants before falling to the products [1]. Reverse activation energy = 80 + 120 = 200 kJ mol⁻¹ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46db39b6-181e-5e6e-be16-515cfe5bed6c', '634a9894-5ef6-5646-bf6e-661a3d21d76c', 4);
