insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('35bbd9fb-6d82-5acb-9ddd-ea193ae87622', 0, 'Water: H₂ + ½O₂ → H₂O (this is also the combustion of hydrogen). Methane: C(s) + 2H₂ → CH₄. Propane: C₃H₈ + 5O₂ → 3CO₂ + 4H₂O. Ammonia: ½N₂ + 1½H₂ → NH₃.', 'H₂(g) + ½O₂(g) → H₂O(l)') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46db39b6-181e-5e6e-be16-515cfe5bed6c', '35bbd9fb-6d82-5acb-9ddd-ea193ae87622', 9);
