insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ee0e6a6f-6f67-5b83-9b24-8dad832aa28f', 'Bonds broken: 436 + 242 = 678 kJ; bonds formed: 2 × 431 = 862 kJ [1]. ΔH = 678 − 862 = −184 kJ mol⁻¹ [1].', 'Bonds broken: 436 + 242 = 678 kJ; bonds formed: 2 × 431 = 862 kJ [1]. ΔH = 678 − 862 = −184 kJ mol⁻¹ [1].', '[{"text": "Marking point 1", "any": ["678", "862"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["184"], "all": [], "marks": 1}]'::jsonb, 'Bonds broken: 436 + 242 = 678 kJ; bonds formed: 2 × 431 = 862 kJ [1]. ΔH = 678 − 862 = −184 kJ mol⁻¹ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
