insert into public.questions (id, kind, prompt, options, marks, image_url) values ('190190df-2cf7-5d76-a0f8-aa529a41a4fd', 'short', '50.0 cm³ of 1.00 mol dm⁻³ HCl is mixed with 50.0 cm³ of 1.00 mol dm⁻³ NaOH. The temperature rises by 6.8 °C. Calculate the enthalpy change of neutralisation in kJ mol⁻¹. (c = 4.18 J g⁻¹ K⁻¹)', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Coffee_cup_calorimeter_pic.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('190190df-2cf7-5d76-a0f8-aa529a41a4fd', 'q = 100 × 4.18 × 6.8 = 2842 J [1]. Moles of water formed = 0.0500 × 1.00 = 0.0500 mol [1]. ΔH = −2842 ÷ 0.0500 = −56 800 J mol⁻¹ = −56.8 kJ mol⁻¹ [1].', 'q = 100 × 4.18 × 6.8 = 2842 J [1]. Moles of water formed = 0.0500 × 1.00 = 0.0500 mol [1]. ΔH = −2842 ÷ 0.0500 = −56 800 J mol⁻¹ = −56.8 kJ mol⁻¹ [1].', '[{"text": "Marking point 1", "any": ["2842", "2840", "2.84"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["0.05"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["56.8", "56.9", "57"], "all": [], "marks": 1}]'::jsonb, 'q = 100 × 4.18 × 6.8 = 2842 J [1]. Moles of water formed = 0.0500 × 1.00 = 0.0500 mol [1]. ΔH = −2842 ÷ 0.0500 = −56 800 J mol⁻¹ = −56.8 kJ mol⁻¹ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46db39b6-181e-5e6e-be16-515cfe5bed6c', '190190df-2cf7-5d76-a0f8-aa529a41a4fd', 17);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('da33f012-8dff-5903-b7be-d402d5027c08', 'mcq', 'What is the effect on the measured temperature rise?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('da33f012-8dff-5903-b7be-d402d5027c08', 0, 'Heat loss, incomplete combustion and heating the calorimeter all mean less energy reaches the water, so the rise is smaller. Reading the thermometer more precisely does not change the rise.', 'Smaller temperature rise') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46db39b6-181e-5e6e-be16-515cfe5bed6c', 'da33f012-8dff-5903-b7be-d402d5027c08', 18);
