insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('3c4f4462-f84d-58f6-8377-f62fdfd1fc4c', 1, 'Heat loss, incomplete combustion and heating the calorimeter all mean less energy reaches the water, so the rise is smaller. Reading the thermometer more precisely does not change the rise.', 'No effect') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
