insert into public.questions (id, kind, prompt, options, marks, image_url) values ('14475930-5c08-5dde-8d4c-1179d8851166', 'short', 'Give two reasons why the experimental value for the enthalpy change of combustion of ethanol (−1045 kJ mol⁻¹) is less exothermic than the data-book value (−1367 kJ mol⁻¹).', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('14475930-5c08-5dde-8d4c-1179d8851166', 'Heat is lost to the surroundings, so not all the energy heats the water [1]. Combustion is incomplete (and some heat is absorbed by the calorimeter) [1].', 'Heat is lost to the surroundings, so not all the energy heats the water [1]. Combustion is incomplete (and some heat is absorbed by the calorimeter) [1].', '[{"text": "Marking point 1", "any": ["heat loss", "heat lost", "lost to the surroundings", "escapes", "heat is lost", "energy lost", "energy is lost"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["incomplete", "calorimeter absorbs", "heat capacity of the calorimeter", "evaporat", "not standard", "heats the calorimeter"], "all": [], "marks": 1}]'::jsonb, 'Heat is lost to the surroundings, so not all the energy heats the water [1]. Combustion is incomplete (and some heat is absorbed by the calorimeter) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
