insert into public.questions (id, kind, prompt, options, marks, image_url) values ('fcc3fa5f-fce1-55a7-abd6-95516ef8fd63', 'mcq', 'What is the standard enthalpy change of formation?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('fcc3fa5f-fce1-55a7-abd6-95516ef8fd63', 0, 'Elements in their standard states: 0. CO₂: −394. The water equation makes two moles, so ΔHf = −572 ÷ 2 = −286 kJ mol⁻¹.', '0') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
