insert into public.questions (id, kind, prompt, options, marks, image_url) values ('cf1f9f4b-1162-586a-be67-3237e7da0876', 'short', 'Calculate ΔH for NH₃(g) + HCl(g) → NH₄Cl(s). ΔHf in kJ mol⁻¹: NH₃ −46, HCl −92, NH₄Cl −314.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hess_cycle.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cf1f9f4b-1162-586a-be67-3237e7da0876', 'Sum for reactants = −46 + (−92) = −138 kJ [1]. ΔH = −314 − (−138) = −176 kJ mol⁻¹ [1].', 'Sum for reactants = −46 + (−92) = −138 kJ [1]. ΔH = −314 − (−138) = −176 kJ mol⁻¹ [1].', '[{"text": "Marking point 1", "any": ["138"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["176"], "all": [], "marks": 1}]'::jsonb, 'Sum for reactants = −46 + (−92) = −138 kJ [1]. ΔH = −314 − (−138) = −176 kJ mol⁻¹ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
