insert into public.questions (id, kind, prompt, options, marks, image_url) values ('7d83c998-3438-5f72-a7c7-87688fb3c4fa', 'short', 'Multiply each ΔHf by the number of moles in the equation.
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7d83c998-3438-5f72-a7c7-87688fb3c4fa', 'Products: −394 + 2 × (−286) = −966 kJ [1]. ΔH = −966 − (−75) = −891 kJ mol⁻¹ [1].', 'Products: −394 + 2 × (−286) = −966 kJ [1]. ΔH = −966 − (−75) = −891 kJ mol⁻¹ [1].', '[{"text": "Marking point 1", "any": ["966"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["891"], "all": [], "marks": 1}]'::jsonb, 'Products: −394 + 2 × (−286) = −966 kJ [1]. ΔH = −966 − (−75) = −891 kJ mol⁻¹ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
