insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5c37b2c8-672c-57f5-8800-4a991850a8a6', 'short', 'Calculate ΔH for CaCO₃(s) → CaO(s) + CO₂(g). ΔHf in kJ mol⁻¹: CaCO₃ −1207, CaO −635, CO₂ −394. State whether the reaction is exothermic or endothermic.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5c37b2c8-672c-57f5-8800-4a991850a8a6', 'Products: −635 + (−394) = −1029 kJ [1]. ΔH = −1029 − (−1207) = +178 kJ mol⁻¹ [1]. The reaction is endothermic [1].', 'Products: −635 + (−394) = −1029 kJ [1]. ΔH = −1029 − (−1207) = +178 kJ mol⁻¹ [1]. The reaction is endothermic [1].', '[{"text": "Marking point 1", "any": ["1029"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["178"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["endothermic"], "all": [], "marks": 1}]'::jsonb, 'Products: −635 + (−394) = −1029 kJ [1]. ΔH = −1029 − (−1207) = +178 kJ mol⁻¹ [1]. The reaction is endothermic [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
