insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d0a934f4-3831-5f8d-b44c-0fea2006cbe1', 'Reactants: −394 + 2 × (−286) = −966 kJ [1]. ΔHf = −966 − (−890) = −76 kJ mol⁻¹ [1].', 'Reactants: −394 + 2 × (−286) = −966 kJ [1]. ΔHf = −966 − (−890) = −76 kJ mol⁻¹ [1].', '[{"text": "Marking point 1", "any": ["966"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["76"], "all": [], "marks": 1}]'::jsonb, 'Reactants: −394 + 2 × (−286) = −966 kJ [1]. ΔHf = −966 − (−890) = −76 kJ mol⁻¹ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
