insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1b265d30-c7f1-5495-ad89-6992927c266f', 'Bonds broken: 610 + 436 = 1046 kJ [1]. Bonds formed: 350 + 2 × 410 = 1170 kJ [1]. ΔH = 1046 − 1170 = −124 kJ mol⁻¹ [1].', 'Bonds broken: 610 + 436 = 1046 kJ [1]. Bonds formed: 350 + 2 × 410 = 1170 kJ [1]. ΔH = 1046 − 1170 = −124 kJ mol⁻¹ [1].', '[{"text": "Marking point 1", "any": ["1046"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["1170"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["124"], "all": [], "marks": 1}]'::jsonb, 'Bonds broken: 610 + 436 = 1046 kJ [1]. Bonds formed: 350 + 2 × 410 = 1170 kJ [1]. ΔH = 1046 − 1170 = −124 kJ mol⁻¹ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
