insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6e0ef609-2dd3-56a1-8bd0-1285f72e7a06', 'short', 'For NH₃(g) → N(g) + 3H(g), ΔH = +1173 kJ mol⁻¹. Calculate the average N–H bond energy.', '[]'::jsonb, 1, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
