insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ffb1d4c1-2b15-5557-a97c-6309449ba9e6', 'short', 'ΔHc in kJ mol⁻¹: C(s) −394, H₂(g) −286, C₃H₈(g) −2219.
(a) Suggest why the enthalpy change of formation of propane cannot be measured directly. (b) Use the values to calculate the enthalpy change of formation of propane: 3C(s) + 4H₂(g) → C₃H₈(g). (c) A value calculated from bond energies is slightly different. Suggest why.', '[]'::jsonb, 5, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ffb1d4c1-2b15-5557-a97c-6309449ba9e6', '(a) Carbon and hydrogen do not react directly to give only propane: other hydrocarbons would form [1]. (b) Reactants: 3 × (−394) + 4 × (−286) = −2326 kJ [1]. ΔHf = −2326 − (−2219) = −107 kJ mol⁻¹ [1]. (c) Bond energies are average values [1] taken from many different compounds, so they are not exact for propane [1].', '(a) Carbon and hydrogen do not react directly to give only propane: other hydrocarbons would form [1]. (b) Reactants: 3 × (−394) + 4 × (−286) = −2326 kJ [1]. ΔHf = −2326 − (−2219) = −107 kJ mol⁻¹ [1]. (c) Bond energies are average values [1] taken from many different compounds, so they are not exact for propane [1].', '[{"text": "Marking point 1", "any": ["other products", "mixture", "other hydrocarbons", "does not react", "do not react", "too slow", "not only propane", "many products"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["2326"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["107"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["average"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["gaseous", "not exact", "different compounds", "other compounds", "approximate"], "all": [], "marks": 1}]'::jsonb, '(a) Carbon and hydrogen do not react directly to give only propane: other hydrocarbons would form [1]. (b) Reactants: 3 × (−394) + 4 × (−286) = −2326 kJ [1]. ΔHf = −2326 − (−2219) = −107 kJ mol⁻¹ [1]. (c) Bond energies are average values [1] taken from many different compounds, so they are not exact for propane [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46db39b6-181e-5e6e-be16-515cfe5bed6c', 'ffb1d4c1-2b15-5557-a97c-6309449ba9e6', 30);
