insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f5687c3c-8111-596f-9384-a5bd534f0bb7', 'mcq', 'What is the oxidation number of the element?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('f5687c3c-8111-596f-9384-a5bd534f0bb7', 6, 'H₂SO₄: 2(+1) + S + 4(−2) = 0, S = +6. SO₂ +4. H₂S −2. NH₃ −3. HNO₃ +5. MnO₄⁻: Mn + 4(−2) = −1, Mn = +7. Cr₂O₇²⁻: 2Cr − 14 = −2, Cr = +6. Peroxide oxygen −1. ClO⁻ +1. Hydride hydrogen −1.', '+6') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
