insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c92dc3c2-1cdb-58c4-bf4e-07197127b0b4', 'short', 'In 2Mg + O₂ → 2MgO, explain why magnesium is oxidised, in terms of electrons and in terms of oxidation number.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c92dc3c2-1cdb-58c4-bf4e-07197127b0b4', 'Each magnesium atom loses two electrons [1], and its oxidation number increases from 0 to +2 [1].', 'Each magnesium atom loses two electrons [1], and its oxidation number increases from 0 to +2 [1].', '[{"text": "Marking point 1", "any": ["loses", "lose", "loss", "lost"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["0 to 2", "increases", "from 0", "rises", "goes up", "increase"], "all": [], "marks": 1}]'::jsonb, 'Each magnesium atom loses two electrons [1], and its oxidation number increases from 0 to +2 [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
