insert into public.questions (id, kind, prompt, options, marks, image_url) values ('caabb877-5cdb-5e1e-9c67-c053de255390', 'short', 'Iron(II) chloride reacts with chlorine: 2FeCl₂ + Cl₂ → 2FeCl₃. (a) State the oxidation number of iron before and after the reaction. (b) State which element is oxidised and which is reduced. (c) Give the oxidation number of chlorine in Cl₂ and in FeCl₃. (d) Name the product using a Roman numeral.', '[]'::jsonb, 5, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('caabb877-5cdb-5e1e-9c67-c053de255390', '(a) Iron changes from +2 to +3 [1]. (b) Iron is oxidised [1]; chlorine is reduced [1]. (c) Chlorine is 0 in Cl₂ and −1 in FeCl₃ [1]. (d) Iron(III) chloride [1].', '(a) Iron changes from +2 to +3 [1]. (b) Iron is oxidised [1]; chlorine is reduced [1]. (c) Chlorine is 0 in Cl₂ and −1 in FeCl₃ [1]. (d) Iron(III) chloride [1].', '[{"text": "Marking point 1", "any": ["2 to 3", "ii to iii", "from 2", "2 and 3"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["iron is oxidised", "iron oxidised", "fe is oxidised", "iron is oxidized", "iron"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["chlorine is reduced", "chlorine reduced", "cl2 is reduced", "chlorine is the one reduced", "chlorine"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["0 to 1", "0 and 1", "from 0", "zero", "0 in cl2", "is 0", "0 in"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["iron iii chloride"], "all": [], "marks": 1}]'::jsonb, '(a) Iron changes from +2 to +3 [1]. (b) Iron is oxidised [1]; chlorine is reduced [1]. (c) Chlorine is 0 in Cl₂ and −1 in FeCl₃ [1]. (d) Iron(III) chloride [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('2b0be7b7-8fdc-5f9b-99f5-68be50876063', 'caabb877-5cdb-5e1e-9c67-c053de255390', 16);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('4b55a619-5668-5e76-900c-62466c5afb24', 'mcq', 'Which is the oxidising agent?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('4b55a619-5668-5e76-900c-62466c5afb24', 1, 'Cu²⁺ (reduced to Cu), Cl₂ (reduced to Cl⁻), O₂ (reduced to O²⁻), Fe₂O₃ (iron reduced from +3 to 0) and MnO₄⁻ (manganese reduced from +7 to +2).', 'Cu²⁺') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('2b0be7b7-8fdc-5f9b-99f5-68be50876063', '4b55a619-5668-5e76-900c-62466c5afb24', 17);
