insert into public.questions (id, kind, prompt, options, marks, image_url) values ('16f01a22-f995-5f4b-ada4-e22b706a9250', 'short', 'Explain what is meant by a reducing agent, and identify the reducing agent in Cl₂ + 2I⁻ → 2Cl⁻ + I₂.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('16f01a22-f995-5f4b-ada4-e22b706a9250', 'A reducing agent donates electrons to another species and is itself oxidised [1]. Here the reducing agent is the iodide ion, I⁻ [1].', 'A reducing agent donates electrons to another species and is itself oxidised [1]. Here the reducing agent is the iodide ion, I⁻ [1].', '[{"text": "Marking point 1", "any": ["donates electrons", "gives electrons", "loses electrons", "is oxidised", "itself oxidised", "donate electrons", "lose electrons", "donor"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["iodide", "2i"], "all": [], "marks": 1}]'::jsonb, 'A reducing agent donates electrons to another species and is itself oxidised [1]. Here the reducing agent is the iodide ion, I⁻ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('2b0be7b7-8fdc-5f9b-99f5-68be50876063', '16f01a22-f995-5f4b-ada4-e22b706a9250', 20);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('62cc3108-62c3-54e3-b725-3328fa314cb7', 'mcq', 'Is the reaction a disproportionation?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('62cc3108-62c3-54e3-b725-3328fa314cb7', 0, 'Chlorine with alkali or water, hydrogen peroxide decomposing and Cu⁺ forming Cu and Cu²⁺ are disproportionations: one element goes up and down. In the other two reactions different elements are oxidised and reduced.', 'Disproportionation') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
