insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5c3ca596-1720-562d-9dbf-33077a442005', 'Chlorine is reduced from 0 to −1 in NaCl [1] and oxidised from 0 to +1 in NaClO [1]. The same element is both oxidised and reduced in the same reaction [1].', 'Chlorine is reduced from 0 to −1 in NaCl [1] and oxidised from 0 to +1 in NaClO [1]. The same element is both oxidised and reduced in the same reaction [1].', '[{"text": "Marking point 1", "any": ["reduced", "reduction", "decreases"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["oxidised", "oxidized", "oxidation", "increases"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["same element", "same species", "both", "simultaneously", "same time"], "all": [], "marks": 1}]'::jsonb, 'Chlorine is reduced from 0 to −1 in NaCl [1] and oxidised from 0 to +1 in NaClO [1]. The same element is both oxidised and reduced in the same reaction [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
