insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('f7247af6-41d9-57ca-a409-ef8a41febd60', 3, 'Mn down 5: 5 Fe²⁺. Two Cr each down 3 (total 6): 6 Fe²⁺. Cu up 2: 2 Ag⁺. Two Mn each down 5 (total 10); each C₂O₄²⁻ goes up 2: 5. Two Al each up 3 (total 6): 6 H⁺.', '6') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
