insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3a5a861d-9943-5ae2-b11b-8bd5fb96d554', 'short', 'In acid, dichromate(VI) ions oxidise iron(II) ions: Cr₂O₇²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H₂O. Show, using oxidation numbers, why six Fe²⁺ ions are needed for each Cr₂O₇²⁻ ion.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3a5a861d-9943-5ae2-b11b-8bd5fb96d554', 'Each chromium goes from +6 to +3, a decrease of 3 [1]. Each iron goes from +2 to +3, an increase of 1 [1]. There are two chromium atoms, a total decrease of 6, so six Fe²⁺ are needed to give a total increase of 6 [1].', 'Each chromium goes from +6 to +3, a decrease of 3 [1]. Each iron goes from +2 to +3, an increase of 1 [1]. There are two chromium atoms, a total decrease of 6, so six Fe²⁺ are needed to give a total increase of 6 [1].', '[{"text": "Marking point 1", "any": ["6 to 3", "from 6", "vi to iii", "decreases by 3", "down by 3", "decrease of 3"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["2 to 3", "from 2", "increases by 1", "up by 1", "increase of 1"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["total", "two chromium", "2 chromium", "2 cr", "6 electrons", "six electrons", "2 x 3", "2 3"], "all": [], "marks": 1}]'::jsonb, 'Each chromium goes from +6 to +3, a decrease of 3 [1]. Each iron goes from +2 to +3, an increase of 1 [1]. There are two chromium atoms, a total decrease of 6, so six Fe²⁺ are needed to give a total increase of 6 [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('2b0be7b7-8fdc-5f9b-99f5-68be50876063', '3a5a861d-9943-5ae2-b11b-8bd5fb96d554', 29);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('7b7862e0-b2cf-579e-9b97-2eb176fde7db', 'short', 'Manganese(IV) oxide reacts with concentrated hydrochloric acid: MnO₂ + 4HCl → MnCl₂ + Cl₂ + 2H₂O. (a) State the change in oxidation number of manganese. (b) Identify the oxidising agent and the reducing agent. (c) Explain why only half of the chlorine in the HCl is oxidised.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7b7862e0-b2cf-579e-9b97-2eb176fde7db', '(a) Manganese changes from +4 to +2 [1]. (b) The oxidising agent is MnO₂ [1]; the reducing agent is HCl (the chloride ion) [1]. (c) Two of the four chloride ions remain as Cl⁻ in MnCl₂ with their oxidation number unchanged at −1; only the two that form Cl₂ are oxidised [1].', '(a) Manganese changes from +4 to +2 [1]. (b) The oxidising agent is MnO₂ [1]; the reducing agent is HCl (the chloride ion) [1]. (c) Two of the four chloride ions remain as Cl⁻ in MnCl₂ with their oxidation number unchanged at −1; only the two that form Cl₂ are oxidised [1].', '[{"text": "Marking point 1", "any": ["4 to 2", "from 4", "iv to ii", "decreases by 2"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["mno2", "manganese iv oxide", "manganese oxide", "manganese dioxide"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["hcl", "chloride", "hydrochloric"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["unchanged", "remain", "stays", "still", "not all", "two of", "does not change", "mncl2"], "all": [], "marks": 1}]'::jsonb, '(a) Manganese changes from +4 to +2 [1]. (b) The oxidising agent is MnO₂ [1]; the reducing agent is HCl (the chloride ion) [1]. (c) Two of the four chloride ions remain as Cl⁻ in MnCl₂ with their oxidation number unchanged at −1; only the two that form Cl₂ are oxidised [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('2b0be7b7-8fdc-5f9b-99f5-68be50876063', '7b7862e0-b2cf-579e-9b97-2eb176fde7db', 30);
