insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e00ff5c6-2245-5c1f-81a4-79725129d414', 'mcq', 'Is the statement true or false for a system at dynamic equilibrium?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('e00ff5c6-2245-5c1f-81a4-79725129d414', 1, 'Both reactions continue at equal rates, so the concentrations stay constant (but are not usually equal). The system must be closed.', 'False') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'e00ff5c6-2245-5c1f-81a4-79725129d414', 1);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('adfd86fd-0907-53f1-a393-bd1d07e9c904', 'short', 'State two features of a system at dynamic equilibrium.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/ChemicalEquilibrium.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('adfd86fd-0907-53f1-a393-bd1d07e9c904', 'The rate of the forward reaction equals the rate of the reverse reaction [1]. The concentrations of the reactants and products remain constant [1].', 'The rate of the forward reaction equals the rate of the reverse reaction [1]. The concentrations of the reactants and products remain constant [1].', '[{"text": "Marking point 1", "any": ["rate", "rates"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["concentration", "constant", "do not change", "remain the same", "closed"], "all": [], "marks": 1}]'::jsonb, 'The rate of the forward reaction equals the rate of the reverse reaction [1]. The concentrations of the reactants and products remain constant [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'adfd86fd-0907-53f1-a393-bd1d07e9c904', 2);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('9efc0c17-13a7-587e-949d-91351b90b92b', 'mcq', 'For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), ΔH = −92 kJ mol⁻¹, which way does the position of equilibrium move?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('9efc0c17-13a7-587e-949d-91351b90b92b', 0, 'Higher pressure: to the side with fewer molecules (right). Higher temperature: in the endothermic direction (left). Adding a reactant or removing the product: right. Catalyst: no change. Lower pressure: left.', 'To the right') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '9efc0c17-13a7-587e-949d-91351b90b92b', 3);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ea2b82d3-8625-5a11-8dbc-a5aa7df65265', 'mcq', 'For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), ΔH = −92 kJ mol⁻¹, which way does the position of equilibrium move?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('ea2b82d3-8625-5a11-8dbc-a5aa7df65265', 1, 'Higher pressure: to the side with fewer molecules (right). Higher temperature: in the endothermic direction (left). Adding a reactant or removing the product: right. Catalyst: no change. Lower pressure: left.', 'To the left') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'ea2b82d3-8625-5a11-8dbc-a5aa7df65265', 4);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('1a160ffb-0d12-5d29-bb4d-f0056e248142', 'mcq', 'What is the effect of increasing the pressure on the position of equilibrium?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('1a160ffb-0d12-5d29-bb4d-f0056e248142', 1, '3 to 2: right. 1 to 2: left. 2 to 2: no change. 3 to 1: right. 0 to 1 gas molecules: left.', 'To the left') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '1a160ffb-0d12-5d29-bb4d-f0056e248142', 5);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('14651bb1-6e34-5592-9308-caa58e483fa9', 'short', 'For 2NO₂(g) ⇌ N₂O₄(g), ΔH = −57 kJ mol⁻¹ (NO₂ is brown, N₂O₄ is colourless). State and explain what is seen when the mixture is heated at constant volume.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('14651bb1-6e34-5592-9308-caa58e483fa9', 'The mixture becomes darker brown [1] because the position of equilibrium moves to the left, forming more NO₂ [1]. This is the endothermic direction, which absorbs heat and so opposes the rise in temperature [1].', 'The mixture becomes darker brown [1] because the position of equilibrium moves to the left, forming more NO₂ [1]. This is the endothermic direction, which absorbs heat and so opposes the rise in temperature [1].', '[{"text": "Marking point 1", "any": ["darker", "more brown", "browner", "brown colour increases", "deeper"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["left", "reverse", "backward", "towards no2", "more no2"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["endothermic"], "all": [], "marks": 1}]'::jsonb, 'The mixture becomes darker brown [1] because the position of equilibrium moves to the left, forming more NO₂ [1]. This is the endothermic direction, which absorbs heat and so opposes the rise in temperature [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '14651bb1-6e34-5592-9308-caa58e483fa9', 6);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('2ba74412-2358-5e3b-b044-d5905c099020', 'short', 'For 2SO₂(g) + O₂(g) ⇌ 2SO₃(g), ΔH = −197 kJ mol⁻¹: (a) predict and explain the effect on the yield of SO₃ of increasing the pressure; (b) predict and explain the effect on the yield of SO₃ of increasing the temperature; (c) explain why the mixture must be in a closed container to reach equilibrium.', '[]'::jsonb, 5, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2ba74412-2358-5e3b-b044-d5905c099020', '(a) The yield increases [1]: the position moves to the right, the side with fewer gas molecules, to reduce the pressure [1]. (b) The yield decreases [1]: the position moves to the left, in the endothermic direction, to absorb the extra heat [1]. (c) So that no reactants or products can escape; otherwise the reverse reaction could not keep up and equilibrium would never be reached [1].', '(a) The yield increases [1]: the position moves to the right, the side with fewer gas molecules, to reduce the pressure [1]. (b) The yield decreases [1]: the position moves to the left, in the endothermic direction, to absorb the extra heat [1]. (c) So that no reactants or products can escape; otherwise the reverse reaction could not keep up and equilibrium would never be reached [1].', '[{"text": "Marking point 1", "any": ["increases", "higher yield", "more so3", "greater yield", "increase"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["fewer", "less molecules", "fewer moles", "3 to 2", "smaller number"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["decreases", "lower yield", "less so3", "decrease", "falls"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["endothermic", "exothermic"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["escape", "leave", "lost", "closed"], "all": [], "marks": 1}]'::jsonb, '(a) The yield increases [1]: the position moves to the right, the side with fewer gas molecules, to reduce the pressure [1]. (b) The yield decreases [1]: the position moves to the left, in the endothermic direction, to absorb the extra heat [1]. (c) So that no reactants or products can escape; otherwise the reverse reaction could not keep up and equilibrium would never be reached [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '2ba74412-2358-5e3b-b044-d5905c099020', 7);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a93fc0b5-6298-54c6-bb2f-ed7e8ae0a65c', 'mcq', 'What are the units of Kc?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a93fc0b5-6298-54c6-bb2f-ed7e8ae0a65c', 0, '2 − 4 = −2: mol⁻² dm⁶. 2 − 2 = 0: no units. 2 − 1 = 1: mol dm⁻³. 2 − 3 = −1: mol⁻¹ dm³. 2 − 2: no units. 2 − 1: mol dm⁻³.', 'No units') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'a93fc0b5-6298-54c6-bb2f-ed7e8ae0a65c', 8);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('83110ac7-abfb-563f-bed9-6d77fc8d180f', 'short', '0.100 mol of N₂O₄ is placed in a 1.00 dm³ flask. At equilibrium 0.020 mol of the N₂O₄ has dissociated: N₂O₄ ⇌ 2NO₂. Calculate Kc, with units.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('83110ac7-abfb-563f-bed9-6d77fc8d180f', 'N₂O₄ remaining = 0.100 − 0.020 = 0.080 mol dm⁻³ [1]. NO₂ formed = 2 × 0.020 = 0.040 mol dm⁻³ [1]. Kc = 0.040² ÷ 0.080 = 0.020 mol dm⁻³ [1].', 'N₂O₄ remaining = 0.100 − 0.020 = 0.080 mol dm⁻³ [1]. NO₂ formed = 2 × 0.020 = 0.040 mol dm⁻³ [1]. Kc = 0.040² ÷ 0.080 = 0.020 mol dm⁻³ [1].', '[{"text": "Marking point 1", "any": ["0.08"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["0.04"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["0.02 mol", "0.020", "0.02"], "all": [], "marks": 1}]'::jsonb, 'N₂O₄ remaining = 0.100 − 0.020 = 0.080 mol dm⁻³ [1]. NO₂ formed = 2 × 0.020 = 0.040 mol dm⁻³ [1]. Kc = 0.040² ÷ 0.080 = 0.020 mol dm⁻³ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '83110ac7-abfb-563f-bed9-6d77fc8d180f', 9);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8f39fa79-b0f3-5fee-abec-9af4bb9a539f', 'mcq', 'What happens to the value of the equilibrium constant?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('8f39fa79-b0f3-5fee-abec-9af4bb9a539f', 1, 'Only temperature changes K: it decreases for an exothermic forward reaction and increases for an endothermic one. Concentration, pressure and catalysts do not change K.', 'Decreases') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '8f39fa79-b0f3-5fee-abec-9af4bb9a539f', 10);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('32d653b5-521c-5d69-ac47-67a752eb1bea', 'short', '0.400 mol of PCl₅ is heated in a 2.00 dm³ vessel: PCl₅(g) ⇌ PCl₃(g) + Cl₂(g). At equilibrium 0.100 mol of Cl₂ is present. (a) Calculate the equilibrium amount of PCl₅. (b) Calculate the equilibrium concentrations of PCl₅ and of Cl₂. (c) Calculate Kc. (d) The forward reaction is endothermic. State the effect on Kc of increasing the temperature.', '[]'::jsonb, 5, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('32d653b5-521c-5d69-ac47-67a752eb1bea', '(a) PCl₅ = 0.400 − 0.100 = 0.300 mol [1]. (b) [PCl₅] = 0.300 ÷ 2.00 = 0.150 mol dm⁻³ [1]; [Cl₂] = [PCl₃] = 0.100 ÷ 2.00 = 0.0500 mol dm⁻³ [1]. (c) Kc = (0.0500 × 0.0500) ÷ 0.150 = 0.0167 mol dm⁻³ [1]. (d) Kc increases [1].', '(a) PCl₅ = 0.400 − 0.100 = 0.300 mol [1]. (b) [PCl₅] = 0.300 ÷ 2.00 = 0.150 mol dm⁻³ [1]; [Cl₂] = [PCl₃] = 0.100 ÷ 2.00 = 0.0500 mol dm⁻³ [1]. (c) Kc = (0.0500 × 0.0500) ÷ 0.150 = 0.0167 mol dm⁻³ [1]. (d) Kc increases [1].', '[{"text": "Marking point 1", "any": ["0.3"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["0.15"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["0.05"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["0.0167", "0.017", "1.67 10", "1.7 10"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["increase"], "all": [], "marks": 1}]'::jsonb, '(a) PCl₅ = 0.400 − 0.100 = 0.300 mol [1]. (b) [PCl₅] = 0.300 ÷ 2.00 = 0.150 mol dm⁻³ [1]; [Cl₂] = [PCl₃] = 0.100 ÷ 2.00 = 0.0500 mol dm⁻³ [1]. (c) Kc = (0.0500 × 0.0500) ÷ 0.150 = 0.0167 mol dm⁻³ [1]. (d) Kc increases [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '32d653b5-521c-5d69-ac47-67a752eb1bea', 11);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d531911a-5eb0-5f86-9353-9d4c02b436a2', 'mcq', 'A mixture contains 1.0 mol of N₂ and 3.0 mol of H₂ at a total pressure of 400 kPa.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('d531911a-5eb0-5f86-9353-9d4c02b436a2', 0, 'Mole fractions 1.0 ÷ 4.0 = 0.25 and 3.0 ÷ 4.0 = 0.75. Partial pressures 0.25 × 400 = 100 kPa and 0.75 × 400 = 300 kPa, which add up to 400 kPa.', '0.25') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'd531911a-5eb0-5f86-9353-9d4c02b436a2', 12);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3015e223-c5d5-5e68-a072-e563bd8b379f', 'short', 'An equilibrium mixture of 2SO₂(g) + O₂(g) ⇌ 2SO₃(g) contains 0.20 mol SO₂, 0.10 mol O₂ and 0.70 mol SO₃ at a total pressure of 200 kPa. Calculate the partial pressure of each gas and then Kp.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3015e223-c5d5-5e68-a072-e563bd8b379f', 'Partial pressures: SO₂ 0.20 × 200 = 40 kPa, O₂ 0.10 × 200 = 20 kPa [1], SO₃ 0.70 × 200 = 140 kPa [1]. Kp = 140² ÷ (40² × 20) = 19600 ÷ 32000 = 0.613 kPa⁻¹ [1].', 'Partial pressures: SO₂ 0.20 × 200 = 40 kPa, O₂ 0.10 × 200 = 20 kPa [1], SO₃ 0.70 × 200 = 140 kPa [1]. Kp = 140² ÷ (40² × 20) = 19600 ÷ 32000 = 0.613 kPa⁻¹ [1].', '[{"text": "Marking point 1", "any": ["40"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["140"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["0.61", "0.613", "0.6125"], "all": [], "marks": 1}]'::jsonb, 'Partial pressures: SO₂ 0.20 × 200 = 40 kPa, O₂ 0.10 × 200 = 20 kPa [1], SO₃ 0.70 × 200 = 140 kPa [1]. Kp = 140² ÷ (40² × 20) = 19600 ÷ 32000 = 0.613 kPa⁻¹ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '3015e223-c5d5-5e68-a072-e563bd8b379f', 13);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ff190102-f816-5575-b5e2-bbfa952badc7', 'mcq', 'Choose the condition used in the Haber process.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('ff190102-f816-5575-b5e2-bbfa952badc7', 0, 'About 450 °C, about 200 atm and an iron catalyst.', 'About 450 °C') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'ff190102-f816-5575-b5e2-bbfa952badc7', 14);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e0d3ee69-5cc9-5179-841b-885f82c5e621', 'short', 'Explain why a temperature of about 450 °C is described as a compromise in the Haber process.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Haber-Bosch-En.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e0d3ee69-5cc9-5179-841b-885f82c5e621', 'The forward reaction is exothermic [1], so a lower temperature would give a higher yield of ammonia [1]. But at a low temperature the rate would be too slow, so 450 °C gives an acceptable yield at an acceptable rate [1].', 'The forward reaction is exothermic [1], so a lower temperature would give a higher yield of ammonia [1]. But at a low temperature the rate would be too slow, so 450 °C gives an acceptable yield at an acceptable rate [1].', '[{"text": "Marking point 1", "any": ["exothermic"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["lower temperature", "low temperature", "higher yield", "yield decreases", "lower yield"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["rate", "slow", "fast", "speed"], "all": [], "marks": 1}]'::jsonb, 'The forward reaction is exothermic [1], so a lower temperature would give a higher yield of ammonia [1]. But at a low temperature the rate would be too slow, so 450 °C gives an acceptable yield at an acceptable rate [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'e0d3ee69-5cc9-5179-841b-885f82c5e621', 15);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a59f511a-ea90-50c3-8fd6-ad6ddd0b24c4', 'mcq', 'Haber process, Contact process, or both?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a59f511a-ea90-50c3-8fd6-ad6ddd0b24c4', 2, 'Iron and 200 atm: Haber. Vanadium(V) oxide and near-atmospheric pressure: Contact. Both use about 450 °C and both forward reactions are exothermic.', 'Both') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'a59f511a-ea90-50c3-8fd6-ad6ddd0b24c4', 16);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('1d52e92a-d1a4-58a2-9fe2-7f3cd9499fdb', 'short', 'In the Haber process an equilibrium mixture at a total pressure of 200 atm contains 2.0 mol N₂, 6.0 mol H₂ and 2.0 mol NH₃. (a) Calculate the mole fraction and the partial pressure of ammonia. (b) Write the expression for Kp (describe it in words or symbols). (c) Explain why a pressure higher than 200 atm is not normally used.', '[]'::jsonb, 5, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1d52e92a-d1a4-58a2-9fe2-7f3cd9499fdb', '(a) Mole fraction of NH₃ = 2.0 ÷ 10.0 = 0.20 [1]; partial pressure = 0.20 × 200 = 40 atm [1]. (b) Kp = the partial pressure of NH₃ squared [1] divided by (the partial pressure of N₂ × the partial pressure of H₂ cubed) [1]. (c) Higher pressures need stronger, more expensive equipment and more energy for compression, and are less safe [1].', '(a) Mole fraction of NH₃ = 2.0 ÷ 10.0 = 0.20 [1]; partial pressure = 0.20 × 200 = 40 atm [1]. (b) Kp = the partial pressure of NH₃ squared [1] divided by (the partial pressure of N₂ × the partial pressure of H₂ cubed) [1]. (c) Higher pressures need stronger, more expensive equipment and more energy for compression, and are less safe [1].', '[{"text": "Marking point 1", "any": ["0.2", "0.20"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["40"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["nh3", "ammonia"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["squared", "2", "cubed", "3"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["cost", "expensive", "strong", "safety", "dangerous", "thick"], "all": [], "marks": 1}]'::jsonb, '(a) Mole fraction of NH₃ = 2.0 ÷ 10.0 = 0.20 [1]; partial pressure = 0.20 × 200 = 40 atm [1]. (b) Kp = the partial pressure of NH₃ squared [1] divided by (the partial pressure of N₂ × the partial pressure of H₂ cubed) [1]. (c) Higher pressures need stronger, more expensive equipment and more energy for compression, and are less safe [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '1d52e92a-d1a4-58a2-9fe2-7f3cd9499fdb', 17);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('36d9f00d-9c5e-56cc-a536-2c1a3f3ee92e', 'mcq', 'Choose the formula.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('36d9f00d-9c5e-56cc-a536-2c1a3f3ee92e', 3, 'H₂SO₄, HNO₃, CH₃COOH, NH₃ and KOH.', 'CH₃COOH') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '36d9f00d-9c5e-56cc-a536-2c1a3f3ee92e', 18);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('2d42d06b-fa54-5e62-93d1-4933d20d3eb6', 'mcq', 'In the forward reaction, is the species acting as an acid or a base?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('2d42d06b-fa54-5e62-93d1-4933d20d3eb6', 1, 'HCl and CH₃COOH donate protons: acids. NH₃ accepts a proton: base. Water accepts a proton from HCl (base) but donates one to NH₃ (acid).', 'Base') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '2d42d06b-fa54-5e62-93d1-4933d20d3eb6', 19);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8d170876-1383-56fb-809d-ccad4293d987', 'mcq', 'Classify the substance.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('8d170876-1383-56fb-809d-ccad4293d987', 1, 'Strong acids: HCl, HNO₃, H₂SO₄. Weak acid: CH₃COOH. Strong bases: NaOH, KOH. Weak base: NH₃.', 'Weak acid') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '8d170876-1383-56fb-809d-ccad4293d987', 20);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5776f2ae-5f76-5196-a4d1-1bc950bc49d2', 'mcq', 'Classify the substance.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('5776f2ae-5f76-5196-a4d1-1bc950bc49d2', 0, 'Strong acids: HCl, HNO₃, H₂SO₄. Weak acid: CH₃COOH. Strong bases: NaOH, KOH. Weak base: NH₃.', 'Strong acid') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '5776f2ae-5f76-5196-a4d1-1bc950bc49d2', 21);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c9c78c88-7c7d-5d09-998b-c081168397df', 'short', 'Explain the difference between a strong acid and a weak acid.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/PH_scale.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c9c78c88-7c7d-5d09-998b-c081168397df', 'A strong acid is fully dissociated in aqueous solution [1]; a weak acid is only partially dissociated [1].', 'A strong acid is fully dissociated in aqueous solution [1]; a weak acid is only partially dissociated [1].', '[{"text": "Marking point 1", "any": ["fully", "completely", "totally"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["partial", "partly", "slightly", "incomplete", "not fully", "only some"], "all": [], "marks": 1}]'::jsonb, 'A strong acid is fully dissociated in aqueous solution [1]; a weak acid is only partially dissociated [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'c9c78c88-7c7d-5d09-998b-c081168397df', 22);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('0248f4a6-30f9-5e51-9bf0-875f41879dae', 'mcq', 'Compare 0.1 mol dm⁻³ HCl with 0.1 mol dm⁻³ CH₃COOH.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('0248f4a6-30f9-5e51-9bf0-875f41879dae', 2, 'HCl has more H⁺ ions: lower pH, higher conductivity, faster reaction. The total amount of acid is the same, so the final volume of hydrogen is the same.', 'The same') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '0248f4a6-30f9-5e51-9bf0-875f41879dae', 23);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('068f2a82-8de8-584a-a12e-754873c401fd', 'short', 'Ammonia reacts with hydrogen chloride: NH₃ + HCl → NH₄⁺ + Cl⁻. (a) Identify the Brønsted–Lowry acid and base, explaining your choice. (b) Write an equation to show why aqueous ammonia is alkaline, and state why ammonia is a weak base. (c) Equal volumes of 0.1 mol dm⁻³ HCl and 0.1 mol dm⁻³ CH₃COOH react with excess magnesium. Compare the rates and the final volumes of hydrogen.', '[]'::jsonb, 5, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('068f2a82-8de8-584a-a12e-754873c401fd', '(a) HCl is the acid because it donates a proton [1]; NH₃ is the base because it accepts a proton [1]. (b) NH₃ + H₂O ⇌ NH₄⁺ + OH⁻; ammonia is only partially dissociated (partly ionised) in water [1]. (c) HCl reacts faster because it has a higher concentration of H⁺ ions [1], but both give the same final volume of hydrogen because the amounts of acid are equal [1].', '(a) HCl is the acid because it donates a proton [1]; NH₃ is the base because it accepts a proton [1]. (b) NH₃ + H₂O ⇌ NH₄⁺ + OH⁻; ammonia is only partially dissociated (partly ionised) in water [1]. (c) HCl reacts faster because it has a higher concentration of H⁺ ions [1], but both give the same final volume of hydrogen because the amounts of acid are equal [1].', '[{"text": "Marking point 1", "any": ["hcl is the acid"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["nh3 is the base", "ammonia is the base"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["nh4", "oh", "partial", "partly", "not fully"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["faster", "slower", "higher rate", "more quickly"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["same volume", "equal volume", "same amount", "same final"], "all": [], "marks": 1}]'::jsonb, '(a) HCl is the acid because it donates a proton [1]; NH₃ is the base because it accepts a proton [1]. (b) NH₃ + H₂O ⇌ NH₄⁺ + OH⁻; ammonia is only partially dissociated (partly ionised) in water [1]. (c) HCl reacts faster because it has a higher concentration of H⁺ ions [1], but both give the same final volume of hydrogen because the amounts of acid are equal [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '068f2a82-8de8-584a-a12e-754873c401fd', 24);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f8090494-a4a8-5a4a-af18-1b3e7f68c0b2', 'mcq', 'Which salt is formed?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('f8090494-a4a8-5a4a-af18-1b3e7f68c0b2', 4, 'Sodium chloride, potassium sulfate, ammonium nitrate, sodium ethanoate and potassium nitrate.', 'Potassium nitrate') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'f8090494-a4a8-5a4a-af18-1b3e7f68c0b2', 25);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('67734a71-6547-5b4e-8032-342aadb338aa', 'mcq', 'Match the description to the titration.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('67734a71-6547-5b4e-8032-342aadb338aa', 0, 'Long vertical section 3 to 11: strong–strong. Equivalence above 7: weak acid–strong alkali (ethanoic acid with NaOH). Equivalence below 7: strong acid–weak alkali (HCl with ammonia). No sharp section: weak–weak.', 'Strong acid, strong alkali') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '67734a71-6547-5b4e-8032-342aadb338aa', 26);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f5607c37-2e6d-560f-81a8-fbbd6f8b9beb', 'mcq', 'Match the description to the titration.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('f5607c37-2e6d-560f-81a8-fbbd6f8b9beb', 2, 'Long vertical section 3 to 11: strong–strong. Equivalence above 7: weak acid–strong alkali (ethanoic acid with NaOH). Equivalence below 7: strong acid–weak alkali (HCl with ammonia). No sharp section: weak–weak.', 'Strong acid, weak alkali') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'f5607c37-2e6d-560f-81a8-fbbd6f8b9beb', 27);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('4c4ca3ca-d892-5854-97c9-e032400a6da7', 'short', 'Describe the pH curve when 0.1 mol dm⁻³ sodium hydroxide is added to 25 cm³ of 0.1 mol dm⁻³ ethanoic acid until in excess. Give the starting pH, the vertical section and the final pH.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('4c4ca3ca-d892-5854-97c9-e032400a6da7', 'The curve starts at about pH 3 [1], rises gradually, then has a vertical section from about pH 7 to pH 11 at 25 cm³, with the equivalence point above pH 7 [1], and levels off at about pH 13 [1].', 'The curve starts at about pH 3 [1], rises gradually, then has a vertical section from about pH 7 to pH 11 at 25 cm³, with the equivalence point above pH 7 [1], and levels off at about pH 13 [1].', '[{"text": "Marking point 1", "any": ["ph 3", "about 3", "3"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["7 to 11", "7 and 11", "above 7", "7 11", "8 to 10", "around 9", "about 9", "ph 7 to ph 11", "7 to ph 11"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["13", "12"], "all": [], "marks": 1}]'::jsonb, 'The curve starts at about pH 3 [1], rises gradually, then has a vertical section from about pH 7 to pH 11 at 25 cm³, with the equivalence point above pH 7 [1], and levels off at about pH 13 [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', '4c4ca3ca-d892-5854-97c9-e032400a6da7', 28);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('cc2361b3-b0c4-5ab0-ae18-e91dc97122cb', 'mcq', 'Which indicator is suitable?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('cc2361b3-b0c4-5ab0-ae18-e91dc97122cb', 2, 'Strong–strong (HCl/NaOH, HNO₃/KOH): either. Weak acid–strong alkali: phenolphthalein. Strong acid–weak alkali: methyl orange. Weak–weak: neither.', 'Either') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'cc2361b3-b0c4-5ab0-ae18-e91dc97122cb', 29);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('bb0a5990-b8aa-5ba6-8f56-2b7b8a79de80', 'short', 'Indicator ranges: methyl orange 3.1–4.4; bromothymol blue 6.0–7.6; phenolphthalein 8.3–10.0.
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('bb0a5990-b8aa-5ba6-8f56-2b7b8a79de80', '(a) H⁺(aq) + OH⁻(aq) [1] → H₂O(l) [1]. (b) The vertical section is from about pH 3 to pH 7 [1], so methyl orange is the most suitable [1]. (c) With a weak acid and a weak alkali there is no sharp vertical section: the pH changes gradually, so no indicator gives a sharp colour change [1].', '(a) H⁺(aq) + OH⁻(aq) [1] → H₂O(l) [1]. (b) The vertical section is from about pH 3 to pH 7 [1], so methyl orange is the most suitable [1]. (c) With a weak acid and a weak alkali there is no sharp vertical section: the pH changes gradually, so no indicator gives a sharp colour change [1].', '[{"text": "Marking point 1", "any": ["h aq oh aq", "h oh h2o", "oh aq h aq"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["h2o"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["3 to 7", "3 and 7", "3 7", "below 7", "4 to 6", "ph 3 to ph 7", "3 to ph 7"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["methyl orange"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["no vertical", "no sharp", "gradual", "not sharp", "no steep", "no rapid"], "all": [], "marks": 1}]'::jsonb, '(a) H⁺(aq) + OH⁻(aq) [1] → H₂O(l) [1]. (b) The vertical section is from about pH 3 to pH 7 [1], so methyl orange is the most suitable [1]. (c) With a weak acid and a weak alkali there is no sharp vertical section: the pH changes gradually, so no indicator gives a sharp colour change [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a2beefc2-6771-5120-94b4-c747f13ac1f7', 'bb0a5990-b8aa-5ba6-8f56-2b7b8a79de80', 30);
insert into public.quiz_classes (quiz_id, class_id) select 'a2beefc2-6771-5120-94b4-c747f13ac1f7', c.id from public.classes c where c.site_slug = 'alevel-chem' and c.owner_kind = 'main' on conflict do nothing;
insert into public.quizzes (id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', '8 Reaction kinetics · Topic quiz', 'Topical quiz for A Level Chemistry, topic 8 Reaction kinetics (subtopics 8.1 to 8.3). Questions come from the interactive lessons. Written answers are marked against the mark scheme; your teacher checks every mark.', null, 2, false, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions;
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a53d57ba-b061-554a-b093-0ed464335c7a', 'mcq', 'Effective or non-effective?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a53d57ba-b061-554a-b093-0ed464335c7a', 1, 'A collision is effective only if the particles have at least the activation energy (and a suitable orientation) so that products form; otherwise they bounce apart.', 'Non-effective collision') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', 'a53d57ba-b061-554a-b093-0ed464335c7a', 1);
