insert into public.questions (id, kind, prompt, options, marks, image_url) values ('b9268b52-5233-5897-a4b4-666363722394', 'short', 'State what is meant by an effective collision.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b9268b52-5233-5897-a4b4-666363722394', 'A collision that leads to a reaction [1], because the particles collide with at least the activation energy [1].', 'A collision that leads to a reaction [1], because the particles collide with at least the activation energy [1].', '[{"text": "Marking point 1", "any": ["reaction", "react", "products"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["activation energy", "enough energy", "sufficient energy", "minimum energy"], "all": [], "marks": 1}]'::jsonb, 'A collision that leads to a reaction [1], because the particles collide with at least the activation energy [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', 'b9268b52-5233-5897-a4b4-666363722394', 3);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('588e2e80-55e3-5501-8662-4d3f83b35790', 'mcq', 'What happens to the rate of reaction?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('588e2e80-55e3-5501-8662-4d3f83b35790', 0, 'More particles per unit volume (higher concentration or pressure): faster. Fewer per unit volume (larger container, dilution): slower. More acid at the same concentration: no change in rate.', 'Increases') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', '588e2e80-55e3-5501-8662-4d3f83b35790', 4);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a8455376-7df8-521c-a7a8-1e770334a8f5', 'mcq', 'What happens to the rate of reaction?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a8455376-7df8-521c-a7a8-1e770334a8f5', 1, 'More particles per unit volume (higher concentration or pressure): faster. Fewer per unit volume (larger container, dilution): slower. More acid at the same concentration: no change in rate.', 'Decreases') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', 'a8455376-7df8-521c-a7a8-1e770334a8f5', 5);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('263bb084-3f5f-5d95-a22b-4e65342ecacd', 'short', 'Explain why increasing the concentration of hydrochloric acid increases the rate of its reaction with magnesium.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('263bb084-3f5f-5d95-a22b-4e65342ecacd', 'There are more acid particles (H⁺ ions) in the same volume [1], so collisions with the magnesium are more frequent [1], and so effective collisions are more frequent [1].', 'There are more acid particles (H⁺ ions) in the same volume [1], so collisions with the magnesium are more frequent [1], and so effective collisions are more frequent [1].', '[{"text": "Marking point 1", "any": ["more particles", "more ions", "more h", "more acid particles", "particles per unit volume", "more molecules", "closer together"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["more frequent", "more often", "more collisions", "collide more", "frequency"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["effective", "successful"], "all": [], "marks": 1}]'::jsonb, 'There are more acid particles (H⁺ ions) in the same volume [1], so collisions with the magnesium are more frequent [1], and so effective collisions are more frequent [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', '263bb084-3f5f-5d95-a22b-4e65342ecacd', 6);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('cff4497c-4883-5099-8d4a-2513b040e848', 'short', 'In a reaction 48 cm³ of gas is collected in the first 20 s. Calculate the average rate of reaction over this time, with units.', '[]'::jsonb, 1, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gas_syringe.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cff4497c-4883-5099-8d4a-2513b040e848', '48 ÷ 20 = 2.4 cm³ s⁻¹ [1].', '48 ÷ 20 = 2.4 cm³ s⁻¹ [1].', '[{"text": "Marking point 1", "any": ["2.4"], "all": [], "marks": 1}]'::jsonb, '48 ÷ 20 = 2.4 cm³ s⁻¹ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
