insert into public.questions (id, kind, prompt, options, marks, image_url) values ('4c71880a-b52c-5f3d-876d-c40d9f68ef02', 'short', 'The concentration of a reactant falls from 0.100 mol dm⁻³ to 0.076 mol dm⁻³ in 60 s. Calculate the average rate of reaction, with units.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gas_syringe.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('4c71880a-b52c-5f3d-876d-c40d9f68ef02', 'Change in concentration = 0.100 − 0.076 = 0.024 mol dm⁻³ [1]. Rate = 0.024 ÷ 60 = 4.0 × 10⁻⁴ mol dm⁻³ s⁻¹ [1].', 'Change in concentration = 0.100 − 0.076 = 0.024 mol dm⁻³ [1]. Rate = 0.024 ÷ 60 = 4.0 × 10⁻⁴ mol dm⁻³ s⁻¹ [1].', '[{"text": "Marking point 1", "any": ["0.024"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["4.0 10", "4 10", "0.0004", "0.00040"], "all": [], "marks": 1}]'::jsonb, 'Change in concentration = 0.100 − 0.076 = 0.024 mol dm⁻³ [1]. Rate = 0.024 ÷ 60 = 4.0 × 10⁻⁴ mol dm⁻³ s⁻¹ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', '4c71880a-b52c-5f3d-876d-c40d9f68ef02', 8);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8be43bf1-ac86-517b-8a91-331d9a026164', 'mcq', 'On a graph of volume of gas against time, what does each feature show?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('8be43bf1-ac86-517b-8a91-331d9a026164', 0, 'Steepest: fastest (highest concentration of reactants). Less steep: slowing as reactants are used up. Horizontal: finished.', 'The reaction is fastest') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', '8be43bf1-ac86-517b-8a91-331d9a026164', 9);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('871242b6-5cf0-50bd-adb1-b915c5cea03a', 'mcq', 'On a graph of volume of gas against time, what does each feature show?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('871242b6-5cf0-50bd-adb1-b915c5cea03a', 2, 'Steepest: fastest (highest concentration of reactants). Less steep: slowing as reactants are used up. Horizontal: finished.', 'The reaction has finished') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', '871242b6-5cf0-50bd-adb1-b915c5cea03a', 10);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3186a4d0-cf85-51ee-97d3-3f1eb664bb5a', 'short', 'Calcium carbonate reacts with hydrochloric acid, giving carbon dioxide. (a) Suggest one way to follow the rate of this reaction. (b) Explain why the rate decreases as the reaction goes on. (c) In one experiment 60 cm³ of gas forms in the first 30 s and 90 cm³ in total after 90 s. Calculate the average rate in the first 30 s and in the next 60 s.', '[]'::jsonb, 5, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3186a4d0-cf85-51ee-97d3-3f1eb664bb5a', '(a) Measure the volume of gas with a gas syringe (or the loss in mass on a balance) at regular times [1]. (b) The concentration of the acid decreases as it is used up [1], so effective collisions are less frequent [1]. (c) First 30 s: 60 ÷ 30 = 2.0 cm³ s⁻¹ [1]. Next 60 s: (90 − 60) ÷ 60 = 0.50 cm³ s⁻¹ [1].', '(a) Measure the volume of gas with a gas syringe (or the loss in mass on a balance) at regular times [1]. (b) The concentration of the acid decreases as it is used up [1], so effective collisions are less frequent [1]. (c) First 30 s: 60 ÷ 30 = 2.0 cm³ s⁻¹ [1]. Next 60 s: (90 − 60) ÷ 60 = 0.50 cm³ s⁻¹ [1].', '[{"text": "Marking point 1", "any": ["gas syringe", "volume of gas", "mass", "balance", "collect the gas"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["used up", "less acid", "fewer particles", "concentration of acid decreases", "lower concentration"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["less frequent", "fewer collisions", "collide less", "less often", "fewer effective"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["2.0", "2 cm3", "2 cm"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["0.5", "0.50"], "all": [], "marks": 1}]'::jsonb, '(a) Measure the volume of gas with a gas syringe (or the loss in mass on a balance) at regular times [1]. (b) The concentration of the acid decreases as it is used up [1], so effective collisions are less frequent [1]. (c) First 30 s: 60 ÷ 30 = 2.0 cm³ s⁻¹ [1]. Next 60 s: (90 − 60) ÷ 60 = 0.50 cm³ s⁻¹ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', '3186a4d0-cf85-51ee-97d3-3f1eb664bb5a', 11);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d53acfed-e9ec-57e0-85de-624ac2b299c4', 'mcq', 'What does each feature of a Boltzmann distribution show?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('d53acfed-e9ec-57e0-85de-624ac2b299c4', 1, 'Whole area: total number of molecules. Peak: most probable energy. Area beyond the activation energy: molecules with enough energy to react. Starting at the origin: no molecules have zero energy.', 'The most probable energy') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', 'd53acfed-e9ec-57e0-85de-624ac2b299c4', 12);
