insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8213bacb-b177-5ab8-9041-e889e8f2aa8d', 'mcq', 'What happens when the temperature is increased?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('8213bacb-b177-5ab8-9041-e889e8f2aa8d', 1, 'The peak is lower and at a higher energy; the total area and the activation energy are unchanged; the area beyond the activation energy, and so the frequency of effective collisions, increases.', 'Decreases') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
