insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('1c4f9f45-9962-57a1-aaab-48e3dfa61834', 0, 'The reaction with the lower activation energy: a much greater proportion of molecules have at least 30 kJ mol⁻¹ than have 150 kJ mol⁻¹.', 'Activation energy 30 kJ mol⁻¹') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
