insert into public.questions (id, kind, prompt, options, marks, image_url) values ('2938e24e-54b1-5151-a5c3-25c010388e3d', 'short', 'Food keeps for longer in a refrigerator. Explain why, in terms of activation energy and collisions.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2938e24e-54b1-5151-a5c3-25c010388e3d', 'At the lower temperature a smaller proportion of the molecules [1] have at least the activation energy [1], so effective collisions are less frequent and the reactions that spoil food are slower [1].', 'At the lower temperature a smaller proportion of the molecules [1] have at least the activation energy [1], so effective collisions are less frequent and the reactions that spoil food are slower [1].', '[{"text": "Marking point 1", "any": ["fewer", "smaller proportion", "less molecules", "lower proportion", "less particles"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["activation energy"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["effective", "successful", "slower", "less frequent", "rate decreases"], "all": [], "marks": 1}]'::jsonb, 'At the lower temperature a smaller proportion of the molecules [1] have at least the activation energy [1], so effective collisions are less frequent and the reactions that spoil food are slower [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', '2938e24e-54b1-5151-a5c3-25c010388e3d', 18);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('616921a0-6366-5116-bb13-21921cf9bf84', 'short', '(a) Describe the shape of a Boltzmann distribution, including where it starts and how it ends. (b) Describe two ways in which the curve changes when the temperature is raised. (c) State what does not change about the curve, and why.', '[]'::jsonb, 5, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('616921a0-6366-5116-bb13-21921cf9bf84', '(a) It starts at the origin [1], rises to a peak and then falls, approaching the x-axis without touching it [1]. (b) The peak becomes lower [1] and moves to the right, to a higher energy [1]. (c) The total area under the curve does not change, because the number of molecules is the same [1].', '(a) It starts at the origin [1], rises to a peak and then falls, approaching the x-axis without touching it [1]. (b) The peak becomes lower [1] and moves to the right, to a higher energy [1]. (c) The total area under the curve does not change, because the number of molecules is the same [1].', '[{"text": "Marking point 1", "any": ["origin", "starts at zero", "0 0", "zero"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["not touch", "never touch", "does not touch", "approaches", "asymptot", "never reaches", "without touching", "approach"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["lower", "flatter"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["right", "higher energy", "broader", "wider"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["area", "same number of molecules", "total number"], "all": [], "marks": 1}]'::jsonb, '(a) It starts at the origin [1], rises to a peak and then falls, approaching the x-axis without touching it [1]. (b) The peak becomes lower [1] and moves to the right, to a higher energy [1]. (c) The total area under the curve does not change, because the number of molecules is the same [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', '616921a0-6366-5116-bb13-21921cf9bf84', 19);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('2472ab71-78ed-59d0-bdf3-d779a72d0399', 'mcq', 'What is the effect of adding a catalyst?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('2472ab71-78ed-59d0-bdf3-d779a72d0399', 2, 'The activation energy is lower, so a greater proportion of molecules can react and the rate increases. ΔH, the position of equilibrium and the amount of catalyst are unchanged.', 'No change') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', '2472ab71-78ed-59d0-bdf3-d779a72d0399', 20);
