insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('f74bf1f7-44ae-5b14-a5e0-91d3487f6085', 2, 'The activation energy is lower, so a greater proportion of molecules can react and the rate increases. ΔH, the position of equilibrium and the amount of catalyst are unchanged.', 'No change') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
