insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a0521874-f368-52a4-94e5-5662891cc556', 'short', 'A reaction has an activation energy of +120 kJ mol⁻¹ and ΔH = −50 kJ mol⁻¹. With a catalyst the activation energy is +70 kJ mol⁻¹. Describe how the reaction pathway diagram changes when the catalyst is used, and what stays the same.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a0521874-f368-52a4-94e5-5662891cc556', 'The peak of the curve is lower: 70 instead of 120 kJ mol⁻¹ above the reactants [1]. The levels of the reactants and products are unchanged [1], so ΔH is still −50 kJ mol⁻¹ [1].', 'The peak of the curve is lower: 70 instead of 120 kJ mol⁻¹ above the reactants [1]. The levels of the reactants and products are unchanged [1], so ΔH is still −50 kJ mol⁻¹ [1].', '[{"text": "Marking point 1", "any": ["lower peak", "peak is lower", "lower hump", "lower maximum", "smaller barrier", "lower barrier", "70"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["reactants and products", "same level", "start and end", "unchanged", "same position", "same energies"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["50", "enthalpy change", "delta h", "h is the same"], "all": [], "marks": 1}]'::jsonb, 'The peak of the curve is lower: 70 instead of 120 kJ mol⁻¹ above the reactants [1]. The levels of the reactants and products are unchanged [1], so ΔH is still −50 kJ mol⁻¹ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', 'a0521874-f368-52a4-94e5-5662891cc556', 22);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('dbb2c647-3fdf-5e15-b424-3b10b7cc995e', 'mcq', 'Raising the temperature or adding a catalyst?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('dbb2c647-3fdf-5e15-b424-3b10b7cc995e', 0, 'Temperature changes the curve; a catalyst lowers the activation energy by providing a different mechanism. Both increase the proportion of molecules that can react, and so the rate.', 'Raising the temperature') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', 'dbb2c647-3fdf-5e15-b424-3b10b7cc995e', 23);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d4cdafe7-4c7c-5fc5-97b1-7577213eafe8', 'mcq', 'Raising the temperature or adding a catalyst?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('d4cdafe7-4c7c-5fc5-97b1-7577213eafe8', 2, 'Temperature changes the curve; a catalyst lowers the activation energy by providing a different mechanism. Both increase the proportion of molecules that can react, and so the rate.', 'Both') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', 'd4cdafe7-4c7c-5fc5-97b1-7577213eafe8', 24);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('756687c6-be4b-5a72-9ba8-372dfe286561', 'short', 'Explain, using the Boltzmann distribution, how a catalyst increases the rate of a reaction.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('756687c6-be4b-5a72-9ba8-372dfe286561', 'The catalysed route has a lower activation energy [1], so a greater proportion of the molecules have at least this energy [1], and effective collisions are more frequent [1].', 'The catalysed route has a lower activation energy [1], so a greater proportion of the molecules have at least this energy [1], and effective collisions are more frequent [1].', '[{"text": "Marking point 1", "any": ["lower activation energy", "activation energy is lower", "lowers the activation energy", "reduces the activation energy", "lower ea"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["more molecules", "greater proportion", "larger proportion", "more particles", "higher proportion"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["effective", "successful"], "all": [], "marks": 1}]'::jsonb, 'The catalysed route has a lower activation energy [1], so a greater proportion of the molecules have at least this energy [1], and effective collisions are more frequent [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', '756687c6-be4b-5a72-9ba8-372dfe286561', 25);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a1998250-a572-5027-8de9-cc68a58b3f1b', 'mcq', 'Is the catalyst homogeneous or heterogeneous?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a1998250-a572-5027-8de9-cc68a58b3f1b', 1, 'Solid catalysts with gaseous reactants are heterogeneous. A catalyst in the same phase as the reactants (aqueous H⁺ with aqueous reactants, a gas with gases) is homogeneous.', 'Heterogeneous') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
