insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('59ea6c64-ecbe-5392-816a-3a5ca9f0cc70', 'A homogeneous catalyst is in the same phase as the reactants [1]; a heterogeneous catalyst is in a different phase [1].', 'A homogeneous catalyst is in the same phase as the reactants [1]; a heterogeneous catalyst is in a different phase [1].', '[{"text": "Marking point 1", "any": ["same phase", "same state", "same physical state"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["different phase", "different state", "different physical state"], "all": [], "marks": 1}]'::jsonb, 'A homogeneous catalyst is in the same phase as the reactants [1]; a heterogeneous catalyst is in a different phase [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
