insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a3536844-f838-5cb3-8e60-df3754ed4120', 'short', 'Hydrogen peroxide decomposes slowly: 2H₂O₂ → 2H₂O + O₂. Solid manganese(IV) oxide catalyses the reaction. (a) State what is meant by a catalyst. (b) State whether manganese(IV) oxide is a homogeneous or a heterogeneous catalyst here, with a reason. (c) Explain how the catalyst increases the rate. (d) State the effect of the catalyst on ΔH.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a3536844-f838-5cb3-8e60-df3754ed4120', '(a) A substance that increases the rate of a reaction [1] and is chemically unchanged at the end [1]. (b) Heterogeneous: it is a solid and the reactant is in solution, a different phase [1]. (c) It provides a different mechanism [1] with a lower activation energy, so a greater proportion of molecules have enough energy to react [1]. (d) No effect: ΔH is unchanged [1].', '(a) A substance that increases the rate of a reaction [1] and is chemically unchanged at the end [1]. (b) Heterogeneous: it is a solid and the reactant is in solution, a different phase [1]. (c) It provides a different mechanism [1] with a lower activation energy, so a greater proportion of molecules have enough energy to react [1]. (d) No effect: ΔH is unchanged [1].', '[{"text": "Marking point 1", "any": ["increases the rate", "speeds up", "faster", "increase the rate"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["unchanged", "not used up", "regenerated", "remains", "not consumed"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["heterogeneous"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["different mechanism", "different route", "alternative", "different pathway", "another route"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["lower activation energy", "activation energy is lower", "lowers the activation energy", "lower ea", "reduces the activation energy"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["no effect", "no change", "unchanged", "same", "does not change", "not affected"], "all": [], "marks": 1}]'::jsonb, '(a) A substance that increases the rate of a reaction [1] and is chemically unchanged at the end [1]. (b) Heterogeneous: it is a solid and the reactant is in solution, a different phase [1]. (c) It provides a different mechanism [1] with a lower activation energy, so a greater proportion of molecules have enough energy to react [1]. (d) No effect: ΔH is unchanged [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4da103f2-d2c4-5114-a375-0d3d208c2106', 'a3536844-f838-5cb3-8e60-df3754ed4120', 30);
