insert into public.questions (id, kind, prompt, options, marks, image_url) values ('50168185-b9b5-5866-b84e-91203cb849b7', 'mcq', 'Which particle is larger?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('50168185-b9b5-5866-b84e-91203cb849b7', 0, 'Na > Cl (smaller nuclear charge). Na⁺ > Mg²⁺. P³⁻ > Al³⁺ (an extra shell). S²⁻ > Cl⁻ (fewer protons, same electrons). Na > Na⁺ (outer shell lost). Cl⁻ > Cl (extra repulsion).', 'Na') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '50168185-b9b5-5866-b84e-91203cb849b7', 3);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d452e6c5-6326-526a-8708-f51d4e38ef1c', 'short', 'Explain why the P³⁻ ion is much larger than the Al³⁺ ion.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Empirical_atomic_radius_trends.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d452e6c5-6326-526a-8708-f51d4e38ef1c', 'P³⁻ (2.8.8) has three occupied shells [1], while Al³⁺ (2.8) has lost its outer shell and has only two [1].', 'P³⁻ (2.8.8) has three occupied shells [1], while Al³⁺ (2.8) has lost its outer shell and has only two [1].', '[{"text": "Marking point 1", "any": ["extra shell", "more shells", "one more shell", "another shell", "three shells", "third shell", "more occupied", "three occupied", "3 shells", "3 occupied", "extra occupied"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["lost", "two shells", "second shell", "outer shell", "fewer shells", "only two"], "all": [], "marks": 1}]'::jsonb, 'P³⁻ (2.8.8) has three occupied shells [1], while Al³⁺ (2.8) has lost its outer shell and has only two [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', 'd452e6c5-6326-526a-8708-f51d4e38ef1c', 4);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('05eb5f15-075d-5de4-8e63-7c98abfb1f3f', 'mcq', 'What must be overcome or broken to melt the element?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('05eb5f15-075d-5de4-8e63-7c98abfb1f3f', 2, 'Metals: metallic bonding. Silicon: covalent bonds throughout the lattice. P₄, S₈ and Ar: only weak forces between molecules or atoms.', 'Weak intermolecular forces') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '05eb5f15-075d-5de4-8e63-7c98abfb1f3f', 5);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('7665df4f-60df-5d8a-a5f1-bdbc9365651a', 'short', 'Explain why the melting point increases from sodium to aluminium.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Silicon.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7665df4f-60df-5d8a-a5f1-bdbc9365651a', 'From Na to Al each atom gives more delocalised electrons [1], and the ions have a higher charge and a smaller radius [1], so the attraction between the ions and the delocalised electrons is stronger and more energy is needed [1].', 'From Na to Al each atom gives more delocalised electrons [1], and the ions have a higher charge and a smaller radius [1], so the attraction between the ions and the delocalised electrons is stronger and more energy is needed [1].', '[{"text": "Marking point 1", "any": ["more delocalised", "more electrons", "three delocalised", "3 delocalised", "number of delocalised"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["higher charge", "greater charge", "charge increases", "al3", "smaller"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["stronger metallic", "stronger attraction", "more energy", "stronger bonding"], "all": [], "marks": 1}]'::jsonb, 'From Na to Al each atom gives more delocalised electrons [1], and the ions have a higher charge and a smaller radius [1], so the attraction between the ions and the delocalised electrons is stronger and more energy is needed [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '7665df4f-60df-5d8a-a5f1-bdbc9365651a', 6);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6aef969a-cd91-5e23-9267-895265be90b8', 'mcq', 'Which element has the higher melting point?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('6aef969a-cd91-5e23-9267-895265be90b8', 6, 'Mg > Na; Si > Al; Si > P; S₈ > P₄ (more electrons per molecule); S > Cl; Cl₂ > Ar.', 'Cl') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '6aef969a-cd91-5e23-9267-895265be90b8', 7);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('43c0e560-037e-5a46-b2ed-20a7605cb503', 'short', '(a) State and explain the trend in atomic radius across Period 3. (b) Explain why silicon has the highest melting point in Period 3. (c) Explain why aluminium is a better electrical conductor than sodium, and why sulfur does not conduct.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('43c0e560-037e-5a46-b2ed-20a7605cb503', '(a) Atomic radius decreases [1] because the nuclear charge increases while the outer electrons are in the same shell with similar shielding [1]. (b) Silicon has a giant molecular structure [1]; many strong covalent bonds must be broken to melt it [1]. (c) Each aluminium atom gives three delocalised electrons and each sodium atom only one, so aluminium has more electrons to carry the charge [1]. Sulfur is made of S₈ molecules with no delocalised electrons [1].', '(a) Atomic radius decreases [1] because the nuclear charge increases while the outer electrons are in the same shell with similar shielding [1]. (b) Silicon has a giant molecular structure [1]; many strong covalent bonds must be broken to melt it [1]. (c) Each aluminium atom gives three delocalised electrons and each sodium atom only one, so aluminium has more electrons to carry the charge [1]. Sulfur is made of S₈ molecules with no delocalised electrons [1].', '[{"text": "Marking point 1", "any": ["decrease"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["nuclear charge", "more protons", "number of protons"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["giant"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["covalent bonds"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["more delocalised", "three delocalised", "3 delocalised", "more electrons"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["no delocalised", "no free electrons", "no mobile", "no charge carriers"], "all": [], "marks": 1}]'::jsonb, '(a) Atomic radius decreases [1] because the nuclear charge increases while the outer electrons are in the same shell with similar shielding [1]. (b) Silicon has a giant molecular structure [1]; many strong covalent bonds must be broken to melt it [1]. (c) Each aluminium atom gives three delocalised electrons and each sodium atom only one, so aluminium has more electrons to carry the charge [1]. Sulfur is made of S₈ molecules with no delocalised electrons [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '43c0e560-037e-5a46-b2ed-20a7605cb503', 8);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('dde1d970-5189-5b42-b46f-4df6e1306075', 'mcq', 'What is the formula of the oxide formed when the element burns in excess oxygen?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('dde1d970-5189-5b42-b46f-4df6e1306075', 6, 'Na₂O, MgO, Al₂O₃, SiO₂, P₄O₁₀ and SO₂.', 'SO₂') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', 'dde1d970-5189-5b42-b46f-4df6e1306075', 9);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('49963c93-2974-5d56-9740-5a5385a7c2dd', 'mcq', 'What is the formula of the chloride formed with excess chlorine?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('49963c93-2974-5d56-9740-5a5385a7c2dd', 1, 'NaCl, MgCl₂, Al₂Cl₆ (AlCl₃ units joined in pairs), SiCl₄ and PCl₅.', 'MgCl₂') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '49963c93-2974-5d56-9740-5a5385a7c2dd', 10);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ec5078ee-08d4-5fe3-95d5-d6217538a951', 'short', 'Write the equation for the reaction of aluminium with chlorine to form Al₂Cl₆, and state the oxidation number of aluminium in the product.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Phosphorus_pentachloride_ampoule.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ec5078ee-08d4-5fe3-95d5-d6217538a951', '2Al + 3Cl₂ → Al₂Cl₆ [1]. The oxidation number of aluminium is +3 [1].', '2Al + 3Cl₂ → Al₂Cl₆ [1]. The oxidation number of aluminium is +3 [1].', '[{"text": "Marking point 1", "any": ["2al 3cl2", "3cl2 2al"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["is 3", "of 3", "number 3", "plus 3", "three"], "all": [], "marks": 1}]'::jsonb, '2Al + 3Cl₂ → Al₂Cl₆ [1]. The oxidation number of aluminium is +3 [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', 'ec5078ee-08d4-5fe3-95d5-d6217538a951', 11);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('75b3b840-de37-5b2c-999a-802fdc6d5071', 'mcq', 'Choose the correct answer.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('75b3b840-de37-5b2c-999a-802fdc6d5071', 2, 'Na + cold water: NaOH and H₂, pH 13 to 14. Mg + cold water: Mg(OH)₂ and H₂, pH 9 to 10. Mg + steam: MgO and H₂.', 'MgO and H₂') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '75b3b840-de37-5b2c-999a-802fdc6d5071', 12);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('4add5c38-34ba-5f5a-a69a-061254ab25fc', 'mcq', 'What is the oxidation number of the Period 3 element?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('4add5c38-34ba-5f5a-a69a-061254ab25fc', 3, 'Na +1; Mg +2; Al +3; Si +4; P +5 in both P₄O₁₀ and PCl₅; S +4 in SO₂ and +6 in SO₃.', '+4') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '4add5c38-34ba-5f5a-a69a-061254ab25fc', 13);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5e9c1832-930d-5878-89ac-f2d33ab709bd', 'short', 'State and explain the pattern in the highest oxidation number of the elements in their oxides from sodium to sulfur.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5e9c1832-930d-5878-89ac-f2d33ab709bd', 'The highest oxidation number increases by one each time, from +1 in Na₂O to +6 in SO₃ [1]. It equals the number of outer-shell electrons of the element [1], because all of these electrons are used in bonding to oxygen [1].', 'The highest oxidation number increases by one each time, from +1 in Na₂O to +6 in SO₃ [1]. It equals the number of outer-shell electrons of the element [1], because all of these electrons are used in bonding to oxygen [1].', '[{"text": "Marking point 1", "any": ["increase", "rises", "goes up"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["outer", "valence", "group"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["all", "bonding", "lost", "shared", "used"], "all": [], "marks": 1}]'::jsonb, 'The highest oxidation number increases by one each time, from +1 in Na₂O to +6 in SO₃ [1]. It equals the number of outer-shell electrons of the element [1], because all of these electrons are used in bonding to oxygen [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '5e9c1832-930d-5878-89ac-f2d33ab709bd', 14);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('fa25e0df-3980-5a0f-8169-6f897b248247', 'mcq', 'What is the likely pH when the oxide is added to water?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('fa25e0df-3980-5a0f-8169-6f897b248247', 2, 'Na₂O 13 to 14; MgO 9 to 10; Al₂O₃ and SiO₂ no reaction, 7; P₄O₁₀ and SO₂ 1 to 2; SO₃ 0 to 1.', '7 (no reaction)') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', 'fa25e0df-3980-5a0f-8169-6f897b248247', 15);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('18b991a4-b54c-5b3b-b934-888c78db35da', 'mcq', 'What is formed when the oxide reacts with water?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('18b991a4-b54c-5b3b-b934-888c78db35da', 1, 'Na₂O gives NaOH; MgO gives Mg(OH)₂; P₄O₁₀ gives H₃PO₄; SO₂ gives H₂SO₃; SO₃ gives H₂SO₄.', 'Mg(OH)₂') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '18b991a4-b54c-5b3b-b934-888c78db35da', 16);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('7db53a6a-5e9a-5d5d-b889-e847d5a69379', 'mcq', 'Classify the oxide or hydroxide.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('7db53a6a-5e9a-5d5d-b889-e847d5a69379', 1, 'Na₂O and MgO are basic. Al₂O₃ and Al(OH)₃ are amphoteric. SiO₂, P₄O₁₀ and SO₃ are acidic.', 'Amphoteric') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '7db53a6a-5e9a-5d5d-b889-e847d5a69379', 17);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6b0acff9-d05f-5974-8817-e746db0e73ba', 'short', 'Explain what is meant by amphoteric, and describe how you could show that aluminium oxide is amphoteric.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aluminium_oxide2.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6b0acff9-d05f-5974-8817-e746db0e73ba', 'Amphoteric means reacting with both acids and bases [1]. Aluminium oxide dissolves in hydrochloric acid to form aluminium chloride [1] and also dissolves in aqueous sodium hydroxide to form sodium aluminate, NaAl(OH)₄ [1].', 'Amphoteric means reacting with both acids and bases [1]. Aluminium oxide dissolves in hydrochloric acid to form aluminium chloride [1] and also dissolves in aqueous sodium hydroxide to form sodium aluminate, NaAl(OH)₄ [1].', '[{"text": "Marking point 1", "any": ["both"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["acid", "hcl", "hydrochloric"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["alkali", "base", "naoh", "sodium hydroxide"], "all": [], "marks": 1}]'::jsonb, 'Amphoteric means reacting with both acids and bases [1]. Aluminium oxide dissolves in hydrochloric acid to form aluminium chloride [1] and also dissolves in aqueous sodium hydroxide to form sodium aluminate, NaAl(OH)₄ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '6b0acff9-d05f-5974-8817-e746db0e73ba', 18);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('2ef37318-9164-57c0-9709-bd8591d66c2b', 'mcq', 'What is the bonding and structure of the oxide?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('2ef37318-9164-57c0-9709-bd8591d66c2b', 0, 'Na₂O and MgO: giant ionic. SiO₂: giant molecular. P₄O₁₀, SO₂ and SO₃: simple molecular.', 'Giant ionic') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '2ef37318-9164-57c0-9709-bd8591d66c2b', 19);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('aafc57cc-1d41-55ca-bb17-6b7b57b9ef44', 'short', 'An oxide X of a Period 3 element is a white solid with a very high melting point. It does not dissolve in water, but it dissolves in both hydrochloric acid and aqueous sodium hydroxide. (a) Identify X. (b) Give the term used for this behaviour. (c) Give the formula of the aluminium-containing product in each reaction. (d) A different oxide, Y, is a white solid that reacts violently with water to give a solution of pH 1. Identify Y and name the acid formed.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('aafc57cc-1d41-55ca-bb17-6b7b57b9ef44', '(a) Aluminium oxide, Al₂O₃ [1]. (b) Amphoteric [1]. (c) With acid: AlCl₃ [1]; with alkali: NaAl(OH)₄, sodium aluminate [1]. (d) Y is P₄O₁₀, phosphorus(V) oxide [1], which forms phosphoric(V) acid, H₃PO₄ [1].', '(a) Aluminium oxide, Al₂O₃ [1]. (b) Amphoteric [1]. (c) With acid: AlCl₃ [1]; with alkali: NaAl(OH)₄, sodium aluminate [1]. (d) Y is P₄O₁₀, phosphorus(V) oxide [1], which forms phosphoric(V) acid, H₃PO₄ [1].', '[{"text": "Marking point 1", "any": ["aluminium oxide", "al2o3"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["amphoteric"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["alcl3", "aluminium chloride"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["naal oh 4", "naal(oh)4", "aluminate"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["p4o10", "phosphorus"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["phosphoric", "h3po4"], "all": [], "marks": 1}]'::jsonb, '(a) Aluminium oxide, Al₂O₃ [1]. (b) Amphoteric [1]. (c) With acid: AlCl₃ [1]; with alkali: NaAl(OH)₄, sodium aluminate [1]. (d) Y is P₄O₁₀, phosphorus(V) oxide [1], which forms phosphoric(V) acid, H₃PO₄ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', 'aafc57cc-1d41-55ca-bb17-6b7b57b9ef44', 20);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('7675c573-9da1-5206-bc74-6834a04f079b', 'mcq', 'Choose the correct answer.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('7675c573-9da1-5206-bc74-6834a04f079b', 1, 'NaCl dissolves to give a neutral solution. MgCl₂ dissolves to give a very slightly acidic solution, about pH 6.5.', 'Dissolves, pH about 6.5') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '7675c573-9da1-5206-bc74-6834a04f079b', 21);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6040d10f-ed0d-5fe5-bcf5-c456106297b9', 'short', 'Explain why aqueous sodium chloride is neutral.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6040d10f-ed0d-5fe5-bcf5-c456106297b9', 'Sodium chloride is ionic: it simply separates into hydrated Na⁺ and Cl⁻ ions [1]. Neither ion reacts with water, so no H⁺ or OH⁻ ions are produced [1].', 'Sodium chloride is ionic: it simply separates into hydrated Na⁺ and Cl⁻ ions [1]. Neither ion reacts with water, so no H⁺ or OH⁻ ions are produced [1].', '[{"text": "Marking point 1", "any": ["ionic", "ions"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["no reaction", "not react", "no hydrolysis", "not hydrolysed", "do not react", "does not react", "neither ion", "neither reacts", "neither of"], "all": [], "marks": 1}]'::jsonb, 'Sodium chloride is ionic: it simply separates into hydrated Na⁺ and Cl⁻ ions [1]. Neither ion reacts with water, so no H⁺ or OH⁻ ions are produced [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '6040d10f-ed0d-5fe5-bcf5-c456106297b9', 22);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('11a0518d-d0c8-5c83-b672-66ccef78367e', 'mcq', 'Use the properties to suggest the bonding in the chloride.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('11a0518d-d0c8-5c83-b672-66ccef78367e', 1, 'High melting points, conduction when molten and neutral solutions: ionic (NaCl, MgCl₂). Low melting or boiling points, fuming and acidic solutions: covalent (Al₂Cl₆, SiCl₄, PCl₅).', 'Covalent') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '11a0518d-d0c8-5c83-b672-66ccef78367e', 23);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('1d978bba-94a4-5efb-a3c9-36c4ee689712', 'short', 'Explain, in terms of electronegativity, why sodium chloride is ionic but silicon tetrachloride is covalent.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1d978bba-94a4-5efb-a3c9-36c4ee689712', 'There is a large difference in electronegativity between sodium and chlorine, so electrons are transferred [1]. Silicon is much closer to chlorine in electronegativity, so the difference is small and the electrons are shared [1].', 'There is a large difference in electronegativity between sodium and chlorine, so electrons are transferred [1]. Silicon is much closer to chlorine in electronegativity, so the difference is small and the electrons are shared [1].', '[{"text": "Marking point 1", "any": ["large difference", "big difference", "greater difference", "much less electronegative", "larger difference", "difference is large"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["small difference", "smaller difference", "similar", "closer", "difference is small", "less difference"], "all": [], "marks": 1}]'::jsonb, 'There is a large difference in electronegativity between sodium and chlorine, so electrons are transferred [1]. Silicon is much closer to chlorine in electronegativity, so the difference is small and the electrons are shared [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '1d978bba-94a4-5efb-a3c9-36c4ee689712', 24);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('b7961800-9b50-501c-bbc7-686b3b1ab396', 'short', 'Chloride A is a white solid that melts at 714 °C and dissolves in water to give a solution of pH 6.5. Chloride B is a pale yellow solid that reacts violently with water, giving steamy fumes and a solution of pH 1. (a) Identify A and B. (b) Suggest the type of bonding in each. (c) Write the equation for the reaction of B with water. (d) Identify the steamy fumes.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b7961800-9b50-501c-bbc7-686b3b1ab396', '(a) A is magnesium chloride, MgCl₂ [1]; B is phosphorus(V) chloride, PCl₅ [1]. (b) A is ionic [1]; B is covalent [1]. (c) PCl₅ + 4H₂O → H₃PO₄ + 5HCl [1]. (d) Hydrogen chloride [1].', '(a) A is magnesium chloride, MgCl₂ [1]; B is phosphorus(V) chloride, PCl₅ [1]. (b) A is ionic [1]; B is covalent [1]. (c) PCl₅ + 4H₂O → H₃PO₄ + 5HCl [1]. (d) Hydrogen chloride [1].', '[{"text": "Marking point 1", "any": ["mgcl2", "magnesium chloride"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["pcl5", "phosphorus"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["ionic"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["covalent"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["pcl5 4h2o", "4h2o pcl5"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["hydrogen chloride", "hcl"], "all": [], "marks": 1}]'::jsonb, '(a) A is magnesium chloride, MgCl₂ [1]; B is phosphorus(V) chloride, PCl₅ [1]. (b) A is ionic [1]; B is covalent [1]. (c) PCl₅ + 4H₂O → H₃PO₄ + 5HCl [1]. (d) Hydrogen chloride [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', 'b7961800-9b50-501c-bbc7-686b3b1ab396', 25);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ba312b0e-3132-5e5a-b547-e4bec5ad3bd2', 'mcq', 'Predict the formula.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('ba312b0e-3132-5e5a-b547-e4bec5ad3bd2', 5, 'RbCl (like NaCl), SrO (like MgO), GeCl₄ (like SiCl₄), H₂Se (like H₂S), NaAt (like NaCl).', 'H₂Se') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', 'ba312b0e-3132-5e5a-b547-e4bec5ad3bd2', 26);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('61a08d8a-e7ed-5dfe-962f-675458ed3563', 'mcq', 'Predict the behaviour.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('61a08d8a-e7ed-5dfe-962f-675458ed3563', 5, 'Rubidium is more reactive than sodium. SrO is a basic metal oxide. SeO₃ is an acidic non-metal oxide, like SO₃. GeCl₄ is covalent and hydrolysed, like SiCl₄. RbCl is ionic and simply dissolves.', 'Dissolves, giving a neutral solution') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '61a08d8a-e7ed-5dfe-962f-675458ed3563', 27);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('72985935-2b42-5453-b511-6ace4047341d', 'mcq', 'In which group is the element most likely to be?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('72985935-2b42-5453-b511-6ace4047341d', 5, 'MCl and violent reaction with water: Group 1. Basic MO: Group 2. Amphoteric M₂O₃: Group 13. Giant molecular with XO₂: Group 14. Acidic XO₂ and XO₃: Group 16. X₂ molecules forming X⁻: Group 17.', 'Group 17') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '72985935-2b42-5453-b511-6ace4047341d', 28);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e87c977c-4531-5cde-893b-83df1fe90ed4', 'short', 'Element R is in Period 3. Its successive ionisation energies show the first large jump after the fifth electron. Its chloride reacts violently with water. Identify R and predict the formula of its highest oxide.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e87c977c-4531-5cde-893b-83df1fe90ed4', 'Five outer electrons, so R is in Group 15: phosphorus [1]. Its highest oxide is P₄O₁₀ [1].', 'Five outer electrons, so R is in Group 15: phosphorus [1]. Its highest oxide is P₄O₁₀ [1].', '[{"text": "Marking point 1", "any": ["phosphorus"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["p4o10", "p2o5"], "all": [], "marks": 1}]'::jsonb, 'Five outer electrons, so R is in Group 15: phosphorus [1]. Its highest oxide is P₄O₁₀ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', 'e87c977c-4531-5cde-893b-83df1fe90ed4', 29);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('70feabe8-e1cd-55c7-b46d-96f871cd4248', 'short', 'Gallium, Ga, is below aluminium in Group 13. (a) Predict the formula of gallium oxide and of gallium chloride. (b) Predict whether gallium oxide is basic, amphoteric or acidic, and give your reason. (c) Predict what you would observe when gallium chloride is added to water, and the approximate pH. (d) Predict whether gallium conducts electricity, with a reason.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('70feabe8-e1cd-55c7-b46d-96f871cd4248', '(a) Ga₂O₃ [1] and GaCl₃ (or Ga₂Cl₆) [1]. (b) Amphoteric, like aluminium oxide, the oxide of the element above it [1]. (c) It reacts with water (is hydrolysed), giving steamy fumes [1] and an acidic solution, about pH 3 [1]. (d) It conducts, because it is a metal with delocalised electrons [1].', '(a) Ga₂O₃ [1] and GaCl₃ (or Ga₂Cl₆) [1]. (b) Amphoteric, like aluminium oxide, the oxide of the element above it [1]. (c) It reacts with water (is hydrolysed), giving steamy fumes [1] and an acidic solution, about pH 3 [1]. (d) It conducts, because it is a metal with delocalised electrons [1].', '[{"text": "Marking point 1", "any": ["ga2o3"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["gacl3", "ga2cl6"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["amphoteric"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["fumes", "hydrolys", "reacts", "steamy"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["acidic", "ph 3", "ph 2", "ph 1", "below 7", "less than 7"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["metal", "delocalised"], "all": [], "marks": 1}]'::jsonb, '(a) Ga₂O₃ [1] and GaCl₃ (or Ga₂Cl₆) [1]. (b) Amphoteric, like aluminium oxide, the oxide of the element above it [1]. (c) It reacts with water (is hydrolysed), giving steamy fumes [1] and an acidic solution, about pH 3 [1]. (d) It conducts, because it is a metal with delocalised electrons [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('cd11d451-33bf-5ed2-9bd5-f8e65eed10ba', '70feabe8-e1cd-55c7-b46d-96f871cd4248', 30);
