insert into public.questions (id, kind, prompt, options, marks, image_url) values ('64a28fd7-6ac8-5f99-8970-f6b2a0884cea', 'short', 'Write the equation for the burning of calcium in oxygen and state the change in oxidation number of calcium.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Flammenf%C3%A4rbungCa.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('64a28fd7-6ac8-5f99-8970-f6b2a0884cea', '2Ca + O₂ → 2CaO [1]. The oxidation number of calcium changes from 0 to +2 [1].', '2Ca + O₂ → 2CaO [1]. The oxidation number of calcium changes from 0 to +2 [1].', '[{"text": "Marking point 1", "any": ["2ca o2", "o2 2ca"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["0 to 2", "0 to plus 2", "zero to", "from 0"], "all": [], "marks": 1}]'::jsonb, '2Ca + O₂ → 2CaO [1]. The oxidation number of calcium changes from 0 to +2 [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('fefb7727-def0-51e5-82e6-ba723b207c7a', '64a28fd7-6ac8-5f99-8970-f6b2a0884cea', 5);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e49bdd54-123d-53e0-bb06-ad6fa3550217', 'mcq', 'What are the products?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('e49bdd54-123d-53e0-bb06-ad6fa3550217', 0, 'Steam gives MgO and H₂. Cold water gives the hydroxide and hydrogen: Mg(OH)₂, Ca(OH)₂ or Ba(OH)₂.', 'MgO and H₂') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('fefb7727-def0-51e5-82e6-ba723b207c7a', 'e49bdd54-123d-53e0-bb06-ad6fa3550217', 6);
