insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ced00da5-6170-521b-8aa7-4a47319d8349', 'short', 'Describe what you would see when a small piece of calcium is added to cold water, and write the equation.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Calcium_hydroxide.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ced00da5-6170-521b-8aa7-4a47319d8349', 'The calcium fizzes steadily as bubbles of hydrogen form [1], and the water turns cloudy white as calcium hydroxide forms [1]. Ca + 2H₂O → Ca(OH)₂ + H₂ [1].', 'The calcium fizzes steadily as bubbles of hydrogen form [1], and the water turns cloudy white as calcium hydroxide forms [1]. Ca + 2H₂O → Ca(OH)₂ + H₂ [1].', '[{"text": "Marking point 1", "any": ["fizz", "bubbl", "efferves", "gas"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["white", "cloudy", "milky", "disappears", "dissolves", "gets smaller", "sinks", "warm", "heat"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["ca 2h2o", "2h2o ca"], "all": [], "marks": 1}]'::jsonb, 'The calcium fizzes steadily as bubbles of hydrogen form [1], and the water turns cloudy white as calcium hydroxide forms [1]. Ca + 2H₂O → Ca(OH)₂ + H₂ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('fefb7727-def0-51e5-82e6-ba723b207c7a', 'ced00da5-6170-521b-8aa7-4a47319d8349', 9);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6c7671fe-af6c-59ed-b406-4468b39191b6', 'mcq', 'What happens?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('6c7671fe-af6c-59ed-b406-4468b39191b6', 0, 'All the chlorides and magnesium sulfate are soluble, so those reactions go to completion. Strontium and barium sulfates are insoluble and coat the metal.', 'Rapid fizzing; the metal dissolves completely') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('fefb7727-def0-51e5-82e6-ba723b207c7a', '6c7671fe-af6c-59ed-b406-4468b39191b6', 10);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('9f2d9317-87a9-5642-9d08-ead8c7dc8362', 'mcq', 'What happens?
