insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d91f6365-a435-50ab-a30e-2f68466e8d27', 'short', 'Explain why barium reacts rapidly with dilute hydrochloric acid, but its reaction with dilute sulfuric acid soon stops.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d91f6365-a435-50ab-a30e-2f68466e8d27', 'Barium chloride is soluble, but barium sulfate is insoluble [1]. The barium sulfate forms a layer on the surface of the metal that stops the acid reaching it [1].', 'Barium chloride is soluble, but barium sulfate is insoluble [1]. The barium sulfate forms a layer on the surface of the metal that stops the acid reaching it [1].', '[{"text": "Marking point 1", "any": ["insoluble"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["layer", "coat", "cover", "barrier", "surface", "prevents", "stops the acid"], "all": [], "marks": 1}]'::jsonb, 'Barium chloride is soluble, but barium sulfate is insoluble [1]. The barium sulfate forms a layer on the surface of the metal that stops the acid reaching it [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('fefb7727-def0-51e5-82e6-ba723b207c7a', 'd91f6365-a435-50ab-a30e-2f68466e8d27', 14);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6b0351dd-ca89-58b4-ba87-d9b85b4bbc5b', 'short', '(a) State the trend in reactivity of the Group 2 metals with water from magnesium to barium. (b) Explain the trend. (c) Predict how radium, the element below barium, reacts with cold water, and give the formula of the radium-containing product.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6b0351dd-ca89-58b4-ba87-d9b85b4bbc5b', '(a) Reactivity increases down the group [1]. (b) The atomic radius increases [1] and there is more shielding by inner shells [1], so the ionisation energies decrease and the two outer electrons are lost more easily [1]. (c) Radium reacts very vigorously, faster than barium [1], forming Ra(OH)₂ and hydrogen [1].', '(a) Reactivity increases down the group [1]. (b) The atomic radius increases [1] and there is more shielding by inner shells [1], so the ionisation energies decrease and the two outer electrons are lost more easily [1]. (c) Radium reacts very vigorously, faster than barium [1], forming Ra(OH)₂ and hydrogen [1].', '[{"text": "Marking point 1", "any": ["increase", "more reactive", "more vigorous"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["radius", "larger atom", "bigger atom", "more shells", "further from"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["shielding", "shielded", "screening"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["ionisation energ", "weaker attraction", "less attraction", "lost more easily", "lose electrons more easily", "easier to lose", "less energy"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["very vigorous", "violent", "more vigorous", "faster", "rapid", "explosive"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["ra oh 2"], "all": [], "marks": 1}]'::jsonb, '(a) Reactivity increases down the group [1]. (b) The atomic radius increases [1] and there is more shielding by inner shells [1], so the ionisation energies decrease and the two outer electrons are lost more easily [1]. (c) Radium reacts very vigorously, faster than barium [1], forming Ra(OH)₂ and hydrogen [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('fefb7727-def0-51e5-82e6-ba723b207c7a', '6b0351dd-ca89-58b4-ba87-d9b85b4bbc5b', 15);
