insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6d66cb9a-5cb2-5a2c-87e3-401dcb23a683', 'Barium hydroxide is much more soluble than magnesium hydroxide [1], so the solution contains a much higher concentration of hydroxide ions [1].', 'Barium hydroxide is much more soluble than magnesium hydroxide [1], so the solution contains a much higher concentration of hydroxide ions [1].', '[{"text": "Marking point 1", "any": ["more soluble", "solubility increases", "less soluble", "insoluble", "sparingly"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["hydroxide ions", "oh", "higher concentration", "more alkaline"], "all": [], "marks": 1}]'::jsonb, 'Barium hydroxide is much more soluble than magnesium hydroxide [1], so the solution contains a much higher concentration of hydroxide ions [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
