insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e1e5d011-5e08-5ac1-b0fb-11d0e64982be', 'SrCO₃ + 2HCl → SrCl₂ + CO₂ + H₂O [1].', 'SrCO₃ + 2HCl → SrCl₂ + CO₂ + H₂O [1].', '[{"text": "Marking point 1", "any": ["srco3 2hcl", "2hcl srco3"], "all": [], "marks": 1}]'::jsonb, 'SrCO₃ + 2HCl → SrCl₂ + CO₂ + H₂O [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
