insert into public.questions (id, kind, prompt, options, marks, image_url) values ('378295b4-9103-515e-bf0e-4bab48f718db', 'short', 'Write the equation for the thermal decomposition of magnesium nitrate, and describe one observation.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('378295b4-9103-515e-bf0e-4bab48f718db', '2Mg(NO₃)₂ → 2MgO [1] + 4NO₂ + O₂ [1]. A brown gas, nitrogen dioxide, is given off [1].', '2Mg(NO₃)₂ → 2MgO [1] + 4NO₂ + O₂ [1]. A brown gas, nitrogen dioxide, is given off [1].', '[{"text": "Marking point 1", "any": ["2mgo"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["4no2"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["brown"], "all": [], "marks": 1}]'::jsonb, '2Mg(NO₃)₂ → 2MgO [1] + 4NO₂ + O₂ [1]. A brown gas, nitrogen dioxide, is given off [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('fefb7727-def0-51e5-82e6-ba723b207c7a', '378295b4-9103-515e-bf0e-4bab48f718db', 29);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('670aaa90-4947-5ab0-ba72-501b88fc24d5', 'short', '(a) State the trend in solubility of the Group 2 hydroxides and of the Group 2 sulfates down the group. (b) Aqueous barium chloride is added to dilute sulfuric acid. State what is seen and give the formula of the solid. (c) Predict whether radium carbonate decomposes at a higher or lower temperature than barium carbonate, and write the equation for the decomposition of calcium carbonate.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('670aaa90-4947-5ab0-ba72-501b88fc24d5', '(a) The solubility of the hydroxides increases down the group [1]; the solubility of the sulfates decreases [1]. (b) A white precipitate forms [1] of BaSO₄ [1]. (c) Higher, because thermal stability increases down the group [1]. CaCO₃ → CaO + CO₂ [1].', '(a) The solubility of the hydroxides increases down the group [1]; the solubility of the sulfates decreases [1]. (b) A white precipitate forms [1] of BaSO₄ [1]. (c) Higher, because thermal stability increases down the group [1]. CaCO₃ → CaO + CO₂ [1].', '[{"text": "Marking point 1", "any": ["hydroxides increase", "hydroxides become more", "hydroxides get more", "hydroxide increases", "hydroxides more soluble", "hydroxides: increase", "solubility of the hydroxides increases"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["sulfates decrease", "sulfates become less", "sulfates get less", "sulfate decreases", "sulfates less soluble", "solubility of the sulfates decreases"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["white precipitate", "white solid", "white ppt"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["baso4"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["higher"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["caco3 cao", "cao co2"], "all": [], "marks": 1}]'::jsonb, '(a) The solubility of the hydroxides increases down the group [1]; the solubility of the sulfates decreases [1]. (b) A white precipitate forms [1] of BaSO₄ [1]. (c) Higher, because thermal stability increases down the group [1]. CaCO₃ → CaO + CO₂ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('fefb7727-def0-51e5-82e6-ba723b207c7a', '670aaa90-4947-5ab0-ba72-501b88fc24d5', 30);
