insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5ad54713-a9c1-5e00-805c-204f3f312f5d', 'mcq', 'Match the description to the halogen.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('5ad54713-a9c1-5e00-805c-204f3f312f5d', 0, 'Chlorine: pale green gas. Bromine: red-brown liquid, orange in solution. Iodine: grey-black solid, purple vapour, brown in solution.', 'Chlorine') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', '5ad54713-a9c1-5e00-805c-204f3f312f5d', 1);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a2aac944-abf9-5079-b631-31cc2fb6b82a', 'mcq', 'Match the description to the halogen.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a2aac944-abf9-5079-b631-31cc2fb6b82a', 1, 'Chlorine: pale green gas. Bromine: red-brown liquid, orange in solution. Iodine: grey-black solid, purple vapour, brown in solution.', 'Bromine') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', 'a2aac944-abf9-5079-b631-31cc2fb6b82a', 2);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('71ce8685-8e4c-5b05-9288-05034af47a41', 'mcq', 'Choose the correct answer.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('71ce8685-8e4c-5b05-9288-05034af47a41', 3, 'Chlorine is the most volatile, iodine the least. Iodine has the most electrons per molecule. Boiling overcomes forces between molecules; splitting into atoms breaks the covalent bond.', 'Forces between molecules') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', '71ce8685-8e4c-5b05-9288-05034af47a41', 3);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a07d7e1b-d3db-5ded-b131-4390fd109438', 'short', 'Explain why iodine is less volatile than chlorine.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Iodine-sample.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a07d7e1b-d3db-5ded-b131-4390fd109438', 'An iodine molecule has more electrons than a chlorine molecule [1], so the instantaneous dipole–induced dipole forces between iodine molecules [1] are stronger and need more energy to overcome [1].', 'An iodine molecule has more electrons than a chlorine molecule [1], so the instantaneous dipole–induced dipole forces between iodine molecules [1] are stronger and need more energy to overcome [1].', '[{"text": "Marking point 1", "any": ["more electrons"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["instantaneous", "induced dipole", "id-id", "london", "dispersion", "van der waals", "intermolecular"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["stronger", "more energy"], "all": [], "marks": 1}]'::jsonb, 'An iodine molecule has more electrons than a chlorine molecule [1], so the instantaneous dipole–induced dipole forces between iodine molecules [1] are stronger and need more energy to overcome [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', 'a07d7e1b-d3db-5ded-b131-4390fd109438', 4);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('441026ed-dc36-5727-b0d4-0142ca1afac4', 'mcq', 'Which has the larger value?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('441026ed-dc36-5727-b0d4-0142ca1afac4', 2, 'Bond energy: Cl₂ > Br₂ > I₂. Bond length: I₂ is longest. Boiling point and intermolecular forces: I₂ > Br₂ > Cl₂.', 'I₂') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', '441026ed-dc36-5727-b0d4-0142ca1afac4', 5);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('2a9ef0f6-e54b-5eaf-9611-f3a4185452f8', 'short', 'Astatine, At, is below iodine in Group 17. (a) Predict the state and appearance of astatine at room temperature. (b) Predict whether astatine is more or less volatile than iodine, and explain your answer. (c) Predict how the At–At bond energy compares with the I–I bond energy, and explain your answer.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2a9ef0f6-e54b-5eaf-9611-f3a4185452f8', '(a) A solid [1], black or very dark [1]. (b) Less volatile than iodine [1], because an At₂ molecule has more electrons, so the instantaneous dipole–induced dipole forces are stronger [1]. (c) The At–At bond is weaker [1], because the atoms are larger, so the bonding pair is further from the nuclei and more shielded [1].', '(a) A solid [1], black or very dark [1]. (b) Less volatile than iodine [1], because an At₂ molecule has more electrons, so the instantaneous dipole–induced dipole forces are stronger [1]. (c) The At–At bond is weaker [1], because the atoms are larger, so the bonding pair is further from the nuclei and more shielded [1].', '[{"text": "Marking point 1", "any": ["solid"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["black", "dark", "darker"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["less volatile", "lower volatility", "higher boiling"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["more electrons"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["weaker", "lower", "smaller", "less than"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["larger", "bigger", "further", "shield"], "all": [], "marks": 1}]'::jsonb, '(a) A solid [1], black or very dark [1]. (b) Less volatile than iodine [1], because an At₂ molecule has more electrons, so the instantaneous dipole–induced dipole forces are stronger [1]. (c) The At–At bond is weaker [1], because the atoms are larger, so the bonding pair is further from the nuclei and more shielded [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', '2a9ef0f6-e54b-5eaf-9611-f3a4185452f8', 6);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5e782163-9bf1-517e-883b-88c51220b60e', 'mcq', 'What is observed when the solutions are mixed?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('5e782163-9bf1-517e-883b-88c51220b60e', 1, 'Chlorine displaces bromine (orange) and iodine (brown). Bromine displaces iodine (brown). Bromine cannot displace chlorine, and iodine displaces neither.', 'Turns brown') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', '5e782163-9bf1-517e-883b-88c51220b60e', 7);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8c7914ed-70ec-5c65-8351-d9fc22a04de7', 'short', 'Write the ionic equation for the reaction of chlorine with bromide ions, and explain why chlorine is a stronger oxidising agent than bromine. Type the equation like this: Cl2 + …', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('8c7914ed-70ec-5c65-8351-d9fc22a04de7', 'Cl₂ + 2Br⁻ → 2Cl⁻ + Br₂ [1]. A chlorine atom is smaller than a bromine atom [1] and its outer shell has less shielding [1], so its nucleus attracts an extra electron more strongly [1].', 'Cl₂ + 2Br⁻ → 2Cl⁻ + Br₂ [1]. A chlorine atom is smaller than a bromine atom [1] and its outer shell has less shielding [1], so its nucleus attracts an extra electron more strongly [1].', '[{"text": "Marking point 1", "any": ["cl2 2br", "2br cl2"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["smaller"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["shielding", "shielded", "fewer shells", "closer to the nucleus", "nearer"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["attract", "gain"], "all": [], "marks": 1}]'::jsonb, 'Cl₂ + 2Br⁻ → 2Cl⁻ + Br₂ [1]. A chlorine atom is smaller than a bromine atom [1] and its outer shell has less shielding [1], so its nucleus attracts an extra electron more strongly [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', '8c7914ed-70ec-5c65-8351-d9fc22a04de7', 8);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('4163fae0-d5be-5961-a52c-9039dab0a6b5', 'mcq', 'Which halogen reacts with hydrogen in this way?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('4163fae0-d5be-5961-a52c-9039dab0a6b5', 0, 'Chlorine explodes in sunlight and forms the strongest H–X bond. Bromine needs heat and a catalyst. Iodine reacts slowly and reversibly and forms the weakest H–X bond.', 'Chlorine') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', '4163fae0-d5be-5961-a52c-9039dab0a6b5', 9);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6aa4bab8-081e-5011-afd1-f83874d01b0f', 'mcq', 'Choose the correct answer.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('6aa4bab8-081e-5011-afd1-f83874d01b0f', 0, 'HCl is the most stable and does not change with a hot wire. HI has the longest, weakest bond, is the least stable and gives purple iodine vapour.', 'HCl') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', '6aa4bab8-081e-5011-afd1-f83874d01b0f', 10);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8351176e-3536-5737-a2da-995dbbbd4465', 'mcq', 'Choose the correct answer.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('8351176e-3536-5737-a2da-995dbbbd4465', 2, 'HCl is the most stable and does not change with a hot wire. HI has the longest, weakest bond, is the least stable and gives purple iodine vapour.', 'HI') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', '8351176e-3536-5737-a2da-995dbbbd4465', 11);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6e87ecfb-9d57-5c5f-8f7a-365135601419', 'short', 'Explain why hydrogen iodide decomposes much more easily than hydrogen chloride when heated.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6e87ecfb-9d57-5c5f-8f7a-365135601419', 'An iodine atom is larger than a chlorine atom, so the H–I bond is longer [1] and weaker (299 compared with 431 kJ mol⁻¹) [1]. Less energy is needed to break it [1].', 'An iodine atom is larger than a chlorine atom, so the H–I bond is longer [1] and weaker (299 compared with 431 kJ mol⁻¹) [1]. Less energy is needed to break it [1].', '[{"text": "Marking point 1", "any": ["larger", "bigger", "longer"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["weaker", "lower bond energy", "smaller bond energy", "299"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["less energy", "easier to break", "more easily broken", "breaks more easily"], "all": [], "marks": 1}]'::jsonb, 'An iodine atom is larger than a chlorine atom, so the H–I bond is longer [1] and weaker (299 compared with 431 kJ mol⁻¹) [1]. Less energy is needed to break it [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', '6e87ecfb-9d57-5c5f-8f7a-365135601419', 12);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('cc0f9ba0-28ac-5974-89b8-e7ccc3cfe134', 'short', 'Bromine water is added to aqueous potassium iodide. (a) State what is seen. (b) Write the ionic equation.(d) State and explain what happens when bromine water is added to aqueous potassium chloride.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cc0f9ba0-28ac-5974-89b8-e7ccc3cfe134', '(a) The solution turns brown [1]. (b) Br₂ + 2I⁻ → 2Br⁻ + I₂ [1]. (c) Bromine is the oxidising agent [1]; iodide ions are oxidised [1]. (d) No reaction [1], because bromine is a weaker oxidising agent than chlorine, so it cannot oxidise chloride ions [1].', '(a) The solution turns brown [1]. (b) Br₂ + 2I⁻ → 2Br⁻ + I₂ [1]. (c) Bromine is the oxidising agent [1]; iodide ions are oxidised [1]. (d) No reaction [1], because bromine is a weaker oxidising agent than chlorine, so it cannot oxidise chloride ions [1].', '[{"text": "Marking point 1", "any": ["brown"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["br2 2i", "2i br2"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["bromine is the oxidising", "oxidising agent is bromine", "oxidising agent: bromine", "br2 is the oxidising", "oxidising agent is br2", "bromine oxidises"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["iodide"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["no reaction", "nothing", "no change", "does not react"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["weaker oxidising", "less reactive", "less oxidising", "cannot oxidise", "not strong enough", "chlorine is a stronger", "chlorine is more reactive"], "all": [], "marks": 1}]'::jsonb, '(a) The solution turns brown [1]. (b) Br₂ + 2I⁻ → 2Br⁻ + I₂ [1]. (c) Bromine is the oxidising agent [1]; iodide ions are oxidised [1]. (d) No reaction [1], because bromine is a weaker oxidising agent than chlorine, so it cannot oxidise chloride ions [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', 'cc0f9ba0-28ac-5974-89b8-e7ccc3cfe134', 13);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('7b42c2a2-03a2-5cb6-b8c4-f22436bf3751', 'mcq', 'Choose the correct answer.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('7b42c2a2-03a2-5cb6-b8c4-f22436bf3751', 1, 'Iodide is the largest ion and the strongest reducing agent. Chloride is the weakest. Bromide reduces chlorine only.', 'Bromide') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', '7b42c2a2-03a2-5cb6-b8c4-f22436bf3751', 14);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f86f27d6-7ad6-556b-abef-0a4b7d672f08', 'mcq', 'What is seen when acidified aqueous silver nitrate is added?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('f86f27d6-7ad6-556b-abef-0a4b7d672f08', 3, 'Chloride: white. Bromide: cream. Iodide: yellow. Nitrate ions give no precipitate.', 'No precipitate') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', 'f86f27d6-7ad6-556b-abef-0a4b7d672f08', 15);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('cd873eaf-4ab0-52a9-b91c-e13ad4ed5aae', 'short', 'Write the ionic equation, with state symbols, for the reaction of aqueous silver nitrate with aqueous sodium bromide, and explain why dilute nitric acid is added first. Type the equation like this: Ag+(aq) + …', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Silver_chloride_%28AgCl%29.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cd873eaf-4ab0-52a9-b91c-e13ad4ed5aae', 'Ag⁺(aq) + Br⁻(aq) [1] → AgBr(s) [1]. Nitric acid removes ions such as carbonate, which would also give a precipitate with silver ions [1].', 'Ag⁺(aq) + Br⁻(aq) [1] → AgBr(s) [1]. Nitric acid removes ions such as carbonate, which would also give a precipitate with silver ions [1].', '[{"text": "Marking point 1", "any": ["ag aq br aq", "br aq ag aq"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["agbr s"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["carbonate", "other ions", "interfer", "false", "hydroxide", "impurit"], "all": [], "marks": 1}]'::jsonb, 'Ag⁺(aq) + Br⁻(aq) [1] → AgBr(s) [1]. Nitric acid removes ions such as carbonate, which would also give a precipitate with silver ions [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', 'cd873eaf-4ab0-52a9-b91c-e13ad4ed5aae', 16);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('0ee0fa98-3ddf-5f72-b400-a1d7fdd2968a', 'mcq', 'What happens to the precipitate?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('0ee0fa98-3ddf-5f72-b400-a1d7fdd2968a', 1, 'AgCl dissolves in dilute ammonia. AgBr dissolves only in concentrated ammonia. AgI dissolves in neither.', 'Does not dissolve') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', '0ee0fa98-3ddf-5f72-b400-a1d7fdd2968a', 17);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('bf44c017-ca22-50ee-b5eb-d507926d788c', 'short', 'Explain why silver chloride dissolves in aqueous ammonia, and give the formula of the silver-containing ion formed.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('bf44c017-ca22-50ee-b5eb-d507926d788c', 'Ammonia reacts with the silver ions to form a soluble complex ion [1], [Ag(NH₃)₂]⁺ [1].', 'Ammonia reacts with the silver ions to form a soluble complex ion [1], [Ag(NH₃)₂]⁺ [1].', '[{"text": "Marking point 1", "any": ["complex", "soluble ion"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ag nh3 2"], "all": [], "marks": 1}]'::jsonb, 'Ammonia reacts with the silver ions to form a soluble complex ion [1], [Ag(NH₃)₂]⁺ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('ef1034af-371a-523b-87fa-05aa6571575e', 'bf44c017-ca22-50ee-b5eb-d507926d788c', 18);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('b97f9e37-b958-581b-aea1-99ee5cf3f5e9', 'short', 'Write the equation for the reaction of solid sodium chloride with concentrated sulfuric acid, and explain why no chlorine is formed. Type the equation like this: NaCl + …', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sodium-chloride-3D-ionic.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b97f9e37-b958-581b-aea1-99ee5cf3f5e9', 'NaCl + H₂SO₄ → NaHSO₄ + HCl [1]. Chloride ions are too weak as reducing agents to reduce sulfuric acid, so they are not oxidised to chlorine [1].', 'NaCl + H₂SO₄ → NaHSO₄ + HCl [1]. Chloride ions are too weak as reducing agents to reduce sulfuric acid, so they are not oxidised to chlorine [1].', '[{"text": "Marking point 1", "any": ["nacl h2so4", "h2so4 nacl"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["weak reducing", "not strong enough", "too weak", "cannot reduce", "weakest reducing", "not a strong enough", "poor reducing", "not oxidised", "cannot be oxidised"], "all": [], "marks": 1}]'::jsonb, 'NaCl + H₂SO₄ → NaHSO₄ + HCl [1]. Chloride ions are too weak as reducing agents to reduce sulfuric acid, so they are not oxidised to chlorine [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
