insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c48117f7-5c17-51ad-a3d3-8d58ff79101b', 'short', 'Write the equation for the reaction in which hydrogen bromide reduces concentrated sulfuric acid, and identify the reducing agent. Type the equation like this: 2HBr + …', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bromine_vial_in_acrylic_cube.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c48117f7-5c17-51ad-a3d3-8d58ff79101b', '2HBr + H₂SO₄ → Br₂ + SO₂ + 2H₂O [1]. The reducing agent is HBr (the bromide ion) [1].', '2HBr + H₂SO₄ → Br₂ + SO₂ + 2H₂O [1]. The reducing agent is HBr (the bromide ion) [1].', '[{"text": "Marking point 1", "any": ["2hbr h2so4", "h2so4 2hbr"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["hbr is the reducing", "bromide", "reducing agent is hbr", "hydrogen bromide is the reducing", "reducing agent is hydrogen bromide", "reducing agent: hbr"], "all": [], "marks": 1}]'::jsonb, '2HBr + H₂SO₄ → Br₂ + SO₂ + 2H₂O [1]. The reducing agent is HBr (the bromide ion) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
