insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3b065970-7508-5867-9b62-d6bcec33b37f', 'short', 'Write the equation for the reaction of chlorine with cold aqueous sodium hydroxide, and explain why it is a disproportionation reaction. Type the equation like this: Cl2 + …', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3b065970-7508-5867-9b62-d6bcec33b37f', 'Cl₂ + 2NaOH → NaCl + NaClO + H₂O [1]. Chlorine is oxidised from 0 to +1 in NaClO [1] and reduced from 0 to −1 in NaCl in the same reaction [1].', 'Cl₂ + 2NaOH → NaCl + NaClO + H₂O [1]. Chlorine is oxidised from 0 to +1 in NaClO [1] and reduced from 0 to −1 in NaCl in the same reaction [1].', '[{"text": "Marking point 1", "any": ["cl2 2naoh", "2naoh cl2", "cl2 2oh"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["oxidised"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["reduced"], "all": [], "marks": 1}]'::jsonb, 'Cl₂ + 2NaOH → NaCl + NaClO + H₂O [1]. Chlorine is oxidised from 0 to +1 in NaClO [1] and reduced from 0 to −1 in NaCl in the same reaction [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
