insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f6f79385-4149-533b-874e-0ca24580c454', 'short', 'In the reaction 3Cl₂ + 6NaOH → 5NaCl + NaClO₃ + 3H₂O, explain in terms of oxidation numbers why five NaCl form for every one NaClO₃.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f6f79385-4149-533b-874e-0ca24580c454', 'One chlorine atom is oxidised from 0 to +5, an increase of 5 [1]. Each chlorine atom that is reduced goes from 0 to −1, so five of them are needed to balance it [1].', 'One chlorine atom is oxidised from 0 to +5, an increase of 5 [1]. Each chlorine atom that is reduced goes from 0 to −1, so five of them are needed to balance it [1].', '[{"text": "Marking point 1", "any": ["0 to 5", "increases by 5", "up by 5", "goes up by 5", "loses 5", "plus 5", "rises by 5"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["0 to 1", "decreases by 1", "down by 1", "each gain", "gains 1", "goes down by 1", "five chlorine", "5 chlorine", "falls by 1"], "all": [], "marks": 1}]'::jsonb, 'One chlorine atom is oxidised from 0 to +5, an increase of 5 [1]. Each chlorine atom that is reduced goes from 0 to −1, so five of them are needed to balance it [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
