insert into public.questions (id, kind, prompt, options, marks, image_url) values ('9c6044c5-94bb-569b-84ea-f64dcc2d928c', 'short', '(a) Define disproportionation. (b) Chlorine is bubbled into hot, concentrated aqueous sodium hydroxide. Give the formulas of the two chlorine-containing products and the oxidation number of chlorine in each. (c) State one condition that must be changed to make NaClO instead.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('9c6044c5-94bb-569b-84ea-f64dcc2d928c', '(a) A reaction in which the same element [1] is both oxidised and reduced [1]. (b) NaCl, with chlorine at −1 [1], and NaClO₃ [1], with chlorine at +5 [1]. (c) Use cold, dilute sodium hydroxide [1].', '(a) A reaction in which the same element [1] is both oxidised and reduced [1]. (b) NaCl, with chlorine at −1 [1], and NaClO₃ [1], with chlorine at +5 [1]. (c) Use cold, dilute sodium hydroxide [1].', '[{"text": "Marking point 1", "any": ["same element", "same species", "one element", "same substance"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["oxidised and reduced", "reduced and oxidised", "both oxidised", "oxidation and reduction", "reduction and oxidation"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["nacl "], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["naclo3"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["is 5", "at 5", "plus 5", "of 5", "5 in", "naclo3 5", "number 5", "to 5"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["cold", "lower temperature", "dilute", "cool", "room temperature"], "all": [], "marks": 1}]'::jsonb, '(a) A reaction in which the same element [1] is both oxidised and reduced [1]. (b) NaCl, with chlorine at −1 [1], and NaClO₃ [1], with chlorine at +5 [1]. (c) Use cold, dilute sodium hydroxide [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
