insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0ee04f5b-2d0a-5e2b-b1f3-4adff4977278', 'The nitrogen atoms are joined by a triple bond [1], which is very strong (944 kJ mol⁻¹), so a large amount of energy is needed to break it [1]. The molecule is also non-polar, so it does not attract other reagents [1].', 'The nitrogen atoms are joined by a triple bond [1], which is very strong (944 kJ mol⁻¹), so a large amount of energy is needed to break it [1]. The molecule is also non-polar, so it does not attract other reagents [1].', '[{"text": "Marking point 1", "any": ["triple"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["strong", "944", "high bond energy", "large amount of energy", "lot of energy", "high activation"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["non-polar", "not polar", "no dipole", "nonpolar", "no polarity", "lack of polarity"], "all": [], "marks": 1}]'::jsonb, 'The nitrogen atoms are joined by a triple bond [1], which is very strong (944 kJ mol⁻¹), so a large amount of energy is needed to break it [1]. The molecule is also non-polar, so it does not attract other reagents [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
