insert into public.questions (id, kind, prompt, options, marks, image_url) values ('53f423c1-9d56-5cde-bc67-d7d1ef6b0d40', 'short', 'Describe how the ammonium ion is formed from ammonia, and state its shape and bond angle.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ammonium-2D.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('53f423c1-9d56-5cde-bc67-d7d1ef6b0d40', 'The lone pair on the nitrogen atom of ammonia forms a coordinate bond to an H⁺ ion [1]. The ammonium ion is tetrahedral [1] with bond angles of 109.5° [1].', 'The lone pair on the nitrogen atom of ammonia forms a coordinate bond to an H⁺ ion [1]. The ammonium ion is tetrahedral [1] with bond angles of 109.5° [1].', '[{"text": "Marking point 1", "any": ["coordinate", "dative", "lone pair"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["tetrahedral"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["109"], "all": [], "marks": 1}]'::jsonb, 'The lone pair on the nitrogen atom of ammonia forms a coordinate bond to an H⁺ ion [1]. The ammonium ion is tetrahedral [1] with bond angles of 109.5° [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
