insert into public.questions (id, kind, prompt, options, marks, image_url) values ('53ebcb54-ca9f-5bf1-a114-b51967596f4c', 'short', 'A white solid is warmed with aqueous sodium hydroxide. A gas is given off that turns damp red litmus paper blue. (a) Identify the gas and the ion present in the solid. (b) Write the ionic equation for the reaction.(d) Explain why a farmer should not add lime, Ca(OH)₂, to soil at the same time as an ammonium fertiliser.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('53ebcb54-ca9f-5bf1-a114-b51967596f4c', '(a) The gas is ammonia [1]; the solid contains the ammonium ion [1]. (b) NH₄⁺ + OH⁻ → NH₃ + H₂O [1]. (c) The ammonium ion is the acid (proton donor) [1]; the hydroxide ion is the base (proton acceptor) [1]. (d) The lime would react with the ammonium salt and ammonia gas would be given off, so the nitrogen is lost from the soil [1].', '(a) The gas is ammonia [1]; the solid contains the ammonium ion [1]. (b) NH₄⁺ + OH⁻ → NH₃ + H₂O [1]. (c) The ammonium ion is the acid (proton donor) [1]; the hydroxide ion is the base (proton acceptor) [1]. (d) The lime would react with the ammonium salt and ammonia gas would be given off, so the nitrogen is lost from the soil [1].', '[{"text": "Marking point 1", "any": ["ammonia", "nh3"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ammonium", "nh4"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["nh4 oh", "oh nh4"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["ammonium ion is the acid", "nh4 is the acid", "acid is nh4", "acid is the ammonium", "acid: nh4", "acid is ammonium", "ammonium is the acid", "nh4 acid"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["hydroxide ion is the base", "oh is the base", "base is oh", "base is the hydroxide", "base: oh", "base is hydroxide", "hydroxide is the base", "oh base"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["lost", "escapes", "wasted", "given off", "released", "displace"], "all": [], "marks": 1}]'::jsonb, '(a) The gas is ammonia [1]; the solid contains the ammonium ion [1]. (b) NH₄⁺ + OH⁻ → NH₃ + H₂O [1]. (c) The ammonium ion is the acid (proton donor) [1]; the hydroxide ion is the base (proton acceptor) [1]. (d) The lime would react with the ammonium salt and ammonia gas would be given off, so the nitrogen is lost from the soil [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
