insert into public.questions (id, kind, prompt, options, marks, image_url) values ('7b3456e3-5d6d-58cc-8c85-8962e00b010d', 'short', 'Write the equation for the formation of nitrogen monoxide in a car engine, and explain why this reaction does not happen in air at room temperature. Type the equation like this: N2 + …', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lightning_NOAA.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7b3456e3-5d6d-58cc-8c85-8962e00b010d', 'N₂ + O₂ → 2NO [1]. The N≡N triple bond is very strong, so the activation energy is very high and the reaction needs a very high temperature [1].', 'N₂ + O₂ → 2NO [1]. The N≡N triple bond is very strong, so the activation energy is very high and the reaction needs a very high temperature [1].', '[{"text": "Marking point 1", "any": ["n2 o2", "o2 n2"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["triple bond", "strong bond", "activation energy", "high temperature", "bond energy", "lot of energy", "very strong"], "all": [], "marks": 1}]'::jsonb, 'N₂ + O₂ → 2NO [1]. The N≡N triple bond is very strong, so the activation energy is very high and the reaction needs a very high temperature [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
