insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('25ddfc91-0e70-5b95-9cde-208394247d9a', '3-methylpentane [1]. The longest carbon chain has five carbon atoms, so the stem is pent-, with a methyl group on carbon 3 [1].', '3-methylpentane [1]. The longest carbon chain has five carbon atoms, so the stem is pent-, with a methyl group on carbon 3 [1].', '[{"text": "Marking point 1", "any": ["3-methylpentane", "3 methyl pentane"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["longest chain", "five carbon", "5 carbon", "longest carbon"], "all": [], "marks": 1}]'::jsonb, '3-methylpentane [1]. The longest carbon chain has five carbon atoms, so the stem is pent-, with a methyl group on carbon 3 [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
