insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8062474e-765b-5931-b5e2-4cb7f6cfefe5', 'short', '(a) Name CH₃CH₂CH₂COOH. (b) Name CH₃CHBrCH₂CH₃. (c) Write the structural formula of 2-methylpropan-2-ol. (d) Give the molecular formula of 2-methylpropan-2-ol. (e) Name the ester CH₃COOCH₃. (f) Give the empirical formula of the ester in (e).', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('8062474e-765b-5931-b5e2-4cb7f6cfefe5', '(a) Butanoic acid [1]. (b) 2-bromobutane [1]. (c) (CH₃)₃COH [1]. (d) C₄H₁₀O [1]. (e) Methyl ethanoate [1]. (f) C₃H₆O₂ [1] (it cannot be simplified).', '(a) Butanoic acid [1]. (b) 2-bromobutane [1]. (c) (CH₃)₃COH [1]. (d) C₄H₁₀O [1]. (e) Methyl ethanoate [1]. (f) C₃H₆O₂ [1] (it cannot be simplified).', '[{"text": "Marking point 1", "any": ["butanoic acid"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["2-bromobutane", "2 bromo butane"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["ch3 3coh", "ch3 2c oh ch3", "ch3c ch3 oh ch3", "ch3c oh ch3 ch3", "c ch3 3oh", "ch3c ch3 2oh"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["c4h10o"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["methyl ethanoate"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["c3h6o2"], "all": [], "marks": 1}]'::jsonb, '(a) Butanoic acid [1]. (b) 2-bromobutane [1]. (c) (CH₃)₃COH [1]. (d) C₄H₁₀O [1]. (e) Methyl ethanoate [1]. (f) C₃H₆O₂ [1] (it cannot be simplified).') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
