insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('0688b6bf-c843-57ea-a884-4d47318232b5', 1, 'Cl• and •CH₃ are free radicals. OH⁻, CN⁻ and NH₃ have lone pairs: nucleophiles. H⁺ and the δ+ hydrogen of HBr accept an electron pair: electrophiles.', 'Nucleophile') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
