insert into public.questions (id, kind, prompt, options, marks, image_url) values ('aafb6c94-aa28-5395-b303-9fe9929bc131', 'short', 'Explain the difference between homolytic fission and heterolytic fission of a covalent bond.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('aafb6c94-aa28-5395-b303-9fe9929bc131', 'In homolytic fission the bond breaks evenly, with one electron going to each atom [1], so two free radicals form [1]. In heterolytic fission both electrons go to the same atom, so a positive ion and a negative ion form [1].', 'In homolytic fission the bond breaks evenly, with one electron going to each atom [1], so two free radicals form [1]. In heterolytic fission both electrons go to the same atom, so a positive ion and a negative ion form [1].', '[{"text": "Marking point 1", "any": ["one electron", "evenly", "equally", "each atom"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["radical"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["both electrons", "two electrons", "ions", "ion"], "all": [], "marks": 1}]'::jsonb, 'In homolytic fission the bond breaks evenly, with one electron going to each atom [1], so two free radicals form [1]. In heterolytic fission both electrons go to the same atom, so a positive ion and a negative ion form [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', 'aafb6c94-aa28-5395-b303-9fe9929bc131', 14);
