insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e39aeffd-08a8-50e3-9eaa-bd1dd5f13efe', 'short', 'Bromoethane reacts with hydroxide ions: CH₃CH₂Br + OH⁻ → CH₃CH₂OH + Br⁻. State the type of reaction and identify the nucleophile, with a reason.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e39aeffd-08a8-50e3-9eaa-bd1dd5f13efe', 'It is a substitution reaction: OH replaces Br [1]. The nucleophile is the hydroxide ion [1], because it donates a lone pair of electrons to the δ+ carbon atom [1].', 'It is a substitution reaction: OH replaces Br [1]. The nucleophile is the hydroxide ion [1], because it donates a lone pair of electrons to the δ+ carbon atom [1].', '[{"text": "Marking point 1", "any": ["substitution"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["oh", "hydroxide"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["lone pair", "donates", "donate", "electron pair", "pair of electrons"], "all": [], "marks": 1}]'::jsonb, 'It is a substitution reaction: OH replaces Br [1]. The nucleophile is the hydroxide ion [1], because it donates a lone pair of electrons to the δ+ carbon atom [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', 'e39aeffd-08a8-50e3-9eaa-bd1dd5f13efe', 16);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('304ec9ec-1746-5c48-93e2-1575aec9805a', 'short', 'State the H–C–H bond angle in ethane and explain it.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Methane-3D-balls.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('304ec9ec-1746-5c48-93e2-1575aec9805a', '109.5° [1]. Each carbon has four bonding pairs of electrons, which repel each other equally and get as far apart as possible [1].', '109.5° [1]. Each carbon has four bonding pairs of electrons, which repel each other equally and get as far apart as possible [1].', '[{"text": "Marking point 1", "any": ["109"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["four bonding pairs", "4 bonding pairs", "repel", "four pairs", "4 pairs", "four electron pairs"], "all": [], "marks": 1}]'::jsonb, '109.5° [1]. Each carbon has four bonding pairs of electrons, which repel each other equally and get as far apart as possible [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', '304ec9ec-1746-5c48-93e2-1575aec9805a', 17);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8cc3ad21-d7aa-530a-a5b3-5ea43c8b7882', 'mcq', 'For ethene, CH₂=CH₂, choose the correct answer.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('8cc3ad21-d7aa-530a-a5b3-5ea43c8b7882', 3, 'sp² carbons, 120°, five σ bonds (four C–H and one C–C), one π bond, planar.', '120°') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', '8cc3ad21-d7aa-530a-a5b3-5ea43c8b7882', 18);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('b8df92f0-bd77-5cd9-bfc0-41dd2d731207', 'short', 'Explain what is meant by describing ethene as planar, and why there is no rotation about the C=C bond.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pi-Bond.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b8df92f0-bd77-5cd9-bfc0-41dd2d731207', 'All six atoms lie in the same plane [1]. Rotation would break the π bond, because the sideways overlap of the p orbitals would be lost [1].', 'All six atoms lie in the same plane [1]. Rotation would break the π bond, because the sideways overlap of the p orbitals would be lost [1].', '[{"text": "Marking point 1", "any": ["same plane", "one plane", "flat"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["pi bond", "π bond", "p orbitals", "overlap"], "all": [], "marks": 1}]'::jsonb, 'All six atoms lie in the same plane [1]. Rotation would break the π bond, because the sideways overlap of the p orbitals would be lost [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', 'b8df92f0-bd77-5cd9-bfc0-41dd2d731207', 19);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a33f19a1-f6e5-5a19-a64e-ac84f761d1b0', 'mcq', 'What is the hybridisation of the carbon atom shown in bold capitals?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a33f19a1-f6e5-5a19-a64e-ac84f761d1b0', 1, 'Four atoms attached: sp³. Three attached (C=C or C=O): sp². Two attached (C≡C or C≡N): sp.', 'sp²') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', 'a33f19a1-f6e5-5a19-a64e-ac84f761d1b0', 20);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('655384f3-d11f-584a-8485-792b2a340d78', 'mcq', 'How many structural isomers are alkanes with this molecular formula?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('655384f3-d11f-584a-8485-792b2a340d78', 0, 'C₃H₈: 1. C₄H₁₀: 2. C₅H₁₂: 3. C₆H₁₄: 5 (hexane, 2-methylpentane, 3-methylpentane, 2,2-dimethylbutane and 2,3-dimethylbutane).', '1') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', '655384f3-d11f-584a-8485-792b2a340d78', 21);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('95dd7b66-851b-58a5-914a-ae424b7d9dff', 'short', 'Name the three structural isomers with the molecular formula C₅H₁₂.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('95dd7b66-851b-58a5-914a-ae424b7d9dff', 'Pentane [1], 2-methylbutane [1] and 2,2-dimethylpropane [1].', 'Pentane [1], 2-methylbutane [1] and 2,2-dimethylpropane [1].', '[{"text": "Marking point 1", "any": ["pentane "], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["2-methylbutane", "2 methyl butane", "methylbutane"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["2,2-dimethylpropane", "2 2 dimethyl propane", "dimethylpropane"], "all": [], "marks": 1}]'::jsonb, 'Pentane [1], 2-methylbutane [1] and 2,2-dimethylpropane [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', '95dd7b66-851b-58a5-914a-ae424b7d9dff', 22);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('8fa95211-edfa-5b37-96d3-1586ede0adc2', 'mcq', 'Are the two compounds positional isomers of each other?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('8fa95211-edfa-5b37-96d3-1586ede0adc2', 3, 'The alcohols and the butenes are positional isomers. Butane and 2-methylpropane are chain isomers. CH₃CH₂CH₂Cl written backwards is the same compound. Propan-1-ol and butan-1-ol have different formulas.', 'No: different molecular formulas') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', '8fa95211-edfa-5b37-96d3-1586ede0adc2', 23);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('fda0d15a-e58a-5429-b23d-49712e014e9a', 'short', '(a) Define structural isomerism. (b) There are four alcohols with the molecular formula C₄H₁₀O. Name them. (c) State the type of isomerism shown by butan-1-ol and 2-methylpropan-1-ol.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('fda0d15a-e58a-5429-b23d-49712e014e9a', '(a) Compounds with the same molecular formula but different structural formulas [1]. (b) Butan-1-ol [1], butan-2-ol [1], 2-methylpropan-1-ol [1] and 2-methylpropan-2-ol [1]. (c) Chain isomerism [1].', '(a) Compounds with the same molecular formula but different structural formulas [1]. (b) Butan-1-ol [1], butan-2-ol [1], 2-methylpropan-1-ol [1] and 2-methylpropan-2-ol [1]. (c) Chain isomerism [1].', '[{"text": "Marking point 1", "any": ["same molecular formula", "different structural"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["butan-1-ol", "butan 1 ol", "1-butanol"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["butan-2-ol", "butan 2 ol", "2-butanol"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["2-methylpropan-1-ol", "2 methyl propan 1 ol", "methylpropan-1-ol"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["2-methylpropan-2-ol", "2 methyl propan 2 ol", "methylpropan-2-ol"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["chain"], "all": [], "marks": 1}]'::jsonb, '(a) Compounds with the same molecular formula but different structural formulas [1]. (b) Butan-1-ol [1], butan-2-ol [1], 2-methylpropan-1-ol [1] and 2-methylpropan-2-ol [1]. (c) Chain isomerism [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', 'fda0d15a-e58a-5429-b23d-49712e014e9a', 24);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e8c64807-0ce0-5984-8fc3-ccb98914f6dd', 'mcq', 'Does the compound show geometrical (cis/trans) isomerism?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('e8c64807-0ce0-5984-8fc3-ccb98914f6dd', 0, 'But-2-ene, 1,2-dichloroethene and pent-2-ene: yes. But-1-ene, 1,1-dichloroethene and 2-methylbut-2-ene have two identical groups on one carbon of the C=C: no. Butane has no double bond.', 'Yes') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', 'e8c64807-0ce0-5984-8fc3-ccb98914f6dd', 25);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('2971f307-aa0a-5480-a4e8-b5327d9e5c1c', 'short', 'Explain why but-2-ene has geometrical isomers but but-1-ene does not.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trans-but-2-ene-3D-balls.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2971f307-aa0a-5480-a4e8-b5327d9e5c1c', 'The π bond causes restricted rotation about the C=C bond [1]. In but-2-ene each carbon of the C=C has two different groups (H and CH₃) [1], but in but-1-ene one carbon has two identical hydrogen atoms, so only one arrangement exists [1].', 'The π bond causes restricted rotation about the C=C bond [1]. In but-2-ene each carbon of the C=C has two different groups (H and CH₃) [1], but in but-1-ene one carbon has two identical hydrogen atoms, so only one arrangement exists [1].', '[{"text": "Marking point 1", "any": ["restricted rotation", "cannot rotate", "no rotation", "no free rotation", "pi bond", "π bond", "prevents rotation"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["two different groups", "different groups on each", "2 different groups"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["two hydrogen", "identical", "two h", "the same", "2 hydrogen", "same group"], "all": [], "marks": 1}]'::jsonb, 'The π bond causes restricted rotation about the C=C bond [1]. In but-2-ene each carbon of the C=C has two different groups (H and CH₃) [1], but in but-1-ene one carbon has two identical hydrogen atoms, so only one arrangement exists [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', '2971f307-aa0a-5480-a4e8-b5327d9e5c1c', 26);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('47427c1d-603f-54c9-9901-1446527676d0', 'mcq', 'Does the compound have a chiral centre?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('47427c1d-603f-54c9-9901-1446527676d0', 1, 'Butan-2-ol, 2-chlorobutane, 2-hydroxypropanoic acid and 2-aminopropanoic acid each have a carbon with four different groups. Propan-2-ol and 2-bromopropane have two identical CH₃ groups; butan-1-ol has no carbon with four different groups.', 'No') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', '47427c1d-603f-54c9-9901-1446527676d0', 27);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5ba2476b-81e3-51b4-9ae2-f46a1dc78176', 'mcq', 'How many chiral centres does the molecule have?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('5ba2476b-81e3-51b4-9ae2-f46a1dc78176', 2, 'CH₃CH₂CH(CH₃)CH₂OH has 1. CH₃CH(OH)CH(OH)CH₂CH₃ has 2. (CH₃)₂CHCH₂OH has 0. 3-Bromopentane has 0, because the central carbon has two ethyl groups. CH₃CH(OH)CH=CH₂ has 1.', '2') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', '5ba2476b-81e3-51b4-9ae2-f46a1dc78176', 28);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('5404d9db-f3ac-5bf1-9732-4a8aa3399b87', 'mcq', 'Which type of stereoisomerism does the compound show?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('5404d9db-f3ac-5bf1-9732-4a8aa3399b87', 1, 'But-2-ene: geometrical only. Butan-2-ol: optical only. CH₃CH=CHCH(OH)CH₃ has a suitable C=C and a chiral centre: both. Propan-1-ol: neither. CH₂=CHCH(Cl)CH₃ has =CH₂, so no cis/trans, but it has a chiral centre: optical only.', 'Optical only') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', '5404d9db-f3ac-5bf1-9732-4a8aa3399b87', 29);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('0fc67c0f-b64f-5a47-9ffd-8deabb9088f0', 'short', 'A compound has the structural formula CH₃CH=CHCH(OH)CH₃. (a) Define stereoisomerism. (b) Explain why this compound shows geometrical isomerism. (c) Identify the chiral centre by naming the four different groups attached to it. (d) State the total number of stereoisomers of this compound.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0fc67c0f-b64f-5a47-9ffd-8deabb9088f0', '(a) Compounds with the same structural formula [1] but a different arrangement of atoms in space [1]. (b) There is restricted rotation about the C=C bond and each carbon of the C=C has two different groups [1]. (c) The carbon bonded to H, OH [1], CH₃ and the CH=CHCH₃ group [1]. (d) 4 stereoisomers: cis and trans, each as two optical isomers [1].', '(a) Compounds with the same structural formula [1] but a different arrangement of atoms in space [1]. (b) There is restricted rotation about the C=C bond and each carbon of the C=C has two different groups [1]. (c) The carbon bonded to H, OH [1], CH₃ and the CH=CHCH₃ group [1]. (d) 4 stereoisomers: cis and trans, each as two optical isomers [1].', '[{"text": "Marking point 1", "any": ["same structural formula", "same structural"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["different arrangement", "arrangement in space", "spatial", "arranged differently in space", "different spatial"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["two different groups", "different groups on each", "restricted rotation", "2 different groups"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["oh", "hydroxyl"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["ch3 ", "methyl"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["4 stereoisomers", "four stereoisomers", "4 isomers", "four isomers", "total 4", "total of 4", "is 4", "are 4", "d 4"], "all": [], "marks": 1}]'::jsonb, '(a) Compounds with the same structural formula [1] but a different arrangement of atoms in space [1]. (b) There is restricted rotation about the C=C bond and each carbon of the C=C has two different groups [1]. (c) The carbon bonded to H, OH [1], CH₃ and the CH=CHCH₃ group [1]. (d) 4 stereoisomers: cis and trans, each as two optical isomers [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('137b5b42-ee8f-5061-b73f-4d9000ef0b80', '0fc67c0f-b64f-5a47-9ffd-8deabb9088f0', 30);
insert into public.quiz_classes (quiz_id, class_id) select '137b5b42-ee8f-5061-b73f-4d9000ef0b80', c.id from public.classes c where c.site_slug = 'alevel-chem' and c.owner_kind = 'main' on conflict do nothing;
insert into public.quizzes (id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', '14 Hydrocarbons · Topic quiz', 'Topical quiz for A Level Chemistry, topic 14 Hydrocarbons (subtopics 14.1 to 14.2). Questions come from the interactive lessons. Written answers are marked against the mark scheme; your teacher checks every mark.', null, 2, false, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions;
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('87b114f1-e9e8-5d42-9cee-96927a4da74f', 'short', 'Explain why alkanes do not react with polar reagents such as aqueous sodium hydroxide.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Methane-3D-balls.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('87b114f1-e9e8-5d42-9cee-96927a4da74f', 'The C–C and C–H bonds are strong [1] and non-polar, because carbon and hydrogen have similar electronegativities, so there is no δ+ or δ− site to attract the reagent [1].', 'The C–C and C–H bonds are strong [1] and non-polar, because carbon and hydrogen have similar electronegativities, so there is no δ+ or δ− site to attract the reagent [1].', '[{"text": "Marking point 1", "any": ["strong"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["non-polar", "not polar", "nonpolar", "similar electronegativ", "same electronegativ", "no dipole", "lack of polarity"], "all": [], "marks": 1}]'::jsonb, 'The C–C and C–H bonds are strong [1] and non-polar, because carbon and hydrogen have similar electronegativities, so there is no δ+ or δ− site to attract the reagent [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', '87b114f1-e9e8-5d42-9cee-96927a4da74f', 1);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a850ade8-b199-53c7-a2a1-a5e189c25907', 'mcq', 'Choose the correct answer.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a850ade8-b199-53c7-a2a1-a5e189c25907', 0, 'Hydrogenation: Pt or Ni and heat; propene gives propane. Cracking: heat with Al₂O₃, giving a shorter alkane and an alkene.', 'Pt or Ni, heat') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', 'a850ade8-b199-53c7-a2a1-a5e189c25907', 2);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('0b6f1d32-7bbc-5a9d-bb76-8964086a44e6', 'mcq', 'Complete or incomplete combustion?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('0b6f1d32-7bbc-5a9d-bb76-8964086a44e6', 0, 'Excess oxygen: complete, giving CO₂ and H₂O with a blue flame. Limited oxygen: incomplete, giving CO or soot and a yellow smoky flame.', 'Complete') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', '0b6f1d32-7bbc-5a9d-bb76-8964086a44e6', 3);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f649543e-41fa-533b-9bdc-9985c7924628', 'short', 'Write the equation for the complete combustion of propane.', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Propane-3D-balls-B.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
