insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cc35b5f1-db99-581c-af65-e2f94278ad65', 'Two methyl radicals combine in a termination step: •CH₃ + •CH₃ → C₂H₆ [1]. This is evidence that methyl radicals are formed, supporting the free-radical mechanism [1].', 'Two methyl radicals combine in a termination step: •CH₃ + •CH₃ → C₂H₆ [1]. This is evidence that methyl radicals are formed, supporting the free-radical mechanism [1].', '[{"text": "Marking point 1", "any": ["two methyl", "2 methyl", "ch3 ch3", "methyl radicals", "two ch3", "2ch3"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["evidence", "shows", "termination", "supports", "proves", "confirms"], "all": [], "marks": 1}]'::jsonb, 'Two methyl radicals combine in a termination step: •CH₃ + •CH₃ → C₂H₆ [1]. This is evidence that methyl radicals are formed, supporting the free-radical mechanism [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
