insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('2d32b1c5-5b9d-5e81-8333-a0ad288d998b', 3, 'HBr gives bromoethane; Br₂ gives 1,2-dibromoethane; HCl gives chloroethane; Cl₂ gives 1,2-dichloroethane. Propene with Br₂ gives 1,2-dibromopropane and with H₂ gives propane.', 'CH₂ClCH₂Cl') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
