insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d57c1894-51f0-57d6-b156-de54014f93eb', 'short', 'A student has two colourless liquids, hexane and hex-1-ene. (a) Describe a chemical test, with the result for each liquid, that tells them apart. (b) Name the type of reaction that takes place with hex-1-ene. (c) Give the reagent and conditions needed to convert hex-1-ene into hexane. (d) Name the class of compound formed when hex-1-ene reacts with steam.', '[]'::jsonb, 6, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bromine_water.jpg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d57c1894-51f0-57d6-b156-de54014f93eb', '(a) Shake each with aqueous bromine [1]. Hex-1-ene turns it from orange to colourless [1]; with hexane there is no change [1]. (b) Addition [1]. (c) Hydrogen with a nickel catalyst and heat [1]. (d) An alcohol [1].', '(a) Shake each with aqueous bromine [1]. Hex-1-ene turns it from orange to colourless [1]; with hexane there is no change [1]. (b) Addition [1]. (c) Hydrogen with a nickel catalyst and heat [1]. (d) An alcohol [1].', '[{"text": "Marking point 1", "any": ["bromine"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["colourless", "decolourise", "decolorise", "decolourised", "loses its colour"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["no change", "stays orange", "remains orange", "no reaction", "stays the same", "does not change"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["addition"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["h2 ni", "h2 pt", "h2 and ni", "h2 and pt", "h2 with ni", "h2 with pt"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["alcohol"], "all": [], "marks": 1}]'::jsonb, '(a) Shake each with aqueous bromine [1]. Hex-1-ene turns it from orange to colourless [1]; with hexane there is no change [1]. (b) Addition [1]. (c) Hydrogen with a nickel catalyst and heat [1]. (d) An alcohol [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', 'd57c1894-51f0-57d6-b156-de54014f93eb', 18);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('1593abe6-841c-55d5-9f62-c0a37366b7d3', 'mcq', 'Bromine with ethene: choose the correct answer.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('1593abe6-841c-55d5-9f62-c0a37366b7d3', 3, 'The π electrons induce a dipole in Br₂; Br^δ+ is the electrophile; Br–Br breaks heterolytically to give a carbocation and Br⁻, which then attacks the carbocation.', 'Heterolytic') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', '1593abe6-841c-55d5-9f62-c0a37366b7d3', 19);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('29a69605-a198-598e-b151-277cfb04855f', 'mcq', 'Put the events of HBr adding to ethene in order.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('29a69605-a198-598e-b151-277cfb04855f', 1, 'The π pair attacks H^δ+; H–Br breaks heterolytically; a carbocation forms; Br⁻ attacks it.', 'Second') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', '29a69605-a198-598e-b151-277cfb04855f', 20);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ffb21762-dd3f-5de6-9b15-cd1ca1fd393e', 'short', 'Give the formula of the carbocation formed when HBr reacts with ethene, and state where each of the two curly arrows in step 1 starts.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bromoethane-3D-balls.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ffb21762-dd3f-5de6-9b15-cd1ca1fd393e', 'The carbocation is CH₃CH₂⁺ [1]. One arrow starts at the C=C double bond [1]; the other starts at the H–Br bond [1].', 'The carbocation is CH₃CH₂⁺ [1]. One arrow starts at the C=C double bond [1]; the other starts at the H–Br bond [1].', '[{"text": "Marking point 1", "any": ["ch3ch2 ", "c2h5 ", "ch3ch2"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["double bond", "c=c", "pi bond", "π bond", "c c bond"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["h-br bond", "h br bond", "hbr bond", "bond between h", "bond in hbr", "bond in h-br", "bond of hbr", "bond in h br"], "all": [], "marks": 1}]'::jsonb, 'The carbocation is CH₃CH₂⁺ [1]. One arrow starts at the C=C double bond [1]; the other starts at the H–Br bond [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', 'ffb21762-dd3f-5de6-9b15-cd1ca1fd393e', 21);
