insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', 'ad7e1238-eb6c-581d-9f8e-947d2c4aa078', 22);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f87feffc-20c8-5d32-a2c1-0bbc1fa7d919', 'short', '2-Methylpropene, (CH₃)₂C=CH₂, reacts with hydrogen bromide. (a) Name the mechanism. (b) Give the formulas of the two possible carbocations. (c) State which carbocation is more stable and classify it. (d) Name the major product. (e) Explain why it is the major product.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f87feffc-20c8-5d32-a2c1-0bbc1fa7d919', '(a) Electrophilic addition [1]. (b) (CH₃)₃C⁺ [1] and (CH₃)₂CHCH₂⁺ [1]. (c) (CH₃)₃C⁺, a tertiary carbocation [1]. (d) 2-bromo-2-methylpropane [1]. (e) It forms through the more stable tertiary carbocation, which is formed faster than the primary one [1].', '(a) Electrophilic addition [1]. (b) (CH₃)₃C⁺ [1] and (CH₃)₂CHCH₂⁺ [1]. (c) (CH₃)₃C⁺, a tertiary carbocation [1]. (d) 2-bromo-2-methylpropane [1]. (e) It forms through the more stable tertiary carbocation, which is formed faster than the primary one [1].', '[{"text": "Marking point 1", "any": ["electrophilic addition"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ch3 3c", "ch3 2c ch3", "c ch3 3"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["ch3 2chch2", "ch3 2ch ch2", "ch2ch ch3 2"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["tertiary"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["2-bromo-2-methylpropane", "2 bromo 2 methyl propane", "2-bromomethylpropane"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["more stable", "most stable", "stability", "forms faster", "formed faster"], "all": [], "marks": 1}]'::jsonb, '(a) Electrophilic addition [1]. (b) (CH₃)₃C⁺ [1] and (CH₃)₂CHCH₂⁺ [1]. (c) (CH₃)₃C⁺, a tertiary carbocation [1]. (d) 2-bromo-2-methylpropane [1]. (e) It forms through the more stable tertiary carbocation, which is formed faster than the primary one [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', 'f87feffc-20c8-5d32-a2c1-0bbc1fa7d919', 23);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c0def069-8791-5679-a8c3-1d7eeefc67b3', 'mcq', 'What is formed with cold, dilute acidified KMnO₄?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('c0def069-8791-5679-a8c3-1d7eeefc67b3', 1, 'Ethene gives ethane-1,2-diol; propene gives propane-1,2-diol; but-2-ene gives butane-2,3-diol; but-1-ene gives butane-1,2-diol. Butane does not react.', 'Propane-1,2-diol') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', 'c0def069-8791-5679-a8c3-1d7eeefc67b3', 24);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('9ef9e83b-c7f2-549e-a971-17f3e02ae916', 'short', 'Write the equation, using [O], for the oxidation of ethene by cold dilute acidified KMnO₄, and state the colour change. Type the equation like this: C2H4 + H2O + [O] → …', '[]'::jsonb, 2, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ethylene-glycol-3D-balls.png?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('9ef9e83b-c7f2-549e-a971-17f3e02ae916', 'C₂H₄ + H₂O + [O] → HOCH₂CH₂OH [1]. The solution changes from purple to colourless [1].', 'C₂H₄ + H₂O + [O] → HOCH₂CH₂OH [1]. The solution changes from purple to colourless [1].', '[{"text": "Marking point 1", "any": ["hoch2ch2oh", "ch2ohch2oh", "ch2 oh ch2 oh", "c2h4 oh 2", "c2h6o2", "ho ch2 2oh"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["purple to colourless", "decolourise", "decolorise"], "all": [], "marks": 1}]'::jsonb, 'C₂H₄ + H₂O + [O] → HOCH₂CH₂OH [1]. The solution changes from purple to colourless [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', '9ef9e83b-c7f2-549e-a971-17f3e02ae916', 25);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6a7c5297-7df0-56bb-be8d-1154b3942735', 'mcq', 'What does this end of the double bond become with hot, concentrated acidified KMnO₄?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('6a7c5297-7df0-56bb-be8d-1154b3942735', 1, 'Two hydrogens: CO₂. One hydrogen: a carboxylic acid. No hydrogens: a ketone.', 'A carboxylic acid') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', '6a7c5297-7df0-56bb-be8d-1154b3942735', 26);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('380e2331-b104-5948-93c6-82047e05216c', 'mcq', 'What are the products with hot, concentrated acidified KMnO₄?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('380e2331-b104-5948-93c6-82047e05216c', 0, 'Propene: ethanoic acid and CO₂. But-2-ene: two ethanoic acid. 2-Methylpropene: propanone and CO₂. 2-Methylbut-2-ene: propanone and ethanoic acid. But-1-ene: propanoic acid and CO₂.', 'CH₃COOH and CO₂') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', '380e2331-b104-5948-93c6-82047e05216c', 27);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('bf0fe326-7df9-5002-a55e-e0dbf2bbcbfd', 'mcq', 'Which alkene gave these products with hot, concentrated acidified KMnO₄?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('bf0fe326-7df9-5002-a55e-e0dbf2bbcbfd', 1, 'Ethanoic acid only: but-2-ene. Propanoic acid and CO₂: but-1-ene. Propanone and CO₂: 2-methylpropene. Ethanoic and propanoic acids: pent-2-ene. Propanone and ethanoic acid: 2-methylbut-2-ene.', 'But-2-ene') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', 'bf0fe326-7df9-5002-a55e-e0dbf2bbcbfd', 28);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f91dc7b4-ade9-59ca-9ae9-282acc460acf', 'mcq', 'Which alkene gave these products with hot, concentrated acidified KMnO₄?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('f91dc7b4-ade9-59ca-9ae9-282acc460acf', 4, 'Ethanoic acid only: but-2-ene. Propanoic acid and CO₂: but-1-ene. Propanone and CO₂: 2-methylpropene. Ethanoic and propanoic acids: pent-2-ene. Propanone and ethanoic acid: 2-methylbut-2-ene.', '2-Methylbut-2-ene') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', 'f91dc7b4-ade9-59ca-9ae9-282acc460acf', 29);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('ae8d9899-d551-5874-a1f5-ee7a3959285c', 'short', '(a) State what happens to the π bond in each monomer during addition polymerisation. (b) Name the polymer formed from propene. (c) State how many carbon atoms are in the chain of one repeat unit of poly(propene), and what group is attached as a side group. (d) Explain why poly(ethene) does not decolourise aqueous bromine.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ae8d9899-d551-5874-a1f5-ee7a3959285c', '(a) The π bond breaks, and the electrons form new σ bonds to the neighbouring monomers [1]. (b) Poly(propene) [1]. (c) Two carbon atoms in the chain [1], with a methyl group, CH₃, as the side group [1]. (d) The polymer is saturated: it has no C=C double bonds left [1], so no addition reaction with bromine can take place [1].', '(a) The π bond breaks, and the electrons form new σ bonds to the neighbouring monomers [1]. (b) Poly(propene) [1]. (c) Two carbon atoms in the chain [1], with a methyl group, CH₃, as the side group [1]. (d) The polymer is saturated: it has no C=C double bonds left [1], so no addition reaction with bromine can take place [1].', '[{"text": "Marking point 1", "any": ["breaks", "broken", "opens"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["poly(propene)", "polypropene", "poly propene", "polypropylene"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["two", "2"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["methyl", "ch3"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["no double bond", "no c=c", "saturated", "no c c double", "does not contain a double", "no carbon-carbon double", "only single"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["addition", "cannot add", "no reaction", "not react", "does not react"], "all": [], "marks": 1}]'::jsonb, '(a) The π bond breaks, and the electrons form new σ bonds to the neighbouring monomers [1]. (b) Poly(propene) [1]. (c) Two carbon atoms in the chain [1], with a methyl group, CH₃, as the side group [1]. (d) The polymer is saturated: it has no C=C double bonds left [1], so no addition reaction with bromine can take place [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c7ead1fc-4e73-5d90-ae6a-db31d5c28dca', 'ae8d9899-d551-5874-a1f5-ee7a3959285c', 30);
