insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3224b1c2-fc6f-584e-892b-58a7955955da', 'short', 'Explain why hydroxide ions attack the carbon atom bonded to the bromine in bromoethane.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3224b1c2-fc6f-584e-892b-58a7955955da', 'Br is more electronegative, so the C–Br bond is polar and the carbon is δ+ [1]; OH⁻ is a nucleophile that donates a lone pair to that carbon [1].', 'Br is more electronegative, so the C–Br bond is polar and the carbon is δ+ [1]; OH⁻ is a nucleophile that donates a lone pair to that carbon [1].', '[{"text": "Marking point 1", "any": ["polar", "electronegative", "partial positive", "delta"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["lone pair", "electron pair", "nucleophile", "donor"], "all": [], "marks": 1}]'::jsonb, 'Br is more electronegative, so the C–Br bond is polar and the carbon is δ+ [1]; OH⁻ is a nucleophile that donates a lone pair to that carbon [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
