insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('9e9d0628-bfa6-5294-bae4-6f687db430fe', 'CH₃CH₂CH₂Cl + NaOH (or OH⁻) [1] → CH₃CH₂CH₂OH + NaCl (or Cl⁻) [1].', 'CH₃CH₂CH₂Cl + NaOH (or OH⁻) [1] → CH₃CH₂CH₂OH + NaCl (or Cl⁻) [1].', '[{"text": "Marking point 1", "any": ["ch3ch2ch2cl naoh", "ch3ch2ch2cl oh"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ch3ch2ch2oh"], "all": [], "marks": 1}]'::jsonb, 'CH₃CH₂CH₂Cl + NaOH (or OH⁻) [1] → CH₃CH₂CH₂OH + NaCl (or Cl⁻) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
