insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a88b754d-d630-58dc-b42e-2bc022b12793', 'short', 'Explain why excess ammonia is used to make ethylamine from bromoethane.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a88b754d-d630-58dc-b42e-2bc022b12793', 'The ethylamine produced is also a nucleophile [1], so it could react further with bromoethane to form secondary/tertiary amines; excess NH₃ makes this less likely [1].', 'The ethylamine produced is also a nucleophile [1], so it could react further with bromoethane to form secondary/tertiary amines; excess NH₃ makes this less likely [1].', '[{"text": "Marking point 1", "any": ["ethylamine", "amine", "product"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["further", "secondary", "more", "again", "nucleophile"], "all": [], "marks": 1}]'::jsonb, 'The ethylamine produced is also a nucleophile [1], so it could react further with bromoethane to form secondary/tertiary amines; excess NH₃ makes this less likely [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
