insert into public.questions (id, kind, prompt, options, marks, image_url) values ('1416e48f-5ed3-5bcf-aca0-6266b3c9c5de', 'short', '1-bromopropane is used to make (a) propan-1-ol, (b) butanenitrile and (c) propylamine. For each, give the reagent and the condition.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1416e48f-5ed3-5bcf-aca0-6266b3c9c5de', '(a) NaOH [1], aqueous, heat under reflux [1]; (b) KCN [1] in ethanol, heat [1]; (c) NH₃ [1], excess, in ethanol, heated in a sealed tube [1].', '(a) NaOH [1], aqueous, heat under reflux [1]; (b) KCN [1] in ethanol, heat [1]; (c) NH₃ [1], excess, in ethanol, heated in a sealed tube [1].', '[{"text": "Marking point 1", "any": ["naoh", "koh", "hydroxide"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["aqueous", "reflux", "heat"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["kcn", "nacn", "cyanide"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["ethanol", "alcoholic", "heat"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["ammonia", "nh3"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["sealed", "excess", "pressure", "ethanol"], "all": [], "marks": 1}]'::jsonb, '(a) NaOH [1], aqueous, heat under reflux [1]; (b) KCN [1] in ethanol, heat [1]; (c) NH₃ [1], excess, in ethanol, heated in a sealed tube [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
