insert into public.questions (id, kind, prompt, options, marks, image_url) values ('fa2dbe03-aca7-59de-8615-a5c3140a9c10', 'short', 'Explain why 2-bromo-2-methylpropane reacts with hydroxide ions by the SN1 mechanism.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('fa2dbe03-aca7-59de-8615-a5c3140a9c10', 'It is a tertiary halogenoalkane [1]; the three alkyl groups donate electrons and stabilise the tertiary carbocation formed [1]; they also crowd the carbon, so attack from the back (SN2) is hindered [1].', 'It is a tertiary halogenoalkane [1]; the three alkyl groups donate electrons and stabilise the tertiary carbocation formed [1]; they also crowd the carbon, so attack from the back (SN2) is hindered [1].', '[{"text": "Marking point 1", "any": ["tertiary", "three alkyl", "3 alkyl"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["carbocation", "stable", "stabilis", "inductive", "push electrons"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["hinder", "crowd", "bulky", "steric", "blocked"], "all": [], "marks": 1}]'::jsonb, 'It is a tertiary halogenoalkane [1]; the three alkyl groups donate electrons and stabilise the tertiary carbocation formed [1]; they also crowd the carbon, so attack from the back (SN2) is hindered [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('b1858bc4-ce4d-5d41-a5c9-7abc9333f166', 'fa2dbe03-aca7-59de-8615-a5c3140a9c10', 21);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('7a635762-18be-5e8f-b799-79b7c960d3e9', 'short', 'Explain why 1-iodobutane is hydrolysed faster than 1-chlorobutane.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7a635762-18be-5e8f-b799-79b7c960d3e9', 'The C–I bond is weaker (lower bond energy) than C–Cl [1], so less energy is needed to break it and it breaks more easily [1].', 'The C–I bond is weaker (lower bond energy) than C–Cl [1], so less energy is needed to break it and it breaks more easily [1].', '[{"text": "Marking point 1", "any": ["c–i", "c-i", "c i", "carbon iodine", "iodine bond"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["weaker", "lower bond energy", "less energy", "breaks more easily", "longer"], "all": [], "marks": 1}]'::jsonb, 'The C–I bond is weaker (lower bond energy) than C–Cl [1], so less energy is needed to break it and it breaks more easily [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
