insert into public.questions (id, kind, prompt, options, marks, image_url) values ('879cf10c-33bf-5ffa-bb82-9b86215ea964', 'short', 'Bromoethane reacts with hydroxide ions in two different ways. (a) Name the mechanism with aqueous NaOH and draw the curly arrows in words. (b) Give the conditions that make ethene instead, and the role of OH⁻.', '[]'::jsonb, 5, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('879cf10c-33bf-5ffa-bb82-9b86215ea964', '(a) SN2 (nucleophilic substitution) [1]: an arrow from the lone pair on OH⁻ to the δ+ carbon [1] and from the C–Br bond to Br, which leaves as Br⁻ [1]. (b) NaOH dissolved in ethanol, heat [1]; OH⁻ acts as a base, removing H⁺ [1].', '(a) SN2 (nucleophilic substitution) [1]: an arrow from the lone pair on OH⁻ to the δ+ carbon [1] and from the C–Br bond to Br, which leaves as Br⁻ [1]. (b) NaOH dissolved in ethanol, heat [1]; OH⁻ acts as a base, removing H⁺ [1].', '[{"text": "Marking point 1", "any": ["sn2", "nucleophilic substitution"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["lone pair", "oh to c", "attacks carbon", "arrow from oh"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["c–br", "c-br", "bond to br", "arrow from bond", "br leaves"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["ethanol", "alcoholic", "heat"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["base", "removes h", "proton"], "all": [], "marks": 1}]'::jsonb, '(a) SN2 (nucleophilic substitution) [1]: an arrow from the lone pair on OH⁻ to the δ+ carbon [1] and from the C–Br bond to Br, which leaves as Br⁻ [1]. (b) NaOH dissolved in ethanol, heat [1]; OH⁻ acts as a base, removing H⁺ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
