insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f38a97b9-d8f6-5a51-a866-24ba9a43c602', 'short', 'Compound X, C₃H₈O, gives steamy fumes with PCl₅. With concentrated H₃PO₄ and heat it forms propene only. It reacts with ethanoic acid to form an ester. (a) What do the fumes show? (b) Give two possible structures for X. (c) Name the ester formed from propan-1-ol.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f38a97b9-d8f6-5a51-a866-24ba9a43c602', '(a) An –OH group (alcohol) [1]. (b) Propan-1-ol, CH₃CH₂CH₂OH [1], or propan-2-ol, CH₃CH(OH)CH₃ [1]. (c) Propyl ethanoate [1].', '(a) An –OH group (alcohol) [1]. (b) Propan-1-ol, CH₃CH₂CH₂OH [1], or propan-2-ol, CH₃CH(OH)CH₃ [1]. (c) Propyl ethanoate [1].', '[{"text": "Marking point 1", "any": ["oh", "hydroxyl", "alcohol"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["propan-1-ol", "ch3ch2ch2oh"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["propan-2-ol", "ch3choh", "ch3ch(oh)ch3"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["propyl ethanoate"], "all": [], "marks": 1}]'::jsonb, '(a) An –OH group (alcohol) [1]. (b) Propan-1-ol, CH₃CH₂CH₂OH [1], or propan-2-ol, CH₃CH(OH)CH₃ [1]. (c) Propyl ethanoate [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
