insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b3cf5fd1-655f-57fc-8563-a656009cf5df', 'The ethyl group donates electrons to the oxygen [1], so the ethoxide ion is less stable than the hydroxide ion and ethanol loses H⁺ less easily [1].', 'The ethyl group donates electrons to the oxygen [1], so the ethoxide ion is less stable than the hydroxide ion and ethanol loses H⁺ less easily [1].', '[{"text": "Marking point 1", "any": ["alkyl", "ethyl", "c2h5", "electron donating", "inductive", "push"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["less stable", "destabilis", "negative charge", "concentrat", "ethoxide"], "all": [], "marks": 1}]'::jsonb, 'The ethyl group donates electrons to the oxygen [1], so the ethoxide ion is less stable than the hydroxide ion and ethanol loses H⁺ less easily [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('5f9e977c-bbce-5c1b-9d3f-db92b9147b5c', 'b3cf5fd1-655f-57fc-8563-a656009cf5df', 29);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('22295963-6190-5b8d-9f62-83605cb1cb64', 'short', 'Three isomers of C₄H₁₀O are butan-1-ol, butan-2-ol and 2-methylpropan-2-ol. Describe how acidified dichromate and the tri-iodomethane test tell them apart, with results.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('22295963-6190-5b8d-9f62-83605cb1cb64', 'Acidified dichromate stays orange with 2-methylpropan-2-ol (tertiary) [1] but turns green with butan-1-ol and butan-2-ol [1]; with alkaline iodine, butan-2-ol gives a pale yellow precipitate [1] and butan-1-ol gives no precipitate [1].', 'Acidified dichromate stays orange with 2-methylpropan-2-ol (tertiary) [1] but turns green with butan-1-ol and butan-2-ol [1]; with alkaline iodine, butan-2-ol gives a pale yellow precipitate [1] and butan-1-ol gives no precipitate [1].', '[{"text": "Marking point 1", "any": ["stays orange", "no change"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["both green", "turn green"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["yellow precipitate"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["no yellow", "no precipitate"], "all": [], "marks": 1}]'::jsonb, 'Acidified dichromate stays orange with 2-methylpropan-2-ol (tertiary) [1] but turns green with butan-1-ol and butan-2-ol [1]; with alkaline iodine, butan-2-ol gives a pale yellow precipitate [1] and butan-1-ol gives no precipitate [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
