insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d78fe02d-bee8-5f07-b210-95419abd2a69', 'CH₃CH₂CH₂CHO + 2[H] → CH₃CH₂CH₂CH₂OH [1].', 'CH₃CH₂CH₂CHO + 2[H] → CH₃CH₂CH₂CH₂OH [1].', '[{"text": "Marking point 1", "any": ["ch3ch2ch2ch2oh", "c4h9oh", "butan-1-ol"], "all": [], "marks": 1}]'::jsonb, 'CH₃CH₂CH₂CHO + 2[H] → CH₃CH₂CH₂CH₂OH [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
