insert into public.questions (id, kind, prompt, options, marks, image_url) values ('44d20288-acf1-56c0-b7b7-c453283d33cd', 'short', 'Describe the two steps of the mechanism for CN⁻ adding to ethanal.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('44d20288-acf1-56c0-b7b7-c453283d33cd', 'The lone pair on the carbon of CN⁻ attacks [1] the δ+ carbonyl carbon, and the π electrons move to oxygen, forming O⁻ [1]; the O⁻ then gains H⁺ from HCN (or water) [1].', 'The lone pair on the carbon of CN⁻ attacks [1] the δ+ carbonyl carbon, and the π electrons move to oxygen, forming O⁻ [1]; the O⁻ then gains H⁺ from HCN (or water) [1].', '[{"text": "Marking point 1", "any": ["lone pair", "cn attacks", "cn- attacks", "arrow from cn"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["partial positive", "carbon of c=o", "carbonyl carbon", "c o carbon"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["hcn", "proton", "water"], "all": [], "marks": 1}]'::jsonb, 'The lone pair on the carbon of CN⁻ attacks [1] the δ+ carbonyl carbon, and the π electrons move to oxygen, forming O⁻ [1]; the O⁻ then gains H⁺ from HCN (or water) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('26e2c5d5-36e8-56f6-b3a3-196400655d09', '44d20288-acf1-56c0-b7b7-c453283d33cd', 11);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('b9028a5e-2297-5119-b905-3f8c2dfecd91', 'short', 'Propanal reacts with HCN/KCN. (a) Name the type of reaction. (b) Draw (describe) the product. (c) Explain why the product mixture is not optically active.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b9028a5e-2297-5119-b905-3f8c2dfecd91', '(a) Nucleophilic addition [1]. (b) CH₃CH₂CH(OH)CN, 2-hydroxybutanenitrile [1]. (c) The C=O group is planar [1], so CN⁻ attacks equally from both sides, giving equal amounts of the two optical isomers (a racemic mixture) [1].', '(a) Nucleophilic addition [1]. (b) CH₃CH₂CH(OH)CN, 2-hydroxybutanenitrile [1]. (c) The C=O group is planar [1], so CN⁻ attacks equally from both sides, giving equal amounts of the two optical isomers (a racemic mixture) [1].', '[{"text": "Marking point 1", "any": ["nucleophilic addition"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ch3ch2ch(oh)cn", "2-hydroxybutanenitrile"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["planar", "flat", "trigonal"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["both sides", "either side", "equal", "racemic", "50"], "all": [], "marks": 1}]'::jsonb, '(a) Nucleophilic addition [1]. (b) CH₃CH₂CH(OH)CN, 2-hydroxybutanenitrile [1]. (c) The C=O group is planar [1], so CN⁻ attacks equally from both sides, giving equal amounts of the two optical isomers (a racemic mixture) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('26e2c5d5-36e8-56f6-b3a3-196400655d09', 'b9028a5e-2297-5119-b905-3f8c2dfecd91', 12);
