insert into public.questions (id, kind, prompt, options, marks, image_url) values ('978d7b57-7b18-5ad5-8378-9dc5eb2f543a', 'short', 'All three give an orange precipitate with 2,4-DNPH. Describe how two further tests identify each one.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('978d7b57-7b18-5ad5-8378-9dc5eb2f543a', 'Tollens'' (or Fehling''s) [1]: butanal and 2-methylpropanal give a silver mirror (red-brown precipitate); butanone gives no change [1]. Alkaline iodine [1]: butanone gives a yellow precipitate of CHI₃ (and the two aldehydes are told apart by melting point of the 2,4-DNPH derivative) [1].', 'Tollens'' (or Fehling''s) [1]: butanal and 2-methylpropanal give a silver mirror (red-brown precipitate); butanone gives no change [1]. Alkaline iodine [1]: butanone gives a yellow precipitate of CHI₃ (and the two aldehydes are told apart by melting point of the 2,4-DNPH derivative) [1].', '[{"text": "Marking point 1", "any": ["tollens", "fehling"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": [], "all": ["butanone", "no"], "marks": 1}, {"text": "Marking point 3", "any": ["iodine", "iodoform", "tri-iodomethane"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": [], "all": ["butanone", "yellow"], "marks": 1}]'::jsonb, 'Tollens'' (or Fehling''s) [1]: butanal and 2-methylpropanal give a silver mirror (red-brown precipitate); butanone gives no change [1]. Alkaline iodine [1]: butanone gives a yellow precipitate of CHI₃ (and the two aldehydes are told apart by melting point of the 2,4-DNPH derivative) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
