insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('9e0f1a61-e7aa-572f-a7c7-44194b483694', 'Step 1: KCN [1] in ethanol, heat under reflux [1], giving propanenitrile [1]. Step 2: heat under reflux with dilute HCl (acid hydrolysis) to give propanoic acid [1].', 'Step 1: KCN [1] in ethanol, heat under reflux [1], giving propanenitrile [1]. Step 2: heat under reflux with dilute HCl (acid hydrolysis) to give propanoic acid [1].', '[{"text": "Marking point 1", "any": ["kcn", "cyanide"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ethanol", "reflux"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["propanenitrile", "ch3ch2cn"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["dilute acid", "hcl", "h2so4", "hydrolys"], "all": [], "marks": 1}]'::jsonb, 'Step 1: KCN [1] in ethanol, heat under reflux [1], giving propanenitrile [1]. Step 2: heat under reflux with dilute HCl (acid hydrolysis) to give propanoic acid [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
