insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c187afad-35fc-5930-9e3d-fbc5771d7826', 'The two carbons that were the C=C form the chain [1], each carrying one CH₃ side group: –CH(CH₃)–CH(CH₃)– [1].', 'The two carbons that were the C=C form the chain [1], each carrying one CH₃ side group: –CH(CH₃)–CH(CH₃)– [1].', '[{"text": "Marking point 1", "any": ["ch(ch3)", "ch ch3", "chch3"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["two", "both carbons", "–ch(ch3)–ch(ch3)–", "ch(ch3)ch(ch3)"], "all": [], "marks": 1}]'::jsonb, 'The two carbons that were the C=C form the chain [1], each carrying one CH₃ side group: –CH(CH₃)–CH(CH₃)– [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
