insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('73ca0194-d21a-5382-8ca9-17da42431e83', 'It is non-biodegradable, so it stays in landfill [1]; burning it [1] releases toxic HCl (and dioxins); it lasts because its C–C and C–H bonds are strong and non-polar, so microbes cannot break it down [1].', 'It is non-biodegradable, so it stays in landfill [1]; burning it [1] releases toxic HCl (and dioxins); it lasts because its C–C and C–H bonds are strong and non-polar, so microbes cannot break it down [1].', '[{"text": "Marking point 1", "any": ["landfill", "non-biodegradable", "not biodegrad", "persist"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["burn", "combust", "incinerat"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["hcl", "hydrogen chloride", "toxic", "acid", "dioxin", "inert", "strong bonds", "non-polar"], "all": [], "marks": 1}]'::jsonb, 'It is non-biodegradable, so it stays in landfill [1]; burning it [1] releases toxic HCl (and dioxins); it lasts because its C–C and C–H bonds are strong and non-polar, so microbes cannot break it down [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('8a9ab173-022d-5a0f-bb58-817d3fb39fb7', '73ca0194-d21a-5382-8ca9-17da42431e83', 10);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('40e1c88d-8e5c-53e2-8d5d-f2783caedc72', 'short', 'Non-stick pans are coated with PTFE, made from tetrafluoroethene, CF₂=CF₂. (a) Name the type of polymerisation. (b) Give the repeat unit. (c) Explain why this polymer is very unreactive.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('40e1c88d-8e5c-53e2-8d5d-f2783caedc72', '(a) Addition [1]. (b) –CF₂–CF₂– [1]. (c) The C–F bonds [1] (and C–C bonds) are very strong, so they are hard to break [1].', '(a) Addition [1]. (b) –CF₂–CF₂– [1]. (c) The C–F bonds [1] (and C–C bonds) are very strong, so they are hard to break [1].', '[{"text": "Marking point 1", "any": ["addition"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["–cf2–cf2–", "cf2cf2", "cf2 cf2", "cf2"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["c–f", "c-f", "c f", "carbon fluorine"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["strong", "high bond energy", "hard to break"], "all": [], "marks": 1}]'::jsonb, '(a) Addition [1]. (b) –CF₂–CF₂– [1]. (c) The C–F bonds [1] (and C–C bonds) are very strong, so they are hard to break [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
