insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0ffa152a-47a7-586e-a949-bd4967d1f1d6', 'Step 1: steam [1] with an H₃PO₄ catalyst (high temperature and pressure), giving propan-2-ol [1]. Step 2: acidified potassium dichromate(VI) [1], heat [1].', 'Step 1: steam [1] with an H₃PO₄ catalyst (high temperature and pressure), giving propan-2-ol [1]. Step 2: acidified potassium dichromate(VI) [1], heat [1].', '[{"text": "Marking point 1", "any": ["steam", "h2o", "water"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["h3po4", "phosphoric", "catalyst"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["dichromate", "k2cr2o7", "cr2o7"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["acid", "h2so4", "heat", "reflux"], "all": [], "marks": 1}]'::jsonb, 'Step 1: steam [1] with an H₃PO₄ catalyst (high temperature and pressure), giving propan-2-ol [1]. Step 2: acidified potassium dichromate(VI) [1], heat [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
