insert into public.questions (id, kind, prompt, options, marks, image_url) values ('52c5d797-48eb-5b7a-8858-38656c756169', 'short', 'Ethanal is converted into 2-hydroxypropanoic acid (lactic acid). Give the two steps with reagents.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('52c5d797-48eb-5b7a-8858-38656c756169', 'Step 1: HCN with KCN, giving 2-hydroxypropanenitrile [1]. Step 2: heat under reflux with dilute acid (hydrolysis) [1].', 'Step 1: HCN with KCN, giving 2-hydroxypropanenitrile [1]. Step 2: heat under reflux with dilute acid (hydrolysis) [1].', '[{"text": "Marking point 1", "any": ["hcn", "kcn"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["hydrolys", "dilute acid", "hcl", "h2so4"], "all": [], "marks": 1}]'::jsonb, 'Step 1: HCN with KCN, giving 2-hydroxypropanenitrile [1]. Step 2: heat under reflux with dilute acid (hydrolysis) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('541abead-cb4c-528d-9566-beac223c1577', '52c5d797-48eb-5b7a-8858-38656c756169', 12);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('89436d3f-8fcd-536d-9198-317dd5266544', 'short', 'Plan a three-step synthesis of ethyl propanoate using ethene as the only organic starting material. Name each intermediate.', '[]'::jsonb, 6, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('89436d3f-8fcd-536d-9198-317dd5266544', 'Make ethanol from ethene with steam/H₃PO₄ [1] [1]. Make bromoethane from ethene with HBr [1]; KCN in ethanol gives propanenitrile [1]; hydrolysis with dilute acid gives propanoic acid [1]; propanoic acid + ethanol with concentrated H₂SO₄, heat, gives ethyl propanoate [1].', 'Make ethanol from ethene with steam/H₃PO₄ [1] [1]. Make bromoethane from ethene with HBr [1]; KCN in ethanol gives propanenitrile [1]; hydrolysis with dilute acid gives propanoic acid [1]; propanoic acid + ethanol with concentrated H₂SO₄, heat, gives ethyl propanoate [1].', '[{"text": "Marking point 1", "any": ["ethanol"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["bromoethane", "chloroethane", "hbr"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["propanenitrile", "kcn"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["propanoic acid", "hydrolys"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["h2so4", "sulfuric"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["steam", "h3po4"], "all": [], "marks": 1}]'::jsonb, 'Make ethanol from ethene with steam/H₃PO₄ [1] [1]. Make bromoethane from ethene with HBr [1]; KCN in ethanol gives propanenitrile [1]; hydrolysis with dilute acid gives propanoic acid [1]; propanoic acid + ethanol with concentrated H₂SO₄, heat, gives ethyl propanoate [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('541abead-cb4c-528d-9566-beac223c1577', '89436d3f-8fcd-536d-9198-317dd5266544', 13);
