insert into public.questions (id, kind, prompt, options, marks, image_url) values ('eeb901d2-e0e1-5fd8-b2f4-0b0570ee9dfc', 'short', 'Propan-1-ol is heated under reflux with acidified dichromate. Describe how the IR spectrum of the product differs from that of propan-1-ol.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('eeb901d2-e0e1-5fd8-b2f4-0b0570ee9dfc', 'A strong C=O absorption appears near 1700 cm⁻¹ [1]; the O–H absorption moves to 2500–3000 cm⁻¹ and becomes very broad [1].', 'A strong C=O absorption appears near 1700 cm⁻¹ [1]; the O–H absorption moves to 2500–3000 cm⁻¹ and becomes very broad [1].', '[{"text": "Marking point 1", "any": ["c=o", "c o", "1700", "1710", "carbonyl"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["2500", "3000", "broader", "very broad"], "all": [], "marks": 1}]'::jsonb, 'A strong C=O absorption appears near 1700 cm⁻¹ [1]; the O–H absorption moves to 2500–3000 cm⁻¹ and becomes very broad [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('59822df6-59db-56d6-82b0-557cad747f76', 'eeb901d2-e0e1-5fd8-b2f4-0b0570ee9dfc', 13);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6427e54c-feb7-5343-bd9f-8885c94023bd', 'short', 'Compound P, C₃H₆O, has a strong absorption at 1720 cm⁻¹ and no absorption between 3200 and 3600 cm⁻¹. It gives an orange precipitate with 2,4-DNPH but no silver mirror with Tollens'' reagent. (a) Which bond causes the 1720 cm⁻¹ peak? (b) What does the absence of 3200–3600 show? (c) Identify P.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6427e54c-feb7-5343-bd9f-8885c94023bd', '(a) C=O [1]. (b) There is no O–H, so P is not an alcohol [1]. (c) Propanone, CH₃COCH₃ [1].', '(a) C=O [1]. (b) There is no O–H, so P is not an alcohol [1]. (c) Propanone, CH₃COCH₃ [1].', '[{"text": "Marking point 1", "any": ["c=o", "carbonyl", "c o"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["no o–h", "no oh", "not an alcohol", "no alcohol", "no o-h"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["propanone", "acetone", "ch3coch3"], "all": [], "marks": 1}]'::jsonb, '(a) C=O [1]. (b) There is no O–H, so P is not an alcohol [1]. (c) Propanone, CH₃COCH₃ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('59822df6-59db-56d6-82b0-557cad747f76', '6427e54c-feb7-5343-bd9f-8885c94023bd', 14);
