insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d9814c8e-252b-580a-a694-2f29aa3444b9', 'short', 'A compound has M⁺ abundance 40.0% and M+1 abundance 2.64%. Calculate the number of carbon atoms.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d9814c8e-252b-580a-a694-2f29aa3444b9', 'n = (100 × 2.64) ÷ (1.1 × 40.0) = 264 ÷ 44 [1] = 6 [1].', 'n = (100 × 2.64) ÷ (1.1 × 40.0) = 264 ÷ 44 [1] = 6 [1].', '[{"text": "Marking point 1", "any": ["264", "44", "100 × 2.64", "1.1 × 40"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["6"], "all": [], "marks": 1}]'::jsonb, 'n = (100 × 2.64) ÷ (1.1 × 40.0) = 264 ÷ 44 [1] = 6 [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
