insert into public.questions (id, kind, prompt, options, marks, image_url) values ('e2041bfb-3cd5-55b2-b841-a57cb6bcaf68', 'short', 'Compound Q has peaks at m/e 108 and 110 of equal height, an M+1 peak showing two carbon atoms, and a fragment at m/e 29. (a) What do the 108/110 peaks show? (b) Use the data to identify Q. (c) Identify the m/e 29 fragment.', '[]'::jsonb, 4, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = coalesce(public.questions.image_url, excluded.image_url);
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e2041bfb-3cd5-55b2-b841-a57cb6bcaf68', '(a) The molecule contains one bromine atom [1], because ⁷⁹Br and ⁸¹Br give M and M+2 peaks in a 1:1 ratio [1]. (b) Bromoethane, C₂H₅Br (12×2 + 5 + 79 = 108) [1]. (c) C₂H₅⁺ [1].', '(a) The molecule contains one bromine atom [1], because ⁷⁹Br and ⁸¹Br give M and M+2 peaks in a 1:1 ratio [1]. (b) Bromoethane, C₂H₅Br (12×2 + 5 + 79 = 108) [1]. (c) C₂H₅⁺ [1].', '[{"text": "Marking point 1", "any": ["bromine", "br"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["1:1", "equal", "79", "81"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["bromoethane", "c2h5br", "ch3ch2br"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["c2h5", "ethyl"], "all": [], "marks": 1}]'::jsonb, '(a) The molecule contains one bromine atom [1], because ⁷⁹Br and ⁸¹Br give M and M+2 peaks in a 1:1 ratio [1]. (b) Bromoethane, C₂H₅Br (12×2 + 5 + 79 = 108) [1]. (c) C₂H₅⁺ [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
