do $$ begin if to_regprocedure('public.sync_level_classes()') is not null then perform public.sync_level_classes(); end if; end $$;
do $$ begin if to_regprocedure('public.sync_independent_sets()') is not null then perform public.sync_independent_sets(); end if; end $$;
select (select count(*) from public.lessons where external_id ~ '^(ACHEM|IGBIO|IGCHEM|ABIO)-') as cambridge_lessons, (select count(*) from public.quizzes where title like '% · Topic quiz' and created_by = 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') as topic_quizzes, (select count(*) from public.classes where site_slug in ('alevel-chem','igcse-bio','alevel-bio')) as classes;
update public.quizzes q set published = true where q.title ~ '^(1[5-9]|2[0-2]) .* · Topic quiz$' and exists (select 1 from public.quiz_classes c join public.classes k on k.id = c.class_id where c.quiz_id = q.id and coalesce(k.site_slug, k.follows) = 'alevel-chem');
update public.quiz_classes c set published = true, published_at = coalesce(c.published_at, now()) from public.quizzes q, public.classes k where q.id = c.quiz_id and k.id = c.class_id and coalesce(k.site_slug, k.follows) = 'alevel-chem' and q.title ~ '^(1[5-9]|2[0-2]) .* · Topic quiz$';
